const RELAW_DATA = {"lastUpdatedDate":"2026-11-17","categories":[{"id":"landlord-tenant","label":"Landlord–Tenant","color":"var(--cat-landlord)"},{"id":"zoning-land-use","label":"Zoning & Land Use","color":"var(--cat-zoning)"},{"id":"reit-securities","label":"REIT & Securities","color":"var(--cat-reit)"},{"id":"construction-defect","label":"Construction Defect","color":"var(--cat-construction)"},{"id":"lending-foreclosure","label":"Lending & Foreclosure","color":"var(--cat-lending)"},{"id":"environmental","label":"Environmental","color":"var(--cat-environmental)"},{"id":"eminent-domain","label":"Eminent Domain","color":"var(--cat-eminent)"},{"id":"lease-disputes","label":"Commercial Lease Disputes","color":"var(--cat-lease)"},{"id":"premises-liability","label":"Premises Liability","color":"var(--cat-premises)"}],"statuses":[{"id":"filed","label":"Filed","color":"var(--status-filed)"},{"id":"pending","label":"Pending","color":"var(--status-pending)"},{"id":"ruling","label":"Ruling Issued","color":"var(--status-ruling)"},{"id":"settled","label":"Settled","color":"var(--status-settled)"},{"id":"appeal","label":"On Appeal","color":"var(--status-appeal)"}],"states":{"AL":"Alabama","AK":"Alaska","AZ":"Arizona","AR":"Arkansas","CA":"California","CO":"Colorado","CT":"Connecticut","DE":"Delaware","FL":"Florida","GA":"Georgia","HI":"Hawaii","ID":"Idaho","IL":"Illinois","IN":"Indiana","IA":"Iowa","KS":"Kansas","KY":"Kentucky","LA":"Louisiana","ME":"Maine","MD":"Maryland","MA":"Massachusetts","MI":"Michigan","MN":"Minnesota","MS":"Mississippi","MO":"Missouri","MT":"Montana","NE":"Nebraska","NV":"Nevada","NH":"New Hampshire","NJ":"New Jersey","NM":"New Mexico","NY":"New York","NC":"North Carolina","ND":"North Dakota","OH":"Ohio","OK":"Oklahoma","OR":"Oregon","PA":"Pennsylvania","RI":"Rhode Island","SC":"South Carolina","SD":"South Dakota","TN":"Tennessee","TX":"Texas","UT":"Utah","VT":"Vermont","VA":"Virginia","WA":"Washington","WV":"West Virginia","WI":"Wisconsin","WY":"Wyoming","DC":"District of Columbia"},"author":{"name":"Jeff Novel","title":"Contributing Author","initials":"JN","bioUrl":"author-jeff-novel.html","linkedin":"https://www.linkedin.com/in/jeffnovel"},"cases":[{"id":"live-002","addedDate":"2026-08-04","title":"Township of Jackson v. Getzel Bee, LLC (NJ Supreme Court Rejects Condemnation to Fund a Land Swap)","brief":"New Jersey's Supreme Court unanimously held Jackson Township could not condemn two LLC-owned lots only to trade them to a developer for open-space land, and sent the case back to set the owners' relief.","category":"eminent-domain","status":"ruling","date":"2026-07-20","jurisdiction":"Supreme Court of New Jersey","parties":[{"name":"Township of Jackson","role":"Plaintiff-Appellant"},{"name":"Getzel Bee, LLC","role":"Defendant-Respondent"},{"name":"Bellevue Jackson, LLC","role":"Defendant-Respondent"},{"name":"State of New Jersey","role":"Defendant"},{"name":"Bellevue Estates, LLC","role":"Developer in the land swap (non-party)"}],"amountUsd":null,"judge":"Stuart Rabner","state":"NJ","amount":"N/A; condemnation orders reversed, relief to be set on remand","source":"live","sourceUrl":"https://www.njcourts.gov/system/files/court-opinions/2026/a_3_25.pdf","summary":"On July 20, 2026, the New Jersey Supreme Court unanimously affirmed an Appellate Division ruling that reversed orders allowing Jackson Township to condemn two lots owned by Getzel Bee, LLC and Bellevue Jackson, LLC. The township took the lots to trade them, with other land, to a developer in exchange for the developer's land to be preserved as open space. Writing for the court, Chief Justice Stuart Rabner held that neither the condemnation statutes nor case law allow taking private land only to exchange it for other property that will be put to public use, and that the township did not deal forthrightly with the owners. Because the swap had already closed, the court remanded for the trial court to decide what relief the owners should receive.","significance":"The court held that the public-use requirement must be met by the condemned property itself, distinguishing Kelo, Midkiff and Berman, where the transfers to private parties served a public purpose. A New Jersey municipality cannot use eminent domain to acquire land to trade to a private party, even to obtain open space elsewhere.","documentUrl":"https://www.njcourts.gov/system/files/court-opinions/2026/a_3_25.pdf","documentLabel":"Read the official opinion","tags":["eminent domain","land swap","condemnation","public use doctrine"],"hasFull":true},{"id":"live-003","addedDate":"2026-08-04","title":"Wilmington Savings Fund Society, FSB v. Milton 90 Pleasant Valley Street LLC (Benchmark 2026-B43 CMBS Foreclosure)","brief":"The Benchmark 2026-B43 CMBS trustee sued to foreclose a $34.4M loan on a Methuen, Mass. site and a Michigan shopping center after a missed first payment, Mortgage Professional America reported.","category":"lending-foreclosure","status":"filed","date":"2026-07-28","jurisdiction":"U.S. District Court, Southern District of New York","parties":[{"name":"Wilmington Savings Fund Society, FSB","role":"Plaintiff (Trustee)"},{"name":"Milton 90 Pleasant Valley Street LLC","role":"Defendant (Borrower)"},{"name":"Development Associates of Benton Harbor LLC","role":"Defendant (Borrower)"}],"judge":"Arun Subramanian","amountUsd":34400000,"amountBasis":"loan","state":"NY","amount":"$34.4M loan balance","source":"live","sourceUrl":"https://www.mpamag.com/us/news/general/trustee-seeks-to-foreclose-344m-cmbs-loan-after-alleged-first-payment-default/584231","summary":"Wilmington Savings Fund Society, FSB, as trustee for the Benchmark 2026-B43 CMBS trust, sued on July 28, 2026 in the Southern District of New York to foreclose a $34.4 million loan on about 46 acres at 90 Pleasant Valley Street in Methuen, Massachusetts and the Fairplain Plaza shopping center in Benton Township, Michigan, Mortgage Professional America reported. The trustee alleges the borrowers missed their first payment, due June 6, 2026, after two guarantors filed Chapter 11, and that the borrowers are not enforcing 99-year leases with affiliated tenants that have also filed Chapter 11. It seeks foreclosure, a UCC foreclosure on personal property and a receiver.","significance":"The complaint's \"affiliate atrophy\" theory treats a borrower's failure to enforce leases with its own affiliates as a reason for a receiver, which would step into those leases and the related bankruptcy cases. The allegations are untested, and no court has ruled on them.","tags":["CMBS","foreclosure","first-payment default","receivership","guarantor bankruptcy"],"docketUrl":"https://www.courtlistener.com/docket/73684397/wilmington-savings-fund-society-fsb-v-milton-90-pleasant-valley-street/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-004","addedDate":"2026-08-04","title":"FitFactariDC LLC v. CoStar Group, Inc. (CRE Lease-Data Hub-and-Spoke Antitrust Suit)","brief":"A commercial tenant's proposed class action claims CoStar was the hub of a scheme to fix office, retail and industrial rents, with CBRE, JLL, Cushman & Wakefield, Colliers and Newmark as the spokes.","category":"lease-disputes","status":"filed","date":"2026-06-12","jurisdiction":"U.S. District Court, Northern District of Illinois","parties":[{"name":"FitFactariDC, LLC","role":"Plaintiff"},{"name":"CoStar Group, Inc.","role":"Defendant"},{"name":"CBRE Group, Inc.","role":"Defendant"},{"name":"Jones Lang LaSalle Incorporated","role":"Defendant"},{"name":"Cushman & Wakefield plc","role":"Defendant"},{"name":"Colliers International USA, LLC","role":"Defendant"},{"name":"Colliers International Group Inc.","role":"Defendant (dismissed without prejudice Aug. 7, 2026)"},{"name":"Newmark Group, Inc.","role":"Defendant"}],"judge":"Joan Humphrey Lefkow","amountUsd":null,"state":"IL","amount":"Proposed class action; no damages figure stated in the source","source":"live","sourceUrl":"https://therealdeal.com/national/2026/06/17/costar-hit-with-lawsuit-alleging-price-fixing-for-cre-rents/","summary":"Commercial tenant FitFactariDC LLC filed a proposed class action in the U.S. District Court for the Northern District of Illinois on June 12, 2026. It alleges that CoStar Group collected and shared sensitive lease data in a \"hub-and-spoke\" conspiracy with brokerages CBRE, JLL, Cushman & Wakefield, Colliers and Newmark, and that the tenant paid \"artificially inflated\" rent on a Denver lease as a result, The Real Deal reported, citing Bisnow. CoStar's general counsel called the suit \"frivolous.\" CoStar and the brokerages moved to dismiss on Aug. 17, 2026.","significance":"The suit tries to carry the hub-and-spoke theory used against RealPage over apartment rents into commercial lease data shared through a comps platform. If it survives the motions to dismiss, brokers and owners that share lease terms through data services could face similar claims, so landlords and tenants should watch how the court treats the theory.","tags":["antitrust","hub-and-spoke","CoStar","lease data","brokerage"],"docketUrl":"https://www.courtlistener.com/docket/73480976/fitfactaridc-llc-v-costar-group-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-005","addedDate":"2026-08-04","title":"SEC v. RAD Diversified REIT, Inc.","brief":"The SEC sued Tampa-based RAD Diversified REIT and its two founders, alleging a fraudulent offering that raised at least $152 million from more than 5,500 retail investors; the SEC has asked the court to approve a consent judgment with the REIT.","category":"reit-securities","status":"filed","date":"2026-07-29","jurisdiction":"U.S. District Court, Middle District of Florida","parties":[{"name":"Securities and Exchange Commission","role":"Plaintiff"},{"name":"RAD Diversified REIT, Inc.","role":"Defendant"},{"name":"The Seminar Solution, LLC","role":"Relief Defendant"}],"judge":"Kathryn Kimball Mizelle","amountUsd":152000000,"amountBasis":"other","state":"FL","amount":"At least $152M raised from investors (alleged)","source":"live","sourceUrl":"https://www.sec.gov/enforcement-litigation/litigation-releases/lr-26596","summary":"The SEC sued RAD Diversified REIT, Inc., its two founders and relief defendant The Seminar Solution, LLC in the U.S. District Court for the Middle District of Florida on July 29, 2026. According to the SEC's litigation release and complaint, the REIT raised at least $152 million from more than 5,500 retail investors from November 2019 through March 2024 while misrepresenting its profitability, stock valuation and liquidity; about $54 million of investor funds was diverted to The Seminar Solution, an entity the founders own, and the founders allegedly misappropriated nearly $5 million. On October 23, 2026 the SEC filed an unopposed motion asking the court to approve a consent judgment as to the REIT.","significance":"The complaint centers on alleged related-party fund flows and on continued fundraising after warning signs the SEC says the defendants knew of, including a bank's refusal of a credit line and mounting foreclosures. The allegations have not been proven, and the docket shows no judgment yet against any defendant.","documentUrl":"https://www.sec.gov/enforcement-litigation/litigation-releases/lr-26596","documentLabel":"Read the SEC litigation release","tags":["REIT","SEC enforcement","securities fraud","non-traded REIT","related-party transactions"],"docketUrl":"https://www.courtlistener.com/docket/73687065/securities-and-exchange-commission-v-rad-diversified-reit-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-006","addedDate":"2026-08-04","title":"In re Silver Star Properties REIT (Second Chapter 11 Filing)","brief":"Houston REIT Silver Star Properties filed for Chapter 11 on May 28, 2026, its second filing since 2023, after a planned shift from office to self-storage; four loans are in default, Bisnow reported.","category":"lending-foreclosure","status":"filed","date":"2026-05-28","jurisdiction":"U.S. Bankruptcy Court, Northern District of Texas","parties":[{"name":"Silver Star Properties REIT, Inc.","role":"Debtor"}],"amountUsd":75000000,"amountBasis":"other","judge":"Mark X. Mullin","state":"TX","amount":"$100M assets vs. $75M liabilities","source":"live","sourceUrl":"https://www.bisnow.com/news/national/commercial-real-estate/silver-star-properties-files-for-chapter-11-134932","summary":"Houston-based REIT Silver Star Properties filed for Chapter 11 protection on May 28, 2026 in the Northern District of Texas, its second Chapter 11 case after a September 2023 filing, Bisnow reported. The company reported $75 million in liabilities and $100 million in assets, and said four loans are in default, along with a $5.75 million promissory note on a self-storage property that moved to foreclosure on June 2. Its 2023 lawsuit accusing founder and former CEO Allen Hartman of fraud and breach of fiduciary duty is still ongoing.","significance":"The filing follows a pivot from office, retail and industrial holdings into self-storage that Bisnow reports was slowed by an SEC investigation, litigation and blocked property sales. The company told shareholders the bankruptcy could cancel their equity.","tags":["REIT bankruptcy","loan default","foreclosure","self-storage","chapter 11"],"docketUrl":"https://www.courtlistener.com/docket/73409172/silver-star-properties-reit-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-007","addedDate":"2026-08-04","title":"Via Mizner Lender 1 LLC v. Via Mizner Owner III, LLC (Mandarin Oriental Residences, Boca Raton Foreclosure)","brief":"Via Mizner Lender 1, agent for a lender group, sued to foreclose on the unfinished Mandarin Oriental condo tower in Boca Raton, seeking $417.7M and priority over contractor and buyer claims.","category":"lending-foreclosure","status":"filed","date":"2026-07-17","jurisdiction":"Fifteenth Judicial Circuit Court, Palm Beach County, Florida","parties":[{"name":"Via Mizner Lender 1 LLC","role":"Plaintiff"},{"name":"Via Mizner Owner III","role":"Defendant"},{"name":"Strategic Group Builders","role":"Lienholder"}],"judge":null,"amountUsd":417700000,"amountBasis":"claim","state":"FL","amount":"$417.7M foreclosure claim","source":"live","sourceUrl":"https://thecoastalstar.com/profiles/blogs/boca-raton-legal-battles-rise-over-unfinished-mandarin-oriental","summary":"Via Mizner Lender 1 LLC, administrative agent for a group of lenders, filed a foreclosure complaint in Palm Beach County Circuit Court on July 17, 2026 against Via Mizner Owner III, the Penn-Florida Companies affiliate building the Mandarin Oriental condominiums in Boca Raton, The Coastal Star reported. The lenders seek $417.7 million to repay an original $270 million loan, secured by an August 2023 mortgage, plus interest, advances and fees, and allege the borrower stopped paying interest in June 2024 and did not pay off the loan in September 2025 as promised. The complaint asks the court to rank the mortgage ahead of claims by 'purported junior lienholders,' including construction manager Strategic Group Builders, and 'purported contract purchasers' of units.","significance":"The case sets a senior construction lender's mortgage against a contractor's recorded lien and the claims of unit buyers on an unfinished condominium project, while a related hotel project is separately in Chapter 11. How the court ranks those claims will matter to lenders, contractors and buyers on other unfinished projects.","tags":["foreclosure","mechanics lien","condo deposits","construction lending","chapter 11"],"hasFull":true},{"id":"live-008","addedDate":"2026-08-05","title":"CommunityAmerica Federal Credit Union v. Metropoint 300/400 Owners (St. Louis Park Office Foreclosure)","brief":"CommunityAmerica Federal Credit Union filed two foreclosure suits seeking roughly $46 million in loans tied to the Metropoint 300 and 400 office buildings in St. Louis Park, Minnesota.","category":"lending-foreclosure","status":"filed","date":"2026-07-23","jurisdiction":"Hennepin County District Court, Minnesota","parties":[{"name":"CommunityAmerica Federal Credit Union","role":"Plaintiff"}],"judge":null,"amountUsd":46000000,"amountBasis":"loan","state":"MN","amount":"$46M combined loan balance (two foreclosure suits)","source":"live","sourceUrl":"https://www.connectcre.com/stories/return-to-lender-week-of-july-23-2026/","summary":"CommunityAmerica Federal Credit Union filed two lawsuits in Hennepin County District Court against the owners of the Metropoint 300 building at 300 Highway 169 S. and the Metropoint 400 building at 400 Highway 169 S. in St. Louis Park, Minnesota, seeking to recover roughly $46 million in loans tied to the properties, the Minneapolis/St. Paul Business Journal reported, according to Connect CRE. Both buildings were scheduled to be sold at a foreclosure auction in September 2026.","significance":"The suits put two buildings in the Metropoint business park on track for a lender-driven sale, with a credit union as the lender seeking to recover about $46 million. Both buildings were set for auction within about two months of the report.","tags":["foreclosure","office","credit union","minnesota","st-louis-park"],"hasFull":true},{"id":"live-009","addedDate":"2026-08-11","title":"SCLS Realty, LLC v. Town of Johnston (Eminent Domain Suit and Contempt Motion)","brief":"After a July 28 ruling against Johnston, RI's condemnation of a 31-acre site planned for 252 affordable units, the landowners sought contempt; on Aug. 11 the judge found the town had not violated the injunction.","category":"eminent-domain","status":"pending","date":"2026-08-04","jurisdiction":"U.S. District Court, District of Rhode Island","parties":[{"name":"SCLS Realty, LLC","role":"Plaintiff"},{"name":"Sixty Three Johnston, LLC","role":"Plaintiff"},{"name":"Town of Johnston, Rhode Island","role":"Defendant"}],"amountUsd":null,"judge":"Melissa R. DuBose","state":"RI","amount":"31-acre parcel; town's own appraisal valued land at $775K","source":"live","sourceUrl":"https://rhodeislandcurrent.com/2026/08/04/federal-judge-schedules-contempt-hearing-in-johnston-eminent-domain-dispute/","summary":"One week after U.S. District Judge Melissa R. DuBose ruled on July 28, 2026 against Johnston, Rhode Island's attempt to take a 31-acre George Waterman Road property, the landowners asked her to hold town officials in contempt over two July 31 Town Council resolutions, the Rhode Island Current reported. DuBose ordered the town to show cause, but on August 11 she found the town's actions did not violate the April 2025 preliminary injunction and canceled the hearing, according to the court docket. The case continues in discovery.","significance":"The court found that putting a charter amendment on the ballot and creating a building authority did not breach the injunction against the condemnation. The landowners' remaining claims are still pending.","tags":["eminent domain","contempt","affordable housing","takings","municipal liability"],"docketUrl":"https://www.courtlistener.com/docket/69723262/scls-realty-llc-v-town-of-johnston-rhode-island/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-010","addedDate":"2026-08-11","title":"111 West 57th Investment LLC v. 111 W57 Mezz Investor LLC (Steinway Tower \"Sole Discretion\" Ruling)","brief":"New York's highest court, 4-3, revived an AmBase vehicle's implied-covenant claim against Apollo entities over the 2017 sale of a $25M Steinway Tower junior mezzanine loan that preceded a strict foreclosure of its equity.","category":"lending-foreclosure","status":"ruling","date":"2026-05-28","jurisdiction":"New York Court of Appeals","parties":[{"name":"111 West 57th Investment LLC","role":"Plaintiff-Appellant"},{"name":"111 W57 Mezz Investor LLC","role":"Defendant"},{"name":"ACREFI Mortgage Lending, LLC","role":"Respondent"},{"name":"Spruce Capital Partners LLC","role":"Respondent"}],"amountUsd":null,"judge":"Rowan D. Wilson","state":"NY","amount":"$65M equity investment; $25M junior mezzanine loan; ~$600M cash flow to equity in Apollo's models (as alleged)","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_03376.shtml","summary":"On May 28, 2026, the New York Court of Appeals, 4-3, reinstated 111 West 57th Investment LLC's claim that Apollo lending entities breached the implied covenant of good faith and fair dealing by assigning a $25 million junior mezzanine loan on the 111 West 57th Street tower project to Spruce Capital Partners in 2017, which then took the joint venture's equity by strict foreclosure. Assuming Apollo had 'sole discretion' to assign the loan, the majority held that discretion did not exempt it from the implied covenant. The court affirmed dismissal of the tortious interference claims and remitted the case to Supreme Court, New York County.","significance":"The majority sided with what it called the prevailing view among the Appellate Division departments, in tension with some First Department decisions, that a 'sole discretion' clause does not exempt a party from the implied covenant, and said its ruling is consistent with Delaware law and 'in no way changes New York law.' The three dissenters warned it would unsettle expectations under existing loan agreements. The ruling addresses only whether the claim was adequately pleaded.","documentUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_03376.shtml","documentLabel":"Read the official opinion","tags":["mezzanine debt","implied covenant","UCC foreclosure","sole discretion","capital stack"],"hasFull":true},{"id":"live-013","addedDate":"2026-08-11","title":"Ayer v. Lightstone Value Plus REIT (Undisclosed $59.8M Chairman Conflict in Liquidation-Delay Proxy)","brief":"A federal judge let a class action proceed against three Lightstone Value Plus REITs, alleging 2022 proxies seeking to scrap liquidation deadlines hid the chairman's $59.8M conflicting stake.","category":"reit-securities","status":"ruling","date":"2026-08-05","jurisdiction":"U.S. District Court, District of New Jersey","parties":[{"name":"Lightstone Value Plus REIT I, Inc.","role":"Defendant"},{"name":"Lightstone Value Plus REIT II, Inc.","role":"Defendant"},{"name":"Lightstone Value Plus REIT III, Inc.","role":"Defendant"},{"name":"Lightstone Value Plus REIT LLC","role":"Defendant"},{"name":"Lightstone Value Plus REIT II LLC","role":"Defendant"},{"name":"Lightstone Value Plus REIT III LLC","role":"Defendant"}],"amountUsd":null,"judge":"Michael A. Shipp","state":"NJ","amount":"$59.8M alleged undisclosed conflict of interest","source":"live","sourceUrl":"https://altswire.com/lightstone-reit-directors-must-face-suit-over-59-8m-undisclosed-conflict/","summary":"U.S. District Judge Michael A. Shipp ruled on August 5, 2026 that investors adequately alleged that 2022 proxy statements and solicitor calls for three Lightstone Value Plus REITs omitted a material conflict held by chairman and CEO David Lichtenstein, AltsWire reported. Plaintiffs allege his subordinated participation interests, potentially worth more than $59.8 million, would have been worthless had REIT II and REIT III liquidated on their original schedules, and that the proxies disclosed the interests but not that fact. All four counts, including breach of fiduciary duty claims against the directors and the advisory entities, will proceed.","significance":"Signals that courts will scrutinize bundled, omnibus REIT charter-amendment proxies — especially those pairing liquidation-timeline changes with fiduciary-duty waivers, quorum reductions, or indemnification expansions — for whether insiders' financial stakes in the outcome were meaningfully disclosed, not just nominally mentioned. Non-traded REIT sponsors, external advisers, and independent directors involved in comparable extension votes should expect increased plaintiff interest and revisit both proxy drafting practices and D&O coverage.","tags":["REIT","proxy disclosure","fiduciary duty","charter amendment","securities class action"],"docketUrl":"https://www.courtlistener.com/docket/69353264/ayer-v-lightstone-value-plus-reit-i-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-015","addedDate":"2026-08-11","title":"Monarch Communities, LLC v. Township of Montville (Inherently Beneficial Use-Variance Standard Revised)","brief":"New Jersey's Supreme Court now requires inherently beneficial use-variance applicants to first prove no substantial impairment of the zone plan, remanding Montville's denial of a 165-unit senior living facility.","category":"zoning-land-use","status":"ruling","date":"2026-07-13","jurisdiction":"Supreme Court of New Jersey","parties":[{"name":"Monarch Communities, LLC","role":"Applicant/Developer"},{"name":"Township of Montville","role":"Defendant"},{"name":"Township of Montville Zoning Board of Adjustment","role":"Defendant"}],"amountUsd":null,"judge":"Anne M. Patterson","state":"NJ","amount":"165-unit senior living facility","source":"live","sourceUrl":"https://www.coleschotz.com/the-new-jersey-supreme-court-modifies-the-long-standing-test-for-inherently-beneficial-use-variances/","summary":"In a unanimous July 13, 2026 opinion by Justice Anne M. Patterson, the New Jersey Supreme Court modified the 1992 Sica test for 'inherently beneficial use' variances, the New Jersey Globe reported. Zoning boards must now first decide whether the applicant has shown the variance would not substantially impair the intent and purpose of the zone plan and zoning ordinance, and must deny it if that showing is not made, before any weighing of benefits and detriments. The Court reversed the Appellate Division, which had sided with developer Monarch Communities after Montville Township's zoning board denied a variance for a 165-unit senior living facility, and sent the case back to the board.","significance":"The ruling makes inherently beneficial use variances for senior housing, hospitals, schools and child care centers in New Jersey harder to win, because the public value of the use no longer carries the application on its own. Applicants will need evidence on how the project fits the municipality's master plan and zoning ordinance, which a law-firm summary of the decision said will typically mean expert planning testimony.","documentUrl":"https://www.njcourts.gov/system/files/court-opinions/2026/a_70_24.pdf","documentLabel":"Read the official opinion","tags":["zoning","use variance","inherently beneficial use","senior housing","land use"],"hasFull":true},{"id":"live-017","addedDate":"2026-08-12","title":"Travelers Property Casualty Co. v. Washington Shoppes LP (Dry-Cleaner PCE Contamination Coverage Dispute)","brief":"Travelers and St. Paul Fire and Marine seek a ruling that pollution exclusions bar coverage for cleaning up a former dry cleaner's PCE contamination at an Indianapolis shopping center.","category":"environmental","status":"filed","date":"2025-11-26","jurisdiction":"Marion Superior Court, Indiana","parties":[{"name":"Travelers Property Casualty Company of America","role":"Plaintiff"},{"name":"St. Paul Fire and Marine Insurance Company","role":"Plaintiff"},{"name":"Washington Shoppes LP","role":"Defendant"},{"name":"The Broadbent Company, Inc.","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"IN","amount":"Pollution-exclusion coverage dispute; remediation costs undisclosed","source":"live","sourceUrl":"https://www.theindianalawyer.com/articles/insurance-companies-sue-indy-shopping-center-in-dispute-over-environmental-site-cleanup-costs","summary":"Travelers Property Casualty Company of America and St. Paul Fire and Marine Insurance Company sued Washington Shoppes LP and The Broadbent Company, Inc. in Marion Superior Court on Nov. 26, 2025, seeking a declaration that they owe no defense or indemnity for cleanup costs at an Indianapolis shopping center, The Indiana Lawyer reported. The center sought coverage after the Indiana Department of Environmental Management identified the property owner as potentially responsible for contamination at a site where Sunrise Dry Cleaners operated from 1987 to 1996. The insurers point to pollution exclusions and argue coverage may also be barred if the center knew of the contamination before buying the site or before the policies were issued.","significance":"The case shows insurers seeking an early coverage ruling on a state environmental claim over a former dry-cleaning tenant's contamination at a shopping center. Its outcome turns on how the policies' pollution exclusions and prior-knowledge terms apply to contamination that predates the current owner.","tags":["environmental","PCE contamination","insurance coverage","dry cleaner","shopping center"],"hasFull":true},{"id":"live-019","addedDate":"2026-08-12","title":"United States and Montana v. Columbia Falls Aluminum Co. (CFAC Superfund Consent Decree, $57.6M Estimated Cleanup)","brief":"Columbia Falls Aluminum Company agreed in a consent decree to perform Superfund cleanup EPA estimates at $57.6 million and repay $1.8 million in past costs at its former Montana smelter site; the court entered it Nov. 12, 2026.","category":"environmental","status":"settled","date":"2026-07-02","jurisdiction":"U.S. District Court for the District of Montana","parties":[{"name":"United States of America","role":"Plaintiff"},{"name":"State of Montana","role":"Plaintiff"},{"name":"Columbia Falls Aluminum Company, LLC","role":"Defendant"}],"judge":"William W. Mercer","amountUsd":57600000,"amountBasis":"settlement","state":"MT","amount":"Cleanup work estimated at $57,634,528, plus $1.8M in past EPA response costs","source":"live","sourceUrl":"https://www.epa.gov/newsreleases/columbia-falls-aluminum-corporation-llc-agrees-57-million-cleanup-former-smelter-site","summary":"The United States and the State of Montana sued Columbia Falls Aluminum Company, LLC (CFAC) in federal court in Montana on July 2, 2026 and lodged a proposed consent decree the same day under which CFAC will carry out the cleanup EPA selected for its former aluminum smelter site near Columbia Falls, work EPA estimates at $57,634,528, and reimburse EPA $1.8 million in past response costs, according to the Justice Department's Federal Register notice. The cleanup addresses arsenic, cyanide, fluoride and PAH contamination. The court entered the consent judgment on November 12, 2026.","significance":"The decree puts the cost of carrying out EPA's January 2025 cleanup plan on the site's corporate successor rather than on public funds, with EPA and Montana regulators overseeing the work. It is a reminder that Superfund liability for a former industrial site can reach an owner or a successor to past owners and operators long after operations end.","tags":["environmental","CERCLA","superfund","industrial site","montana"],"docketUrl":"https://www.courtlistener.com/docket/73568530/united-states-of-america-v-columbia-falls-aluminum-company-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-022","addedDate":"2026-08-15","title":"RealPage, Inc. v. James (First Amendment Challenge to New York's Algorithmic Rent-Pricing Law)","brief":"A federal judge blocked enforcement of the part of New York's law that bars landlords from setting rents on coordinating software's advice, finding RealPage \"marginally\" likely to win, and denied dismissal.","category":"landlord-tenant","status":"ruling","date":"2026-09-29","jurisdiction":"U.S. District Court, S.D.N.Y.","parties":[{"name":"RealPage, Inc.","role":"Plaintiff"},{"name":"New York State Attorney General (Letitia James, in her official capacity)","role":"Defendant"}],"judge":"Valerie Elaine Caproni","amountUsd":null,"state":"NY","amount":"Preliminary injunction sought; no damages claimed","source":"live","sourceUrl":"https://www.law360.com/real-estate-authority/articles/2513580/ny-ag-says-2nd-circ-ruling-doesn-t-back-pricing-law-case","summary":"On September 29, 2026, U.S. District Judge Valerie E. Caproni preliminarily enjoined New York's attorney general from enforcing Section 3 of the state's algorithmic rent-pricing law, which bars residential landlords from setting rents or lease terms based on recommendations from software that performs a \"coordinating function,\" and denied the state's motion to dismiss. Calling it a close call, she found RealPage, Inc. \"marginally\" likely to succeed on its First Amendment claim. She held that Section 2, which bars facilitating agreements among competing landlords not to compete, regulates conduct rather than protected speech. The attorney general has asked the court to reconsider.","significance":"The order is an early ruling on whether software-generated rent recommendations are protected commercial speech, a question that bears on other state and local limits on algorithmic pricing tools used by apartment owners. The injunction covers only the provision aimed at landlords, not the law's separate ban on facilitating agreements among competing landlords.","tags":["algorithmic pricing","realpage","first amendment","landlord-tenant","new york"],"docketUrl":"https://www.courtlistener.com/docket/71964352/realpage-inc-v-james/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-023","addedDate":"2026-08-15","title":"U.S. Bank Receivership Suit Over Republic Plaza, Denver's Tallest Tower","brief":"U.S. Bank, on behalf of lenders, asked Denver District Court to appoint a receiver for Republic Plaza, Denver's 56-story tallest tower, after a March 2026 loan default, the Denver Gazette reported.","category":"lending-foreclosure","status":"pending","date":"2026-08-10","jurisdiction":"Denver District Court, Colorado","parties":[{"name":"U.S. Bank National Association","role":"Plaintiff (on behalf of lenders)"},{"name":"Brookfield Properties (BGRE)","role":"Owner/Manager"},{"name":"MetLife Investment Management","role":"Co-owner"},{"name":"Trigild","role":"Receiver"}],"judge":null,"amountUsd":null,"amountBasis":"loan","state":"CO","amount":"Defaulted loan reported at about $130M (Denver Business Journal) and $230.1M (Morningstar Credit); property appraised at $136.0M","source":"live","sourceUrl":"https://www.denvergazette.com/2026/08/14/downtown-denvers-tallest-building-faces-receivership-after-loan-default/","summary":"U.S. Bank National Association, on behalf of lenders, filed a complaint in Denver District Court on August 10, 2026 seeking a receiver for Republic Plaza, the 56-story tower at 370 17th St. that is Denver's tallest building, after a loan default in March, the Denver Gazette reported. The building is owned and managed by Brookfield Properties, recently rebranded as BGRE, and co-owned by MetLife Investment Management. Trigild has since been appointed receiver, Connect CRE reported, citing Morningstar Credit and the Denver Business Journal.","significance":"Republic Plaza narrowly avoided foreclosure in 2023, and the new filing shows that deal did not resolve the loan. Receivership puts a court-appointed manager in charge of the property while the default plays out, and the receiver reportedly plans a sale in 2027.","tags":["receivership","cmbs","office","loan default","denver"],"hasFull":true},{"id":"live-024","addedDate":"2026-08-16","title":"U.S. Bank v. Brightline Investment Holdings, LLC (MiamiCentral Station Retail Foreclosure)","brief":"U.S. Bank, acting for its lenders, sued to foreclose on the 124,000 square feet of retail at Brightline's MiamiCentral station over a $65 million senior loan, alleging missed principal and interest payments.","category":"lending-foreclosure","status":"filed","date":"2026-08-05","jurisdiction":"Miami-Dade County Circuit Court","parties":[{"name":"U.S. Bank","role":"Plaintiff (for two lender groups)"},{"name":"XYQ Cayman Ltd.","role":"Senior lender"},{"name":"Brightline Investment Holdings","role":"Defendant/Borrower"},{"name":"FECI Realty","role":"Defendant (property manager)"}],"judge":null,"amountUsd":65000000,"amountBasis":"loan","state":"FL","amount":"$65M senior loan (part of a $128.5M 2022 loan)","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/08/05/brightlines-miami-retail-hit-with-65-million-foreclosure/","summary":"U.S. Bank, representing two lender groups, has sued Brightline Investment Holdings, one of its subsidiaries and property manager FECI Realty to foreclose on the 124,000 square feet of retail at MiamiCentral station, 600 Northwest First Avenue in Miami, The Real Deal reported, citing the South Florida Business Journal. The suit alleges the borrower missed a $16 million principal payment due Dec. 26, 2025, a $6 million payment due March 15, 2026, and quarterly interest payments starting in December 2025, and says the full $65 million senior loan is now due. It asks for foreclosure, enforcement of guarantees from Brightline Investment Holdings and its subsidiary, and a court-appointed receiver.","significance":"The suit reaches only the senior piece of a split loan on the station's retail space, leaving the rail operation, the office buildings and the junior debt outside the case. Junior lenders and tenants in similar transit-oriented projects should know where they sit in the debt stack, because the senior lender can push for foreclosure and a receiver over the retail space on its own.","tags":["foreclosure","receivership","transit-oriented development","retail","bifurcated loan"],"hasFull":true},{"id":"live-026","addedDate":"2026-08-17","title":"Acres Loan Origination LLC v. DMG Investments Affiliate (Auden Buffalo Student Housing Foreclosure)","brief":"Acres Loan Origination sued to foreclose on the Auden Buffalo student housing community in Amherst, NY, alleging $32.5 million in 2021 construction loans to a DMG Investments affiliate matured unpaid.","category":"lending-foreclosure","status":"filed","date":"2026-08-13","jurisdiction":"Erie County Supreme Court, New York","parties":[{"name":"Acres Loan Origination LLC","role":"Plaintiff"}],"judge":null,"amountUsd":32500000,"amountBasis":"loan","state":"NY","amount":"$32.5M in construction loans (Auden Buffalo)","source":"live","sourceUrl":"https://www.connectcre.com/stories/return-to-lender-week-of-august-13-2026/","summary":"Acres Loan Origination LLC, an affiliate of commercial mortgage lender Acres Capital, filed a foreclosure complaint in New York state Supreme Court against the Auden Buffalo student housing community at 2915-2949 N. Forest Road in Amherst, Buffalo Business First reported, according to Connect CRE's August 13, 2026 roundup. Acres says it made two loans totaling $32.5 million in early 2021 to build the property, and that the loan matured in January 2024 with the entire principal unpaid. The defendant is an affiliate of New York City developer DMG Investments, which days earlier faced a separate foreclosure filing by a lender group represented by Deutsche Bank National Trust Co. over the Air Buffalo apartment building at 1265 Sweet Home Rd., also owned by a DMG affiliate.","significance":"The Auden Buffalo complaint is the second foreclosure action within days against a DMG affiliate's Amherst apartment property, brought by a different lender. Acres describes a maturity default: construction debt that came due in January 2024 and, it says, remained entirely unpaid.","tags":["foreclosure","construction loan","student housing","multifamily","loan maturity default"],"hasFull":true},{"id":"live-028","addedDate":"2026-08-18","title":"PSEG Renewable Transmission LLC v. Arentz Family, LP (Piedmont Line Pre-Condemnation Survey Entry)","brief":"The Fourth Circuit upheld an injunction letting PSEG Renewable Transmission survey landowners' property for the 67-mile Maryland Piedmont power line before state approval; 60 landowners have petitioned the Supreme Court.","category":"eminent-domain","status":"appeal","date":"2026-08-06","jurisdiction":"U.S. Court of Appeals for the Fourth Circuit","parties":[{"name":"PSEG Renewable Transmission LLC","role":"Plaintiff-Appellee"},{"name":"Arentz Family, LP","role":"Defendant-Appellant"},{"name":"Barney's Farm, LLC","role":"Defendant-Appellant"},{"name":"HZ Properties, LLC","role":"Defendant-Appellant"},{"name":"M & R, LLC","role":"Defendant-Appellant"},{"name":"The Dug Hill Rod and Gun Club, Inc.","role":"Defendant-Appellant"},{"name":"Troyer Farms, LLC","role":"Defendant-Appellant"},{"name":"Troyer Real Estate, LLC","role":"Defendant-Appellant"},{"name":"Dells Generation Farms, LLC","role":"Defendant"},{"name":"Groves Mill, LLC","role":"Defendant"},{"name":"Panora Acres, Inc.","role":"Defendant"},{"name":"Peter and John Radio Fellowship, Inc.","role":"Defendant"},{"name":"RBC Real Estate I, LLC","role":"Defendant"},{"name":"School of Living","role":"Defendant"}],"judge":"Nicole G. Berner","amountUsd":null,"state":"MD","amount":"117 landowner-appellants; 67-mile transmission project","source":"live","sourceUrl":"https://marylandmatters.org/2026/08/06/piedmont-power-line-surveys-4th-circuit/","summary":"In a published August 6, 2026 opinion by Judge Nicole G. Berner, the Fourth Circuit affirmed a June 2025 preliminary injunction letting PSEG Renewable Transmission LLC enter properties along the proposed 67-mile Maryland Piedmont Reliability Project to conduct surveys over owners' objections, Maryland Matters reported. The 117 appellants argued PSEG could not use Maryland's survey-entry statute before receiving a certificate from the Public Service Commission; the panel held PSEG likely qualifies as a body 'having the power of eminent domain' under the statute. On November 4, 2026, 60 landowners petitioned the U.S. Supreme Court to review the decision.","significance":"The decision lets a company selected to build a transmission line use Maryland's survey-entry statute before the state has approved the project, on the reasoning that the surveys are needed to obtain that approval. Owners along proposed utility corridors in Maryland will find it harder to block pre-approval survey access, though the ruling does not authorize construction or any taking of land.","tags":["eminent domain","utility easement","right of entry","transmission line","takings"],"docketUrl":"https://www.courtlistener.com/docket/70689952/pseg-renewable-transmission-llc-v-arentz-family-lp/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-029","addedDate":"2026-08-19","title":"Via Mizner Owner III LLC v. Via Mizner Lender 1 LLC (Mandarin Oriental Boca Raton Lender-Liability Suit)","brief":"Penn-Florida affiliates sued their Mandarin Oriental Boca Raton lender, an affiliate of Madison Realty Capital, for more than $500 million, alleging it \"created the defaults\"; a New York judge temporarily blocked a UCC auction.","category":"lending-foreclosure","status":"filed","date":"2026-08-13","jurisdiction":"Supreme Court of the State of New York","parties":[{"name":"Via Mizner Owner III LLC","role":"Plaintiff"},{"name":"Via Mizner Pledgor III LLC","role":"Plaintiff"},{"name":"Via Mizner Lender 1 LLC","role":"Defendant"},{"name":"Via Mizner Lender 2 LLC","role":"Defendant"}],"amountUsd":500000000,"amountBasis":"damages sought","judge":"Andrew Borrok","state":"NY","amount":"$500M+ damages sought","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/08/17/mandarin-oriental-boca-raton-developer-sues-lender-madison/","summary":"Two Penn-Florida Companies affiliates, Via Mizner Owner III LLC and Via Mizner Pledgor III LLC, sued their lender, a Madison Realty Capital affiliate, through the entities Via Mizner Lender 1 and Via Mizner Lender 2 LLC, in New York state court on Aug. 13, 2026, seeking more than $500 million. They allege Madison \"created the defaults\" it is using to foreclose on the stalled Mandarin Oriental-branded hotel and condo project in Boca Raton. On Aug. 17, Justice Andrew Borrok temporarily blocked a scheduled UCC foreclosure auction and set a hearing for Oct. 1, The Real Deal reported. Madison did not immediately respond to a request for comment.","significance":"The developer answered a fast UCC sale of its pledged ownership interests by suing the lender in New York, apart from the Florida mortgage foreclosure, and won a temporary pause. Lenders who take both a mortgage and an equity pledge should expect a borrower to fight on both fronts, and borrowers facing a UCC auction should know a court may hold it while claims about the lender's conduct are heard.","tags":["lender liability","UCC foreclosure","construction loan","equity pledge","condo default"],"hasFull":true},{"id":"live-031","addedDate":"2026-08-20","title":"U.S. Bank National Association v. Lenox Drive Office Park LLC (Princeton Pike Corporate Center Foreclosure)","brief":"U.S. Bank, as trustee for a 2016 CMBS trust, sued to foreclose on the Lenox Drive office park in Mercer County, N.J., saying a $130M loan matured unpaid, and asked for a receiver, Mortgage Professional America reported.","category":"lending-foreclosure","status":"filed","date":"2026-08-12","jurisdiction":"U.S. District Court, District of New Jersey","parties":[{"name":"US Bank National Association as Trustee for Morgan Stanley Bank of America Merrill Lynch Trust 2016-C28, Commercial Mortgage Pass-Through Certificates, Series 2016-C28","role":"Plaintiff"},{"name":"Lenox Drive Office Park LLC","role":"Defendant"}],"judge":null,"amountUsd":130000000,"amountBasis":"loan","state":"NJ","amount":"$130M loan balance; matured unpaid January 1, 2026","source":"live","sourceUrl":"https://www.mpamag.com/us/specialty/commercial/cmbs-trust-moves-to-foreclose-on-office-park-over-130-million-loan/586071","summary":"U.S. Bank National Association, as trustee for the Morgan Stanley Bank of America Merrill Lynch Trust 2016-C28, sued Lenox Drive Office Park LLC on August 12, 2026 in the U.S. District Court for the District of New Jersey, Mortgage Professional America reported. The trust says a $130 million loan made in December 2015 matured on January 1, 2026 without being repaid and that $141,767,219.75 was owed as of July 1, 2026. It seeks foreclosure and sale of the Lenox Drive office buildings and a receiver to run the property and conduct the sale.","significance":"The suit is a maturity default: the trust's claim is that a ten-year CMBS office loan came due and was not repaid. The docket shows a clerk's entry of default in October 2026 and a receivership filing in November.","tags":["cmbs","foreclosure","receivership","office","maturity default"],"docketUrl":"https://www.courtlistener.com/docket/74638795/us-bank-national-association-as-trustee-for-morgan-stanley-bank-of-america/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-035","addedDate":"2026-08-22","title":"9 New York Ave LLC v. Jones Lang LaSalle Americas, Inc. (Pinnacle Apartments, Washington, D.C., NOI Projection Fraud Suit)","brief":"A developer and the owner of the 115-unit Pinnacle apartments in Washington, D.C. sued JLL for about $12.4 million, alleging it inflated income projections to clear a lender's debt-yield test; JLL did not comment.","category":"lending-foreclosure","status":"filed","date":"2026-08-21","jurisdiction":"Circuit Court of Cook County, Illinois","parties":[{"name":"9 New York Ave LLC","role":"Plaintiff"},{"name":"Jones Lang LaSalle Americas Inc.","role":"Defendant"}],"judge":null,"amountUsd":12400000,"amountBasis":"damages sought","state":"IL","amount":"About $12.4 million sought, per Bisnow (more than $12 million, per Law360)","source":"live","sourceUrl":"https://www.law360.com/real-estate-authority/residential/articles/2515929/jll-hit-with-developer-s-12m-fraud-suit-over-dc-project","summary":"A developer and property owner 9 New York Ave LLC sued Jones Lang LaSalle Americas, Inc. in Cook County, Illinois in August 2026, alleging JLL fraudulently inflated its projections of stabilized net operating income for the Pinnacle, a 14-story, 115-unit apartment building at 7 New York Ave. NE in Washington, D.C., Law360 and Bisnow reported. According to Bisnow, the suit alleges JLL raised its projection in successive versions until it cleared the 8.5% minimum debt yield JLL said construction lenders would require, implying a $51 million stabilized value; the building sold in April 2026 for $30.5 million. The suit seeks about $12.4 million on claims including fraud and breach of fiduciary duty, and JLL did not respond to Bisnow's requests for comment.","significance":"The suit tests whether an adviser's income projections, prepared while a project was seeking construction financing, can support fraud and fiduciary-duty claims rather than an ordinary dispute over a forecast that missed. The allegations are untested, and JLL has not publicly responded.","tags":["broker fraud","NOI projections","debt yield","construction lending","multifamily"],"propertyType":"Multifamily","hasFull":true},{"id":"live-036","addedDate":"2026-08-22","title":"Wilmington Trust v. Rubenstein Partners (312 Elm Street Office Tower Foreclosure, Cincinnati)","brief":"Rubenstein Partners admitted defaulting on the $46.1M note on 312 Elm St., a Cincinnati office tower, in Wilmington Trust's 2024 foreclosure; the tower was later set for a June 2026 sheriff's sale.","category":"lending-foreclosure","status":"ruling","date":"2024-08-12","jurisdiction":"Hamilton County Court of Common Pleas, Ohio","parties":[{"name":"Wilmington Trust","role":"Plaintiff/Lender"},{"name":"Rubenstein Partners","role":"Defendant/Borrower"}],"judge":"Lisa Allen","amountUsd":39600000,"amountBasis":"loan","state":"OH","amount":"$39.6M sought on 312 Elm St.'s $46.1M note; companion suit sought $16.2M on 312 Plum St.'s $18.4M loan","source":"live","sourceUrl":"https://www.colliers.com/en/news/cincinnati/receiver-appointed-for-prominent-downtown-office-building-facing-foreclosure","summary":"Wilmington Trust sued Philadelphia-based Rubenstein Partners on June 7, 2024 to foreclose on the 312 Elm St. office tower in downtown Cincinnati, claiming $39.6 million in principal, interest, late charges and fees on a $46.1 million note from 2015, the Cincinnati Business Courier reported. Rubenstein's August 12, 2024 answer admitted every allegation, including the default, after Hamilton County Common Pleas Judge Lisa Allen appointed a Colliers executive as receiver on July 30, 2024. In May 2026 the Business Courier reported that the foreclosure cases over 312 Elm and Rubenstein's nearby 312 Plum St. tower were resolved and both buildings were listed for a sheriff's auction starting June 17, 2026.","significance":"The Elm Street case moved from filing to a court-appointed receiver and an admitted default in about two months, and the same lender later sued the same owner over a second tower bought the same day in 2015. The Business Courier said the sheriff's sales would likely see both buildings revert to their lenders.","tags":["foreclosure","office","receivership","loan default","cincinnati"],"hasFull":true},{"id":"live-037","addedDate":"2026-08-23","title":"BNK 2018-BNK13 LLC 10 East 34th Street LLC v. 10East34th, LLC (10 East 34th Street CMBS Foreclosure)","brief":"The lender on a $37.5 million CMBS mortgage sued in federal court to foreclose on 10 East 34th Street, a 55,000-square-foot Midtown office building, and to have a receiver appointed.","category":"lending-foreclosure","status":"filed","date":"2026-08-14","jurisdiction":"U.S. District Court for the Southern District of New York","parties":[{"name":"BNK 2018-BNK13 LLC 10 East 34th Street LLC","role":"Plaintiff"},{"name":"10East34th, LLC","role":"Defendant"},{"name":"New York City Environmental Control Board","role":"Defendant"}],"judge":"Ronnie Abrams","amountUsd":37500000,"amountBasis":"loan","state":"NY","amount":"$37.5M mortgage; lender also seeks appointment of a receiver","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/08/18/lender-sues-to-foreclose-on-midtown-office-building/","docketUrl":"https://www.courtlistener.com/docket/74650685/bnk-2018-bnk13-llc-10-east-34th-street-llc-v-10east34th-llc/","docketLabel":"CourtListener docket","summary":"The lender on a $37.5 million mortgage securitized in the BANK 2018-BNK13 CMBS trust sued 10East34th, LLC in the Southern District of New York on August 14, 2026, to foreclose on 10 East 34th Street, a 10-story, 55,000-square-foot Midtown office building, and to have a receiver appointed. The complaint alleges the owner stopped making monthly payments on April 1, 2026, and that servicer Trimont's May 6 letter demanding more than $500,000 for the April and May payments went unpaid, The Real Deal reported. In October the parties submitted a proposed consent order on the appointment of a receiver.","significance":"Shows how fast a CMBS loan on a lightly leased Manhattan office building can move from missed payments to a foreclosure complaint that asks for a receiver at the outset. When most of a building's space has gone dark, the lender's case for taking control of the property is easier to make early, and a consent order on a receiver can come within weeks of filing.","tags":["foreclosure","CMBS","office","receivership","loan default"],"hasFull":true},{"id":"live-038","addedDate":"2026-08-23","title":"UMB Bank, N.A. v. Public Finance Authority (Delray Beach Proton Therapy Center Leasehold Foreclosure)","brief":"UMB Bank, as bond trustee, filed an $81.32 million leasehold foreclosure suit over the South Florida Proton Therapy Institute at Delray Medical Center, the South Florida Business Journal reported.","category":"lending-foreclosure","status":"filed","date":"2026-07-13","jurisdiction":"Fifteenth Judicial Circuit Court, Palm Beach County, Florida","parties":[{"name":"UMB Bank N.A.","role":"Plaintiff (bond trustee)"},{"name":"Public Finance Authority","role":"Defendant"},{"name":"Tenet Healthcare Corp.","role":"Defendant (named as possible interest holder; not a guarantor)"},{"name":"Proton International LLC","role":"Defendant (named as possible interest holder; not a guarantor)"},{"name":"Varian Medical Systems","role":"Defendant (named as possible interest holder; not a guarantor)"}],"judge":null,"amountUsd":81320000,"amountBasis":"loan","state":"FL","amount":"$81.32M foreclosure suit (bond debt), per the South Florida Business Journal","source":"live","sourceUrl":"https://www.bondbuyer.com/news/umb-sues-pfa-and-managers-of-defaulted-proton-center","summary":"UMB Bank, as trustee for investors in two bond funds, filed a leasehold foreclosure lawsuit on July 13, 2026 against Public Finance Authority, the Wisconsin-based conduit issuer that issued bonds to finance the South Florida Proton Therapy Institute at Delray Medical Center, according to the South Florida Business Journal as summarized by Connect CRE. The $81.32 million suit seeks receivership and foreclosure of the property, The Bond Buyer reported. It also names Tenet Healthcare Corp., Proton International LLC and Varian Medical Systems as parties that may claim an interest in the center, while stating they are not guarantors.","significance":"Because the suit forecloses a leasehold interest, parties that may hold interests in the facility are brought into the case even though the complaint says none of them guarantees the debt. The receivership request would put the property under a court-appointed manager while the foreclosure proceeds.","tags":["lending-foreclosure","conduit bonds","healthcare real estate","receivership","municipal finance"],"hasFull":true},{"id":"live-039","addedDate":"2026-08-24","title":"148 State Street Owner v. City of Boston (Commercial Assessment \"Add-Back Policy\" Retaliation Class Action)","brief":"A legal group suing Boston for 148 State Street's owner says city data shows 182 assessment increases on 150 commercial properties after tax appeals, with about $19 million disputed.","category":"zoning-land-use","status":"ruling","date":"2026-05-11","jurisdiction":"Massachusetts Superior Court, Suffolk County (Business Litigation Session)","parties":[{"name":"HS 148SST LLC","role":"Plaintiff"},{"name":"City of Boston","role":"Defendant"}],"amountUsd":null,"judge":"Peter B. Krupp","state":"MA","amount":"~$19M in disputed additional taxes across 150 properties (182 instances)","source":"live","sourceUrl":"https://bankerandtradesman.com/boston-increased-assessments-on-150-properties-after-appeals/","summary":"The Pioneer New England Legal Foundation, which represents the owner of 148 State St. in a class action against the City of Boston, said on August 18, 2026 that data the city provided shows assessments rose on 150 commercial properties, in 182 instances, after owners appealed to the state Appellate Tax Board, Banker & Tradesman reported. The foundation puts the disputed payments at about $19 million. Suffolk Superior Court Judge Peter B. Krupp let the case proceed in May, writing that the alleged Add-Back Policy \"plausibly chills all commercial property owners from exercising their right to seek an abatement.\" City officials have said they \"stabilized\" the values of properties with open appeals at prior-year levels.","significance":"The case tests whether raising assessments on owners who appeal can be challenged as retaliation for petitioning, separate from the abatement process itself. If the city-provided figures hold up, the dispute is much larger than the roughly 60 properties first estimated.","tags":["property tax","assessment retaliation","first amendment","class action","commercial office"],"hasFull":true},{"id":"live-040","addedDate":"2026-08-24","title":"Borough of Seaside Park v. Shree Jyoti, LLC (Eminent Domain Ordinance Public-Use Disclosure Ruling)","brief":"New Jersey's Supreme Court ruled 6-1 that Seaside Park did not have to state its intended public use in the ordinance authorizing the taking of the Desert Palm Inn motel.","category":"eminent-domain","status":"ruling","date":"2026-08-10","jurisdiction":"Supreme Court of New Jersey","parties":[{"name":"Borough of Seaside Park","role":"Plaintiff-Respondent"},{"name":"Shree Jyoti, LLC","role":"Defendant-Appellant"}],"amountUsd":null,"judge":"Michael Noriega","state":"NJ","amount":"Condemnation of a motel property; no compensation figure at issue in this ruling","source":"live","sourceUrl":"https://newjerseymonitor.com/2026/08/10/nj-supreme-court-seaside-park-eminent-domain/","summary":"In a 6-1 decision on August 10, 2026, the New Jersey Supreme Court held that neither the state's Eminent Domain Act nor its Local Lands and Buildings Law requires a municipality to state its intended public use in the ordinance authorizing a taking, resolving Seaside Park's effort to acquire the Desert Palm Inn, a motel owned by Shree Jyoti, LLC, the New Jersey Monitor reported. Justice Michael Noriega wrote for the majority. Justice John Hoffman dissented, saying he would have blocked the acquisition because the borough declined to disclose its known plans for the property when the owner asked.","significance":"The ruling removes a textual challenge to condemnation ordinances that recite only a general public purpose. The majority still faulted the borough's lack of candor, and the dissent shows the 'square corners' duty of government fair dealing remains a possible line of attack for owners.","tags":["eminent domain","condemnation","new jersey","local government","square corners doctrine"],"hasFull":true},{"id":"live-041","addedDate":"2026-08-25","title":"100 Norfolk Street Realty Trust v. Chen's Food Enterprise, Inc. (Summary Process Refiling Not Barred by Claim Preclusion)","brief":"The Massachusetts Appeals Court held a commercial landlord's second summary process suit against Chen's Food Enterprise was not barred by claim preclusion, reversing the Appellate Division and remanding.","category":"lease-disputes","status":"ruling","date":"2026-08-24","jurisdiction":"Massachusetts Appeals Court","parties":[{"name":"100 Norfolk Street Realty Trust (through its trustee)","role":"Landlord/Plaintiff"},{"name":"Chen's Food Enterprise, Inc.","role":"Tenant/Defendant"}],"amountUsd":198000,"amountBasis":"judgment","judge":"Sookyoung Shin","state":"MA","amount":"$198,000 trial-court award plus interest and costs; Appellate Division review of the tenant's remaining arguments pending","source":"live","sourceUrl":"https://www.mass.gov/doc/eng-v-chens-food-enterprise-inc-ac-s25p1222/download","summary":"The Massachusetts Appeals Court on August 24, 2026 reversed a Boston Municipal Court Appellate Division ruling that had thrown out a commercial landlord's $198,000 trial win against its warehouse tenant, Chen's Food Enterprise, Inc., on claim-preclusion grounds. The landlord's first summary process case had been dismissed because it did not prove it sent the notice of termination the lease required. Writing for the panel, Justice Shin held that G. L. c. 239, § 7, which says a summary process judgment is not a bar to a later action to recover the premises, authorized the second case. The court sent the matter back to the Appellate Division to decide the tenant's remaining appeal arguments.","significance":"The court held that the summary process statute, not Mass. R. Civ. P. 41(b)(3), controls whether a dismissed summary process case bars a new one, so a dismissal that does not say it is without prejudice still does not bar a later action for possession and damages. It noted that issue preclusion still prevents relitigating issues actually decided.","tags":["commercial lease","summary process","claim preclusion","landlord-tenant","massachusetts"],"propertyType":"Industrial","hasFull":true},{"id":"live-045","addedDate":"2026-08-27","title":"Wells Fargo Bank, N.A. v. Workspace Property Trust Affiliates (Multistate CMBS Foreclosure on $1.28B Suburban Office Portfolio)","brief":"Wells Fargo, as trustee for a CMBS trust, filed foreclosure suits in multiple states in August 2026 over a $1.28B loan backing Workspace Property Trust's four-state office and industrial portfolio, Bisnow reported.","category":"lending-foreclosure","status":"filed","date":"2026-08-24","jurisdiction":"Hennepin County District Court, Minnesota, and other state courts; earlier action in Maricopa County, Arizona","parties":[{"name":"Wells Fargo Bank","role":"Plaintiff (CMBS trustee)"},{"name":"Workspace Property Trust","role":"Borrower"},{"name":"KeyBank National Association","role":"Special Servicer"}],"judge":null,"amountUsd":1230000000,"amountBasis":"loan","amount":"$1.23B unpaid principal, plus accrued interest, special servicer fees, and attorneys' fees, on a $1.28B original CMBS loan","source":"live","sourceUrl":"https://www.bisnow.com/news/national/capital-markets/wells-fargo-moves-to-foreclose-workspace-property-trust-portfolio","summary":"Wells Fargo Bank, representing the CMBS trust that holds a $1.28 billion loan to Workspace Property Trust, filed foreclosure lawsuits in multiple states in August 2026, Bisnow reported. A suit in Hennepin County, Minnesota puts the unpaid principal at about $1.23 billion plus interest, special servicer fees and attorney expenses. The 2018 loan, backed by a portfolio now of 143 office and industrial properties in Arizona, Florida, Minnesota and Pennsylvania, went to special servicing in May 2023, and Trigild was appointed receiver for the whole portfolio after a September 2025 Arizona suit. Workspace Property Trust declined to comment.","significance":"The loan is one of the largest CMBS loans in special servicing, and the filings move it from a receivership into foreclosure in several states at once. Morningstar Credit values the collateral at $1.24 billion, about the size of the unpaid balance and down from $1.63 billion at issuance.","tags":["CMBS","foreclosure","special servicing","receivership","office distress"],"hasFull":true},{"id":"live-046","addedDate":"2026-08-27","title":"Lakes at Marshall Ridge HOA v. Town of Westlake (Circle T Data Center Notice Challenge)","brief":"A Texas judge's Aug. 17 TRO barred Westlake from voting on an agreement for the Circle T Data Center after a neighboring HOA alleged defective notice; the order lapsed in September.","category":"zoning-land-use","status":"pending","date":"2026-08-17","jurisdiction":"342nd District Court, Tarrant County, Texas","parties":[{"name":"The Lakes at Marshall Ridge Homeowners Association, Inc.","role":"Plaintiff"},{"name":"Town of Westlake","role":"Defendant"},{"name":"City of Keller","role":"Sought temporary injunction against Westlake; settled with developer"},{"name":"Circle T Owner LP","role":"Developer entity; settled with Keller"}],"amountUsd":null,"judge":"Kimberly Fitzpatrick","state":"TX","amount":"Not a damages claim; TRO sought to block a town vote on a development agreement for a 1.1M-SF data center campus","source":"live","sourceUrl":"https://dallasexpress.com/metroplex/judge-signs-tro-blocking-westlake-data-center-vote/","summary":"Judge Kimberly Fitzpatrick of Tarrant County's 342nd District Court signed a temporary restraining order on Aug. 17, 2026 barring the Town of Westlake, Texas from voting on or implementing Resolution 26-25, a proposed development agreement for the 1.1-million-square-foot Circle T Data Center, in a suit by the Lakes at Marshall Ridge Homeowners Association and two residents alleging the town failed to give legally required notice of earlier zoning action, The Dallas Express reported. The judge struck broader proposed restrictions on permits and site work. The order expired Sept. 25 without extension, Fox 4 reported, and the City of Keller, which had sought its own injunction, signed a settlement with developer entity Circle T Owner LP on Nov. 5.","significance":"The case shows how a neighbor's notice challenge can delay a town vote on a large data center agreement even where the town says the use is already allowed by existing zoning. Here the temporary order was narrow and short-lived, and the neighboring city's dispute ended in a negotiated settlement over noise, screening and emergency-response funding.","tags":["data center","zoning notice","TRO","development agreement","texas"],"hasFull":true},{"id":"live-047","addedDate":"2026-08-28","title":"Access Point Financial Hotel Loan Guaranty Appeal (Eve-of-Foreclosure Bankruptcy Filing Triggers Full Recourse)","brief":"The Eleventh Circuit upheld a $3,954,244.04 guaranty judgment on a $56.33 million hotel loan, holding the borrower's eve-of-foreclosure Chapter 11 filing was a full-recourse event.","category":"lending-foreclosure","status":"ruling","date":"2026-08-26","jurisdiction":"U.S. Court of Appeals for the Eleventh Circuit (on appeal from the U.S. District Court for the Northern District of Georgia)","parties":[{"name":"Access Point Financial, LLC","role":"Plaintiff-Appellee"}],"judge":null,"amountUsd":3954244.04,"amountBasis":"judgment","state":"TX","amount":"$3,954,244.04 judgment (deficiency on a $56.33 million loan)","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/08/26/access_point_financial_llc_v._charles_everhardt.pdf","summary":"The Eleventh Circuit on August 26, 2026 affirmed a Northern District of Georgia judgment holding the guarantor of a $56.33 million Access Point Financial loan on three Texas properties personally liable for $3,954,244.04, the balance left after foreclosure sales. The day before a scheduled foreclosure, the Houston borrower's membership interests were transferred without the lender's consent and the borrower, under new management, filed a Chapter 11 petition. The unpublished opinion held that the filing alone was a full-recourse event, rejecting the guarantor's argument that the new owner had no authority to file it.","significance":"The ruling applies the guaranty as written: where a borrower's voluntary bankruptcy petition triggers full recourse, an argument that new owners filed it without authority did not avoid liability. The opinion is unpublished and does not bind later Eleventh Circuit panels.","tags":["hotel finance","guaranty","bad boy carve-out","bankruptcy","recourse liability"],"docketUrl":"https://www.courtlistener.com/docket/74701388/access-point-financial-llc-v-charles-everhardt/","docketLabel":"CourtListener docket (11th Cir. appeal)","hasFull":true},{"id":"live-048","addedDate":"2026-08-28","title":"Held Properties, Inc. v. WealthStone, LLC (Century City Office Rent Default and Personal Guaranty Suit)","brief":"Held Properties, owner of 1880 Century Park East in Los Angeles, sued office tenant WealthStone and its guarantor for about $1.1 million, including an earlier $393,000 award and $708,000 more it says is owed.","category":"lease-disputes","status":"filed","date":"2026-08-13","jurisdiction":"Los Angeles County Superior Court","parties":[{"name":"Held Properties","role":"Plaintiff/Landlord"},{"name":"WealthStone","role":"Defendant/Tenant"}],"judge":null,"amountUsd":1100000,"amountBasis":"damages sought","state":"CA","amount":"~$1.1M sought (a prior $393K judgment plus $708K in additional claimed unpaid rent)","source":"live","sourceUrl":"https://therealdeal.com/la/2026/08/13/held-properties-sues-tenant-in-century-city/","summary":"Held Properties, the family-owned landlord of the 1880 Century Park East office tower in Century City, sued tenant WealthStone and its guarantor, Andres Szita, in an early August 2026 complaint seeking about $1.1 million in unpaid rent and other charges, The Real Deal reported. The total combines $393,000 the landlord was awarded in an earlier suit against WealthStone with another $708,000 it says it is owed. Neither Robert Held, Held Properties' CEO, nor Szita responded to requests for comment.","significance":"The landlord is pursuing the lease guarantor as well as the tenant, for a total that includes an amount already awarded in an earlier case. A personal guaranty can leave a principal exposed to everything a tenant owes, so landlords should get one from tenants without much credit history, and principals should track the lease they back.","tags":["personal guaranty","commercial lease","rent default","office","century city"],"hasFull":true},{"id":"live-049","addedDate":"2026-08-29","title":"Emerald Necklace Conservancy v. City of Boston (White Stadium $325M Redevelopment Standing Ruling)","brief":"Massachusetts' highest court ruled that White Stadium's parcel is not protected parkland and that opponents lack standing to enforce the trust that owns it, letting Boston's $325 million rebuild continue.","category":"zoning-land-use","status":"ruling","date":"2026-08-19","jurisdiction":"Massachusetts Supreme Judicial Court","parties":[{"name":"Emerald Necklace Conservancy, Inc.","role":"Plaintiff"},{"name":"City of Boston","role":"Defendant"},{"name":"Trustees of the George Robert White Fund","role":"Defendant"},{"name":"Boston public schools","role":"Defendant"},{"name":"parks and recreation department of Boston","role":"Defendant"},{"name":"Boston Unity Soccer Partners LLC","role":"Defendant"},{"name":"Boston Unity Stadco LLC","role":"Defendant"}],"amountUsd":null,"state":"MA","amount":"$325M public-private redevelopment ($135M city funding, $190M from Boston Legacy FC ownership group)","source":"live","sourceUrl":"https://www.wbur.org/news/2026/08/19/sjc-white-stadium-wu-boston","summary":"The Massachusetts Supreme Judicial Court ruled on Aug. 19, 2026 that Boston can continue rebuilding White Stadium in Franklin Park, a $325 million public-private project with National Women's Soccer League team Boston Legacy FC, WBUR reported. In an opinion by Justice Gabrielle R. Wolohojian, the court held that the Emerald Necklace Conservancy and 20 individual plaintiffs lack standing to enforce the terms of the George Robert White Fund, the charitable trust that owns the stadium, and that 1947 and 1950 legislation removed the parcel from parkland status before Article 97 was ratified in 1972. The ruling affirms a Superior Court judgment for the defendants.","significance":"The decision limits who may enforce the terms of a public charitable trust when the Attorney General declines to act, and it makes a parcel's legislative history, not its current recreational use, decisive for Article 97 protection. Both points bear on development of trust-held or formerly park-designated public land in Massachusetts.","judge":"Gabrielle R. Wolohojian","tags":["standing","charitable trust","Article 97","eminent domain","public-private partnership"],"hasFull":true},{"id":"live-050","addedDate":"2026-08-29","title":"Worldwide Plaza Foreclosure Receivership (825 Eighth Avenue, Manhattan)","brief":"Cushman & Wakefield replaced SL Green as manager of Worldwide Plaza under receiver Hilco Global as a $940 million CMBS foreclosure proceeds, Bisnow reported.","category":"lending-foreclosure","status":"pending","date":"2026-07-01","jurisdiction":"Supreme Court of the State of New York, New York County","parties":[{"name":"Wilmington Trust, National Association","role":"Plaintiff"},{"name":"WWP Office, LLC","role":"Defendant"}],"amountUsd":940000000,"amountBasis":"loan","state":"NY","amount":"$940M senior mortgage; bondholders could lose up to $488M (Bloomberg, as cited by Bisnow)","source":"live","sourceUrl":"https://www.bisnow.com/news/new-york/office/worldwide-plaza-foreclosure-receivership-sl-green-rxr-extell-cmbs","summary":"A judge approved moving management of Worldwide Plaza, the 49-story office tower at 825 Eighth Ave., away from SL Green by July 1, and Cushman & Wakefield has replaced it under court-appointed receiver Hilco Global, Bisnow reported, citing court filings. Hilco was appointed in March in a foreclosure suit over the $940 million senior mortgage, now pursued by Wilmington Trust for CMBS bondholders after Goldman Sachs and Deutsche Bank were removed as plaintiffs. Separately, Extell Development is pursuing a UCC foreclosure on the property's mezzanine debt, which owners SL Green and RXR are contesting on appeal.","significance":"The case shows lenders at different levels of the capital stack pursuing separate remedies against one building: a receivership and judicial foreclosure by the senior lender and a UCC foreclosure by a mezzanine holder. The receiver has already replaced the owners' property manager before any sale.","judge":null,"tags":["CMBS foreclosure","receivership","mezzanine debt","UCC sale","office"],"hasFull":true},{"id":"live-051","addedDate":"2026-08-30","title":"Centre Square Receivership Sale Order (1500 Market Street, Philadelphia)","brief":"A federal judge approved and directed the $70 million receivership sale of Centre Square, Philadelphia's largest office complex, to affiliates of Dean Adler and PMC Property Group, Bisnow reported.","category":"lending-foreclosure","status":"appeal","date":"2026-08-17","jurisdiction":"U.S. District Court, Eastern District of Pennsylvania","parties":[{"name":"Wells Fargo Bank, National Association, as Trustee for the benefit of registered holders of J.P. Morgan Chase Commercial Mortgage Securities Trust 2020-MKST","role":"Plaintiff"},{"name":"NG 1500 Market St. LLC","role":"Defendant"},{"name":"CBRE, Inc.","role":"Receiver"},{"name":"Universal Group Company Inc.","role":"Proposed intervenor (rival bidder); appellant"}],"amountUsd":70000000,"amountBasis":"purchase price","state":"PA","amount":"$70M court-approved sale (21% of the 2017 purchase price); $390M 2019 loan from JPMorgan Chase","source":"live","sourceUrl":"https://www.bisnow.com/news/philadelphia/office/centre-square-sale-court-ruling","summary":"On Aug. 17, 2026, U.S. District Judge Nitza I. Quiñones Alejandro approved and directed the $70 million sale of Centre Square, the 2.2-million-square-foot two-tower office complex at 1500 Market St., to affiliates of Dean Adler and PMC Property Group ahead of an Oct. 16 deadline, Bisnow reported, citing the Philadelphia Business Journal. The buyers had tried to get out of the deal despite a $5 million nonrefundable deposit, and rival bidder Universal Group Co. has appealed. The sale comes in a CMBS foreclosure that Wells Fargo, as trustee, filed in January 2023.","significance":"The court approved the receiver's sale even though the winning buyer had tried to exit and a rival bidder said it had offered more. Universal Group's pending appeal to the Third Circuit means the order is still under challenge.","judge":"Nitza I. Quiñones Alejandro","tags":["CMBS foreclosure","receivership","office","receivership sale","federal court order"],"docketUrl":"https://www.courtlistener.com/docket/66730007/wells-fargo-bank-national-association-as-trusteefor-the-benefit-of/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-052","addedDate":"2026-08-30","title":"Wilmington Trust v. SPNA-Linked Borrowers (137-Unit Chicago Condo Foreclosure)","brief":"Wilmington Trust sued in Cook County to foreclose on 137 condo units in seven Chicago towers held by entities tied to Strategic Properties of North America, seeking nearly $51 million on two credit lines.","category":"lending-foreclosure","status":"filed","date":"2026-08-27","jurisdiction":"Circuit Court of Cook County, Illinois","parties":[{"name":"Wilmington Trust National Association","role":"Plaintiff"}],"judge":null,"amountUsd":51000000,"amountBasis":"loan","state":"IL","amount":"~$51M sought in principal and accrued interest (excluding late charges, fees, costs) on $85M combined revolving credit lines","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/08/27/condo-buyout-specialist-yitzy-klor-hit-by-big-chicago-foreclosures/","summary":"Wilmington Trust National Association, as trustee for the Redwood Trust subsidiary that holds the debt, sued in Cook County Circuit Court to foreclose on 137 condominium units in seven Chicago buildings and their rents. The Real Deal, which obtained the filing, reported that the suit seeks nearly $51 million in principal and accrued interest drawn on two revolving credit lines totaling $85 million, originated by CoreVest and extended in November 2021 and January 2023. The borrowers are two entities for which Yitzy Klor, head of Strategic Properties of North America (SPNA), is the registered agent, and Klor personally backs the debt. Klor did not immediately respond to The Real Deal's request for comment.","significance":"Lenders that finance a sponsor's piecemeal purchase of condo units are betting on a future building-wide buyout that unit owners can block. When those buyouts stall, the collateral is scattered units in occupied buildings rather than a stabilized rental property, and that is a different credit. Condo boards weighing a bulk offer, and lenders backing these strategies, should plan for the vote failing.","tags":["foreclosure","condo deconversion","personal guaranty","revolving credit","cook county"],"hasFull":true},{"id":"live-053","addedDate":"2026-08-31","title":"500-512 Seventh Avenue Foreclosure Judgment (Midtown Office Buildings Ordered Sold Over $356M Debt)","brief":"A New York judge ordered 500 and 512 Seventh Avenue in Midtown sold at a foreclosure auction to satisfy a $356 million debt; the borrower agreed not to oppose.","category":"lending-foreclosure","status":"ruling","date":"2026-08-24","jurisdiction":"Supreme Court of the State of New York, New York County","parties":[{"name":"500-512 Seventh Avenue Limited Partnership","role":"Defendant (Borrower)"}],"judge":null,"amountUsd":356000000,"amountBasis":"judgment","state":"NY","amount":"$356M debt in foreclosure judgment; $375M loan (2018)","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/08/24/chetrit-moinian-minskoffs-midtown-tower-faces-foreclosure/","summary":"A New York Supreme Court judge has ordered the Midtown office buildings at 500 and 512 Seventh Avenue sold at a foreclosure auction to satisfy a $356 million debt, The Real Deal reported. The borrower, 500-512 Seventh Avenue Limited Partnership, is a partnership of brothers Meyer and Joseph Chetrit, Joseph Moinian and Edward Minskoff; it took out $375 million against the property in 2018 and agreed not to oppose the foreclosure motion. The lender, which sued in July 2025, alleges self-dealing, including the Chetrit Group's failure to pay rent on its own offices in No. 512.","significance":"Unpaid rent from an owner's own affiliate is one of the clearest things a lender can point to when it alleges self-dealing, and here it became a central part of the foreclosure record. Owners that lease space in their own buildings to related companies should keep that rent current and documented, because lenders read lapses as diverting the property's income.","tags":["foreclosure","non-recourse carve-out","personal guaranty","self-dealing","manhattan office"],"hasFull":true},{"id":"live-054","addedDate":"2026-08-31","title":"The Retail Property Trust v. Nassau County Dept. of Assessment (Roosevelt Field $4.8M Reporting-Fine Appeal)","brief":"The Second Circuit upheld Nassau County's $4.8 million fine on Roosevelt Field's Simon-affiliated owner for skipping two years of income and expense filings, holding businesses can invoke the Excessive Fines Clause but this fine was not excessive.","category":"zoning-land-use","status":"ruling","date":"2026-08-06","jurisdiction":"U.S. Court of Appeals for the Second Circuit","parties":[{"name":"The Retail Property Trust","role":"Plaintiff-Appellant"},{"name":"Nassau County Department of Assessment","role":"Defendant-Appellee"},{"name":"The Nassau County Legislature","role":"Defendant-Appellee"},{"name":"The County of Nassau","role":"Defendant-Appellee"}],"judge":"Richard J. Sullivan","amountUsd":4800000,"amountBasis":"other","state":"NY","amount":"$4.8M cumulative fine for two years of non-compliance","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/08/06/the_retail_property_trust_v._nassau_cnty._dept_of_assessment.pdf","summary":"The Second Circuit on August 6, 2026 affirmed summary judgment for Nassau County in a challenge by The Retail Property Trust, which owns the Roosevelt Field mall in Garden City, to a $4.8 million fine for not filing Annual Statements of Income and Expense for 2013 and 2014. Writing for the panel, Judge Richard J. Sullivan held that the Eighth Amendment's Excessive Fines Clause protects business entities but that the fine, a fraction of one percent of the property's value, was not grossly disproportional. Judge Richard C. Wesley concurred, writing that the court did not need to decide whether the clause covers businesses.","significance":"The ruling makes it Second Circuit precedent that trusts and corporations can invoke the Excessive Fines Clause, while upholding a penalty scaled to a commercial property's market value. Nassau County owners who fail to file income and expense statements face fines of 0.25% to 0.75% of market value, and the court held that an Article 78 proceeding is adequate process to contest one.","tags":["excessive fines clause","property tax reporting","shopping mall","second circuit","simon property group"],"docketUrl":"https://www.courtlistener.com/opinion/10940797/the-retail-property-trust-v-nassau-cnty-dept-of-assessment/","docketLabel":"CourtListener opinion","hasFull":true},{"id":"live-055","addedDate":"2026-08-31","title":"Atlanta City Council Approves Eminent Domain Plan for Azalea Gardens and Magnolia Park Apartments","brief":"Atlanta's City Council unanimously approved a measure to acquire the Azalea Gardens and Magnolia Park apartments by eminent domain for affordable housing. Azalea's owner says it already plans to redevelop, Bisnow reported.","category":"eminent-domain","status":"pending","date":"2025-08-18","jurisdiction":"Atlanta City Council","parties":[{"name":"TYTA LLC","role":"Property Owner"},{"name":"John Eagan Homes I and II LP","role":"Property Owner"}],"judge":null,"amountUsd":null,"state":"GA","amount":"Resolution covering a 92-unit and a 300-unit apartment complex; acquisition cost not reported","source":"live","sourceUrl":"https://www.bisnow.com/news/atlanta/affordable-housing/atlanta-council-approves-eminent-domain-against-two-apartments-130626","summary":"The Atlanta City Council on August 18, 2025 unanimously approved a resolution to acquire the Magnolia Park and Azalea Gardens apartment complexes on the city's Westside through eminent domain and redevelop them as affordable housing through a public-private partnership, Bisnow reported. The city has 60 days to draft a plan covering the acquisition timeline, financing, redevelopment and tenant relocation. A manager at TYTA LLC, Azalea Gardens' owner, told Bisnow the company plans to ask the city to hold off because it is already planning to demolish the now-vacant complex for its own affordable housing project.","significance":"The resolution is a first step; no condemnation case had been filed when Bisnow reported it. The council also approved a separate measure directing staff to list multifamily properties with long-running blight for acquisition, which could put other apartment owners on the same path.","tags":["eminent domain","blight","affordable housing","apartment complex","atlanta"],"hasFull":true},{"id":"live-056","addedDate":"2026-08-31","title":"Harbor Custom Development Chapter 11 — Pacific Ridge Apartments Credit Bid (Sound Capital NW)","brief":"In Harbor Custom Development's Chapter 11, lender Sound Capital NW took the 80-unit Pacific Ridge Apartments in Tacoma with a $5 million credit bid against a roughly $20.3 million loan balance.","category":"lending-foreclosure","status":"settled","date":"2024-08-21","jurisdiction":"U.S. Bankruptcy Court, Western District of Washington","parties":[{"name":"Harbor Custom Development, Inc.","role":"Debtor"},{"name":"Pacific Ridge CMS LLC","role":"Debtor (member case)"},{"name":"Sound Capital NW Holdings LLC","role":"Lender"},{"name":"Sound Capital Construction Fund, LLC","role":"Lender"}],"judge":"Mary Jo Heston","amountUsd":20300000,"amountBasis":"loan","state":"WA","amount":"$5M credit bid against a construction loan with an approximately $20.3M outstanding balance","source":"live","sourceUrl":"https://www.aol.com/bankrupt-tacoma-developer-apartment-property-120000775.html","summary":"In Harbor Custom Development's Chapter 11 case, lender Sound Capital NW Holdings LLC took possession of Pacific Ridge Apartments, an 80-unit Tacoma complex completed in 2022, through a $5 million credit bid on August 21, 2024, The News Tribune reported. Court filings put the construction loan balance at about $20.3 million as of June 2024, and Pierce County assessed the property at more than $17.5 million. The company's second amended plan provided that the related lien would be extinguished and the loan deemed satisfied.","significance":"The transfer is a data point on construction-loan recoveries in a developer's Chapter 11 wind-down: a $5 million credit bid against a roughly $20.3 million balance on a completed complex. The plan treated the loan as satisfied through the property transfer.","tags":["Chapter 11","credit bid","construction loan","multifamily","bankruptcy"],"docketUrl":"https://www.courtlistener.com/docket/68078274/harbor-custom-development-inc-lead-case-consolidated-w-member-cases/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-057","addedDate":"2026-08-31","title":"Charlotte Hawkins LLC v. Bar One Lounge South End LLC (Linea Tower Ground-Floor Lease Default)","brief":"A landlord entity tied to Portman Holdings, owner of Charlotte's Linea tower, sued Bar One Lounge South End and its owners, alleging default on a 10-year lease for about 2,400 square feet of space.","category":"lease-disputes","status":"filed","date":"2025-04-01","jurisdiction":"Mecklenburg County Superior Court, North Carolina","parties":[{"name":"Charlotte Hawkins LLC","role":"Plaintiff (Landlord)"},{"name":"Bar One Lounge South End LLC","role":"Defendant (Tenant)"}],"judge":null,"amountUsd":null,"state":"NC","amount":"10-year, ~2,400-SF ground-floor lease; damages not specified in available reporting","source":"live","sourceUrl":"https://www.yahoo.com/news/south-end-landlord-sues-bar-132443957.html","summary":"Charlotte Hawkins LLC, which the Charlotte Business Journal describes as tied to Atlanta-based Portman Holdings, owner of the Linea apartment tower in South End, sued Bar One Lounge South End LLC and its owners in Mecklenburg County Superior Court. The suit alleges they defaulted on a 10-year lease for a nearly 2,400-square-foot space. The Business Journal reported the case in April 2025.","significance":"The case concerns a ground-floor restaurant lease for a planned location whose future, the Business Journal reported, is undetermined. The amount the landlord seeks was not reported.","tags":["lease default","restaurant tenant","ground-floor retail","South End","Charlotte"],"hasFull":true},{"id":"live-058","addedDate":"2026-08-31","title":"Oakworth Capital Bank v. RC Nashville Development Partners (Ritz-Carlton Nashville Foreclosure)","brief":"Oakworth Capital Bank sued the developer of a planned Ritz-Carlton tower in Nashville over a $10 million loan; the site later sold at foreclosure for $35 million and the court entered judgments for the bank.","category":"lending-foreclosure","status":"ruling","date":"2023-10-28","jurisdiction":"U.S. District Court, Middle District of Tennessee (No. 3:23-cv-01145); foreclosure sale at Metro Nashville Courthouse","parties":[{"name":"Oakworth Capital Bank","role":"Plaintiff"},{"name":"RC Nashville Development Partners, LLC","role":"Defendant"}],"judge":"Eli Jeremy Richardson","amountUsd":10470772.9,"amountBasis":"damages sought","state":"TN","amount":"$10,470,772.90 sought in the underlying suit; property sold at foreclosure auction for $35M","source":"live","sourceUrl":"https://www.nashvillepost.com/business/development/ritz-carlton-project-faces-financing-snag-as-bank-sues-developer/article_d56330b6-7809-11ee-ad3a-67466a6e47ad.html","summary":"Oakworth Capital Bank sued RC Nashville Development Partners, LLC and its principal in the Middle District of Tennessee on October 28, 2023, seeking $10,470,772.90 plus interest on a $10 million loan tied to a planned Ritz-Carlton hotel and condominium tower in Nashville's SoBro area, the Nashville Post reported. The 1.2-acre site at 727 Korean Veterans Boulevard sold at a foreclosure auction on April 11, 2024 to R Squared Properties LLC for $35 million, the Tennessean reported. The court later entered summary judgment against the principal and a default judgment against RC Nashville, and closed the case in August 2025.","significance":"The case moved from a matured, unpaid loan to a foreclosure sale of the site within about six months of the suit. The developer said in court filings that the property's value would make the bank whole.","tags":["Ritz-Carlton","loan default","foreclosure auction","hospitality development","Nashville"],"docketUrl":"https://www.courtlistener.com/docket/67940311/oakworth-capital-bank-v-rc-nashville-development-partners-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-062","addedDate":"2026-09-01","title":"United States, et al. v. LivCor, LLC (RealPage Algorithmic Pricing Antitrust Consent Judgment)","brief":"Blackstone-affiliated landlord LivCor will pay $7 million and stop using rivals' non-public data to set rents, settling DOJ and nine-state RealPage antitrust claims. It admitted no wrongdoing.","category":"landlord-tenant","status":"settled","date":"2026-06-26","jurisdiction":"U.S. District Court, Middle District of North Carolina","parties":[{"name":"United States of America","role":"Plaintiff"},{"name":"State of California","role":"Plaintiff"},{"name":"State of Colorado","role":"Plaintiff"},{"name":"State of Connecticut","role":"Plaintiff"},{"name":"State of Minnesota","role":"Plaintiff"},{"name":"State of North Carolina","role":"Plaintiff"},{"name":"State of Oregon","role":"Plaintiff"},{"name":"State of Tennessee","role":"Plaintiff"},{"name":"State of Illinois","role":"Plaintiff"},{"name":"Commonwealth of Massachusetts","role":"Plaintiff"},{"name":"LivCor, LLC","role":"Defendant"}],"amountUsd":7000000,"amountBasis":"settlement","state":"NC","amount":"$7M multistate settlement; LivCor controls ~3,500 apartment units in North Carolina","source":"live","sourceUrl":"https://abc11.com/post/attorney-general-jeff-jackson-announces-7m-settlement-major-nc-apartment-landlord-livcor/19325116/","documentUrl":"https://storage.courtlistener.com/recap/gov.uscourts.ncmd.99417/gov.uscourts.ncmd.99417.199.0.pdf","documentLabel":"Read the states' Final Consent Judgment (June 26, 2026)","summary":"U.S. District Judge William L. Osteen Jr. of the Middle District of North Carolina entered a final judgment between the Justice Department and LivCor, LLC on May 19, 2026, and a consent judgment between LivCor and nine states on June 26, 2026. Both resolve claims that the Blackstone-affiliated landlord used RealPage software and rivals' data to set apartment rents. North Carolina Attorney General Jeff Jackson announced the $7 million state settlement on June 18, ABC11 reported; LivCor agreed to stop using other landlords' non-public data to set rents and admitted no wrongdoing. The case continues against RealPage and other defendants, whose motions to dismiss the judge denied on September 30, 2026.","significance":"The LivCor resolution pairs a payment with limits on how the landlord sets rents, following earlier settlements by Greystar and Cortland that North Carolina's attorney general cited. It narrows the case to RealPage and the landlords that have not fully resolved the claims.","judge":"William Lindsay Osteen Jr.","tags":["algorithmic pricing","RealPage","antitrust","multistate settlement","consent decree"],"docketUrl":"https://www.courtlistener.com/docket/69074245/united-states-of-america-v-realpage-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-063","addedDate":"2026-09-01","title":"J. Safra Real Estate v. Sugar Factory (Faneuil Hall Marketplace Unpaid Rent Suit)","brief":"Faneuil Hall Marketplace owner J. Safra Real Estate sued Sugar Factory for more than $930,000 in unpaid rent, interest and fees, one of seven tenant suits totaling over $2 million, Bisnow reported.","category":"lease-disputes","status":"filed","date":"2026-07-10","jurisdiction":"Suffolk County Superior Court, Massachusetts","parties":[{"name":"J. Safra Real Estate","role":"Landlord (Plaintiff)"},{"name":"Sugar Factory","role":"Tenant (Defendant)"}],"judge":null,"amountUsd":930000,"amountBasis":"damages sought","state":"MA","amount":"~$930K sought from Sugar Factory; over $2M across seven tenant suits","source":"live","sourceUrl":"https://www.bisnow.com/news/boston/retail/faneuil-hall-landlord-j-safra-group-sues-tenants-over-2m-in-unpaid-rent","summary":"J. Safra Real Estate, which acquired the ground lease for Boston's Faneuil Hall Marketplace in 2024, sued candy and restaurant franchise Sugar Factory on July 10, 2026 for more than $930,000 in unpaid rent, interest and attorney's fees, Bisnow reported, citing filings first reported by the Boston Business Journal. It is one of seven suits J. Safra filed against current and former tenants between 2024 and July 2026, seeking more than $2 million in all. J. Safra told Bisnow it does not comment on litigation; FoMu, another tenant sued, denies owing back rent.","significance":"The suits show a new ground lessee pursuing rent claims under leases signed with the prior owner, Ashkenazy Acquisition Corp. J. Safra says it is also carrying out an improvement plan and has raised ground-floor retail occupancy to 93% from 76% in 2024.","tags":["commercial lease","unpaid rent","retail","faneuil hall","lease default"],"hasFull":true},{"id":"live-064","addedDate":"2026-09-01","title":"C.D. Smith Construction, Inc. v. The Edison Project LLC (Milwaukee Mass-Timber Tower Lien Foreclosure)","brief":"A Milwaukee County judge entered an $11.3 million default judgment for contractor C.D. Smith against two Neutral entities behind the stalled Edison tower, advancing its lien foreclosure, Urban Milwaukee reported.","category":"lending-foreclosure","status":"ruling","date":"2026-06-29","jurisdiction":"Milwaukee County Circuit Court","parties":[{"name":"C.D. Smith Construction, Inc.","role":"Plaintiff"},{"name":"The Edison Project LLC","role":"Defendant"},{"name":"The Edison SPE, LLC","role":"Defendant"},{"name":"Neutral","role":"Developer"}],"amountUsd":11301705,"amountBasis":"judgment","state":"WI","amount":"$11,301,704.63 default money judgment, plus costs and attorneys' fees","source":"live","sourceUrl":"https://www.enr.com/articles/63313-contractor-wins-113m-judgment-in-milwaukee-timber-tower-lawsuit","summary":"Milwaukee County Circuit Judge Glenn H. Yamahiro signed an order on June 29, 2026 granting general contractor C.D. Smith Construction a default money judgment of $11,301,704.63 against The Edison Project LLC and The Edison SPE, LLC, entities of developer Neutral, over unpaid work on the stalled Edison tower in downtown Milwaukee. The default followed Neutral's failure to file a legally valid response; the court struck a filing by Neutral's CEO, who is not an attorney, asking that the dispute go to mediation or arbitration, Urban Milwaukee reported. A written foreclosure order is still needed before the site can be sold.","significance":"The judgment moves the contractor closer to forcing a sale of the site under its construction lien. It also shows that a filing made for a company by a non-lawyer executive can be struck, leaving the claim effectively uncontested.","judge":"Glenn H. Yamahiro","tags":["construction lien","foreclosure","mass timber","default judgment","wisconsin"],"hasFull":true},{"id":"live-065","addedDate":"2026-09-02","title":"In re Palmer Center Foreclosure — Wells Fargo Tower & FirstBank Building (Colorado Springs Public Trustee Foreclosure)","brief":"Foreclosure notices were filed over a roughly $59 million unpaid loan balance on Colorado Springs' two tallest buildings, the Wells Fargo Tower and FirstBank Building at Palmer Center.","category":"lending-foreclosure","status":"filed","date":"2026-08-25","jurisdiction":"El Paso County Public Trustee, Colorado (non-judicial foreclosure)","parties":[{"name":"RPalmer LLC","role":"Owner"},{"name":"Overland Palmer LLC","role":"Owner"},{"name":"Palmer Center Owner LLC","role":"Owner"},{"name":"DPalmer LLC","role":"Owner"}],"judge":null,"amountUsd":59000000,"amountBasis":"loan","state":"CO","amount":"~$59M unpaid principal balance on an original $74M loan","source":"live","sourceUrl":"https://gazette.com/2026/08/25/colorado-springs-tallest-most-prominent-buildings-fall-into-foreclosure/","summary":"El Paso County Public Trustee's Office records show a foreclosure notice filed against RPalmer LLC, Overland Palmer LLC and Palmer Center Owner LLC, Delaware companies controlled by real estate firms with principal offices in California and Canada, The Gazette reported on August 25, 2026. The owners have an unpaid principal balance of about $59 million on a $74 million loan now held by a trustee for Bank of America, and a foreclosure auction was scheduled for October 21. The filings cover the Wells Fargo Tower and FirstBank Building at Palmer Center, the city's two tallest buildings, and several business-suite properties; the adjacent Antlers hotel is not in foreclosure.","significance":"The filing puts the two most prominent office buildings in downtown Colorado Springs into Colorado's non-judicial public trustee foreclosure process. The Gazette reported that it was unclear what led to the default, while a longtime local developer it quoted tied the foreclosures to wider office-market conditions.","tags":["foreclosure","office","public trustee","colorado springs","loan default"],"hasFull":true},{"id":"live-066","addedDate":"2026-09-02","title":"SITC Inc. v. Sarasota County (Live Local Act Zoning-Preemption Dispute)","brief":"Sitc Inc. sued Sarasota County and its commissioners over a 540-unit Live Local Act project, one of four suits after the county excluded two zoning districts from the law, Business Observer reported.","category":"zoning-land-use","status":"pending","date":"2026-05-20","jurisdiction":"Twelfth Judicial Circuit Court, Sarasota County, Florida","parties":[{"name":"Sitc Inc.","role":"Plaintiff"},{"name":"Sarasota County","role":"Defendant"}],"amountUsd":null,"state":"FL","amount":"540-unit Sitc project; more than 4,000 apartments proposed across the four suits","source":"live","sourceUrl":"https://www.businessobserverfl.com/news/2026/sep/02/sarasota-county-live-local-lawsuits/","summary":"Sitc Inc. sued Sarasota County and its five commissioners on May 20, 2026, after the commission voted unanimously on April 7 that Florida's Live Local Act does not apply to the county's Open Use and Residential Estate One zoning districts, halting Sitc's 540-unit apartment application, the Business Observer reported. It is one of four suits by developers whose Live Local projects together proposed more than 4,000 apartments; the county has moved to dismiss all four. A non-jury trial in the Sitc case is set for Aug. 23, 2027.","significance":"The suits test whether a county can exclude zoning districts from the Live Local Act by interpretation, a course the county attorney warned in an April 3 memo would be an \"uphill battle.\" Two of the suits also name commissioners personally, which led the commission to cap the legal fees it will reimburse.","judge":null,"tags":["zoning","live local act","affordable housing","land use","florida"],"hasFull":true},{"id":"live-068","addedDate":"2026-09-03","title":"RCA Trade Center, Inc. v. Neighboring Unit Owners (Hawaii Anti-SLAPP Dismissal Affirmed)","brief":"Hawaii's appeals court affirmed the 2024 anti-SLAPP dismissal of RCA Trade Center's suit against neighboring unit owners whose letter to agencies questioned its Marconi Point warehouses.","category":"zoning-land-use","status":"ruling","date":"2026-06-23","jurisdiction":"Hawaii Intermediate Court of Appeals","parties":[{"name":"RCA Trade Center, Inc.","role":"Plaintiff-Appellant"},{"name":"MP Unit 21, LLC","role":"Plaintiff-Appellant"}],"judge":"Sonja M.P. McCullen","amountUsd":null,"state":"HI","amount":"Attorney fees and costs awarded to defendants","source":"live","sourceUrl":"https://www.forbes.com/sites/jayadkisson/2026/07/23/hawaii-real-estate-developer-pounded-by-the-uniform-public-expression-protection-act-in-hu/","summary":"On June 23, 2026, the Hawaii Intermediate Court of Appeals affirmed a May 2024 circuit court order dismissing a suit by RCA Trade Center, Inc. and MP Unit 21, LLC against two owners of a unit in the Marconi Point Condominiums, an agricultural condominium project in Kahuku, Oahu. The suit, filed in October 2023, targeted a letter the owners sent to RCA and government agencies questioning eight warehouses RCA built on its units; the circuit court dismissed it under the Hawaii Public Expression Protection Act, the state's version of the uniform anti-SLAPP law. The appeals court held the late motion was properly allowed for good cause and that RCA waived its challenge to the fee award.","significance":"The published opinion confirms that a letter to regulators questioning a developer's zoning and permit compliance can be protected expression under Hawaii's statute. A developer that sues over such a letter risks dismissal and paying the other side's fees.","tags":["anti-slapp","upepa","zoning","agricultural land use","hawaii"],"hasFull":true},{"id":"live-071","addedDate":"2026-09-03","title":"Wells Fargo Bank, N.A. v. 181 West Madison Property LLC ($240M Loan Foreclosure on Chicago Loop Office Tower)","brief":"Wells Fargo sued in federal court to foreclose on a $240 million loan on 181 West Madison, a 50-story Loop office tower; the court appointed a receiver after the borrower did not respond.","category":"lending-foreclosure","status":"pending","date":"2026-03-27","jurisdiction":"U.S. District Court, Northern District of Illinois (Eastern Division)","parties":[{"name":"Wells Fargo Bank, N.A.","role":"Plaintiff"},{"name":"181 West Madison Property LLC","role":"Defendant"}],"judge":"Robert W. Gettleman","amountUsd":240000000,"amountBasis":"loan","state":"IL","amount":"$240 million loan; more than $223 million due, per the receivership motion as reported","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/04/19/inside-situs-big-loop-office-foreclosure-lawsuit/","summary":"Wells Fargo Bank, N.A. sued 181 West Madison Property LLC in federal court in Chicago on March 27, 2026 to foreclose on the $240 million loan on the 50-story Loop office tower, and on April 3 moved to have Hilco Real Estate's Matthew Mason appointed receiver. The Real Deal reported that the loan's special servicer, Situs, is behind the suit, and that the default followed anchor tenant Northern Trust's shrinking its space from 400,000 to 225,000 square feet. The borrower did not respond or appear, and the court appointed Mason receiver on April 24 and entered a default against the borrower on June 14.","significance":"A single large tenant shrinking its lease can cut an office building's income enough to stop debt payments, even when the building looks stable. Here the borrower did not contest the receivership, and a receiver took control within a month of the motion. That shows how quickly an owner can lose control of operations once a lender files.","tags":["foreclosure","receivership","special servicer","chicago office","cmbs"],"docketUrl":"https://www.courtlistener.com/docket/73105372/wells-fargo-bank-na-v-181-west-madison-property-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-073","addedDate":"2026-09-04","title":"Kentucky Industrial Alliance LLC v. City of Cave City (Data Center Moratorium and Annexation Challenge)","brief":"Kentucky Industrial Alliance's consolidated suits challenge Cave City's 12-month data-center moratorium; the court will first decide whether the developer's land was ever validly annexed.","category":"zoning-land-use","status":"pending","date":"2026-08-24","jurisdiction":"Barren Circuit Court, Kentucky (43rd Judicial Circuit)","parties":[{"name":"Kentucky Industrial Alliance LLC","role":"Plaintiff"},{"name":"City of Cave City","role":"Defendant"},{"name":"Cave City Council","role":"Defendant"},{"name":"Joint City-County Planning Commission of Barren County","role":"Defendant"}],"amountUsd":null,"state":"KY","amount":"Declaratory and injunctive relief sought (non-monetary)","source":"live","sourceUrl":"https://bgdailynews.com/2026/08/27/barren-data-center-suits-proceed/","summary":"Kentucky Industrial Alliance LLC's two June 2026 lawsuits, one over Cave City's 12-month moratorium on data centers and one over the city's annexation of the company's land, will be consolidated, the Bowling Green Daily News reported after an August 24, 2026 hearing in Barren Circuit Court. Judge John T. Alexander will decide first whether the land was validly annexed, since the moratorium would not apply if it was not. Cave City has moved to dismiss the moratorium suit as based on an incomplete application, and it argues the company lacks standing to challenge the annexation.","significance":"The case puts two recurring data-center questions before a Kentucky court: whether an application filed before a moratorium is judged under the old rules, and whether an annexation defect takes a site outside a city's zoning reach. The annexation question could decide the case before the vested-rights argument is reached.","judge":"John T. Alexander","tags":["zoning","data center","moratorium","vested rights","kentucky"],"hasFull":true},{"id":"live-076","addedDate":"2026-09-05","title":"Rialto Capital Advisors v. Jenel ($17.7M Loop Retail Foreclosure, 36 South State Street)","brief":"Rialto Capital Advisors, as special servicer, sued in Cook County to foreclose on a nearly 19,000-square-foot Loop retail property at 36 South State Street after a maturity default, claiming $17.7 million.","category":"lending-foreclosure","status":"filed","date":"2026-03-31","jurisdiction":"Circuit Court of Cook County, Illinois","parties":[{"name":"Rialto Capital Advisors","role":"Plaintiff (special servicer for a securitized loan trust)"}],"judge":null,"amountUsd":17700000,"amountBasis":"claim","state":"IL","amount":"$17.7M claimed (default interest and fees on ~$16.8M principal)","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/04/01/rialto-files-loop-retail-foreclosure-lawsuit-against-jenel/","summary":"Rialto Capital Advisors, acting as special servicer for a securitized mortgage loan trust, filed a foreclosure complaint in Cook County on March 31, 2026 against New York landlord Jenel over the nearly 19,000-square-foot retail property at 36 South State Street. The complaint alleges the loan, a $16.8 million balance Jenel took on when it bought the property from Thor Equities for $26 million in 2018, went unpaid when it matured last June; Rialto claims $17.7 million including default interest and liquidation fees. The Real Deal reported that a hearing was set for Sept. 28.","significance":"A fully leased retail building that covers its debt payments can still end up in foreclosure if its value falls and the owner cannot pay off the loan when it comes due. Owners with loans maturing on downtown retail should start refinancing talks early and plan for a lower appraisal, not just today's rent.","tags":["cmbs foreclosure","special servicer","retail condo","loan maturity default","chicago"],"hasFull":true},{"id":"live-078","addedDate":"2026-09-05","title":"Neighbors' Noise Nuisance Class Action Against PrimeBlock Operations, LLC (Murphy, N.C. Data Center Remand Fight)","brief":"Neighbors' proposed class action alleges unremitting noise from a crypto-mining and AI data center in Murphy, North Carolina; after a defendant removed it to federal court, they moved on August 31, 2026 to remand.","category":"environmental","status":"pending","date":"2026-08-31","jurisdiction":"U.S. District Court, Western District of North Carolina","parties":[{"name":"PrimeBlock Operations, LLC","role":"Defendant"},{"name":"PrimeBlock Mining LLC","role":"Defendant"},{"name":"Exponential Digital LLC","role":"Defendant"},{"name":"Exponential Digital Murphy, LLC","role":"Defendant"},{"name":"Innotech Z, Inc.","role":"Defendant"}],"judge":"Martin Reidinger","amountUsd":null,"state":"NC","amount":"Proposed class of nearly 1,000 nearby property owners; damages unspecified","source":"live","sourceUrl":"https://www.law360.com/real-estate-authority/residential/articles/2520088","summary":"Two Cherokee County, North Carolina residents filed a proposed class action on July 7, 2026 in Cherokee County Superior Court against PrimeBlock Operations, LLC, PrimeBlock Mining LLC, Exponential Digital LLC, Exponential Digital Murphy, LLC and Innotech Z, Inc. They allege that a cryptocurrency-mining and AI data center at 3125 Harshaw Road in Murphy has produced excessive, unremitting noise since about September 2021. Innotech Z removed the case to the U.S. District Court for the Western District of North Carolina on August 7, and the plaintiffs moved on August 31 to send it back to state court, Law360 reported. The motion is fully briefed.","significance":"The suit shows neighbors of a crypto-mining and data center site turning years of noise complaints into a proposed class action seeking damages and an injunction. The remand motion will decide whether a state or federal court hears the claims.","tags":["data center","nuisance","class action","remand","north carolina"],"docketUrl":"https://www.courtlistener.com/docket/73738334/stines-v-primeblock-operations-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-080","addedDate":"2026-09-06","title":"Transportation Consultants, Inc. v. Certain Underwriters at Lloyd's, London (Louisiana Surplus Lines Arbitration Ruling)","brief":"The Fifth Circuit held a Louisiana surplus lines property policy's arbitration clause unenforceable against its nine domestic insurers, and sent back whether their court case should pause while two foreign insurers arbitrate.","category":"environmental","status":"ruling","date":"2026-09-03","jurisdiction":"U.S. Court of Appeals for the Fifth Circuit","parties":[{"name":"Transportation Consultants, Incorporated, doing business as TCI Trucking","role":"Plaintiff-Appellee"},{"name":"Certain Underwriters at Lloyd's, London, Severally subscribing to Certificate No. AMR-36854-07","role":"Defendant-Appellant"},{"name":"Indian Harbor Insurance Company","role":"Defendant-Appellant"},{"name":"QBE Specialty Insurance Company","role":"Defendant-Appellant"},{"name":"Steadfast Insurance Company","role":"Defendant-Appellant"},{"name":"General Security Indemnity Company of Arizona","role":"Defendant-Appellant"},{"name":"United Specialty Insurance Company","role":"Defendant-Appellant"},{"name":"Lexington Insurance Company","role":"Defendant-Appellant"},{"name":"HDI Global Specialty SE","role":"Defendant-Appellant"},{"name":"Old Republic Union Insurance Company","role":"Defendant-Appellant"},{"name":"GeoVera Specialty Insurance Company","role":"Defendant-Appellant"},{"name":"Transverse Specialty Insurance Company","role":"Defendant-Appellant"}],"judge":"Stephen A. Higginson","amountUsd":null,"state":"LA","amount":"Surplus lines commercial property coverage dispute; damages undisclosed","source":"live","sourceUrl":"https://law.justia.com/cases/federal/appellate-courts/ca5/25-30372/25-30372-2026-09-03.html","summary":"On September 3, 2026, the Fifth Circuit affirmed a ruling that the arbitration clause in a surplus lines commercial property policy covering Transportation Consultants, Inc.'s Louisiana property cannot be enforced against the nine domestic insurers on the policy, while the two foreign insurers must still arbitrate. Following Town of Vinton v. Indian Harbor Insurance Co. and Crescent City Surgical Operating Co. v. Interstate Fire & Casualty Co., the panel also rejected the insurers' equitable estoppel argument. It vacated the order lifting the stay of litigation against the domestic insurers and remanded for the district court to decide whether that litigation should pause during the arbitration.","significance":"The ruling confirms that, in the Fifth Circuit, a Louisiana commercial property policy shared by domestic and foreign insurers can split one coverage dispute into arbitration with the foreign insurers and court litigation with the domestic ones. Whether the court case must wait for the arbitration is left to a fact-specific stay analysis in the district court.","tags":["insurance coverage","arbitration","surplus lines","hurricane ida","louisiana"],"docketUrl":"https://www.courtlistener.com/opinion/10966064/transportation-conslt-v-certain-undwr/","docketLabel":"CourtListener opinion","hasFull":true},{"id":"live-081","addedDate":"2026-09-06","title":"Vesta Realty Partner's Fraud Suit Against CEO Marc Kulick (Kansas)","brief":"A business partner's 199-page Kansas suit alleges Vesta Realty CEO Marc Kulick used the multifamily company's funds for personal spending while hiding its finances from investors.","category":"reit-securities","status":"pending","date":"2026-04-01","jurisdiction":"Kansas state court (court and county not named in the sources reviewed)","parties":[{"name":"Vesta Realty, LLC","role":"Company at issue (CEO Marc Kulick is the named defendant)"}],"amountUsd":null,"state":"KS","amount":"At least $37M in alleged personal credit card payments from company funds (per KJRH)","source":"live","sourceUrl":"https://oklahomawatch.org/2026/04/08/a-rats-nest-of-fraud-and-deceit-new-lawsuit-adds-to-vesta-realty-ceos-legal-troubles/","summary":"A business partner of Vesta Realty CEO Marc Kulick filed a 199-page lawsuit in Kansas alleging Kulick used the Tulsa-based multifamily company's entities as his 'personal piggy bank' and concealed its financial condition from investors, Oklahoma Watch reported on April 8, 2026. KJRH reported that the suit alleges Kulick used company funds to pay at least $37 million in personal credit card payments. Kulick did not respond to Oklahoma Watch, and KJRH reported no criminal charges had been filed.","significance":"The suit puts an insider's allegations about how Vesta's cash was managed before a court while the company faces many other lawsuits. The allegations have not been proven.","judge":null,"tags":["investor fraud","llc governance","multifamily","vesta realty","kansas"],"hasFull":true},{"id":"live-083","addedDate":"2026-09-07","title":"Copper Property CTL Pass Through Trust v. Onyx Partners (Suit Over Stalled $947M JCPenney Portfolio Sale)","brief":"Copper Property CTL Pass Through Trust, which holds JCPenney's real estate, sued Onyx Partners alleging a 'sham' offer for the 119-store, $947 million portfolio, and seeks at least $150 million; Onyx has since bid again.","category":"reit-securities","status":"filed","date":"2026-08-25","jurisdiction":"Massachusetts Superior Court","parties":[{"name":"Copper Property CTL Pass Through Trust","role":"Plaintiff"},{"name":"Onyx Partners","role":"Defendant"}],"judge":null,"amountUsd":150000000,"amountBasis":"damages sought","state":"MA","amount":"$947M portfolio; Copper seeks $150M+ in damages","source":"live","sourceUrl":"https://therealdeal.com/national/2026/09/01/jcpenney-real-estate-holding-company-sues-prospective-buyer/","summary":"Copper Property CTL Pass Through Trust, the entity created in JCPenney's 2020 bankruptcy to hold its real estate, sued Boston private equity firm Onyx Partners and founder Anton Melchionda on Aug. 25, 2026 in Massachusetts Superior Court, The Real Deal reported, citing Bisnow. Copper alleges Onyx misled it about its financing and made a \"sham\" offer for the 119-store portfolio Onyx had agreed to buy for $947 million, and seeks at least $150 million. Onyx earlier sued Copper to recover part of its $5 million deposit, and last month made a new $934 million bid; it says it wants to resolve the dispute and close.","significance":"Large portfolio sales that run past their closing deadline can turn into competing lawsuits over who caused the delay and who keeps the deposit. Sellers should document the buyer's financing representations as the deal goes on, and buyers should expect those statements to be tested in court if the deal stalls.","tags":["reit litigation","purchase agreement","breach of contract","bankruptcy real estate","retail portfolio"],"documentUrl":"https://www.sec.gov/Archives/edgar/data/1837671/000183767126000066/copperpropertytrust-onyx.htm","documentLabel":"Read the filed complaint","hasFull":true},{"id":"live-087","addedDate":"2026-09-08","title":"Wilmington Trust v. Nakash Lincoln LLC (Hotel Lincoln Land Parcel CMBS Foreclosure)","brief":"Wilmington Trust, for CMBS bondholders, sued to foreclose a $25.4 million loan on the land under Chicago's Hotel Lincoln after it matured unpaid; the hotel's leasehold is not targeted.","category":"lending-foreclosure","status":"filed","date":"2026-08-14","jurisdiction":"Circuit Court of Cook County, Illinois","parties":[{"name":"Wilmington Trust","role":"Plaintiff (trustee for CMBS bondholders)"},{"name":"Nakash Lincoln LLC","role":"Defendant (Borrower)"},{"name":"Lincoln 1816 LLC","role":"Defendant (Borrower)"}],"judge":null,"amountUsd":25400000,"amountBasis":"loan","state":"IL","amount":"$25.4M ground-parcel loan, plus $842,580 in claimed interest and default fees","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/08/18/nakash-family-faces-25m-foreclosure-lawsuit-on-hotel-lincoln/","summary":"Wilmington Trust, representing bondholders in a commercial mortgage pool, sued Nakash Lincoln LLC and Lincoln 1816 LLC in Cook County on Aug. 14, 2026, alleging they failed to repay a $25.4 million loan on the land at 1816 North Clark Street when it matured earlier this year. The suit seeks the owner's fee interest and landlord rights in the land under Hotel Lincoln, and leaves the hotel's ground lease and leasehold, held by a separate Nakash-led entity, in place, The Real Deal reported. The hotel building has its own $35 million loan, which is not part of this case.","significance":"Splitting a hotel into a land parcel and a building leasehold, each with its own loan, means a default on one need not reach the other: here the lender is going after the land and the rent it earns, not the hotel. Lenders and buyers looking at split-ownership hotels should review each layer's debt and the ground lease separately.","tags":["foreclosure","CMBS","hospitality","illinois","loan maturity default"],"hasFull":true},{"id":"live-088","addedDate":"2026-09-08","title":"The Alder at Lake Park LLC v. Town of Lake Park (Suit Alleging Coercion Over Affordable Housing Site)","brief":"Alder at Lake Park sued the Town of Lake Park, Florida in federal court, alleging the town attorney pushed it to sell its affordable housing site and then had 34 code violations issued; the town attorney denies it.","category":"zoning-land-use","status":"pending","date":"2026-08-27","jurisdiction":"U.S. District Court, Southern District of Florida","propertyType":"Mixed-Use","parties":[{"name":"The Alder At Lake Park LLC","role":"Plaintiff"},{"name":"Town of Lake Park","role":"Defendant"}],"judge":"Ed Artau","amountUsd":null,"state":"FL","amount":"Injunctive relief plus unspecified damages","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/09/08/developer-sues-lake-park-alleging-corruption/","summary":"The Alder at Lake Park LLC, an entity linked to Daniel Goldstein of New York-based Bofsa Properties, sued the Town of Lake Park, Florida in the Southern District of Florida on Aug. 27, 2026 over its stalled Kelsey at Park Avenue mixed-use affordable housing project. The complaint alleges Town Attorney Tom Baird said \"all problems would go away\" if Alder sold its seven-parcel site to a developer he had lined up, and then directed 34 code violations after it refused. Alder asks the court to stop further code fines, require the town to decide its applications and award damages. Baird told The Real Deal he denies the allegations and called the suit retaliation for enforcing town codes.","significance":"The suit tests how far a developer can go in federal court when it says a small town used code enforcement to push it off a site. Developers working in small municipalities should keep a written record of every meeting with officials, especially any talk of selling to another buyer.","tags":["zoning","code enforcement","affordable housing","florida","municipal liability"],"docketUrl":"https://www.courtlistener.com/docket/74712343/the-alder-at-lake-park-llc-v-town-of-lake-park/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-089","addedDate":"2026-09-09","title":"Kane Creek Development Watch v. Lieutenant Governor of Utah (Echo Canyon Preliminary Municipality Challenge)","brief":"Kane Creek Development Watch and Living Rivers sued to void Utah's 2024 preliminary municipality law and Echo Canyon's certification, which gives a landowner-dominated board zoning power over a project near Moab.","category":"zoning-land-use","status":"pending","date":"2026-02-10","jurisdiction":"Utah Seventh District Court, Grand County","parties":[{"name":"Friends of the Abajos d/b/a Kane Creek Development Watch","role":"Plaintiff"},{"name":"Living Rivers","role":"Plaintiff"},{"name":"Utah Lieutenant Governor (official capacity)","role":"Defendant"},{"name":"Kane Creek Preservation & Development, LLC","role":"Defendant"},{"name":"Echo Canyon preliminary municipality","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"UT","amount":"Constitutional challenge; no damages sought","source":"live","sourceUrl":"https://www.sltrib.com/news/2026/02/14/utah-law-shifts-power-elected/","summary":"Two advocacy groups, Friends of the Abajos (doing business as Kane Creek Development Watch) and Living Rivers, sued on February 10, 2026 in Utah's 7th Judicial District Court to overturn SB258, the 2024 \"preliminary municipality\" law, and void the certification it gave Echo Canyon, a proposed 176-acre mixed-use development southwest of Moab, The Salt Lake Tribune reported. They allege the law unconstitutionally shifts zoning authority from elected county officials to a board largely appointed by private landowners. The developer says the project complies with SB258 and other governing law.","significance":"The case tests whether a state may let a landowner-affiliated board exercise zoning authority over its own project before any residents live there. Because Echo Canyon was the first project certified under SB258 and others have applied, a ruling would affect every project using the law.","tags":["zoning","land use","utah","municipal incorporation","constitutional challenge"],"hasFull":true},{"id":"live-090","addedDate":"2026-09-09","title":"Four Mile Capital LLC v. Reynolds South Tower LLC (River's Edge at Manchester Construction-Defect Fraud Suit)","brief":"A Richmond judge on Sept. 21, 2026 largely denied the developers' bid to dismiss Four Mile Capital's $40M+ suit over water leaks at the 212-unit River's Edge at Manchester; the defendants deny wrongdoing.","category":"construction-defect","status":"ruling","date":"2026-09-21","jurisdiction":"Richmond Circuit Court, Virginia","parties":[{"name":"Four Mile Capital","role":"Plaintiff"},{"name":"Reynolds South Tower LLC","role":"Defendant"},{"name":"Purcell Construction Corp.","role":"Defendant"}],"amountUsd":40000000,"amountBasis":"damages sought","state":"VA","amount":"$40M+","source":"live","sourceUrl":"https://richmondbizsense.com/2026/08/17/water-leaks-at-manchester-apartments-lead-to-40m-lawsuit-between-developer-current-owner/","summary":"Four Mile Capital, which bought the 212-unit River's Edge apartment tower at 505 Porter St. in Richmond in 2021, sued developer Reynolds South Tower LLC and Purcell Construction Corp. in Richmond Circuit Court in May 2025, alleging fraud, breach of contract, negligence and business conspiracy over water leaks and seeking more than $40 million, Richmond BizSense reported. On September 21, 2026, Judge Jacqueline McClenney largely denied the defendants' demurrer, though she sustained it on certain counts against Purcell. The defendants deny wrongdoing.","significance":"The ruling lets the buyer's fraud claims go forward even though it knew of leaks before closing and accepted the sellers' repair arrangement, facts the developers said defeated those claims. The case now moves toward a jury trial, with no date set.","tags":["construction defect","fraud","virginia","multifamily","richmond"],"judge":"Jacqueline S. McClenney","hasFull":true},{"id":"live-091","addedDate":"2026-09-09","title":"Mack Real Estate Group v. X Denver Ownership (X Denver Apartments Receivership Suit)","brief":"A Denver judge on October 9, 2026 appointed Trigild IVL LLC as receiver of X Denver, a 455-unit apartment building, after Mack Real Estate Group alleged its $170M loan has been in default since January 2025.","category":"lending-foreclosure","status":"ruling","date":"2026-09-03","jurisdiction":"Denver District Court, Colorado","parties":[{"name":"Mack Real Estate Group","role":"Plaintiff/Lender"},{"name":"Trigild IVL LLC","role":"Court-appointed receiver"}],"judge":"Heidi Kutcher","amountUsd":170000000,"amountBasis":"loan","state":"CO","amount":"$170M","source":"live","sourceUrl":"https://businessden.com/lender-wants-receiver-appointed-for-x-denver/","summary":"New York-based Mack Real Estate Group sued in Denver District Court on September 3, 2026 to have a receiver appointed for X Denver, a 12-story apartment building near Coors Field, alleging the $170 million loan on the property has been in default since it matured in January 2025, BusinessDen reported. BusinessDen said the current owner is unclear. On October 9, Judge Heidi Kutcher appointed Trigild IVL LLC as receiver, Bisnow reported, citing the Denver Business Journal; the owner's representatives did not appear in court or respond to the complaint.","significance":"The order hands day-to-day control of a five-year-old building to a receiver that may sell it with the lender's approval, more than 18 months after the loan matured. The same receiver also oversees Republic Plaza in Denver.","tags":["receivership","loan default","colorado","multifamily","denver"],"hasFull":true},{"id":"live-092","addedDate":"2026-09-10","title":"Rialto Capital Advisors v. WC MRP Calumet Center, LLC ($45.6M Calumet City Retail Foreclosure)","brief":"Special servicer Rialto Capital has sued to foreclose on a Calumet City, Illinois shopping center held by an entity backed by Nate Paul, seeking $45.6 million after a 2025 reinstatement deal broke down, The Real Deal reported.","category":"lending-foreclosure","status":"filed","date":"2026-08-10","jurisdiction":"Circuit Court of Cook County, Illinois","parties":[{"name":"Rialto Capital Advisors","role":"Special Servicer (Plaintiff)"},{"name":"WC MRP Calumet Center, LLC","role":"Defendant"}],"judge":null,"amountUsd":45600000,"amountBasis":"loan","state":"IL","amount":"$45.6M","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/08/10/nate-paul-faces-big-foreclosure-suit-in-chicago-court/","summary":"Rialto Capital, acting as special servicer for a CMBS trust, filed a $45.6 million foreclosure suit in Cook County against WC MRP Calumet Center, LLC, an entity backed by Austin developer Nate Paul's World Class Holdings. The property is a shopping center of more than 159,000 square feet at 410-500 River Oaks West Road in Calumet City, Illinois, and it is one of six retail centers securing a $38.3 million loan, The Real Deal reported. The lawsuit alleges the borrower paid the first $500,000 quarterly installment under a 2025 reinstatement agreement but did not make the December payment or those due in 2026.","significance":"A reinstatement agreement protects a borrower only while the payments keep coming; here the suit alleges one missed installment led to a default notice and then acceleration of the debt. Owners whose property is one of several securing a single cross-collateralized loan should watch the whole pool, because the lender can enforce against each property in turn.","tags":["foreclosure","cmbs","retail","illinois","special servicer"],"hasFull":true},{"id":"live-093","addedDate":"2026-09-10","title":"Solera Multifamily, LLC v. Tegethoff (Old Hickory Village Investor Fraud Suit)","brief":"A federal magistrate judge let Old Hickory Village investors amend their fraud suit against developer Jeffrey Tegethoff and his companies, then stayed the whole case in September for a related bankruptcy.","category":"reit-securities","status":"pending","date":"2026-06-17","jurisdiction":"U.S. District Court, Eastern District of Missouri","parties":[{"name":"Solera Multifamily, LLC","role":"Plaintiff"},{"name":"Hickory Investors, LLC","role":"Plaintiff"},{"name":"Tegethoff Development Co, LLC","role":"Defendant"},{"name":"Tegethoff Development, LLC","role":"Defendant"}],"amountUsd":null,"state":"MO","amount":"Nearly $3M investment at issue, according to the plaintiffs","source":"live","sourceUrl":"https://molawyersmedia.com/2026/07/13/missouri-fraud-complaint-amended-real-estate-case/","summary":"On June 17, 2026, U.S. Magistrate Judge John M. Bodenhausen allowed Solera Multifamily, LLC and Hickory Investors, LLC to file an amended complaint against developer Jeffrey J. Tegethoff and his development companies over the Old Hickory Village project in St. Peters, Missouri, denied the defendants' motion to dismiss without prejudice, and stayed claims against the two Tegethoff Development entities after they filed for Chapter 11, Missouri Lawyers Media reported. The plaintiffs allege nearly $3 million they invested was used for other purposes. On September 22, 2026, the court stayed the entire case pending the bankruptcy.","significance":"The bankruptcy's automatic stay protected only the debtor companies, but the court then used its own power to pause the claims against the developer and the remaining defendants because they are intertwined with the bankruptcy. Investors suing a sponsor alongside its bankrupt entities may see the whole case wait on the bankruptcy even where the stay does not formally reach every defendant.","tags":["securities fraud","investor fraud","missouri","multifamily","bankruptcy"],"judge":"John M. Bodenhausen","docketUrl":"https://www.courtlistener.com/docket/72081019/solera-multifamily-llc-v-tegethoff/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-094","addedDate":"2026-09-10","title":"Feather-Craft et al. v. City of Brentwood (Manchester Road Blight Designation Appeal)","brief":"Three Brentwood, Missouri businesses and their landlord are appealing a ruling upholding the city's blight designation of Manchester Road properties, a step toward eminent domain for a $436 million plan.","category":"eminent-domain","status":"appeal","date":"2025-09-26","jurisdiction":"Circuit Court of St. Louis County, Missouri (on appeal to the Missouri Court of Appeals, Eastern District)","parties":[{"name":"Feather-Craft Fly Fishing","role":"Plaintiff"},{"name":"Time for Dinner","role":"Plaintiff"},{"name":"Convergence Dance and Body Center","role":"Plaintiff"},{"name":"8307 Manchester, LLC","role":"Plaintiff (building owner)"},{"name":"City of Brentwood","role":"Defendant"}],"amountUsd":null,"state":"MO","amount":"$436M redevelopment plan at issue","source":"live","sourceUrl":"https://reason.com/2025/10/03/missouri-judge-backs-citys-eminent-domain-redevelopment-plan/","summary":"A St. Louis County judge in September 2025 upheld Brentwood, Missouri's blight designation of properties along the Manchester Road Corridor, which would let the city use eminent domain for a $436 million redevelopment plan, Reason reported. Judge Kristine Allen Kerr held that the designation was 'fairly debatable' and that the city had not acted arbitrarily and capriciously. The plaintiffs appealed; the Missouri Supreme Court denied their application to transfer the case from the Court of Appeals in April 2026.","significance":"The appeal tests how much deference Missouri courts give a city's blight finding under the state's post-Kelo eminent domain reforms. The plaintiffs argue the trial court applied the wrong standard of review; Brentwood officials did not respond to Reason's request for comment.","tags":["eminent domain","blight","redevelopment","missouri","retail"],"judge":"Kristine Allen Kerr","hasFull":true},{"id":"live-095","addedDate":"2026-09-10","title":"Wilmington Trust National Association v. NG 211 N. Pennsylvania St LLC (Regions Tower $75M Foreclosure)","brief":"Wilmington Trust, as trustee, sued to foreclose on Indianapolis' 36-story Regions Tower after its owners missed an Oct. 1, 2023 payoff deadline, alleging about $74.9 million owed, and asked for a receiver.","category":"lending-foreclosure","status":"pending","date":"2024-02-02","jurisdiction":"Marion Superior Court, Indiana","parties":[{"name":"Wilmington Trust National Association","role":"Plaintiff"},{"name":"NG 211 N. Pennsylvania St LLC","role":"Defendant"},{"name":"Regions Tower MF LLC","role":"Defendant"}],"judge":null,"amountUsd":74894311.9,"amountBasis":"loan","state":"IN","amount":"$74.9M","source":"live","sourceUrl":"https://www.ibj.com/articles/regions-tower-owners-face-75m-foreclosure-suit-after-missing-loan-deadline","summary":"Wilmington Trust National Association, acting as trustee with KeyBank as debt servicer, sued on February 2, 2024 in Marion Superior Court to foreclose on Regions Tower in downtown Indianapolis, the Indianapolis Business Journal reported. The suit says owner entities NG 211 N. Pennsylvania St LLC and Regions Tower MF LLC missed an October 1, 2023 deadline to pay off the loan; WISH-TV reported the owners owe $74,894,311.90. The lender seeks repayment or foreclosure and asks the court to appoint a receiver.","significance":"The suit puts one of downtown Indianapolis' best-known office towers into foreclosure and asks for a receiver to run it while the case proceeds. The IBJ called it at least the second major downtown office building to face foreclosure in six months.","tags":["foreclosure","office","indiana","receivership"],"hasFull":true},{"id":"live-096","addedDate":"2026-09-10","title":"Oxbow Estates HOA et al v. Metropolitan Development Commission (Willows \"The Elements\" Rezoning Settlement)","brief":"Neighbors' suit over the rezoning for J.C. Hart Co.'s $61 million apartment project on the former Willows site in Indianapolis ended in a deal cutting it to 168 apartments; the council approved it 24-0.","category":"zoning-land-use","status":"settled","date":"2024-02-05","jurisdiction":"Marion Superior Court, Indiana","parties":[{"name":"Oxbow Estates Homeowners Association","role":"Plaintiff"},{"name":"Spirit Lake Co-owners Association","role":"Plaintiff"},{"name":"Metropolitan Development Commission","role":"Defendant"},{"name":"Evergreen LLC","role":"Defendant"},{"name":"J.C. Hart Co.","role":"Defendant"},{"name":"Chase Development","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"IN","amount":"$61M redevelopment at issue","source":"live","sourceUrl":"https://www.ibj.com/articles/developer-neighbors-reach-last-minute-deal-on-willows-redevelopment","summary":"Two neighborhood associations and two neighboring property owners sued Indianapolis' Metropolitan Development Commission, J.C. Hart Co., Chase Development and property owner Evergreen LLC in Marion County Superior Court in January 2024, after the MDC approved a rezoning for a $61 million project of 192 apartments and 16 town houses on the former Willows Event Center site, the Indianapolis Business Journal reported. They argued the approval ignored 2003 commitments limiting density around Spirit Lake to 1.94 units per acre. On February 5, 2024, the sides reached a deal cutting the project to 168 apartments with no condos or town houses, the City-County Council approved it 24-0, and the IBJ reported the suit was expected to be dismissed with prejudice.","significance":"The neighbors did not stop the project, but their suit came before a last-minute deal that cut the apartment count and dropped the town houses ahead of the council's final vote. No court ruled on whether the approved density violated the 2003 commitments.","tags":["zoning","rezoning","indiana","multifamily","settlement"],"hasFull":true},{"id":"live-097","addedDate":"2026-09-10","title":"Fairlane Town Center Receivership (Dearborn Mall Lender Seeks Default Ruling Against Kohan Owner)","brief":"Dearborn's Fairlane Town Center has been in receivership since January 2026; a lender has asked a Wayne County judge to declare Kohan's mall in default on a loan with more than $35 million outstanding.","category":"lending-foreclosure","status":"pending","date":"2026-07-09","jurisdiction":"3rd Circuit Court, Wayne County, Michigan","parties":[{"name":"Kohan Retail Investment Group","role":"Owner / Borrower"}],"amountUsd":35000000,"amountBasis":"loan","state":"MI","amount":"Loan balance of more than $35 million (per lender's July 2026 request)","source":"live","sourceUrl":"https://www.aol.com/articles/receiver-fairlane-town-center-prepping-202822139.html","summary":"Fairlane Town Center, the Dearborn, Michigan mall owned by New York-based Kohan Retail Investment Group, has been in receivership since January 2026, the Detroit Free Press reported. In early July, one of the mall's lenders asked a Wayne County judge to declare the mall and its owner in default on a loan with an outstanding balance of more than $35 million. The court-appointed receiver told the Free Press he is preparing bidding and sale procedures for a future sale.","significance":"Fairlane has changed hands three times since 2014 and is now headed toward a court-supervised sale. The Free Press reported that many storefronts remain occupied, which shows that occupancy alone did not keep the owner current on its obligations.","tags":["foreclosure","receivership","retail","mall","michigan"],"judge":null,"hasFull":true},{"id":"live-098","addedDate":"2026-09-10","title":"Waukesha State Bank v. 225 East Michigan Street LLC ($6.57M Mackie Building Foreclosure)","brief":"Waukesha State Bank's foreclosure suit over Milwaukee's historic Mackie Building was dismissed by stipulation on Sept. 14 after the owner and lender settled; the developer says the loan was reinstated.","category":"lending-foreclosure","status":"settled","date":"2026-08-03","jurisdiction":"Milwaukee County Circuit Court","parties":[{"name":"Waukesha State Bank","role":"Plaintiff"},{"name":"225 East Michigan Street LLC","role":"Defendant"}],"judge":"William Pocan","amountUsd":6200000,"amountBasis":"loan","state":"WI","amount":"$6.2M owed ($5.9M principal) on a $6.57M loan, per the bank","source":"live","sourceUrl":"https://dailyreporter.com/2026/08/10/historic-milwaukee-mackie-building-foreclosure-grain-exchange/","summary":"Waukesha State Bank sued 225 East Michigan Street LLC, an affiliate of J. Jeffers & Co., in Milwaukee County Circuit Court on August 3, 2026, alleging it defaulted on a $6.57 million loan on the historic Mackie Building and owed $6.2 million, including $5.9 million in principal. Developer Joshua Jeffers attributed the default to lower percentage rent from anchor tenant The Grain Exchange. The Milwaukee Journal Sentinel reported that Judge William Pocan dismissed the suit by stipulation on September 14 and that a companion money-judgment suit in Waukesha County was dismissed the next day; Jeffers said the loan had been reinstated.","significance":"The case shows how a percentage-rent lease can leave a landlord short of debt service when an anchor tenant's revenue stays below pre-pandemic levels. It also shows a foreclosure filing ending in a negotiated resolution: both suits were dropped by agreement within about six weeks.","tags":["foreclosure","hospitality","historic building","wisconsin","percentage rent"],"hasFull":true},{"id":"live-099","addedDate":"2026-09-10","title":"Fortress Credit Corp. v. 601W Cos. (Dayton's Project Foreclosure, About $220M Owed)","brief":"A judge approved potential foreclosure on the Dayton's Project in Minneapolis, where developer 601W owes lender Fortress about $220 million on a building the city assesses at about $27 million.","category":"lending-foreclosure","status":"ruling","date":"2026-04-27","jurisdiction":"Hennepin County District Court, Minnesota","parties":[{"name":"Fortress Credit Corp.","role":"Lender (Plaintiff)"},{"name":"601W Cos.","role":"Borrower (Defendant)"},{"name":"Hightower Initiatives","role":"Borrower's partner (Defendant)"}],"judge":null,"amountUsd":220000000,"amountBasis":"loan","state":"MN","amount":"$220M unpaid principal, interest, and fees","source":"live","sourceUrl":"https://www.axios.com/local/twin-cities/2026/04/27/future-daytons-project-foreclosure-redevelopnent","summary":"A judge has approved the potential foreclosure of The Dayton's Project, New York developer 601W's $350 million redevelopment of the former Dayton's department store in downtown Minneapolis, Axios Twin Cities reported on April 27, 2026. 601W owes lender Fortress about $220 million in unpaid principal, interest and fees, while the building's city-assessed value is about $27 million. A Hennepin County judge had placed the property in receivership on September 23, 2024, when Fortress said $177 million was owed. No auction date had been set.","significance":"The case shows a wide gap between a redevelopment's cost and its current assessed value: about $220 million owed on a building assessed at about $27 million. A Fortress attorney told the court that foreclosure would bring \"the privilege of owning an empty building,\" which frames the lender's choice between holding and selling.","tags":["foreclosure","office","cmbs","minnesota","receivership"],"hasFull":true},{"id":"live-100","addedDate":"2026-09-10","title":"Deutsche Bank (CMBS Trustee) Foreclosure on Minneapolis's Foshay Tower, Home of the W Minneapolis","brief":"A Hennepin County judge ruled Aug. 25 that the Foshay Tower's owner owes more than $42.3 million on a defaulted loan, and the tower, home of the W Minneapolis hotel, is set for a Dec. 18 foreclosure sale.","category":"lending-foreclosure","status":"ruling","date":"2026-08-25","jurisdiction":"Hennepin County District Court, Minnesota","parties":[{"name":"Deutsche Bank","role":"Plaintiff (trustee for CMBS bondholders)"}],"judge":null,"amountUsd":42300000,"amountBasis":"judgment","state":"MN","amount":"$51M mortgage; judgment of $42.3M+","source":"live","sourceUrl":"https://www.connectcre.com/stories/return-to-lender-week-of-nov-5-2026/","summary":"Deutsche Bank, as trustee for bondholders in a commercial mortgage-backed securities trust, sued the owner of Minneapolis's Foshay Tower after it failed to pay off a $51 million mortgage that matured in May 2025, seeking a receiver and roughly $43 million in unpaid principal, interest and fees, Weekly Real Estate News reported in April 2026, citing the Star Tribune. A Hennepin County District Court judge ruled on August 25, 2026 that the owner of the 32-story tower at 821 S. Marquette Ave., which houses the 229-room W Minneapolis hotel, owes more than $42.3 million, and a foreclosure sale is scheduled for December 18, 2026, Connect CRE reported, citing the Minneapolis/St. Paul Business Journal.","significance":"The ruling sets the amount owed on the matured CMBS loan and moves one of downtown Minneapolis's best-known landmarks, now a hotel, toward a foreclosure sale. The case began as a maturity default: the loan came due in May 2025 without being paid off.","tags":["foreclosure","hotel","cmbs","minnesota","minneapolis"],"hasFull":true},{"id":"live-101","addedDate":"2026-09-10","title":"Dillard Store Services, Inc. v. Winrock Partners LLC (Winrock Town Center Redevelopment Dispute)","brief":"Dillard's sued Winrock Town Center's owners in 2022, alleging prolonged redevelopment blocked its Albuquerque store entrances and parking without its consent; the federal case is still in pretrial litigation.","category":"lease-disputes","status":"pending","date":"2026-06-24","jurisdiction":"U.S. District Court, District of New Mexico","parties":[{"name":"Dillard Store Services, Inc.","role":"Plaintiff"},{"name":"Winrock Partners LLC","role":"Defendant"},{"name":"Integrated Property Services Company","role":"Defendant"}],"amountUsd":null,"judge":"David H. Urias","state":"NM","amount":"Unspecified lost-profits damages","source":"live","sourceUrl":"https://www.pacermonitor.com/public/case/47005124/Dillard_Store_Services,_Inc_v_Winrock_Partners_LLC_et_al","summary":"Dillard Store Services sued Winrock Partners LLC and Integrated Property Services Company in federal court in New Mexico on December 1, 2022, alleging that redevelopment of Albuquerque's Winrock Town Center blocked its store entrances and parking without the consent its 1992 lease requires, KRQE reported at the time. The suit seeks lost profits and attorney's fees on claims including breach of contract and negligent misrepresentation. The case remains in pretrial litigation: Magistrate Judge John F. Robbenhaar granted a Dillard's motion to compel on June 24, 2026, and in November 2026 the parties were briefing a Dillard's motion for a protective order, according to the docket.","significance":"The case shows how a phased conversion of an enclosed mall can lead to lease claims by a long-term anchor tenant whose consent rights cover common areas and parking. Nearly four years after filing, it is still in pretrial proceedings.","tags":["mall redevelopment","anchor tenant","lease breach","construction disruption","discovery dispute"],"docketUrl":"https://www.courtlistener.com/docket/66581116/dillard-store-services-inc-v-winrock-partners-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-102","addedDate":"2026-09-10","title":"Kuna Neighbors' Appeal of Gemstone Technology Park Data Center Approval (Idaho Supreme Court)","brief":"A Kuna farmer and two Toledo dairy companies appealed to the Idaho Supreme Court after a judge rejected their claim that a council member's conflict tainted approval of a 620-acre data center park.","category":"zoning-land-use","status":"appeal","date":"2026-08-19","jurisdiction":"Idaho Supreme Court","parties":[{"name":"Toledo Dairy I LLC","role":"Petitioner/Appellant"},{"name":"Toledo Land Holdings LLC","role":"Petitioner/Appellant"},{"name":"City of Kuna","role":"Respondent"}],"judge":"James Cawthon","amountUsd":null,"state":"ID","amount":"620-acre data center project (non-monetary land-use challenge)","source":"live","sourceUrl":"https://boisedev.com/news/2026/08/19/kuna-farmers-appeal-to-idaho-supreme-court-after-petition-against-a-kuna-data-center-was-thrown-out/","summary":"A neighboring farmer and two dairy companies, Toledo Dairy I LLC and Toledo Land Holdings LLC, petitioned in August 2025 for judicial review of the City of Kuna's approval of Diode Ventures' 620-acre Gemstone Technology Park data center project, BoiseDev reported. They argued council member Greg McPherson should have recused himself because the farmer employed him. District Judge James Cawthon denied the petition in May 2026, finding no \"immediate or direct\" economic impact on the farmer, and the petitioners appealed to the Idaho Supreme Court in June 2026.","significance":"The appeal asks how direct a neighboring landowner's economic stake must be before a council member he employs has to step aside. A ruling for the petitioners could reopen an approval the council granted by a single vote.","tags":["data center","rezoning","conflict of interest","judicial review","Idaho Supreme Court"],"hasFull":true},{"id":"live-103","addedDate":"2026-09-10","title":"BB's Childcare, LLC Commercial Lease-Purchase Eviction Appeal (Nebraska Supreme Court Jurisdiction Ruling)","brief":"The Nebraska Supreme Court held a commercial lease's purchase options and rent credits arguably gave childcare tenant BB's Childcare an equitable interest, so the county court had no jurisdiction over the eviction case.","category":"lease-disputes","status":"ruling","date":"2026-05-08","jurisdiction":"Nebraska Supreme Court","parties":[{"name":"BB's Childcare, LLC","role":"Appellant"}],"judge":"Cassel","amountUsd":null,"state":"NE","amount":"$3,000/month commercial lease; purchase-option rights at stake","source":"live","sourceUrl":"https://law.justia.com/cases/nebraska/supreme-court/2026/s-24-914.html","summary":"On May 8, 2026, the Nebraska Supreme Court vacated a judgment that had restored a commercial property to its owner in a forcible entry and detainer action against BB's Childcare, LLC and its principal, and directed that the case be dismissed for lack of subject matter jurisdiction. In an opinion by Justice Cassel, the court held that the lease's purchase options, credit of rent toward the price and limits on the owner's right to sell arguably conferred an equitable interest in the property, creating a title dispute that a forcible entry and detainer action cannot decide.","significance":"The ruling means a Nebraska owner whose commercial lease gives the tenant purchase rights may be unable to use the summary forcible entry and detainer procedure to recover possession and may have to litigate in district court. The court limited its reach, rejecting the argument that every written lease creates a title dispute and expressing no view on the merits of the tenants' title claims.","tags":["forcible entry and detainer","lease-to-own","equitable interest","subject matter jurisdiction","Nebraska Supreme Court"],"hasFull":true},{"id":"live-104","addedDate":"2026-09-10","title":"Pioneer Hi-Bred International, Inc. et al. v. AltEn, LLC (Mead Ethanol Plant Cleanup-Cost Litigation)","brief":"Seed companies' federal suit against the former AltEn ethanol plant near Mead, Nebraska was dismissed in November 2025 after a settlement; court papers point to environmental covenants restricting the land's use.","category":"environmental","status":"settled","date":"2025-11-26","jurisdiction":"U.S. District Court, District of Nebraska","parties":[{"name":"Pioneer Hi-Bred International, Inc.","role":"Plaintiff"},{"name":"AgReliant Genetics, LLC","role":"Plaintiff"},{"name":"Beck's Superior Hybrids, Inc.","role":"Plaintiff"},{"name":"Corteva Agriscience, LLC","role":"Plaintiff"},{"name":"Winfield Solutions, LLC","role":"Plaintiff"},{"name":"AltEn, LLC","role":"Defendant"},{"name":"AltEn Operating Company, LLC","role":"Defendant"},{"name":"E3 Biofuels, LLC","role":"Defendant"},{"name":"Earth Energy & Environment, LLC","role":"Defendant"},{"name":"Falcon Energy, LLC","role":"Defendant"},{"name":"Green Disposal Mead LLC","role":"Defendant"},{"name":"Integrated Recycling, LLC","role":"Defendant"},{"name":"Mead Acquisition Company, LLC","role":"Defendant"},{"name":"Mead Cattle Company, LLC","role":"Defendant"},{"name":"Platte River Green Fuels, LLC","role":"Defendant"},{"name":"State of Nebraska","role":"Interested Party"}],"amountUsd":null,"amountBasis":null,"judge":"Brian C. Buescher","state":"NE","amount":"Undisclosed settlement; cleanup privately funded by the seed companies","source":"live","sourceUrl":"https://nebraskaexaminer.com/2025/12/09/pillen-touts-alten-cleanup-progress-after-federal-lawsuit-settled/","summary":"Seed companies that took over cleanup of the former AltEn ethanol plant near Mead, Nebraska sued AltEn and related entities in federal court in February 2022. On November 26, 2025, U.S. District Judge Brian C. Buescher accepted the parties' joint stipulation and dismissed the consolidated cases with prejudice. The Nebraska Examiner reported that settlement details may not be disclosed but that court papers indicate the property's owners must accept environmental restrictions, including a bar on homes, schools and child care facilities.","significance":"The case ended with restrictions recorded against the contaminated industrial land itself rather than a money judgment reported in public. The settlement may also help resolve the Nebraska Attorney General's separate state suit over the plant, the Nebraska Examiner reported.","tags":["ethanol plant","environmental covenant","contamination","settlement","nebraska"],"docketUrl":"https://www.courtlistener.com/docket/63107484/pioneer-hi-bred-international-inc-v-alten-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-105","addedDate":"2026-09-10","title":"Tucker United v. West Virginia Air Quality Board (Ridgeline Data Center Permit Appeal)","brief":"West Virginia's Intermediate Court of Appeals dismissed environmental groups' two challenges to the air permit for Fundamental Data's Ridgeline power-and-data-center project in Tucker County, finding it lacked jurisdiction.","category":"environmental","status":"appeal","date":"2026-08-26","jurisdiction":"Intermediate Court of Appeals of West Virginia","parties":[{"name":"Tucker United","role":"Petitioner"},{"name":"West Virginia Highlands Conservancy","role":"Petitioner"},{"name":"Sierra Club","role":"Petitioner"},{"name":"Friends of Blackwater","role":"Petitioner"},{"name":"West Virginia Air Quality Board","role":"Respondent"},{"name":"Fundamental Data, LLC","role":"Intervenor (developer)"}],"judge":null,"amountUsd":null,"state":"WV","amount":"No damages at issue; air permit for a gas-fired power facility serving a planned data center complex","source":"live","sourceUrl":"https://www.legalnewsline.com/west-virginia-record/ica-dismisses-two-tucker-co-data-center-environmental-cases/article_1c0102fc-3c78-4bcb-9cd6-761fc9ecaec3.html","summary":"The West Virginia Intermediate Court of Appeals dismissed two appeals challenging the air-quality permit for Fundamental Data, LLC's proposed Ridgeline project near Thomas and Davis in Tucker County, which includes a natural-gas-fired power facility to serve a planned data center complex, the West Virginia Record reported on August 26, 2026. The court held that one appeal belonged in the state Supreme Court of Appeals, or in Kanawha County Circuit Court if all parties agreed, and that the other belonged in circuit court and was moot. It said it would find good cause for a late notice of appeal to the Supreme Court but could not require that court to accept one.","significance":"The rulings leave the groups' challenge to the Ridgeline permit unresolved on the merits, turning instead on which court can hear it. For developers of power plants built to serve data centers, the case shows how a dispute over the proper appellate forum can lengthen the time a permit remains under challenge.","tags":["data center","air quality permit","jurisdictional dismissal","power plant","recusal"],"hasFull":true},{"id":"live-107","addedDate":"2026-09-10","title":"Hembree Insurance Trust v. Maples Industries, Inc. (Scottsboro Industrial Lease Dispute)","brief":"The Alabama Supreme Court reversed a ruling voiding a five-year, 135,847-square-foot Scottsboro industrial lease, holding tenant Maples Industries generally cannot dispute its landlord's title in a roof-repair suit.","category":"lease-disputes","status":"ruling","date":"2025-04-11","jurisdiction":"Supreme Court of Alabama","parties":[{"name":"Hembree Insurance Trust","role":"Appellant"},{"name":"Maples Industries, Inc.","role":"Appellee"}],"amountUsd":null,"judge":"Sarah H. Stewart","state":"AL","amount":"N/A — five-year industrial lease's validity and enforceability at issue","source":"live","sourceUrl":"https://www.insurancebusinessmag.com/us/news/legal-insights/alabama-supreme-court-sides-with-insurance-trust-in-commercial-lease-dispute-532711.aspx","documentUrl":"https://www.courtlistener.com/opinion/10376752/hembree-insurance-trust-v-maples-industries-inc-appeal-from-jackson/","documentLabel":"Read the Alabama Supreme Court's opinion","summary":"The Alabama Supreme Court reversed a Jackson Circuit Court judgment that had declared a five-year lease of a 135,847-square-foot Scottsboro industrial building \"null and void in all respects\" because landlord Hembree Insurance Trust had transferred title in 2014 to Woods Cove Industrial Property, LLC, of which it was the sole member. Hembree had sued tenant Maples Industries in March 2024 for failing to repair the roof as the lease required. In an April 11, 2025 opinion by Chief Justice Sarah H. Stewart, the Court held that a tenant in possession generally cannot dispute its landlord's title and remanded, Insurance Business reported. Hembree later appealed again, and the Court affirmed without opinion on October 31, 2025.","significance":"The decision holds that a landlord need not hold record title to lease property it lawfully controls, and that a tenant that took possession and paid rent generally cannot void the lease by attacking the landlord's title. It left open whether fraud, misrepresentation or mistake claims could arise from the ownership issue.","tags":["commercial lease","landlord title","estoppel","industrial property","alabama supreme court"],"hasFull":true},{"id":"live-108","addedDate":"2026-09-10","title":"CBS Holdings, LLC v. Hexagon US Federal, Inc. (Madison County Lease Renewal & Fee Fight)","brief":"After Hexagon US Federal won its lease-renewal case against new owner CBS Holdings, the Alabama Supreme Court found heavily redacted bills did not support its $174,987.45 fee award and sent it back.","category":"lease-disputes","status":"appeal","date":"2025-07-11","jurisdiction":"Supreme Court of Alabama","parties":[{"name":"CBS Holdings, LLC","role":"Appellant"},{"name":"Hexagon US Federal, Inc.","role":"Appellee"}],"amountUsd":174987.45,"amountBasis":"award","judge":"Gregory Cook","state":"AL","amount":"$174,987.45 in disputed attorney fees; underlying lease renewal upheld","source":"live","sourceUrl":"https://law.justia.com/cases/alabama/supreme-court/2024/sc-2024-0077.html","documentUrl":"https://caselaw.findlaw.com/court/al-supreme-court/117470240.html","documentLabel":"Read the attorney-fee opinion","summary":"Hexagon US Federal, Inc. ('HexFed') sued CBS Holdings, LLC in Madison Circuit Court in April 2021 after CBS Holdings, which bought the Huntsville building in 2016, rejected HexFed's notice renewing its lease of two bays. After a bench trial, the court ruled for HexFed on all claims and on CBS Holdings' counterclaims, reformed the lease to correct a mutual mistake and held HexFed was entitled to fees; the Alabama Supreme Court affirmed on October 18, 2024. In a second appeal decided July 11, 2025, the court reversed the $174,987.45 award of costs and fees because HexFed's invoices were almost entirely redacted, and remanded for HexFed to support its application and for the trial court to explain its calculation.","significance":"In Alabama, winning a contractual fee award in a commercial lease case does not end the fee fight. An application based on time spent must describe the work well enough for the court to check it, and the order must show how the court weighed the Peebles factors. HexFed keeps its entitlement to fees but must document the amount on remand.","tags":["commercial lease renewal","lease reformation","attorney fees","madison county","huntsville"],"hasFull":true},{"id":"live-109","addedDate":"2026-09-10","title":"Ready Capital Mortgage Financing 2023-FL 12, LLC v. Drexel Flats Acquisition LLC (Oklahoma City Apartment Foreclosure)","brief":"An Oklahoma County judge granted a lender's motion for a receiver at the Drexel Flats apartments in Oklahoma City on May 20, 2026; the borrower entities appealed to the state Supreme Court.","category":"lending-foreclosure","status":"ruling","date":"2026-05-20","jurisdiction":"Oklahoma County District Court, Oklahoma","parties":[{"name":"Ready Capital Mortgage Financing 2023-FL 12, LLC","role":"Plaintiff"},{"name":"Drexel Flats Acquisition LLC","role":"Defendant"},{"name":"Drexel Flats Acquisition Tic Llc","role":"Defendant"},{"name":"Ysa Investments 1, Llc","role":"Defendant"},{"name":"Iplumb Co. Llc","role":"Defendant"},{"name":"Nix Lumber, Inc","role":"Defendant"},{"name":"Rasa Floors & Carpet Cleaning, Llc","role":"Defendant"},{"name":"Tres Palm Supply, Llc","role":"Defendant"},{"name":"The Board Of County Commissioners Of Oklahoma County","role":"Defendant"},{"name":"The Oklahoma County Treasurer","role":"Defendant"}],"amountUsd":28000000,"amountBasis":"loan","judge":"Amy Palumbo","state":"OK","amount":"$28M loan; lender alleges more than $30M is owed","source":"live","sourceUrl":"https://kfor.com/news/in-your-corner/judge-decides-to-remove-vesta-realty-as-the-property-management-company-for-sw-okc-apartment-complex/","documentUrl":"https://www.oscn.net/dockets/GetCaseInformation.aspx?db=oklahoma&number=CJ-2026-1275","documentLabel":"View the Oklahoma County District Court docket (CJ-2026-1275)","summary":"Ready Capital Mortgage Financing 2023-FL 12, LLC sued in Oklahoma County District Court on February 18, 2026 to foreclose on the Drexel Flats apartments in southwest Oklahoma City, naming borrower entities linked to Vesta Realty and its CEO, Marc Kulick. KFOR reported the suit concerns a $28 million loan that matured in January 2025 and that court papers say more than $30 million is owed. Judge Amy Palumbo granted the lender's motion for a receiver on May 20, 2026; the borrower entities posted a $200,000 cash appeal bond and filed a petition in error with the Oklahoma Supreme Court, and the lender's summary-judgment motion is pending.","significance":"The case shows a lender obtaining a receiver to take over a multifamily property's operations while the foreclosure itself is still being litigated. It is one of a number of Oklahoma County suits filed by lenders and contractors against Vesta-linked entities in 2026.","tags":["foreclosure","receivership","multifamily","oklahoma","vesta"],"hasFull":true},{"id":"live-110","addedDate":"2026-09-10","title":"Thompson Thrift Construction, Inc. v. Modus Studio, PLLC (Fayetteville Student Housing Defect Suit)","brief":"After a $13,529,726 award against contractor Thompson Thrift over a Fayetteville student housing project, an Arkansas appeals court revived its claims against architect Modus Studio despite the statute of repose.","category":"construction-defect","status":"ruling","date":"2025-04-02","jurisdiction":"Arkansas Court of Appeals","parties":[{"name":"Thompson Thrift Construction, Inc.","role":"Appellant"},{"name":"Modus Studio, PLLC","role":"Appellee"},{"name":"Center Point Contractors, Inc.","role":"Appellee"},{"name":"Icrete Technologies, LLC","role":"Appellee"},{"name":"Prestige Construction & Development, LLC","role":"Appellee"},{"name":"Roofing Systems, Inc.","role":"Appellee"},{"name":"U.S. Framing, Inc.","role":"Appellee"}],"amountUsd":13529726,"amountBasis":"award","judge":"Brandon Harrison","state":"AR","amount":"$13,529,726 underlying arbitration award against the general contractor","source":"live","sourceUrl":"https://thelawyerworld.com/blog/arkansass-five-year-construction-defect-deadline/","documentUrl":"https://caselaw.findlaw.com/court/crt-app-ark-div-iii/117132257.html","documentLabel":"Read the Arkansas Court of Appeals opinion","summary":"After owner West Center Partners, LLC won a $13,529,726 arbitration award against general contractor Thompson Thrift Construction over defects in a Fayetteville student housing project, Thompson Thrift sought to recover from the project's architect, Modus Studio, PLLC, and several subcontractors. A Washington County circuit court dismissed Thompson Thrift's refiled claims against Modus as barred by Arkansas's five-year construction statute of repose. On April 2, 2025, the Arkansas Court of Appeals reversed, holding in a case of first impression that the one-year savings statute lets a party that timely filed such claims refile them within a year of a nonsuit even after the repose period has run.","significance":"The decision establishes in Arkansas that the construction statute of repose does not cut off the savings statute for a claim first filed within the five-year window, dismissed without prejudice and refiled within a year. That gives a general contractor held liable for defects more room to pursue claims against the designers and subcontractors who did the work, and makes repose deadlines less absolute once a qualifying dismissal and timely refiling are involved.","tags":["construction defect","statute of repose","savings statute","student housing","fayetteville"],"hasFull":true},{"id":"live-111","addedDate":"2026-09-10","title":"Mississippi Supreme Court Upholds Private Title to Biloxi Waterfront Tract (Tidelands Dispute)","brief":"The Mississippi Supreme Court affirmed that about an acre of Biloxi waterfront, once leased for the Lady Luck Casino, is privately owned under a 1784 Spanish land grant rather than State tidelands.","category":"zoning-land-use","status":"ruling","date":"2024-04-04","jurisdiction":"Supreme Court of Mississippi","parties":[{"name":"The State of Mississippi","role":"Appellant"},{"name":"Secretary of State of the State of Mississippi","role":"Appellant"},{"name":"City of Biloxi","role":"Appellee"},{"name":"Biloxi Public School District","role":"Appellee"},{"name":"Harrison County, Mississippi","role":"Appellee"}],"amountUsd":null,"judge":"David M. Ishee","state":"MS","amount":"~1 acre of Biloxi waterfront commercial land at issue","source":"live","sourceUrl":"https://www.wlox.com/2024/04/04/supreme-court-judge-affirms-lower-court-ruling-aldrich-family-retain-waterfront-property/","documentUrl":"https://www.courtlistener.com/opinion/10627629/the-state-of-mississippi-and-the-secretary-of-state-of-the-state-of/","documentLabel":"Read the Mississippi Supreme Court's opinion","summary":"On April 4, 2024, the Mississippi Supreme Court affirmed a Harrison County Chancery Court ruling that roughly one acre of waterfront land in East Biloxi belongs to the family that has long held it, not to the State. The State and the Secretary of State had claimed the land as public trust tidelands under a 1994 boundary map; the chancellor traced the family's title to a 1784 Spanish land grant. The family once ran the Fisherman's Wharf restaurant on the site, and the land was later leased for the Lady Luck Casino, the Sun Herald reported.","significance":"The ruling confirms private title to a waterfront tract that the owner has optioned for a proposed casino development, with the City of Biloxi and Harrison County siding with the owner against the State. It also shows that the Secretary of State's 1994 tidelands map can be overcome where the State did not follow the statutory mapping procedures and the owner's title traces to a pre-statehood grant.","tags":["tidelands","land title","casino development","biloxi","public trust doctrine"],"hasFull":true},{"id":"live-112","addedDate":"2026-09-10","title":"State of Mississippi v. RW Development, LLC (Biloxi Casino Pier Tidelands Lease Authority)","brief":"Mississippi's Supreme Court held Biloxi had statutory authority to lease tidelands at Veterans Avenue to RW Development for a public/private pier without a lease from the Secretary of State.","category":"zoning-land-use","status":"ruling","date":"2023-03-02","jurisdiction":"Supreme Court of Mississippi","parties":[{"name":"State of Mississippi","role":"Appellant"},{"name":"RW Development, LLC","role":"Appellee"},{"name":"City of Biloxi, Mississippi","role":"Appellee"},{"name":"Harrison County, Mississippi","role":"Appellee"}],"amountUsd":null,"judge":"Coleman","state":"MS","amount":"N/A — municipal authority to lease tidelands for a casino pier upheld","source":"live","sourceUrl":"https://www.wlox.com/2023/12/21/rw-development-scores-big-with-casino-site-approval/","documentUrl":"https://www.courtlistener.com/opinion/10627673/state-of-mississippi-by-and-through-michael-watson-in-his-official/","documentLabel":"Read the Mississippi Supreme Court's opinion","summary":"The Mississippi Supreme Court on March 2, 2023 affirmed a Harrison County Chancery Court ruling that the City of Biloxi and Harrison County could lease public trust tidelands at the foot of Veterans Avenue to RW Development, LLC for a joint public/private pier without first obtaining a tidelands lease from the Secretary of State. Writing for the en banc court, Justice Coleman held that state ports and harbors statutes gave the city that authority. WLOX later reported that the lease helped RW win Mississippi Gaming Commission approval in December 2023 for a casino site at Veterans Avenue and Highway 90.","significance":"The ruling holds that specific statutory grants to Gulf Coast municipalities can authorize leases of public trust tidelands without a separate lease from the Secretary of State. For RW Development, the upheld lease became part of its successful casino site application.","tags":["tidelands","casino resort","public-private pier","biloxi","land-use authority"],"hasFull":true},{"id":"live-114","addedDate":"2026-09-10","title":"Service Credit Union v. Granite Senior Services (Littleton, NH Senior Living Construction-Loan Fraud Suit)","brief":"Service Credit Union sued the owners of an unfinished Littleton, NH senior living campus and a former SCU loan officer, alleging fraud tied to a $30 million construction loan, the Caledonian Record reported.","category":"lending-foreclosure","status":"filed","date":"2026-06-24","jurisdiction":"Grafton Superior Court, New Hampshire","parties":[{"name":"Service Credit Union","role":"Plaintiff"},{"name":"Granite Senior Services LLC","role":"Defendant"},{"name":"Granite Senior Operations LLC","role":"Defendant"},{"name":"Blue Lodge Spray Foam LLC","role":"Defendant"},{"name":"CTC Commercial LLC","role":"Defendant"}],"judge":null,"amountUsd":30000000,"amountBasis":"damages sought","state":"NH","amount":"$30M sought from the primary defendants plus $1.5M from CTC Commercial and related defendants; property valued at $22M","source":"live","sourceUrl":"https://www.nhbr.com/new-lawsuit-alleges-coordinated-fraud/","summary":"Service Credit Union (SCU) filed a 10-count suit on June 24, 2026 in Grafton Superior Court against the owners of an unfinished senior living campus at 1262 St. Johnsbury Road in Littleton, New Hampshire, their companies, a mortgage broker's firm and a former SCU loan officer, the Caledonian Record reported in an article shared by NH Business Review. The credit union alleges the defendants conspired to obtain a $30 million construction loan and used loan disbursements for their own benefit. SCU values the property at $22 million and told the court a sale likely would not cover the defaulted loan.","significance":"Because the lender's own former loan officer is a defendant, the case tests fraud claims aimed at the lender's side of a construction loan as well as the borrower's. SCU's position that a $22 million property cannot cover a $30 million loan shows the shortfall a construction lender can face when a project stops before it is finished.","tags":["construction loan fraud","credit union","senior living","bankruptcy","new hampshire"],"hasFull":true},{"id":"live-115","addedDate":"2026-09-10","title":"Greenwood Park Mall Shooting Negligent-Security Suit Against Simon Property Group (Indiana Supreme Court)","brief":"The Indiana Supreme Court heard argument Jan. 15, 2026 on whether Simon Property Group and its security contractor can be sued over the 2022 Greenwood Park Mall shooting.","category":"premises-liability","status":"appeal","date":"2026-01-15","jurisdiction":"Supreme Court of Indiana","parties":[{"name":"Simon Property Group, L.P.","role":"Appellant-Defendant"},{"name":"Universal Protection Service, LLC","role":"Appellant-Defendant"}],"judge":"Christina R. Klineman","amountUsd":null,"state":"IN","amount":"Unspecified compensatory damages sought; underlying premises-liability and negligence claims","source":"live","sourceUrl":"https://indianacapitalchronicle.com/2026/01/16/fate-of-greenwood-mall-shooting-lawsuit-now-with-indiana-supreme-court/","summary":"The Indiana Supreme Court heard oral argument on January 15, 2026 in a negligence suit brought by a woman wounded in the attack and her family against Greenwood Park Mall owner Simon Property Group, L.P. and security contractor Universal Protection Service, LLC over the July 17, 2022 food-court shooting that killed three people, the Indiana Capital Chronicle reported. The defendants argue the suit should be dismissed because such an attack could not be foreseen. A Marion County trial court and the Indiana Court of Appeals both refused to dismiss the case.","significance":"The court's answer will shape whether Indiana negligent-security claims against mall owners and their security contractors over a mass shooting can get past a motion to dismiss and into discovery. Related wrongful-death suits are on hold until it rules.","tags":["negligent security","premises liability","mall shooting","foreseeability","open carry","Indiana Supreme Court"],"hasFull":true},{"id":"live-116","addedDate":"2026-09-10","title":"Family of Shooting Victim v. The Galleria and Its Security Companies (Houston Mall Garage Shooting Negligent-Security Suit)","brief":"The family of a man killed in a Galleria parking garage in June 2025 sued the Houston mall, its parent company and its security companies, alleging they failed to enforce a ban on the suspects.","category":"premises-liability","status":"filed","date":"2026-09-03","jurisdiction":"Harris County District Court, Texas","parties":[],"judge":null,"amountUsd":1000000,"amountBasis":"damages sought","state":"TX","amount":"More than $1,000,000 sought","source":"live","sourceUrl":"https://abc13.com/post/family-sues-houstons-galleria-mall-security-companies-2025-fatal-shooting-lawsuit-says/19782644/","summary":"The family of a man who was shot and killed in a parking garage at Houston's Galleria mall on June 3, 2025, has sued the shopping center, its parent company and the security companies responsible for the property, ABC13 reported on September 3, 2026. The family alleges the two men accused of the shooting had been banned from the mall but were able to return, and that the mall and its security providers were negligent in failing to enforce their own policies. The suit seeks more than $1 million.","significance":"The claim turns on whether the property enforced bans it had already issued against specific people, not on the area's general crime history. Malls and other large properties that keep ban lists may face the same question about how those bans work in practice.","tags":["negligent security","premises liability","shopping mall","parking garage","ban enforcement","Texas"],"hasFull":true},{"id":"live-117","addedDate":"2026-09-10","title":"Publix Super Markets Slip-and-Fall Verdict (Kissimmee, Osceola County, Florida)","brief":"An Osceola County jury found Publix 100% liable and awarded $3,967,000 over a fall on liquid in a Kissimmee store's soft drink aisle; Publix has moved for a new trial over the medical-bill evidence.","category":"premises-liability","status":"ruling","date":"2026-02-24","jurisdiction":"Ninth Judicial Circuit Court, Osceola County, Florida","parties":[{"name":"Publix Super Markets, Inc.","role":"Defendant"}],"judge":null,"amountUsd":3967000,"amountBasis":"award","state":"FL","amount":"$3,967,000 jury verdict","source":"live","sourceUrl":"https://www.prnewswire.com/news-releases/rubenstein-law-secures-3-967-000-jury-verdict-against-publix-super-markets-inc-in-osceola-county-302696076.html","summary":"An Osceola County jury in February 2026 found Publix Super Markets, Inc. 100% responsible for a shopper's June 5, 2023 fall on liquid in the soft drink aisle of its North John Young Parkway store in Kissimmee and awarded $3,967,000, according to News 6 (WKMG) and a press release from the plaintiff's law firm. Publix denied liability at trial, and in March 2026 it moved for a new trial on damages, arguing the court let the jury see inflated medical bills in violation of Florida law.","significance":"Evidence that employees had cleaned liquid in the same area before the fall was central to the plaintiff's case, according to her law firm, which shows how a store's own cleanup history can be used to prove notice of a hazard. Publix's motion also tests the Florida statute that limits how past medical expenses may be proved at trial.","tags":["slip and fall","premises liability","grocery store","prior notice","Florida"],"hasFull":true},{"id":"live-118","addedDate":"2026-09-10","title":"The Original Saugus Café LLC v. North Valley Construction Co. LLC (Wrongful Lockout Suit)","brief":"The longtime operator of Santa Clarita's Original Saugus Café sued North Valley Construction Co. LLC and the property's owners, alleging a Jan. 5, 2026 lockout without court process and attempts to trademark the café's name.","category":"lease-disputes","status":"filed","date":"2026-01-14","jurisdiction":"Los Angeles County Superior Court","parties":[{"name":"The Original Saugus Café LLC","role":"Plaintiff"},{"name":"North Valley Construction Co. LLC","role":"Defendant"}],"judge":null,"amountUsd":1000000,"amountBasis":"damages sought","state":"CA","amount":"Damages exceeding $1,000,000 sought","source":"live","sourceUrl":"https://www.hometownstation.com/santa-clarita-news/community-news/original-saugus-cafe-operator-alleges-wrongful-lockout-trademark-theft-in-lawsuit-578829","summary":"The longtime operator of the Original Saugus Café in Santa Clarita and his company, The Original Saugus Café LLC, sued North Valley Construction Co. LLC, the trustee of the landlord family's trust and the trust's property manager on January 14, 2026 in Los Angeles County Superior Court, KHTS reported. He alleges he arrived on January 5 to find the locks changed and was barred from retrieving equipment and inventory, and that the defendants tried to file trademark applications for the café's name without his consent. The 16-count complaint alleges damages exceeding $1 million.","significance":"The case tests a commercial tenant's claims over a lockout carried out without a court process, together with a fight over who owns a long-running restaurant's name. The allegations have not been tested in court.","tags":["wrongful lockout","self-help eviction","commercial lease dispute","restaurant","California"],"hasFull":true},{"id":"live-119","addedDate":"2026-09-10","title":"The State of Texas v. JRJ Pusok Holdings, LLC","brief":"The Texas Supreme Court held the State cannot invoke sovereign immunity to block JRJ Pusok Holdings' statutory right to repurchase surplus Tomball land TxDOT condemned for a highway project.","category":"eminent-domain","status":"ruling","date":"2026-06-12","jurisdiction":"Supreme Court of Texas","parties":[{"name":"The State of Texas","role":"Petitioner"},{"name":"JRJ Pusok Holdings, LLC","role":"Respondent"}],"amountUsd":null,"judge":"Jane Bland","state":"TX","amount":"N/A — no monetary judgment; case remanded to the trial court for further proceedings on the merits","source":"live","sourceUrl":"https://texasscorecard.com/state/texas-supreme-court-sides-with-citizens-in-eminent-domain-dispute/","summary":"The Supreme Court of Texas held on June 12, 2026 that the State cannot invoke sovereign immunity to defeat a former landowner's claim under Chapter 21 of the Texas Property Code to repurchase condemned land no longer needed for public use, Texas Scorecard reported. The case involves a Mueschke Road property in Tomball that TxDOT acquired for a road project along the Grand Parkway after filing a condemnation suit in 2014; the owners agreed to sell before judgment, and TxDOT later said about 20,000 square feet was surplus after the road was rerouted. Justice Jane Bland wrote for a six-justice majority affirming the Fourteenth Court of Appeals and remanding to the trial court; Justice Young concurred, and Justice Hawkins dissented, joined by Justice Sullivan and, except as to one part, Chief Justice Blacklock.","significance":"The ruling limits a condemning authority's ability to keep land it acquired under a condemnation suit once the project no longer needs it: the repurchase right applies even when the suit settled before judgment, and it can reach only the surplus portion of a tract. Owners of land along road and utility corridors should track whether condemned parcels later become unnecessary for the stated use.","documentUrl":"https://search.txcourts.gov/SearchMedia.aspx?MediaVersionID=ed3ce8c0-36e7-4012-b9c8-46156f1eb2b8&coa=cossup&DT=OPINION&MediaID=b4db616d-131b-4712-868f-19275f6c0139","documentLabel":"Read the official opinion","tags":["eminent domain","sovereign immunity","repurchase right","TxDOT","condemnation","Texas"],"docketUrl":"https://search.txcourts.gov/Case.aspx?cn=24-0447&coa=cossup","docketLabel":"Tex. Sup. Ct. No. 24-0447","hasFull":true},{"id":"live-120","addedDate":"2026-09-10","title":"City of San Antonio and Toyota Motor Manufacturing Texas, Inc. v. Southside Affordable Development, LLC","brief":"The Fourth Court of Appeals dismissed Southside Affordable Development's challenge to San Antonio's Toyota zoning agreement, finding no standing because the challenged ordinances predated its purchase.","category":"zoning-land-use","status":"ruling","date":"2025-07-16","jurisdiction":"Fourth Court of Appeals, San Antonio, Texas","parties":[{"name":"City of San Antonio","role":"Appellant"},{"name":"Toyota Motor Manufacturing Texas, Inc.","role":"Appellant"},{"name":"Southside Affordable Development, LLC","role":"Appellee"}],"amountUsd":null,"judge":"H. Todd McCray","state":"TX","amount":"N/A — claims dismissed with prejudice for lack of standing","source":"live","sourceUrl":"https://www.ksat.com/news/local/2023/12/05/lawsuit-filed-against-city-toyota-alleges-20-year-agreement-is-unconstitutional/","summary":"The Fourth Court of Appeals in San Antonio on July 16, 2025 reversed the trial court and dismissed with prejudice Southside Affordable Development, LLC's claims against the City of San Antonio challenging the 2003 Project Starbright Agreement, which addresses zoning within a three-mile \"Enhanced Zoning Area\" around Toyota's South Side plant. Southside, which sued the city and Toyota in December 2023 after city officials said they would not support rezoning part of its 97-acre tract for multifamily housing, called the arrangement unconstitutional contract zoning and a taking, KSAT reported. The appeals court held Southside lacked standing because the challenged ordinances predated its 2017 purchase and it showed no assignment of the prior owner's claims.","significance":"A cautionary tale for any developer buying into an area covered by a long-standing development agreement between a city and a major industrial tenant: a purchaser who did not own the land when the underlying ordinances were adopted generally cannot revive a constitutional challenge to them absent an explicit assignment of claims from the prior owner, and informal statements of non-support from city staff do not themselves trigger a takings claim. Developers eyeing land inside negotiated 'enhanced zoning area' buffers near large industrial users should diligence the origin and assignability of any zoning challenge before relying on it as a path around a restrictive framework.","documentUrl":"https://search.txcourts.gov/SearchMedia.aspx?MediaVersionID=af4b9665-0b2d-4219-b13c-d41c95355ab9&coa=coa04&DT=Opinion&MediaID=467bb86a-40fa-4100-b63a-b7e9f88def9b","documentLabel":"Read the official opinion","tags":["contract zoning","standing","Toyota","Starbright Agreement","takings","Texas"],"docketUrl":"https://search.txcourts.gov/Case.aspx?cn=04-24-00371-CV&coa=coa04","docketLabel":"Tex. App.—San Antonio No. 04-24-00371-CV","hasFull":true},{"id":"live-121","addedDate":"2026-09-10","title":"ATC Indoor DAS LLC v. MM CCM 48M Leasing, LLC and MM CCM 48M, LLC (Collin Creek Mall Lease Dispute)","brief":"A Dallas appeals court held the buyer of Collin Creek Mall could not invoke impracticability to excuse ending ATC Indoor DAS's antenna lease, which it had assumed and performed, and rendered judgment for ATC.","category":"lease-disputes","status":"ruling","date":"2026-01-29","jurisdiction":"Fifth Court of Appeals, Dallas, Texas","parties":[{"name":"ATC Indoor DAS LLC","role":"Appellant"},{"name":"MM CCM 48M Leasing, LLC","role":"Appellee"},{"name":"MM CCM 48M, LLC","role":"Appellee"}],"amountUsd":null,"judge":"Emily Miskel","state":"TX","amount":"N/A — summary judgment reversed and rendered in part on liability; remanded in part on attorney's fees","source":"live","sourceUrl":"https://tcjl.com/dallas-court-of-appeals-rules-for-tenant-in-lease-dispute-arising-from-failed-shopping-mall/","summary":"The Fifth Court of Appeals in Dallas reversed a summary judgment for the owners of the closed Collin Creek Mall in Plano and rendered judgment for wireless-infrastructure tenant ATC Indoor DAS LLC on its breach-of-contract claim, according to the Texas Civil Justice League's summary of the January 29, 2026 opinion. MM CCM 48M, LLC bought the mall in 2018, assumed ATC's host lease and performed under it for several months before a letter from MM CCM 48M Leasing, LLC ended the lease, said the mall had closed and gave ATC 30 days to remove its equipment. The court held the buyer was quasi-estopped from claiming impracticability and that the defense failed anyway because shifting market conditions do not excuse performance; it remanded ATC's attorney's fees claim and its claims against MM CCM 48M Leasing.","significance":"The decision confirms that a buyer who knowingly acquires a declining property, assumes its leases and performs under them cannot later argue that the property's decline made those leases impracticable. Buyers of retail properties with specialty tenants, such as antenna, rooftop or signage leases, should treat assumed leases as binding even if they plan to close or redevelop the property.","documentUrl":"https://search.txcourts.gov/SearchMedia.aspx?MediaVersionID=9ab2edf3-a327-460b-b90f-ba8d569dcf7d&coa=coa05&DT=Opinion&MediaID=34d9bf60-5c2e-4396-853c-1476010f8451","documentLabel":"Read the official opinion","tags":["shopping mall","lease assumption","impossibility defense","distributed antenna system","Collin Creek Mall","Texas"],"docketUrl":"https://search.txcourts.gov/Case.aspx?cn=05-24-00769-CV&coa=coa05","docketLabel":"Tex. App.—Dallas No. 05-24-00769-CV","hasFull":true},{"id":"live-122","addedDate":"2026-09-10","title":"Holiday Inn Club Vacations Inc. v. CBRE, Inc., ACI Architectural Concepts, Inc., and T&G Corporation f/k/a T&G Constructors","brief":"The Fourteenth Court of Appeals revived Holiday Inn Club Vacations' water-intrusion defect suit against CBRE, T&G and ACI over a Galveston resort, reversing a take-nothing summary judgment on limitations and other grounds.","category":"construction-defect","status":"ruling","date":"2025-02-04","jurisdiction":"Fourteenth Court of Appeals, Houston, Texas","parties":[{"name":"Holiday Inn Club Vacations Inc.","role":"Appellant"},{"name":"CBRE, Inc.","role":"Appellee"},{"name":"ACI Architectural Concepts, Inc.","role":"Appellee"},{"name":"T&G Corporation f/k/a T&G Constructors","role":"Appellee"}],"amountUsd":null,"judge":"Kevin Jewell","state":"TX","amount":"N/A — take-nothing summary judgment reversed and remanded for further proceedings","source":"live","sourceUrl":"https://www.wshblaw.com/publication-texas-court-revives-construction-defect-claims-key-lessons-for-managing-latent-defect-risk","summary":"On February 4, 2025, the Fourteenth Court of Appeals in Houston reversed a take-nothing summary judgment against Holiday Inn Club Vacations Inc. in its construction-defect suit over the Holiday Inn Club Vacations Galveston Seaside Resort. The court held that CBRE, Inc., T&G Corporation f/k/a T&G Constructors and ACI Architectural Concepts, Inc. had not conclusively established their limitations defenses, that Holiday Inn raised fact issues on its standing and capacity to sue CBRE as the original owner's assignee, and that the economic loss rule did not conclusively bar its negligence claim. Rehearing was denied, and the Supreme Court of Texas denied review in October 2025.","significance":"The opinion holds that evidence an owner knew of some leaks during construction does not by itself start the limitations clock on later, broader defect claims unless the defendant ties those early leaks to the damage being sued over. It also treats an anti-assignment clause covering \"the agreement\" as no bar to a successor owner pursuing an assigned claim for breach.","documentUrl":"https://search.txcourts.gov/SearchMedia.aspx?MediaVersionID=9bacebca-5e6c-4ae3-980b-cfa1ca4695ae&coa=coa14&DT=Opinion&MediaID=f6979f28-a233-454f-960c-ad8a564acff9","documentLabel":"Read the official opinion","tags":["construction defect","water intrusion","discovery rule","statute of limitations","CBRE","timeshare resort","Texas"],"docketUrl":"https://search.txcourts.gov/Case.aspx?cn=14-23-00976-CV&coa=coa14","docketLabel":"Tex. App.—Houston [14th Dist.] No. 14-23-00976-CV","propertyType":"Hospitality","hasFull":true},{"id":"live-124","addedDate":"2026-09-10","title":"California Department of Toxic Substances Control Settlement Over Former Halford's Cleaners Site (Modesto Groundwater Contamination Superfund Site)","brief":"A federal judge approved DTSC's $2 million consent decree with the owners of the Modesto property that housed Halford's Cleaners, resolving the state's cleanup-cost claims over PCE contamination.","category":"environmental","status":"settled","date":"2026-07-07","jurisdiction":"U.S. District Court, Eastern District of California","parties":[{"name":"California Department of Toxic Substances Control","role":"Plaintiff"},{"name":"Toxic Substances Control Account","role":"Plaintiff"}],"judge":"John A. Mendez","amountUsd":2000000,"amountBasis":"settlement","state":"CA","amount":"$2M consent-decree settlement","source":"live","sourceUrl":"https://dtsc.ca.gov/2026/07/15/dtsc-secures-2-million-settlement-for-cleanup-at-the-modesto-groundwater-contamination-superfund-site/","summary":"On July 7, 2026, Senior U.S. District Judge John A. Mendez approved a consent decree under which the owners of the property at 941 McHenry Avenue in Modesto, where Halford's Cleaners operated, will pay the California Department of Toxic Substances Control and the Toxic Substances Control Account $2 million toward past and future cleanup costs at the Modesto Groundwater Contamination Superfund site. DTSC's complaint, filed February 26, 2026 together with the proposed decree, sought cost recovery under CERCLA from the owners, who had leased the property to dry-cleaning operators. The owners did not admit liability. DTSC announced the settlement on July 15, 2026.","significance":"The case shows California's toxic-substances agency recovering cleanup costs under CERCLA from the landlords of a long-running dry-cleaning tenant as owners of the facility, years after the same owners settled with the EPA. For owners and buyers of property leased to dry cleaners, the site's history shows how solvent contamination can produce government claims over decades.","tags":["environmental","CERCLA","Superfund","dry cleaner","PCE contamination","current-owner liability","California"],"docketUrl":"https://www.courtlistener.com/docket/72337565/ca-dept-of-toxic-substances-control-v-lyon/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-125","addedDate":"2026-09-10","title":"The Mission LLC v. State of California and City of Santa Barbara","brief":"A federal judge dismissed, with leave to amend, The Mission LLC's suit claiming SB 158 singles out its 270-unit builder's-remedy project behind the Santa Barbara Mission; it filed an amended complaint July 10.","category":"zoning-land-use","status":"ruling","date":"2026-06-02","jurisdiction":"U.S. District Court, Central District of California","parties":[{"name":"The Mission LLC","role":"Plaintiff"},{"name":"The State of California","role":"Defendant"},{"name":"The City of Santa Barbara","role":"Defendant"}],"amountUsd":null,"judge":"Hernán D. Vera","state":"CA","amount":"N/A: declaratory and injunctive relief; first complaint dismissed with leave to amend","source":"live","sourceUrl":"https://www.independent.com/2026/06/10/federal-judge-dismisses-mission-llcs-lawsuit-against-state-city-of-santa-barbara/","summary":"On June 2, 2026, U.S. District Judge Hernán D. Vera dismissed The Mission LLC's suit against the State of California and the City of Santa Barbara, finding it unripe because the project application is still under review and that the company had not overcome the state's sovereign immunity, the Santa Barbara Independent reported. The company alleges SB 158, a budget trailer bill, illegally singles out its 270-unit builder's-remedy project behind the Santa Barbara Mission. The judge said the law raises \"serious constitutional questions\" and allowed an amended complaint, which the company filed on July 10, 2026; the defendants have moved to dismiss again.","significance":"The ruling leaves open a constitutional challenge to a state law the developer says targets a single project, while holding that the challenge must wait for a concrete dispute. The case continues on the amended complaint.","tags":["builder's remedy","SB 158","equal protection","sovereign immunity","ripeness","housing element","California"],"docketUrl":"https://www.courtlistener.com/docket/71746386/the-mission-llc-v-the-state-of-california/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-127","addedDate":"2026-09-11","title":"Anchorage Community Development Authority v. Hughes Family LLC and Anchorage Innovation District LLC (Downtown Nordstrom Site Partition Action)","brief":"The Anchorage Community Development Authority, which owns four of the five lots at the former downtown Nordstrom, sued two co-owner companies seeking a court-ordered sale, citing an impasse.","category":"eminent-domain","status":"filed","date":"2026-07-21","jurisdiction":"Superior Court for the State of Alaska, Third Judicial District at Anchorage","parties":[{"name":"Anchorage Community Development Authority","role":"Plaintiff"},{"name":"Hughes Family LLC","role":"Defendant"},{"name":"Anchorage Innovation District LLC","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"AK","amount":"Partition and court-ordered sale sought; proceeds to be split proportionately (ACDA holds an 80% interest)","source":"live","sourceUrl":"https://www.adn.com/alaska-news/anchorage/2026/08/12/anchorage-agency-sues-landowners-to-advance-redevelopment-at-former-nordstrom-building/","summary":"The Anchorage Community Development Authority sued Hughes Family LLC and Anchorage Innovation District LLC on July 21, 2026 in state Superior Court, asking the court to order the sale of all five lots of the former Nordstrom building in downtown Anchorage, the Anchorage Daily News reported. ACDA owns 80% of the building, or four of the five lots, and says it is at \"an impasse\" with the other two companies over redevelopment. It asks that sale proceeds be split proportionally among the three.","significance":"The suit shows how split ownership of a redevelopment site can stall a public agency's plans, leaving a court-ordered sale as the majority owner's chosen route. The outcome will shape who controls the former Nordstrom site that the city has targeted for redevelopment.","tags":["partition action","redevelopment authority","co-ownership dispute","downtown revitalization","Alaska"],"hasFull":true},{"id":"live-129","addedDate":"2026-09-12","title":"LDG Development, LLC v. City of Prospect, Kentucky (Prospect Cove Fair Housing Zoning-Denial Verdict)","brief":"A Jefferson County jury awarded LDG Development $36.3 million against Prospect, Kentucky, finding the city violated the Fair Housing Act and the Equal Protection Clause in opposing a 198-unit senior apartment project.","category":"zoning-land-use","status":"ruling","date":"2026-08-25","jurisdiction":"Jefferson Circuit Court, Kentucky","parties":[{"name":"LDG Development","role":"Plaintiff"},{"name":"City of Prospect","role":"Defendant"},{"name":"Louisville Metro Government","role":"Defendant (settled)"}],"judge":null,"amountUsd":36300000,"amountBasis":"award","state":"KY","amount":"$36.3M jury verdict, including more than $7.3M in punitive damages (per LDG's counsel)","source":"live","sourceUrl":"https://www.law360.com/real-estate-authority/residential/articles/2518782","summary":"A Jefferson County, Kentucky jury on August 25, 2026 awarded affordable-housing developer LDG Development $36.3 million against the City of Prospect, ruling for LDG on five of eight counts, including Fair Housing Act and equal protection claims, Louisville Public Media and Law360 reported. LDG's trial counsel said the award includes more than $7.3 million in punitive damages. The case arose from the Louisville Metro Council's 2017 rejection of LDG's Prospect Cove senior apartment project; Louisville Metro settled separately for $6 million and policy changes. Prospect's mayor said the city disagrees with the verdict and is evaluating its next steps.","significance":"The verdict puts a dollar figure on a suburb's opposition to an affordable housing project, even though the zoning vote itself was cast by Louisville Metro Council. Developers and local governments will watch whether the award holds up if Prospect challenges it.","tags":["fair housing","zoning denial","affordable housing","equal protection","kentucky"],"hasFull":true},{"id":"live-130","addedDate":"2026-09-12","title":"Town of Nahant v. Northeastern University (East Point Eminent Domain Reversal)","brief":"The Massachusetts SJC reversed a Superior Court ruling that Nahant's easement taking on Northeastern University's East Point land was in bad faith, and ordered entry of an order establishing the town's right to take.","category":"eminent-domain","status":"ruling","date":"2026-09-03","jurisdiction":"Massachusetts Supreme Judicial Court","parties":[{"name":"Town of Nahant","role":"Petitioner"},{"name":"Northeastern University","role":"Respondent"}],"amountUsd":null,"state":"MA","amount":"Just compensation not yet set; the SJC vacated a Superior Court award of more than $1 million in fees and costs to Northeastern","source":"live","sourceUrl":"https://law.justia.com/cases/massachusetts/supreme-court/2026/sjc-13844.html","summary":"On September 3, 2026, the Massachusetts Supreme Judicial Court reversed a Superior Court judgment that had dismissed the Town of Nahant's petition to take conservation and access easements over about 12 acres of Northeastern University's land at East Point, and it vacated an award of more than $1 million in fees and costs to the university. Writing for the court, Justice Elizabeth Dewar held that Northeastern had no reasonable expectation of proving the taking was a bad-faith pretext to block its planned Marine Science Center expansion. The case was remanded for entry of an order establishing the town's right to take.","significance":"The decision holds that a town's documented conservation and open-space purpose can support a taking even when the town pursued it in response to a specific development and the taking will block that project. As the SJC reads its 1987 Pheasant Ridge decision, the bad-faith rule reaches extreme cases where the stated purpose is not genuinely intended, not every taking driven partly by opposition to a project.","judge":"Elizabeth Dewar","tags":["eminent domain","public purpose","pretext doctrine","university property","massachusetts"],"hasFull":true},{"id":"live-131","addedDate":"2026-09-12","title":"Jovia Financial Federal Credit Union v. S Indiana Avenue LLC (South Loop Office Foreclosure & Personal Guaranty Suit)","brief":"Jovia Financial Federal Credit Union filed a $17.1 million foreclosure on a 129,200-square-foot South Loop office building after the State of Illinois ended its primary tenant's lease, and is also pursuing the owner's principal under a personal guaranty.","category":"lending-foreclosure","status":"filed","date":"2026-09-04","jurisdiction":"Circuit Court of Cook County, Illinois","parties":[{"name":"Jovia Financial Federal Credit Union","role":"Plaintiff"},{"name":"S Indiana Avenue LLC","role":"Defendant"}],"judge":null,"amountUsd":17100000,"amountBasis":"loan","state":"IL","amount":"$17.1M sought, including under an unlimited personal guaranty","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/09/11/reuven-rivlin-faces-jovias-south-loop-office-foreclosure/","summary":"On September 4, 2026, Jovia Financial Federal Credit Union filed a $17.1 million foreclosure suit in Cook County Circuit Court against S Indiana Avenue LLC, an entity controlled by Lakewood, New Jersey investor Reuven Y. Rivlin, over a 10-story, 129,200-square-foot office building at 1911-1921 South Indiana Avenue. The credit union says the borrower defaulted on a $17.5 million mortgage after a three-month forbearance agreement expired in June. The building's primary tenant, a state agency that leased space for the Department of Children and Family Services, stopped paying rent after December 2025, and a state spokesperson told The Real Deal the lease was terminated for cause.","significance":"A single-tenant office loan can fail quickly when the tenant can terminate over the building's condition; here the state cited code violations and structural maintenance problems. Because the lender is also suing under an unlimited personal guaranty, its recovery is not limited to what the building sells for.","tags":["foreclosure","personal guaranty","office","government tenant","illinois"],"hasFull":true},{"id":"live-132","addedDate":"2026-09-12","title":"Portland Music Holdings LLC v. City of Portland (Targeted Zoning Buffer Takings & Due Process Suit)","brief":"Portland Music Holdings sued Portland, Maine in federal court, alleging councilors adopted a moratorium and a buffer between large music venues to block its proposed 3,300-seat venue next to Merrill Auditorium.","category":"zoning-land-use","status":"pending","date":"2026-06-09","jurisdiction":"U.S. District Court, District of Maine","parties":[{"name":"Portland Music Holdings LLC","role":"Plaintiff"},{"name":"City of Portland","role":"Defendant"}],"judge":"John C. Nivison","amountUsd":null,"state":"ME","amount":"No dollar amount reported","source":"live","sourceUrl":"https://www.pressherald.com/2026/06/09/group-that-sought-live-nation-music-venue-in-portland-sues-city-over-buffer/","summary":"Portland Music Holdings LLC sued the City of Portland, Maine in the U.S. District Court for the District of Maine on June 9, 2026, alleging councilors illegally blocked its proposed 3,300-seat music venue by voting for a 180-day moratorium and then a buffer between large music venues, the Portland Press Herald reported. The city has moved to dismiss, and Magistrate Judge John C. Nivison heard oral argument on that motion on September 30, 2026, according to the court docket.","significance":"The case tests a developer's claim that a zoning change applied retroactively to a pending project was adopted to stop that project rather than for a planning reason. The ruling on the city's motion to dismiss will show whether such a claim can proceed in federal court.","tags":["zoning","moratorium","section 1983","music venue","maine"],"docketUrl":"https://www.courtlistener.com/docket/73457710/portland-music-holdings-llc-v-city-of-portland/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-133","addedDate":"2026-09-13","title":"KREF Capital LLC v. LAK Bourse Owner, LLC (Bourse Building Mortgage Default Suit)","brief":"KKR Real Estate Finance Trust sought a $24.2 million judgment and a public sale of Philadelphia's Bourse after hotel conversion work stopped amid the owners' partnership split; the case was dropped Oct. 12.","category":"lending-foreclosure","status":"ruling","date":"2026-07-28","jurisdiction":"U.S. District Court for the Eastern District of Pennsylvania","parties":[{"name":"KREF Capital LLC","role":"Plaintiff"},{"name":"LAK Bourse Owner, LLC","role":"Defendant"},{"name":"LAK Bourse Master HTC Landlord, LLC","role":"Defendant"}],"judge":null,"amountUsd":24200000,"amountBasis":"damages sought","state":"PA","amount":"$24.2M judgment sought plus interest and fees; the $83.7M loan also financed 400 Market St., which is not part of the suit","source":"live","sourceUrl":"https://www.inquirer.com/real-estate/commercial/bourse-keystone-dean-adler-lawsuit-20260807.html","summary":"KKR Real Estate Finance Trust, through plaintiff KREF Capital LLC, sued LAK Bourse Owner, LLC and LAK Bourse Master HTC Landlord, LLC in the U.S. District Court for the Eastern District of Pennsylvania on July 28, 2026, seeking a $24.2 million judgment plus interest and fees and a public auction of the Bourse, The Philadelphia Inquirer reported. The lender alleged the owners defaulted when the development team abandoned its hotel-conversion plans and stopped work amid a split between Dean Adler and Keystone Development + Investment. The lender voluntarily dismissed the case on October 12, 2026, according to the court docket.","significance":"The lender moved for a forced sale while the sponsors' control fight was still before the Delaware court. Its notice of dismissal gives no reason, and the sources reviewed do not report how the loan default or the Delaware dispute was resolved.","tags":["foreclosure","joint venture breakup","hotel conversion","pennsylvania","voluntary dismissal"],"docketUrl":"https://www.courtlistener.com/docket/73680947/kref-capital-llc-v-lak-bourse-owner-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-134","addedDate":"2026-09-13","title":"Palm Beach Marriott Singer Island Condominium Association v. Urgo Hotels (Hotel-Condo Shared-Facility Fee Dispute)","brief":"The condo association at the 239-unit Palm Beach Marriott Singer Island is seeking punitive damages and a freeze on fees charged by hotel owner Urgo Hotels; its lawyer says fees charged since 2013 could top $45 million. Trial is set for early 2027.","category":"lease-disputes","status":"pending","date":"2026-09-11","jurisdiction":"Circuit Court, Fifteenth Judicial Circuit, Palm Beach County, Florida","parties":[{"name":"Palm Beach Marriott Singer Island Condominium Association","role":"Plaintiff"},{"name":"Urgo Hotels","role":"Defendant (hotel owner)"},{"name":"UH-SI LLC","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"FL","amount":"Association's attorney says fees charged since 2013 could exceed $45M; punitive damages sought","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/09/11/inside-florida-hotel-condo-owners-overcharging-lawsuit/","summary":"The condominium association for the 239-unit Palm Beach Marriott Singer Island in Riviera Beach, Florida, sued the hotel's owner, Urgo Hotels, in 2015, alleging unit owners were charged duplicative fees for the upkeep of shared facilities. In August 2026 the association asked the court for punitive damages and a temporary stay of the fees ahead of a trial set for early 2027. Its attorney, Stevan Pardo, told The Real Deal the fees charged since 2013 could exceed $45 million. Urgo has argued in court filings that a 2013 settlement of an earlier suit should have ended the case.","significance":"In a hotel-condominium the hotel owner usually controls the shared facilities and sets what unit owners pay for them, so disputes turn on whether the fees track real costs. Hotel owners and associations both benefit from itemized accounting of formula-based charges such as per-occupied-day fees, because disputes over those charges can run for years.","tags":["hotel condominium","fee dispute","punitive damages","operator dispute","florida"],"hasFull":true},{"id":"live-135","addedDate":"2026-09-13","title":"Soros Fund Management v. Eretz Group (224 West 57th Street Foreclosure)","brief":"Soros Fund Management, which bought the defaulted $145 million mortgage, took back 224 West 57th Street at a Sept. 1 foreclosure auction; owner Eretz says the foreclosure was a lease-exit scheme.","category":"lending-foreclosure","status":"ruling","date":"2026-09-01","jurisdiction":"New York County Supreme Court","parties":[{"name":"Soros Fund Management","role":"Plaintiff (Lender)"},{"name":"The Eretz Group","role":"Defendant (Borrower/Owner)"}],"judge":null,"amountUsd":158700000,"amountBasis":"judgment","state":"NY","amount":"$158.7M foreclosure judgment (on a $145M original mortgage)","source":"live","sourceUrl":"https://www.crainsnewyork.com/real-estate/commercial/cny-two-midtown-buildings-return-to-lenders-20260901/","summary":"224 West 57th Street, a Midtown Manhattan office building whose principal tenant is the Open Society Foundations, was sold back to its lender, Soros Fund Management, at a foreclosure auction on September 1, 2026, Crain's New York Business reported. Soros Fund bought the defaulted $145 million mortgage from Aareal Capital in 2023 and sued owner Eretz Group to foreclose in April 2024; Crain's reported a $158.7 million foreclosure judgment. Eretz has alleged that the mortgage purchase and foreclosure were a scheme to let Open Society leave its lease early without paying termination penalties.","significance":"The case shows a lender linked to a building's main tenant using a purchased mortgage to take control of the property. The owner's claim that the foreclosure was a way around lease-termination penalties remains its allegation; the auction went forward after the judgment was entered.","tags":["foreclosure","office","loan default","new york"],"hasFull":true},{"id":"live-136","addedDate":"2026-09-13","title":"Cimerring v. Arbor Realty Trust, Inc. ($175M Georgia Bridge-Loan Foreclosure Fraud Suit)","brief":"Former owners of a 474-unit College Park, Georgia apartment complex are suing Arbor Realty Trust for $175 million, alleging it held out a Fannie Mae refinancing before foreclosing; Arbor denies the claims and has moved to dismiss.","category":"lending-foreclosure","status":"pending","date":"2026-03-27","jurisdiction":"New York state court","parties":[{"name":"Arbor Realty Trust","role":"Defendant"},{"name":"Velocity Consulting","role":"Defendant"}],"judge":null,"amountUsd":175000000,"amountBasis":"damages sought","state":"GA","amount":"$175M sought in damages","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/07/16/arbor-sued-for-fraud/","summary":"Brothers Yisroel and Hanoch Cimerring, who bought the 474-unit Chelsea Gardens Apartments in College Park, Georgia for nearly $45 million in 2022, sued Arbor Realty Trust in New York state court in late March 2026, seeking $175 million. They allege Arbor kept them on a high-rate bridge loan with promises of a Fannie Mae refinancing that never closed, ending in a foreclosure where an Arbor affiliate bought the property for $40 million. Arbor denies the allegations and in June asked the court to dismiss the case, saying the refinancing stalled because the owners would not make required repairs. Due diligence firm Velocity Consulting, also a defendant, has moved to dismiss as well.","significance":"For borrowers on bridge loans, a lender's statements about a future agency refinancing are not a commitment, especially when approval depends on inspections and repairs. Lenders should document refinancing conditions clearly, since a stalled takeout followed by a foreclosure sale to the lender's own affiliate invites this kind of suit.","tags":["bridge loan","foreclosure","fraud","multifamily","georgia"],"hasFull":true},{"id":"live-137","addedDate":"2026-09-14","title":"United States v. Joshua Schuster ($13.8M Real Estate Investor Fraud Sentencing)","brief":"Former New York developer Josh Schuster was sentenced on August 11, 2026 to four years in federal prison for securities fraud in what The Real Deal called a $13 million Ponzi scheme; the court also entered a $13.8 million forfeiture money judgment.","category":"reit-securities","status":"ruling","date":"2026-08-11","jurisdiction":"U.S. District Court, Southern District of New York","parties":[{"name":"United States of America","role":"Plaintiff"}],"amountUsd":13830665,"amountBasis":"other","state":"NY","amount":"$13.8M forfeiture money judgment; 4 years federal prison","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/08/11/josh-schuster-gets-4-years-in-prison-for-ponzi-scheme/","summary":"U.S. District Judge Valerie E. Caproni of the Southern District of New York sentenced developer Joshua Schuster on August 11, 2026 to four years in prison and three years of supervised release. Schuster pleaded guilty on February 27, 2026 to one count of securities fraud. The judgment requires forfeiture of $13,830,665, and the court entered a separate restitution order on October 7, 2026. His surrender date was later moved to November 17, 2026.","significance":"Sponsors who raise money from investors for development deals face criminal exposure, not just civil claims, when they misuse it. Investors should note that forfeiture and restitution are separate; here the court set the forfeiture amount at sentencing and decided restitution about two months later.","tags":["securities fraud","investor fraud","sentencing","ponzi scheme","new york"],"judge":"Valerie E. Caproni","docketUrl":"https://www.courtlistener.com/docket/70189262/united-states-v-schuster/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-138","addedDate":"2026-09-14","title":"Gunwerks, LLC v. Forward Cody Wyoming, Inc. (Manufacturing Facility Design-Build Third-Party Beneficiary Appeal)","brief":"The Wyoming Supreme Court revived Gunwerks' $14 million suit over defects at its Cody manufacturing facility, reinstating claims against the architect and contractor and against Forward Cody.","category":"construction-defect","status":"ruling","date":"2026-02-02","jurisdiction":"Supreme Court of Wyoming","parties":[{"name":"Gunwerks, LLC","role":"Appellant/Plaintiff"},{"name":"Forward Cody Wyoming, Inc.","role":"Appellee/Defendant"},{"name":"Sletten Construction of Wyoming, Inc.","role":"Appellee/Crossclaim Defendant"},{"name":"Plan One Architects","role":"Appellee/Crossclaim Defendant"}],"amountUsd":14000000,"amountBasis":"damages sought","state":"WY","amount":"$14M sought in underlying construction-defect claims","source":"live","sourceUrl":"https://cowboystatedaily.com/2026/02/02/wyoming-supreme-court-revives-gunmakers-14m-lawsuit-over-business-council-project/","summary":"On February 2, 2026, the Wyoming Supreme Court unanimously reversed two Park County District Court rulings in Gunwerks, LLC v. Forward Cody Wyoming, Inc., 2026 WY 16. The district court had dismissed Gunwerks' claims against architect Plan One Architects and contractor Sletten Construction of Wyoming, Inc., and had granted summary judgment to Forward Cody, the economic development group that contracted for the facility using Wyoming Business Council funds. Justice Bridget Hill's opinion held that Gunwerks adequately alleged it was an intended third-party beneficiary of Forward Cody's contracts with the two firms, and it sent the case back for further proceedings, Cowboy State Daily reported.","significance":"The ruling means a business that never signed the design and construction contracts for its own facility may still sue the architect and contractor when those contracts were made to build that facility for it. That matters for projects financed through economic development groups or other intermediaries that hold the contracts on a company's behalf.","tags":["construction defect","third-party beneficiary","design-build","economic development","wyoming"],"judge":"Bridget Hill","hasFull":true},{"id":"live-140","addedDate":"2026-09-15","title":"Landesbank Hessen-Thüringen Girozentrale v. 29 West 34 Owner LLC (Herald Square Foreclosure Settlement)","brief":"Helaba's foreclosure on Jeff Sutton's 29 West 34th Street retail property in Herald Square ended in an Aug. 5, 2026 stipulation after the bank assigned its $50 million mortgage; the receiver is to be discharged.","category":"lending-foreclosure","status":"settled","date":"2026-08-05","jurisdiction":"Supreme Court of the State of New York, New York County","parties":[{"name":"Landesbank Hessen-Thüringen Girozentrale","role":"Plaintiff (Lender)"},{"name":"29 West 34 Owner LLC","role":"Defendant (Borrower)"},{"name":"29 W. 34th Street Holdings LLC","role":"Assignee Lender"},{"name":"29 W. 34th Street Lender LLC","role":"Assignee Lender"}],"amountUsd":50000000,"amountBasis":"loan","state":"NY","amount":"$50M mortgage","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/08/07/jeff-sutton-regains-control-of-herald-square-property/","summary":"German bank Helaba (Landesbank Hessen-Thüringen Girozentrale), which made a $50 million mortgage on 29 West 34th Street in 2018, sued Jeff Sutton's 29 West 34 Owner LLC to foreclose in September 2025 after sending default notices over unpaid real estate taxes. In July 2026 Helaba assigned the mortgage to 29 W. 34th Street Holdings LLC, which passed it to 29 W. 34th Street Lender LLC; The Real Deal reported that SL Green's chief legal officer, Andrew S. Levine, is an executive vice president of the Holdings entity. On August 5, 2026, the owner, the new lender and the receiver signed a stipulation to discharge receiver Ian Lagowitz, return control to the owner and dismiss the case without prejudice, pending Judge Francis Kahn III's signature.","significance":"A foreclosure can end without an auction when the loan changes hands and the new holder reaches terms with the borrower. Borrowers and receivers should watch for mortgage assignments during a case, because a new lender can change its direction quickly.","tags":["foreclosure","cmbs-adjacent","retail","receivership","new york"],"judge":"Francis A. Kahn III","hasFull":true},{"id":"live-143","addedDate":"2026-09-16","title":"Park Social Winter Park Staircase Fall: $644.7M Jury Verdict Against Soho WP and BE-1 Concept Holdings","brief":"An Orange County jury returned a verdict of more than $644.7 million against Soho WP and BE-1 Concept Holdings over a 2017 fall on the stairs at Park Social, a Winter Park bar, the plaintiff's law firm said.","category":"premises-liability","status":"ruling","date":"2026-03-12","jurisdiction":"Ninth Judicial Circuit Court, Orange County, Florida","parties":[{"name":"Soho WP","role":"Defendant (owner/operator of Park Social)"},{"name":"BE-1 Concept Holdings","role":"Defendant (owner/operator of Park Social)"}],"judge":null,"amountUsd":644751855.08,"amountBasis":"award","state":"FL","amount":"$644,751,855.08 jury verdict","source":"live","sourceUrl":"https://www.clickorlando.com/news/local/2026/03/12/man-wins-644m-lawsuit-after-falling-down-stairs-at-winter-park-bar/","summary":"An Orange County, Florida jury returned a $644,751,855.08 verdict against Soho WP and BE-1 Concept Holdings, which owned and operated Park Social, a second-story bar in Winter Park, WKMG ClickOrlando reported on March 12, 2026, citing a release from the plaintiff's law firm. The plaintiff, then 57, fell down about 20 stairs while leaving the bar in November 2017 and was left partially quadriplegic, according to the firm. The article did not include a response from the defendants.","significance":"The verdict turned on the condition of a staircase in a 1926 building used by a bar open to the public, and the award ran against both companies that owned and operated the bar. The reported figures come from the plaintiff's law firm's release.","tags":["premises liability","staircase","jury verdict","florida","hospitality"],"hasFull":true},{"id":"live-144","addedDate":"2026-09-16","title":"In re The Ruins, LLC (Watertown, SD Redevelopment Site Sold to Backup Bidder in Chapter 7)","brief":"A bankruptcy judge authorized the sale of The Ruins in downtown Watertown, South Dakota to backup buyer Archer Land Co. for $6.1 million after the original developer's company failed to close its $11.265 million bid.","category":"lending-foreclosure","status":"ruling","date":"2026-08-17","jurisdiction":"U.S. Bankruptcy Court, District of North Dakota","parties":[{"name":"The Ruins, LLC","role":"Debtor"},{"name":"Red River State Bank","role":"Primary Secured Lender"},{"name":"Build, LLC","role":"Winning Bidder/Adversary Plaintiff"},{"name":"Archer Land Co., LLC","role":"Buyer"},{"name":"Watertown Development Company","role":"Second Mortgage Holder"}],"amountUsd":6100000,"state":"SD","amount":"$6.1M sale to backup buyer after an $11.265M winning bid failed to close; $1,126,500 earnest money forfeited","source":"live","sourceUrl":"https://www.northeastradiosd.com/post/watertown-the-ruins-redevelopment-deal-collapses-as-jesse-craig-forfeits-1-1m-property-sells-to","summary":"On August 17, 2026, U.S. Bankruptcy Judge Shon Hastings authorized the Chapter 7 trustee of The Ruins, LLC to sell its property at 315 E. Kemp Avenue in downtown Watertown, South Dakota, to backup buyer Archer Land Co., LLC for $6.1 million, Northeast Radio SD reported. Build, LLC, a company owned by the project's original developer, had won the auction with an $11.265 million bid but missed an August 14 closing deadline and forfeited its $1,126,500 earnest money deposit. The station reported that the proceeds will fall well short of primary lender Red River State Bank's debt.","significance":"The case shows how a winning bankruptcy auction bid can unravel before closing, here after a dispute over listing every lien on the property for title insurance. When the backup bid is much lower, junior lienholders such as a second mortgage holder and contractors with mechanic's liens may recover nothing from the sale.","judge":"Shon Hastings","tags":["chapter 7 bankruptcy","bankruptcy sale","south dakota","redevelopment","mechanic's liens"],"docketUrl":"https://www.courtlistener.com/docket/69518085/the-ruins-llc/","docketLabel":"CourtListener docket","amountBasis":"purchase price","hasFull":true},{"id":"live-145","addedDate":"2026-09-16","title":"Proven Business Skills v. Phoenix American Hospitality, LLC (Non-Traded Hotel REIT Securities Class Action)","brief":"An investor's proposed class action accuses Phoenix American Hospitality, two non-traded hotel REITs and its president of securities fraud, after the SEC's June settled action over $86 million raised.","category":"reit-securities","status":"filed","date":"2026-09-15","jurisdiction":"U.S. District Court, Northern District of Texas","parties":[{"name":"Proven Business Skills Inc","role":"Plaintiff"},{"name":"Phoenix American Hospitality, LLC","role":"Defendant"},{"name":"American Hospitality Properties REIT, Inc.","role":"Defendant"},{"name":"American Hospitality Properties REIT II, Inc.","role":"Defendant"}],"judge":"Jane J. Boyle","amountUsd":null,"state":"TX","amount":"$86M+ raised from 2,000+ retail investors across two non-traded REIT funds; class damages not yet quantified","source":"live","sourceUrl":"https://www.financialcontent.com/article/bizwire-2026-9-16-federman-and-sherwood-announces-filing-of-securities-class-action-lawsuit-against-phoenix-american-hospitality-llc-american-hospitality-properties-reit-inc-american-hospitality-properties-reit-ii-inc-and-william-lee-nelson","summary":"Proven Business Skills, Inc. filed a proposed securities class action in the U.S. District Court for the Northern District of Texas on September 15, 2026 against Phoenix American Hospitality, LLC (PAH), American Hospitality Properties REIT, Inc., American Hospitality Properties REIT II, Inc. and PAH's president, the court docket shows. The complaint asserts claims under Sections 10(b) and 20(a) of the Exchange Act for investors who bought shares in the two REITs between March 1, 2022 and July 31, 2024, according to the plaintiff's counsel's announcement. It follows a June 2026 SEC settled action alleging PAH and its president raised about $86 million from more than 2,000 retail investors with untrue statements about the funds' hotels and profits.","significance":"The SEC settled without the defendants admitting its allegations, but its complaint covers the same period and statements the private suit targets. The private claims have not been tested in court.","tags":["reit securities","sec enforcement","class action","hotel reit","non-traded reit"],"docketUrl":"https://www.courtlistener.com/docket/74794536/proven-business-skills-inc-v-phoenix-american-hospitality-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-146","addedDate":"2026-09-16","title":"Blue Sky Towers IV LLC v. Town of Waldoboro (Wireless Tower Siting / Telecommunications Act Suit)","brief":"Blue Sky Towers IV sued Waldoboro, Maine and its town boards after a variance denial for a 194-foot tower about five miles from Route 1, alleging an effective prohibition of wireless service.","category":"zoning-land-use","status":"filed","date":"2026-09-11","jurisdiction":"U.S. District Court, District of Maine","parties":[{"name":"Blue Sky Towers IV LLC","role":"Plaintiff"},{"name":"Cellco Partnership d/b/a Verizon Wireless","role":"Carrier (suit brought for its benefit)"},{"name":"Town of Waldoboro","role":"Defendant"},{"name":"Waldoboro Board of Appeals","role":"Defendant"},{"name":"Waldoboro Planning Board","role":"Defendant"}],"judge":"Stacey D. Neumann","amountUsd":null,"state":"ME","amount":"Non-monetary; seeks injunctive relief compelling tower-siting approval plus attorneys' fees","source":"live","sourceUrl":"https://wirelessestimator.com/articles/2026/blue-sky-towers-federal-lawsuit-targets-maine-towns-rule-restricting-towers-to-route-1-corridor/","summary":"Blue Sky Towers IV LLC sued the Town of Waldoboro, Maine, its Board of Appeals and its Planning Board in the U.S. District Court for the District of Maine on September 11, 2026, Wireless Estimator reported. The suit follows the Board of Appeals' unanimous August 20 denial of a variance for a 194-foot tower at 2734 Friendship Road, about five miles from Route 1, where a town rule confines wireless facilities to within 300 yards of that road. Blue Sky alleges the denial effectively prohibits personal wireless service in violation of the Telecommunications Act and lacked substantial evidence.","significance":"The case tests whether a town rule limiting wireless facilities to one road corridor can stand when a carrier claims a coverage gap elsewhere in town. The town attorney's view that the rule is a location requirement the appeals board could not vary leaves the federal question to the court.","tags":["zoning","telecommunications act","wireless siting","maine","land use"],"docketUrl":"https://www.courtlistener.com/docket/74781923/blue-sky-towers-iv-llc-v-town-of-waldoboro/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-147","addedDate":"2026-09-16","title":"Circle K Stores Parking-Lot Fall Appeal (Fourth Circuit Premises-Liability Summary-Judgment Reversal)","brief":"The Fourth Circuit revived a customer's fall suit against Circle K, holding a jury must decide whether a lot just washed with a chemical cleaner was an open and obvious hazard. The case was dismissed on a settlement order before trial.","category":"premises-liability","status":"settled","date":"2026-05-13","jurisdiction":"U.S. Court of Appeals for the Fourth Circuit","parties":[{"name":"Circle K Stores Inc.","role":"Defendant-Appellee"}],"amountUsd":null,"state":"SC","amount":"Settlement terms not disclosed; the Fourth Circuit said the customer's medical expenses were about $430,000","source":"live","sourceUrl":"https://law.justia.com/cases/federal/appellate-courts/ca4/25-1964/25-1964-2026-05-13.html","summary":"On May 13, 2026, the Fourth Circuit reversed summary judgment for Circle K Stores Inc. in a suit by a customer who fell in the parking lot of a Myrtle Beach, South Carolina store after an employee washed a painted line with water and a powdered concrete cleaner. Judge J. Harvie Wilkinson III, joined by Judges Julius N. Richardson and Toby Heytens, held that whether the hazard was 'open and obvious' was a question for a jury and that expert testimony was not required to prove causation. On remand, the district court dismissed the case under a 60-day settlement order on October 26, 2026, the day before trial was to begin.","significance":"The opinion narrows the open-and-obvious defense that property owners and retail operators often use to win premises cases at summary judgment: in the court's view, visible wetness alone does not make a surface obviously dangerous when the real hazard is an unannounced cleaning chemical. The absence of signs, cones or the safety vest that company policy appeared to require weighed against the store.","judge":"J. Harvie Wilkinson III","tags":["premises liability","slip and fall","fourth circuit","south carolina","summary judgment","settlement"],"docketUrl":"https://www.courtlistener.com/docket/67279084/lewis-v-circle-k-stores-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-148","addedDate":"2026-09-17","title":"Hughes Center Receivership (Court-Approved Sale of Las Vegas Office Park to Borden Industries)","brief":"A Clark County judge approved the receiver's sale of Las Vegas' Hughes Center office park to Borden Industries on July 28, 2026; court filings do not show the price, the Review-Journal reported.","category":"lending-foreclosure","status":"ruling","date":"2026-07-28","jurisdiction":"Eighth Judicial District Court, Clark County, Nevada","parties":[{"name":"Logic Commercial Real Estate","role":"Receiver"},{"name":"Borden Industries","role":"Buyer"}],"amountUsd":325000000,"amountBasis":"loan","state":"NV","amount":"$325M loan reportedly unpaid; sale price to Borden Industries redacted from court filings","source":"live","sourceUrl":"https://www.reviewjournal.com/business/vegas-business/building-las-vegas/sale-of-big-office-park-near-las-vegas-strip-pushes-ahead-3860743/","summary":"Clark County District Judge Maria Gall on July 28, 2026 approved a motion by court-appointed receiver Logic Commercial Real Estate to sell the Hughes Center, an office park with nearly 1.4 million square feet of office space a mile east of the Las Vegas Strip, to Borden Industries, the Las Vegas Review-Journal reported. The price was redacted from the filed purchase agreement, and Logic moved to seal the deal terms. Logic was appointed receiver in 2024 after the landlord reportedly stopped making payments on a $325 million loan.","significance":"The case shows a court-supervised receivership being used to sell a large office property with high vacancy. It also shows a receiver asking to keep a sale price out of a public court file before closing, though in Clark County the price is normally public once the deed is recorded.","judge":"Maria Gall","tags":["receivership","office","nevada","loan default","court-approved sale"],"hasFull":true},{"id":"live-149","addedDate":"2026-09-17","title":"OKO Group Affiliate v. Zurich American Insurance Co. et al. (Missoni Baia Builder's-Risk Coverage Suit)","brief":"OKO Group affiliate 700 Edgewater Development sued four builder's-risk insurers in Miami federal court for $22.4 million it says remains unpaid on a $55.7 million claim over foundation settling at Missoni Baia; the insurers have paid $33.9 million.","category":"construction-defect","status":"pending","date":"2026-04-03","jurisdiction":"U.S. District Court, Southern District of Florida","parties":[{"name":"700 Edgewater Development, LLC","role":"Plaintiff"},{"name":"Zurich American Insurance Company","role":"Defendant"},{"name":"Allianz Global Risks US Insurance Company","role":"Defendant"},{"name":"ACE American Insurance Company","role":"Defendant"},{"name":"National Fire & Marine Insurance Company","role":"Defendant"}],"judge":"Roy Kalman Altman","amountUsd":22400000,"amountBasis":"claim","state":"FL","amount":"$22.4M disputed balance of a $55.7M builder's-risk claim; $33.9M already paid by insurers","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/04/07/oko-group-sues-over-22-million-claim-tied-to-missoni-baia/","summary":"On April 3, 2026, 700 Edgewater Development, LLC, an affiliate of Vlad Doronin's OKO Group, sued Zurich American Insurance, Allianz Global Risks US Insurance, ACE American Insurance and National Fire & Marine Insurance in the U.S. District Court for the Southern District of Florida. The complaint says uneven foundation settling during construction of the 249-unit Missoni Baia tower in 2021 led to delays and costs that brought its builder's-risk claim to $55.7 million, of which the insurers paid $33.9 million. The case, assigned to Judge Roy Kalman Altman, was stayed on May 28, 2026, according to the docket.","significance":"Builder's-risk claims on large towers can include delay costs such as postponed sale closings, financing expense and soft costs, and carriers may pay part of a claim while contesting the rest. Developers should expect a coverage fight over an unpaid balance to run alongside any defect suits over the same building.","tags":["builder's risk","insurance coverage","construction defect","florida","condo development"],"docketUrl":"https://www.courtlistener.com/docket/73144273/700-edgewater-development-llc-v-zurich-american-insurance-company/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-150","addedDate":"2026-09-17","title":"State of Idaho, Idaho Transportation Board v. Triple Crown Development, LLC (Business-Damages Condemnation Appeal)","brief":"The Idaho Supreme Court held that business damages in a highway condemnation turn on fee title ownership, affirming dismissal of claims by Triple Crown Development and four affiliated companies.","category":"eminent-domain","status":"ruling","date":"2026-09-02","jurisdiction":"Idaho Supreme Court","parties":[{"name":"State of Idaho","role":"Plaintiff-Respondent"},{"name":"Idaho Transportation Board","role":"Plaintiff-Respondent"},{"name":"Triple Crown Development, LLC","role":"Defendant-Appellant"},{"name":"Thueson Construction, Inc.","role":"Defendant Intervenor-Appellant"},{"name":"Americrete Ready Mix Concrete, Inc.","role":"Defendant Intervenor-Appellant"},{"name":"Americrete Land Holding LLC","role":"Defendant Intervenor-Appellant"},{"name":"River Rock Sand & Gravel LLC","role":"Defendant Intervenor-Appellant"}],"judge":"Colleen D. Zahn","amountUsd":null,"state":"ID","amount":"Business-damages claim rejected; underlying land value stipulated separately","source":"live","sourceUrl":"https://www.mealeys.com/mealeys/mealeys-attorney-fees/articles/2524720","summary":"The Idaho Supreme Court on September 2, 2026 affirmed a Canyon County ruling that dismissed business-damages claims brought by Triple Crown Development, LLC and four commonly controlled companies after the state condemned part of Triple Crown's land for a highway interchange. The Court held that \"owned\" in Idaho Code section 7-711(2) means fee title ownership, so a beneficial or joint-venture interest does not qualify. It declined to award the state attorney fees on appeal because the appeal was not frivolous.","significance":"The opinion reads Idaho's business-damages statute by legal title, so commonly controlled companies cannot pool their interests to claim damages for a taking of one affiliate's land. The Court noted that the companies' fairness concerns about related business entities are for the legislature.","tags":["eminent domain","business damages","idaho","condemnation","highway interchange"],"hasFull":true},{"id":"live-151","addedDate":"2026-09-17","title":"Wal-Mart Stores East, LP Appeal (Contractor Technician Shock Injury, Florida Second DCA)","brief":"Florida's Second DCA affirmed a jury verdict against Wal-Mart Stores East for a door contractor's technician shocked by an ungrounded junction box in a locked room at a Hillsborough County store.","category":"premises-liability","status":"ruling","date":"2026-06-24","jurisdiction":"Florida Second District Court of Appeal","parties":[{"name":"Wal-Mart Stores East, LP","role":"Appellant"}],"judge":"Sleet","amountUsd":null,"state":"FL","amount":"Jury verdict affirmed; amount not stated in the opinion or the Tampa Free Press report","source":"live","sourceUrl":"https://www.tampafp.com/walmart-loses-florida-appeal-over-electrically-dangerous-box-that-shocked-contractor/","summary":"Florida's Second District Court of Appeal on June 24, 2026 affirmed a final judgment entered on a jury verdict against Wal-Mart Stores East, LP in a negligence suit by a service technician for D.H. Pace Door Company, who was shocked and fell from a ladder in July 2020 while connecting a new automatic door at a Hillsborough County store. The court held that Walmart could not rely on the independent contractor defense because the evidence supported that it had constructive knowledge of an ungrounded junction box in a locked area only its staff could open, a hazard not inherent in the door work.","significance":"The opinion applies the exception to Florida's independent contractor defense for concealed dangers that the owner knows or should know about and that are not inherent in the contracted work. It treats the owner's exclusive control of a restricted area, and the length of time a defect existed, as support for constructive knowledge.","documentUrl":"https://flcourts-media.flcourts.gov/content/download/2490436/opinion/Opinion_2025-0567.pdf","documentLabel":"Read the official opinion","tags":["premises liability","independent contractor","florida","personal injury","retail"],"hasFull":true},{"id":"live-154","addedDate":"2026-09-18","title":"Herb Simon v. David Simon's Family (SFG Co. Restructuring Suit)","brief":"Herb Simon is suing the family of his late nephew David Simon, alleging David dissolved private real estate company SFG Co. and moved its assets to a new entity without equity holders' consent; Eli Simon calls the suit meritless.","category":"reit-securities","status":"filed","date":"2026-07-31","jurisdiction":"Indiana state court","parties":[{"name":"Melvin Simon & Associates, Inc.","role":"Plaintiff"},{"name":"Simon Hollywood Developers, Inc.","role":"Plaintiff"},{"name":"Bank of America","role":"Plaintiff"},{"name":"SFG Manager, LLC","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"IN","amount":"Undisclosed; plaintiffs seek to unwind the restructuring plus compensatory and punitive damages","source":"live","sourceUrl":"https://therealdeal.com/national/2026/08/06/simon-family-feud-explodes-over-restructure-of-private-firm/","summary":"Herb Simon and several affiliated entities sued 17 defendants in Indiana state court in late July 2026, alleging his late nephew David Simon used his control of SFG Manager LLC to dissolve SFG Co., a private real estate company formed in 1995 to hold property interests kept outside Simon Property Group when it went public. The complaint says David moved SFG Co.'s assets into a new entity, SFG HoldCo, less than two weeks before his death in March 2026, under an operating agreement that removed preferred distribution rights. The plaintiffs seek to unwind the restructuring and recover compensatory and punitive damages. Eli Simon, David's son, who heads SFG Manager and succeeded his father as Simon Property Group's CEO, called it a 'meritless complaint.'","significance":"Members of a closely held real estate LLC are protected only as far as its consent provisions are honored; here the plaintiffs say a unanimous-consent requirement was bypassed. Families and co-investors holding property through private LLCs should check who can amend or dissolve the entity and what notice members are owed.","tags":["reit","llc governance","fiduciary duty","indiana","family business dispute"],"hasFull":true},{"id":"live-155","addedDate":"2026-09-18","title":"MLP Ventures v. Upper Merion Township (King of Prussia Data Center Denial Appeal)","brief":"Developer Brian O'Neill sued Upper Merion's supervisors on Sept. 16, 2026 to reverse their Aug. 13 denial of five data center plans near King of Prussia, alleging a bad-faith reversal, the Inquirer reported.","category":"zoning-land-use","status":"filed","date":"2026-09-16","jurisdiction":"Montgomery County Court of Common Pleas, Pennsylvania","parties":[{"name":"MLP Ventures","role":"Plaintiff"},{"name":"Upper Merion Township Board of Supervisors","role":"Defendant"},{"name":"Upper Merion Township","role":"Defendant"},{"name":"Upper Merion Township Planning Commission","role":"Defendant (August 2026 suit)"}],"judge":null,"amountUsd":null,"state":"PA","amount":"5-building, 4.6M-square-foot data center campus","source":"live","sourceUrl":"https://www.inquirer.com/news/pennsylvania/data-centers-upper-merion-township-lawsuit-20260918.html","summary":"Developer Brian O'Neill filed land-use appeals on September 16, 2026 in Montgomery County Court of Common Pleas against the Upper Merion Township Board of Supervisors, seeking to reverse its unanimous August 13 denial of five data center plans totaling about 4.6 million square feet, The Philadelphia Inquirer reported. The suits claim the board acted in bad faith after officials had said data centers qualify as permitted warehouses. Township officials declined to comment pending review. In October, PhillyVoice reported, the developers withdrew related zoning hearing board applications while pursuing the court challenges.","significance":"The appeals ask a court to decide whether the township could reject data center plans after its zoning officer had called the use permitted. The developer is also asking the court to take fact-finding away from the board by appointing an independent referee.","tags":["zoning","data center","pennsylvania","land use appeal","municipal law"],"hasFull":true},{"id":"live-158","addedDate":"2026-09-19","title":"Eagle Nest Investments, LLC v. Spencer (Pavilion Park Below-Market Land Sale & Breach of Fiduciary Duty Trial)","brief":"Minority owners of Pavilion Park LC allege its manager sold two West Des Moines parcels to an affiliate below market value; defendants deny it. Post-trial briefs were due Oct. 9, Business Record reported.","category":"reit-securities","status":"pending","date":"2026-09-16","jurisdiction":"Iowa District Court for Polk County","parties":[{"name":"Eagle Nest Investments LLC","role":"Plaintiff"},{"name":"Gratias Properties LLC","role":"Plaintiff"},{"name":"TJK Investments LC","role":"Defendant"},{"name":"Wendover Reserve LLC","role":"Defendant"},{"name":"Landmark Brokerage Inc.","role":"Defendant"}],"judge":null,"amountUsd":null,"state":"IA","amount":"Alleged gaps of about $6.94M on the 126.52-acre commercial parcel ($11.4M sale vs. alleged value of at least $18.34M) and about $390,000 on the 25.52-acre residential parcel ($1.6M vs. $1.99M)","source":"live","sourceUrl":"https://www.businessrecord.com/post-trial-briefs-in-pavilion-park-trial-due-oct-9/","summary":"Minority owners of Pavilion Park LC allege that its manager, William Spencer, and TJK Investments LC arranged to sell two parcels of the West Des Moines development site to Wendover Reserve LLC, an entity Spencer owns or manages, below fair market value and over their objections, and to pay an excessive commission to Landmark Brokerage Inc., Business Record reported. The defendants deny any wrongdoing. A bench trial in Polk County District Court ended in early September 2026, with post-trial briefs due Oct. 9.","significance":"The case asks a judge to decide whether a managing member's sale of jointly owned development land to an entity he controls, and a commission paid to his brokerage, harmed the minority owners. The defendants deny any wrongdoing, and no decision date has been set.","tags":["breach of fiduciary duty","minority owners","land sale","iowa","self-dealing"],"hasFull":true},{"id":"live-161","addedDate":"2026-09-20","title":"Northwest Bank v. North Pearl LLC (Pearl District Shelter Building Foreclosure)","brief":"Northwest Bank sued to foreclose on Portland's Premier Gear Works Building, leased to the city for a 200-bed shelter, saying a $6 million loan that matured in March 2024 now totals about $7.2 million.","category":"lending-foreclosure","status":"filed","date":"2026-08-25","jurisdiction":"Multnomah County Circuit Court, Oregon","parties":[{"name":"Northwest Bank","role":"Plaintiff"},{"name":"Sturgeon Development Partners","role":"Defendant"},{"name":"North Pearl LLC","role":"Defendant"}],"judge":null,"amountUsd":7200000,"amountBasis":"loan","state":"OR","amount":"$6M original loan principal; approximately $7.2M currently claimed owed, including accrued interest","source":"live","sourceUrl":"https://www.wweek.com/news/city/2026/08/27/northwest-building-used-for-mayor-wilsons-overnight-shelter-faces-foreclosure/","summary":"Northwest Bank filed a foreclosure suit in Multnomah County Circuit Court on August 25, 2026 against North Pearl LLC, Sturgeon Development Partners and developer Vanessa Sturgeon over a $6 million loan taken out in 2022, Willamette Week reported. The bank says the loan matured in March 2024 without repayment and that about $7.2 million is now owed, including nearly $2 million in accrued interest. The Pearl District building had been leased to the City of Portland for $18,000 a month for the 200-bed NW Northrup Shelter, which was scheduled to close on September 18, 2026.","significance":"The case shows a commercial loan left unpaid more than two years past maturity reaching foreclosure while the collateral is leased to a government tenant. The city said it did not expect the suit to affect the shelter's planned closure, and Willamette Week noted it was unclear whether the case could complicate the city's lease.","tags":["foreclosure","oregon","loan default","government lease","portland"],"hasFull":true},{"id":"live-162","addedDate":"2026-09-20","title":"South Union Township v. Namdar Realty Group & Uniontown Mall Realty (Court-Supervised Mall Safety Compliance)","brief":"South Union Township's suit led a Fayette County judge to order Namdar Realty to fix blocked exits, vermin and crumbling roads at Uniontown Mall; she set a Sept. 30 site visit, the Herald-Standard reported.","category":"premises-liability","status":"pending","date":"2026-05-22","jurisdiction":"Court of Common Pleas, Fayette County, Pennsylvania","parties":[{"name":"South Union Township","role":"Plaintiff"},{"name":"Namdar Realty Group","role":"Defendant"},{"name":"Uniontown Mall Realty","role":"Defendant"}],"amountUsd":null,"state":"PA","amount":"Not a monetary claim; court-ordered remediation of a roughly 690,000 sq. ft. regional mall","source":"live","sourceUrl":"https://www.heraldstandard.com/editors_pick/2026/jul/02/court-schedules-site-visit-to-uniontown-mall/","summary":"South Union Township, Pennsylvania sued Uniontown Mall owners Namdar Realty Group and Uniontown Mall Realty in November 2025 over conditions it called dangerous and unlawful, including blocked, locked or obstructed emergency exits, vermin and deteriorating roads and parking areas. Fayette County Judge Linda Cordaro ordered Namdar on May 22, 2026 to make repairs, and in early July found \"moderate compliance, although not complete compliance,\" the Herald-Standard reported. She scheduled a Sept. 30 site visit and an Oct. 15 hearing if work remained, and said she would order the mall closed if Namdar still had not finished.","significance":"The township used a lawsuit and a court order, not citations alone, to push repairs at the mall, and the judge has kept the case open to check the work. Her warning that she could order the mall closed raises the stakes if the emergency-exit repairs are not finished.","judge":"Linda Cordaro","tags":["premises liability","pennsylvania","mall","code enforcement","retail"],"hasFull":true},{"id":"live-163","addedDate":"2026-09-21","featured":true,"title":"Town of Marshfield v. Commonwealth (SJC Affirms Dismissal of Challenge to MBTA Communities Act)","brief":"Massachusetts' SJC affirmed dismissal of Marshfield's suit claiming the MBTA Communities Act is an unfunded mandate and violates home rule and the Zoning Act, leaving the multifamily zoning requirement in place.","category":"zoning-land-use","status":"ruling","date":"2026-09-18","jurisdiction":"Massachusetts Supreme Judicial Court","parties":[{"name":"Town of Marshfield","role":"Plaintiff-Appellant"},{"name":"Select board of Marshfield","role":"Plaintiff-Appellant"},{"name":"Commonwealth of Massachusetts","role":"Defendant-Appellee"},{"name":"Executive Office of Housing and Livable Communities","role":"Defendant-Appellee"}],"amountUsd":null,"state":"MA","amount":"Not a monetary claim; challenge to the statewide MBTA Communities Act multifamily zoning requirement","source":"live","sourceUrl":"https://www.mass.gov/news/ag-campbell-issues-statement-after-sjc-rejects-marshfields-claims-challenging-the-mbta-communities-law","summary":"On September 18, 2026, the Massachusetts Supreme Judicial Court affirmed the dismissal of a suit by the Town of Marshfield and its select board challenging the MBTA Communities Act, the 2021 law requiring MBTA-served municipalities to allow multifamily housing as of right in at least one district. In an opinion by Justice Serge Georges, Jr., the court held the town had not plausibly alleged an unfunded local mandate, lacked standing to assert its town meeting voters' constitutional voting rights, and could not prevail on Home Rule Amendment or Zoning Act theories.","significance":"The ruling rejects a municipality's unfunded-mandate, home-rule and Zoning Act objections to the MBTA Communities Act at the pleading stage, following the SJC's 2025 decision in Attorney General v. Milton. The court held that town meeting voters may reject a proposal, but cannot exempt the town from complying with a valid state law.","documentUrl":"https://www.mass.gov/doc/marshfield-v-commonwealth-sjc-s13840/download","documentLabel":"Read the SJC's full opinion","judge":"Serge Georges, Jr.","tags":["zoning","massachusetts","multifamily","mbta communities act","municipal law"],"hasFull":true},{"id":"live-164","addedDate":"2026-09-21","featured":true,"title":"NSI, A.1 LLC v. City of Springfield (Developer Sues to Block Springfield's Data Center Moratorium)","brief":"NSI, A.1 LLC sued Springfield, Missouri to block its 120-day data center moratorium, saying the city twice confirmed in writing that the site's PD 251 zoning allowed the planned use.","category":"zoning-land-use","status":"filed","date":"2026-09-17","jurisdiction":"Circuit Court of Greene County, Missouri","judge":"Nathan Taylor","amountUsd":null,"state":"MO","amount":"Not a monetary damages claim; developer seeks declaratory and injunctive relief blocking enforcement of a 120-day data center moratorium against a project it says the city already approved in writing","source":"live","sourceUrl":"https://sbj.net/stories/breaking-news-developer-asks-court-to-block-data-center-moratorium,105817","summary":"Developer NSI, A.1 LLC sued the City of Springfield in Greene County Circuit Court on September 17, 2026, seeking to block the 120-day data center moratorium the City Council adopted June 29, the Springfield Business Journal reported. The six-count petition argues the moratorium is zoning legislation in substance that did not follow Missouri's planning and zoning law, was not validly enacted under the city charter's rules for emergency and one-reading bills, and should not apply to a project the developer says the city confirmed in writing was allowed under the site's PD 251 zoning. A separate count alleges the city violated the Sunshine Law in handling a public records request. SBJ reported in November that the judge denied NSI's request for a preliminary injunction.","significance":"The case tests whether a city can pause a use through a moratorium after its staff has issued written zoning verifications for a specific project, and whether that moratorium had to follow the procedures that govern zoning changes. Developers who spend on design and predevelopment in reliance on a city's written zoning confirmation will watch how the court treats that reliance.","parties":[{"name":"NSI, A.1 LLC","role":"Plaintiff"},{"name":"City of Springfield, Missouri","role":"Defendant"}],"propertyType":"Data Center","tags":["data center","missouri","zoning moratorium","vested rights","sunshine law"],"hasFull":true},{"id":"live-165","addedDate":"2026-09-21","title":"NSI6 LLC v. Benton County (Missouri Court Blocks County Data Center Moratorium for Now)","brief":"A Missouri judge granted developer NSI6 LLC a TRO against Benton County's six-month data center moratorium on Sept. 8 and extended it Sept. 21; the county can't enforce it pending a final ruling.","category":"zoning-land-use","status":"pending","date":"2026-09-08","jurisdiction":"Circuit Court of Benton County, Missouri","judge":null,"amountUsd":null,"state":"MO","amount":"Not a monetary claim; developer seeks a restraining order and injunction against enforcement of a six-month county data center moratorium","source":"live","sourceUrl":"https://www.ky3.com/2026/09/02/data-center-moratorium-fight-plays-out-benton-county-courtroom/","summary":"A Benton County, Missouri judge granted a temporary restraining order on Sept. 8, 2026 blocking the county's six-month data center moratorium, adopted Aug. 10, from applying to a project by developer NSI6 LLC, and extended it after a Sept. 21 hearing on a preliminary injunction, KY3 reported. The county argued the moratorium applied because the developer had only committed to buy the land and had not started work; the purchase of the roughly 12-acre site closed Sept. 9. As of Nov. 9, the county could not enforce the moratorium until a final judgment, KY3 reported.","significance":"The dispute turns on whether a moratorium adopted after a developer committed to buy land, but before closing, can reach that project. The court's interim orders have so far kept the moratorium from applying while the case proceeds, but no final ruling has been issued.","parties":[{"name":"NSI6 LLC","role":"Plaintiff"},{"name":"Benton County, Missouri","role":"Defendant"}],"propertyType":"Data Center","tags":["data center","missouri","temporary restraining order","zoning moratorium","benton county"],"hasFull":true},{"id":"live-166","addedDate":"2026-09-21","title":"Preserve Montgomery County v. Montgomery County (Judge Lets Challenge to Amazon Data Center Approvals Proceed)","brief":"A Cole County judge let Preserve Montgomery County's suit over an Amazon data center proceed, finding the group has standing, but dismissed a grant-monitoring claim against Missouri's economic development agency.","category":"zoning-land-use","status":"ruling","date":"2026-09-18","jurisdiction":"Circuit Court of Cole County, Missouri","amountUsd":null,"state":"MO","amount":"Not a monetary claim; advocacy group seeks to halt a data center project over alleged public-notice and disclosure failures, including on a tax abatement","source":"live","sourceUrl":"https://www.kbia.org/missouri-news-network/2026-09-21/advocacy-group-can-continue-to-challenge-data-centers-being-built-in-montgomery-county-judge-rules","summary":"Cole County Circuit Judge Cotton Walker ruled on Sept. 18, 2026 that the advocacy group Preserve Montgomery County has standing to pursue most of its lawsuit against Montgomery County, Missouri over an Amazon data center, the Columbia Missourian reported in a story published by KBIA. The group, which sued in February to halt the project, alleges the county and state failed to post proper public notice, did not adequately disclose the data centers' water and electricity use, and did not fully inform residents of the tax-abatement terms. The judge dismissed a claim that the Missouri Department of Economic Development failed to properly monitor an American Rescue Plan Act grant agreement, removing the agency from the case.","significance":"The ruling lets a citizen group press public-notice and disclosure claims over a county's approvals and tax abatement for a large data center project, though it does not decide the merits. The county and state have argued there is no factual evidence supporting the claims.","parties":[{"name":"Preserve Montgomery County","role":"Plaintiff"},{"name":"Montgomery County, Missouri","role":"Defendant"},{"name":"Missouri Department of Economic Development","role":"Defendant (dismissed)"}],"propertyType":"Data Center","judge":"Cotton Walker","tags":["data center","missouri","public notice","standing","amazon"],"hasFull":true},{"id":"live-168","addedDate":"2026-09-22","title":"U.S. Bank N.A. v. 1592 Boston Street LLC (Bostonian Apartments Foreclosure)","brief":"U.S. Bank sued to foreclose on the Bostonian Apartments in Aurora, Colorado, saying it lent the owner $3.28 million and was not repaid; the owner's Chapter 11 case was dismissed in May.","category":"lending-foreclosure","status":"filed","date":"2026-09-10","jurisdiction":"Denver District Court, Colorado","judge":null,"amountUsd":3280000,"amountBasis":"loan","state":"CO","amount":"$3,280,000 loan the bank says was not repaid","source":"live","sourceUrl":"https://businessden.com/the-docket-real-estate-lawsuit-roundup-for-9-17-26/","summary":"U.S. Bank National Association filed a foreclosure suit against 1592 Boston Street LLC on September 10, 2026, BusinessDen's weekly lawsuit roundup reported. The bank says it lent the company $3,280,000, has not been repaid and can foreclose on the Bostonian Apartments at 1592 Boston St. in Aurora. Federal bankruptcy records show the owner filed for Chapter 11 in January 2026 and that the case was dismissed in May.","significance":"The filing came about four months after the owner's Chapter 11 case was dismissed. It shows how a lender can move to enforce a loan in state court once a borrower's bankruptcy case has ended.","parties":[{"name":"U.S. Bank National Association","role":"Lender/Plaintiff"},{"name":"1592 Boston Street LLC","role":"Borrower/Defendant"}],"propertyType":"Multifamily","tags":["foreclosure","colorado","multifamily","chapter 11"],"hasFull":true},{"id":"live-169","addedDate":"2026-09-22","title":"Advenir Azora Development, LLC v. City of Hendersonville (Zoning Denial Suit — Partial Dismissal)","brief":"A Henderson County judge kept Advenir Azora's arbitrary-and-capricious claim alive but dismissed two others in its suit over Hendersonville's denial of a 180-unit, 21-acre rental rezoning.","category":"zoning-land-use","status":"ruling","date":"2026-09-01","jurisdiction":"Henderson County Superior Court, North Carolina","amountUsd":null,"state":"NC","amount":"180-unit, 21-acre rezoning denial; declaratory and injunctive relief sought, no liquidated damages claim","source":"live","sourceUrl":"https://www.hendersonvillelightning.com/news/16296-although-city-won-two-rounds-haywood-road-zoning-lawsuit-survives.html","summary":"Special Superior Court Judge Troy J. Stafford dismissed two of three counts in Miami-based developer Advenir Azora Development LLC's suit over the Hendersonville City Council's January 2026 denial of its rezoning request for a 180-unit rental community on Haywood Road, the Hendersonville Lightning reported. The dismissed counts alleged that the denial was not authorized by statute and that the city's conditional zoning provisions are unconstitutional. The claim that the denial was arbitrary and capricious remains, and no hearing date has been set.","significance":"The city keeps its conditional zoning process intact for now, while the developer's challenge to the denial itself goes forward. Whether the council's January 2026 decision stands now turns on the remaining arbitrary-and-capricious claim.","parties":[{"name":"Advenir Azora Development, LLC","role":"Plaintiff"},{"name":"City of Hendersonville, North Carolina","role":"Defendant"}],"propertyType":"Multifamily","judge":"Troy Stafford","tags":["zoning","north carolina","rezoning denial","arbitrary and capricious","multifamily"],"hasFull":true},{"id":"live-170","addedDate":"2026-09-22","title":"LRK, LLC v. City of St. George (Kleinpeter Tract Downzoning Challenge — TRO Granted)","brief":"A Louisiana judge temporarily barred St. George from rezoning a nearly 60-acre tract at Pecue Lane and I-10; landowner LRK LLC also claims the city was never legally incorporated.","category":"zoning-land-use","status":"pending","date":"2026-07-13","jurisdiction":"19th Judicial District Court, East Baton Rouge Parish, Louisiana","judge":null,"amountUsd":null,"state":"LA","amount":"Nearly 60-acre parcel; declaratory and injunctive relief sought","source":"live","sourceUrl":"https://www.theadvocate.com/baton_rouge/news/courts/st-george-rezoning-lawsuit/article_b2538455-124f-4683-bffe-323678f2c4a3.html","summary":"A 19th Judicial District Court judge signed a temporary restraining order on July 13, 2026 barring the City of St. George, Louisiana from adopting or enforcing a proposed ordinance that would rezone a nearly 60-acre parcel of the Kleinpeter family's land near the Pecue Lane interchange with I-10, The Advocate reported. Landowner LRK LLC sued on June 8, arguing the proposed reclassification to a mixed-use district is more restrictive than the tract's long-held C-2 heavy commercial zoning. The suit also asks the court to declare that St. George was never legally incorporated, a claim the mayor disputes.","significance":"The case shows how a citywide zoning-code overhaul can be challenged parcel by parcel when it moves land with long-standing commercial zoning into a more restrictive district. LRK's added claim that St. George was never legally incorporated puts the young city's authority to zone at issue alongside the rezoning itself.","parties":[{"name":"LRK, LLC","role":"Plaintiff"},{"name":"City of St. George, Louisiana","role":"Defendant"}],"propertyType":"Land/Development","tags":["zoning","louisiana","downzoning","temporary restraining order","incorporation dispute"],"hasFull":true},{"id":"live-171","addedDate":"2026-09-23","featured":true,"title":"Sheetz, Inc. v. City of Centerville (Ohio Supreme Court Allows Separate Damages Suit After Site-Plan Appeal Win)","brief":"Ohio's Supreme Court ruled unanimously that Sheetz may sue Centerville for damages over a rejected site plan even though it did not seek damages in its administrative appeal; the case returns to federal court.","category":"zoning-land-use","status":"ruling","date":"2026-09-15","jurisdiction":"Supreme Court of Ohio","amountUsd":null,"state":"OH","amount":"Damages claim pending in federal court; no figure reported","source":"live","sourceUrl":"https://www.daytondailynews.com/local/ohio-supreme-court-sheetz-can-pursue-legal-action-against-centerville/article_c8e22d40-fdfa-5b31-a69d-8b84ac655822.html","summary":"The Supreme Court of Ohio ruled unanimously on September 15, 2026 that Sheetz, Inc. may pursue a separate lawsuit for damages against the City of Centerville, answering a question certified by the federal court hearing Sheetz's damages case. In an opinion by Justice Joseph T. Deters, the court held that because damages and declaratory claims cannot be brought in an R.C. Chapter 2506 administrative appeal, res judicata does not bar them later. The damages case will proceed in the U.S. District Court for the Southern District of Ohio, the Dayton Daily News reported.","significance":"The decision means an Ohio developer that wins an administrative appeal of a zoning or site-plan denial does not lose its damages claim by leaving it out of that appeal. Liability and any damages in Sheetz's case remain to be decided in federal court.","parties":[{"name":"Sheetz, Inc.","role":"Plaintiff"},{"name":"City of Centerville, Ohio","role":"Defendant"}],"propertyType":"Retail","judge":"Joseph T. Deters","tags":["zoning","ohio","site plan","administrative appeal","damages"],"docketUrl":"https://www.courtlistener.com/docket/68291241/sheetz-inc-v-city-of-centerville-oh/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-172","addedDate":"2026-09-23","title":"Schurman Family Company TIC v. Superior Court (Privette Doctrine Extended to Non-Hiring Landlord)","brief":"A California appeals court ruled the Privette doctrine shields an Oakland warehouse landlord from a contractor employee's injury suit even though the landlord did not hire the contractor, Business Insurance reported.","category":"premises-liability","status":"ruling","date":"2026-08-26","jurisdiction":"California Court of Appeal, First Appellate District, Division Two","judge":"Tara M. Desautels","amountUsd":null,"state":"CA","amount":"Not a monetary ruling; writ relief directing entry of summary judgment for the warehouse-owner landlord","source":"live","sourceUrl":"https://www.businessinsurance.com/california-court-says-landlord-protected-from-contractor-injury-suit/","summary":"California's First Appellate District ruled on Aug. 26, 2026 that the Privette doctrine can shield a warehouse owner from a contractor's employee's injury suit even though the owner did not hire the contractor, Business Insurance reported. Schurman Family Company TIC had leased portions of its Oakland warehouse to Verizon for communications equipment, and Verizon hired L.D. Strobel, whose employee fell through a skylight. The court held the landlord fell within the \"chain of delegation\" and ordered summary judgment in its favor.","significance":"The decision extends Privette protection to a landlord whose lease contemplates the tenant hiring an independent contractor for the work at issue, unless a recognized exception applies. Landlords that lease roof or equipment space to tenants who bring in their own contractors are the most directly affected.","parties":[{"name":"Schurman Family Company TIC","role":"Petitioner (warehouse owner, defendant below)"},{"name":"Verizon Wireless","role":"Tenant (co-defendant below; granted summary judgment)"}],"propertyType":"Industrial","tags":["premises liability","california","privette doctrine","contractor injury","verizon"],"hasFull":true},{"id":"live-173","addedDate":"2026-09-23","featured":true,"title":"Computershare Trust Co. v. Showboat Properties LLC (CMBS Foreclosure on Atlantic City's Showboat Hotel)","brief":"Computershare, for CMBS investors, seeks to foreclose on Atlantic City's 475-room Showboat Hotel, arcade and garage, alleging no payments since April 2025 on a $48.5 million loan; Showboat wants a rent receiver.","category":"lending-foreclosure","status":"pending","date":"2026-06-30","jurisdiction":"Superior Court of New Jersey, Chancery Division, Atlantic County","judge":null,"amountUsd":48500000,"state":"NJ","amount":"$48.5 million loan alleged in default; trustee seeks foreclosure and a sheriff's sale","source":"live","sourceUrl":"https://pressofatlanticcity.com/news/local/casinos/article_0740fbf3-cfb8-434a-8fd6-bf88dd3dab7f.html","summary":"Computershare Trust Co., representing holders of commercial mortgage-backed securities, filed a foreclosure complaint in June 2026 over a $48.5 million loan on Atlantic City's Showboat hotel, the Press of Atlantic City and The Philadelphia Inquirer reported. The lender alleges developer Bart Blatstein's Showboat entities have made no monthly payments since April 2025 and breached other loan terms. Showboat's attorneys asked the court to appoint a rent receiver instead of ordering foreclosure, and Blatstein told the Press there were no financial problems.","significance":"Beyond missed payments, the lender pleads unfinished renovations, contractor liens, a tax lien and unpaid insurance as separate defaults. Showboat's alternative, a rent receiver who would collect income and resume debt payments, would keep the hotel operating while the case proceeds.","parties":[{"name":"Computershare Trust Co.","role":"Trustee/Plaintiff"},{"name":"Showboat Properties LLC","role":"Defendant/Borrower"}],"propertyType":"Hospitality","tags":["hotel foreclosure","cmbs","new jersey","atlantic city","receivership"],"amountBasis":"loan","hasFull":true},{"id":"live-174","addedDate":"2026-09-23","title":"Cogent Bank v. Horizon Edge Hospitality LLC (SBA-Backed Foreclosure on Shuttered Rochester Wyndham)","brief":"Cogent Bank is seeking to foreclose on the shuttered Wyndham Rochester Downtown, alleging $6,347,940.30 was owed as of July 7 on an SBA loan and a conventional loan, 13WHAM reported.","category":"lending-foreclosure","status":"filed","date":"2026-07-07","jurisdiction":"Supreme Court of the State of New York, Monroe County","judge":null,"amountUsd":6347940.3,"amountBasis":"loan","state":"NY","amount":"$6,347,940.30 alleged owed as of July 7, 2026 on a $5 million SBA-guaranteed loan and an $850,000 conventional loan","source":"live","sourceUrl":"https://13wham.com/news/local/foreclosure-lawsuit-filed-against-shuttered-wyndham-rochester-downtown-hotel-cogent-bank","summary":"Cogent Bank has sued in Monroe County Supreme Court to foreclose on the Wyndham Rochester Downtown at 32-70 State Street, naming the owner's companies, Horizon Edge Hospitality LLC and Horizon Edge Capital LP, and other parties with interests in the property, 13WHAM News reported on September 1, 2026. The bank alleges the borrowers defaulted on a $5 million SBA loan and an $850,000 conventional loan, and then on a second forbearance agreement signed in May. It says $6,347,940.30 was owed as of July 7, with interest still accruing.","significance":"The suit lands on a hotel the city has already closed over code violations, and the bank wants a receiver to take possession while the foreclosure proceeds. Who controls the property will matter because it cannot reopen until the violations are fixed and a new certificate of occupancy is issued.","parties":[{"name":"Cogent Bank","role":"Plaintiff/Lender"},{"name":"Horizon Edge Hospitality LLC","role":"Defendant/Borrower"},{"name":"Horizon Edge Capital LP","role":"Defendant"}],"propertyType":"Hospitality","tags":["hotel foreclosure","sba loan","new york","receivership","code violations"],"hasFull":true},{"id":"live-175","addedDate":"2026-09-24","featured":true,"title":"Alexandria Real Estate Equities Securities Class Action (Dismissed With Leave to Amend Over Impairment Claims)","brief":"A federal judge dismissed, with leave to amend, a securities class action alleging Alexandria Real Estate Equities misled investors about its lab portfolio before large impairments; an amended complaint followed.","category":"reit-securities","status":"pending","date":"2026-09-10","jurisdiction":"U.S. District Court for the Central District of California","amountUsd":null,"state":"CA","amount":"Putative securities class action over impairment charges of $323M (Q3 2025) and $1.7B (Q4 2025); damages not stated","source":"live","sourceUrl":"https://www.bisnow.com/news/national/capital-markets/judge-dismisses-suit-alleging-alexandria-misled-investors-over-portfolio-strength","summary":"U.S. District Judge George H. Wu dismissed, with leave to amend, a proposed securities class action accusing Alexandria Real Estate Equities and three executives of misleading investors about its life-science leasing outlook, Bisnow reported. The court issued a tentative ruling on September 8, 2026 and adopted it as final after a September 10 hearing, according to the docket. Wu found Alexandria's account that it acted in good faith \"the more cogent-and-compelling explanation\"; the lead plaintiffs filed an amended complaint on October 15, 2026.","significance":"The ruling is a setback for the plaintiffs but not the end of the case, since they were allowed to amend and have done so. It shows that a large write-down, standing alone, did not persuade the court that executives knowingly misled investors.","parties":[{"name":"Alexandria Real Estate Equities, Inc.","role":"Defendant"},{"name":"Menora Mivtachim Insurance Ltd. and affiliated pension entities","role":"Lead Plaintiffs"}],"propertyType":"Life Sciences","judge":"George H. Wu","tags":["reit","securities fraud","life sciences","california","class action"],"docketUrl":"https://www.courtlistener.com/docket/71959712/warren-hern-v-alexandria-real-estate-equities-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-176","addedDate":"2026-09-24","title":"Citibank, N.A. v. Golub & Company (Magnificent Mile Office Tower Foreclosure Receivership)","brief":"A Cook County judge put the office floors of 625 North Michigan Avenue, a 28-story Magnificent Mile building, under a receiver in a foreclosure over a $50.6 million CMBS loan the lenders say went unpaid at maturity.","category":"lending-foreclosure","status":"ruling","date":"2026-06-16","jurisdiction":"Circuit Court of Cook County, Illinois","judge":null,"amountUsd":50600000,"amountBasis":"loan","state":"IL","amount":"$50.6 million CMBS loan alleged in default","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/06/27/receiver-appointed-in-625-n-michigan-ave-foreclosure/","summary":"Citibank, as trustee for CMBS bondholders, and special servicer LNR Partners sued to foreclose on the office portion of 625 North Michigan Avenue, a 28-story building on Chicago's Magnificent Mile. They allege owners Golub & Company and BlueFive Capital defaulted on a $50.6 million loan that came due on March 6, 2026 and was not paid off. On June 16, 2026, a Cook County judge named Scott Shefman of Friedman Real Estate Management as receiver, The Real Deal reported, citing court records.","significance":"Once an office loan passes maturity without a payoff, a special servicer can go from a default notice to a court-appointed receiver within a few months. From then on the receiver, not the owner, collects rent, signs leases and helps market the building, even though the foreclosure itself is still pending.","parties":[{"name":"Citibank, N.A.","role":"Trustee/Plaintiff"},{"name":"LNR Partners","role":"Special Servicer"},{"name":"Golub & Company","role":"Defendant/Borrower"},{"name":"BlueFive Capital","role":"Defendant/Borrower"}],"propertyType":"Office","tags":["cmbs foreclosure","receivership","illinois","office","magnificent mile"],"hasFull":true},{"id":"live-177","addedDate":"2026-09-24","title":"Receiver Appointed for Unico-Linked First and Union Retail Condo After $14.5M Loan Default","brief":"A King County court commissioner appointed a Trigild receiver, with Unico and lender HFX Funding in agreement, for retail condo units at 1419 First Ave. in Seattle after a $14.5 million loan default.","category":"lending-foreclosure","status":"ruling","date":"2026-07-29","jurisdiction":"King County Superior Court, Washington","parties":[{"name":"HFX Funding LLC","role":"Lender"},{"name":"Unico Properties","role":"Owner (borrower is an affiliated entity)"},{"name":"Trigild","role":"Receiver"}],"judge":null,"amountUsd":14500000,"amountBasis":"loan","state":"WA","amount":"$14.5M loan default","source":"live","sourceUrl":"https://news.theregistryps.com/unico-retail-property-near-pike-place-market-in-seattle-enters-receivership-after-14-5mm-default/","summary":"A downtown Seattle retail property owned by an entity linked to Unico Properties was placed in receivership after a default on a $14.5 million loan that matured two years earlier, the Puget Sound Business Journal reported, as summarized by Connect CRE. King County Superior Court Commissioner Sarah Moen appointed a Trigild representative as custodial receiver for the retail condominium units at 1419 First Ave., next to Pike Place Market. Unico and lender HFX Funding LLC agreed to the receivership.","significance":"The receivership was agreed to by the owner and the lender rather than contested, putting a neutral manager in charge of the property. The Registry linked the property's occupancy decline to the November 2025 closing of Pike Brewing's taproom there.","propertyType":"Retail","tags":["receivership","loan default","retail","seattle","washington"],"hasFull":true},{"id":"live-178","addedDate":"2026-09-25","featured":true,"title":"Charles Cohen v. Fortress Investment Group ($204M Claim Over UCC Foreclosure Auction)","brief":"Charles Cohen, who paid off a $187 million Fortress judgment in June, told the court he will keep pursuing a roughly $204 million claim over a 2024 foreclosure auction, Crain's reported.","category":"lending-foreclosure","status":"pending","date":"2026-06-25","jurisdiction":"Supreme Court of the State of New York, New York County (Commercial Division)","state":"NY","amount":"About $204M in damages sought (Bisnow: $203.7M), after a $187M guaranty judgment was paid","source":"live","sourceUrl":"https://www.crainsnewyork.com/real-estate/commercial/cny-cohen-demands-203m-from-fortress-20260629/","summary":"Developer Charles Cohen paid off a $187 million judgment owed to Fortress Investment Group in June 2026, and in a June 25 letter to the New York court his attorney said Cohen would pursue his defenses and counterclaims against Fortress, Crain's New York Business reported. Cohen is seeking about $204 million in a lawsuit filed roughly a year earlier, which alleges the out-of-court auction of four of his properties was not commercially reasonable, according to The Real Deal. Fortress has denied the allegations in court filings and says it will keep pursuing its own remaining claims against Cohen.","significance":"The dispute shows that paying a guaranty judgment does not end a borrower's fight with its lender: Cohen is still challenging how the collateral was sold, while Fortress presses separate claims. How a court weighs the commercial-reasonableness claim will matter to lenders that foreclose on pledged equity and acquire the collateral themselves.","judge":null,"parties":[{"name":"Fortress Investment Group","role":"Lender/Defendant"},{"name":"Fortress Credit Corp.","role":"Lender/Judgment creditor (Fortress affiliate)"}],"amountUsd":204000000,"amountBasis":"damages sought","tags":["ucc foreclosure","commercial reasonableness","loan default","new york","office"],"hasFull":true},{"id":"live-179","addedDate":"2026-09-25","title":"Pinnacle North, LLC Veil-Piercing Appeal (Michigan Court of Appeals Affirms Personal Liability for Office Tenant's Lease Default)","brief":"In an unpublished opinion, Michigan's Court of Appeals affirmed rulings holding a defunct office tenant's sole member personally liable for its $52,548.24 lease judgment to Pinnacle North and voiding a $50,000 payment to him.","category":"lease-disputes","status":"ruling","date":"2026-03-24","jurisdiction":"Michigan Court of Appeals","state":"MI","amount":"$52,548.24 default judgment plus interest and costs; about $92,000 attorney fee award affirmed; $50,000 transfer held voidable","source":"live","sourceUrl":"https://www.courts.michigan.gov/siteassets/case-documents/uploads/OPINIONS/FINAL/COA/20260324_C370640_39_370640.opn.pdf","summary":"In an unpublished per curiam opinion issued March 24, 2026, the Michigan Court of Appeals affirmed Oakland Circuit Court rulings that landlord Pinnacle North, LLC could pierce the veil of its former tenant, Marketplace Home Mortgage, LLC, and hold the company's sole member and president personally liable for a $52,548.24 default judgment on its office lease, plus interest, costs and fees. The court also affirmed that a $50,000 check the insolvent company wrote to him in December 2019 was a voidable transfer, and upheld an award of about $92,000 in attorney fees under the lease.","significance":"The panel affirmed on a record showing that the tenant's assets were sold without the lease liability while its principal used company funds to pay down obligations for which he could be personally liable and to pay himself. Because the opinion is unpublished, it is not binding precedent in Michigan.","judge":"Per curiam (Patel, P.J., Swartzle and Mariani, JJ.)","parties":[{"name":"Pinnacle North, LLC","role":"Plaintiff-Appellee/Landlord"},{"name":"Marketplace Home Mortgage, LLC","role":"Former tenant (not a party to this appeal)"}],"amountUsd":52548.24,"amountBasis":"judgment","propertyType":"Office","documentUrl":"https://www.courts.michigan.gov/siteassets/case-documents/uploads/OPINIONS/FINAL/COA/20260324_C370640_39_370640.opn.pdf","documentLabel":"Read the official Court of Appeals opinion","tags":["veil piercing","alter ego","commercial lease","michigan","judgment collection"],"hasFull":true},{"id":"live-184","addedDate":"2026-09-26","featured":true,"title":"Wells Fargo Foreclosure Auction of 100 Summer Street (Rockpoint, Boston)","brief":"Rockpoint was the sole bidder at a $260 million foreclosure auction of 100 Summer St., the Boston tower it bought for $806 million in 2019 with a $470 million Wells Fargo loan.","category":"lending-foreclosure","status":"filed","date":"2026-09-23","jurisdiction":"Suffolk County, Massachusetts (non-judicial foreclosure by power of sale)","state":"MA","amount":"$470M mortgage; $806M 2019 purchase price; $260M winning auction bid","source":"live","sourceUrl":"https://www.bostonglobe.com/2026/09/23/business/rockpoint-downtown-boston-office-tower-auction/","summary":"Wells Fargo foreclosed in September 2026 on 100 Summer St., a 32-story, 1.1-million-square-foot downtown Boston office tower owned by Rockpoint, which bought it for $806 million in October 2019 with a $470 million Wells Fargo mortgage, the Boston Globe and Bisnow reported. The foreclosure auction, first set for Oct. 20, was rescheduled. Rockpoint was the sole bidder at the $260 million opening bid, Bisnow reported on Oct. 27.","significance":"The $260 million result, Rockpoint's single bid at the auctioneer's opening price, is about a third of the 2019 purchase price. It follows other Boston office auctions, including One Lincoln St., which sold at auction last year for $400 million.","judge":null,"parties":[{"name":"Rockpoint Group","role":"Borrower/Owner"},{"name":"Wells Fargo","role":"Lender"}],"amountUsd":470000000,"amountBasis":"loan","propertyType":"Office","tags":["foreclosure","foreclosure auction","office","boston"],"hasFull":true},{"id":"live-186","addedDate":"2026-09-26","title":"Embassy Suites Portland Airport $49.7M CMBS Loan Moves to Special Servicing After Missed Maturity","brief":"The $49.7 million CMBS loan on the 251-key Embassy Suites by Hilton Portland Airport moved to special servicing after missing its August 2026 maturity, Connect CRE and The Registry reported.","category":"lending-foreclosure","status":"pending","date":"2026-09-11","jurisdiction":"Multnomah County, Oregon (pre-litigation; loan in special servicing)","state":"OR","amount":"$49.7M CMBS loan (GSMS 2016-GS3 / GSMS 2016-GS4)","source":"live","sourceUrl":"https://news.theregistryps.com/251-key-embassy-suites-portland-airport-hits-special-servicing-after-missing-49-7mm-loan-maturity/","summary":"The $49.7 million CMBS loan on the 251-key Embassy Suites by Hilton Portland Airport moved to special servicing after it missed its August 2026 maturity date, Connect CRE reported. The loan is split between the GSMS 2016-GS3 and GSMS 2016-GS4 securitizations, and KBRA said the GS4 portion transferred to special servicing on September 11, 2026. The Registry reported that Rialto Capital Advisors is handling the workout.","significance":"The loan stayed current for its whole term on thin cash flow and defaulted only at maturity, when the full balance came due. No foreclosure or receivership filing had been reported.","judge":null,"parties":[{"name":"Rialto Capital Advisors","role":"Special Servicer"}],"amountUsd":49700000,"amountBasis":"loan","propertyType":"Hospitality","tags":["cmbs","special servicing","hospitality","hotel","oregon"],"hasFull":true},{"id":"live-187","addedDate":"2026-09-26","featured":true,"title":"From $97.3M Default to Rebrand: ACORE Capital Repositions Salt Lake City's Industry SLC as Foundry43","brief":"After suing over a $97.3 million loan default, ACORE Capital took control of Salt Lake City's Industry SLC office campus and has relaunched it as Foundry43 with Lincoln Property Company.","category":"lending-foreclosure","status":"settled","date":"2026-09-24","jurisdiction":"Utah Business and Chancery Court","state":"UT","amount":"$97.3M loan default alleged","source":"live","sourceUrl":"https://buildingsaltlake.com/foreclosed-industry-slc-rebrands-as-foundry43-under-lender-acore/","summary":"ACORE Capital and Lincoln Property Company have relaunched Industry SLC, a 230,000-square-foot office campus in Salt Lake City's Granary District, as Foundry43, with JLL leading leasing, Building Salt Lake reported on September 24, 2026. ACORE Capital Mortgage sued in Utah's Business and Chancery Court in fall 2025, alleging Catalyst Opportunity Funds had defaulted on a $97.3 million loan; the property went into receivership and a foreclosure sale was scheduled for early March 2026. A deed signed March 9 and recorded June 1 conveyed the parcels from ACORE to Marwood Investment Trust, a Delaware statutory trust.","significance":"The relaunch shows a lender finishing and re-leasing a defaulted adaptive-reuse campus rather than selling it. Work on the remaining office and fitness space is still under way.","judge":null,"parties":[{"name":"ACORE Capital Mortgage","role":"Plaintiff/Lender"},{"name":"Catalyst Opportunity Funds","role":"Defendant/Borrower"},{"name":"Marwood Investment Trust","role":"Grantee of the property"}],"amountUsd":97300000,"amountBasis":"loan","propertyType":"Office","tags":["foreclosure","office distress","utah","adaptive reuse","private credit"],"hasFull":true},{"id":"live-188","addedDate":"2026-09-26","title":"Joliet Residents for Responsible Growth v. City of Joliet (Joliet Technology Center Data Center Zoning Suit)","brief":"A Will County judge on Oct. 19, 2026 ruled against all four counts of a challenge to Joliet's approval of the $20 billion Joliet Technology Center data center, leaving room to replead a zoning claim.","category":"zoning-land-use","status":"ruling","date":"2026-10-19","jurisdiction":"Circuit Court of Will County, Illinois","state":"IL","amount":"$20 billion project value at stake","source":"live","sourceUrl":"https://www.shawlocal.com/the-herald-news/2026/08/18/lawsuit-against-joliet-data-center-heading-to-court-hearing/","summary":"Joliet Residents for Responsible Growth and three of its members sued the City of Joliet and three companies tied to the $20 billion, 795-acre Joliet Technology Center on May 18, 2026, seeking to void the City Council's 8-1 approval of the data center's annexation agreement on March 19, The Herald-News reported. The suit alleged defective public notice, Open Meetings Act and due process violations, and an unconstitutional rezoning. On October 19, 2026, Will County Judge Victoria Breslan ruled for the defendants on all four counts, dismissing the zoning count without prejudice, according to a law-firm analysis of the order.","significance":"The order has been described as the first significant Illinois trial-court ruling on challenges to local hyperscale data center approvals. It held that a hearing notice need not call a project a data center, while leaving room for zoning claims by neighbors who can plead concrete harm to their own parcels.","judge":"Victoria Breslan","parties":[{"name":"Joliet Residents For Responsible Growth","role":"Plaintiff"},{"name":"City of Joliet","role":"Defendant"},{"name":"Powerhouse Hillwood Holding","role":"Defendant"},{"name":"HW Technology Park Development","role":"Defendant"},{"name":"American Real Estate Partners","role":"Defendant"}],"amountUsd":20000000000,"amountBasis":"other","propertyType":"Data Center","tags":["data center","zoning","open meetings act","illinois","annexation"],"hasFull":true},{"id":"live-189","addedDate":"2026-09-26","title":"City of Edgerton, Kansas Suit Over Data Center Petition Struck Under State Anti-SLAPP Law","brief":"A Kansas judge struck Edgerton's suit against two residents and their nonprofit over a petition to block data centers, finding it violated the state anti-SLAPP law.","category":"zoning-land-use","status":"ruling","date":"2026-09-03","jurisdiction":"Johnson County District Court, Kansas","state":"KS","amount":"Not applicable (challenge to a citizen petition)","source":"live","sourceUrl":"https://johnsoncountypost.com/2026/09/10/judge-dismisses-city-of-edgertons-lawsuit-295865/","summary":"Johnson County District Judge Stephanie Goodenow on September 3, 2026 granted a motion to strike the City of Edgerton, Kansas's lawsuit against two residents and their nonprofit, Public Trust Collective Inc., over a citizen petition aimed at stopping data centers in the city, the Johnson County Post reported. She found the suit violated the defendants' rights under the Kansas Public Speech Protection Act. The city said it respects the decision but still has concerns about the proposed ordinance and is evaluating its options.","significance":"The ruling applies Kansas's anti-SLAPP law to a suit brought by a city against its own residents over a petition. It was not reported to settle whether the petition's ordinance is legislative and so eligible for a public vote, which was being fought in a separate case.","judge":"Stephanie Goodenow","parties":[{"name":"City of Edgerton","role":"Plaintiff"},{"name":"Public Trust Collective Inc.","role":"Defendant"}],"amountUsd":null,"propertyType":"Data Center","tags":["data center","anti-slapp","citizen petition","kansas","municipal litigation"],"hasFull":true},{"id":"live-192","addedDate":"2026-09-27","title":"A&F Williams Street LLC v. New York Power Authority ($3M+ Structural Damage Suit Over White Plains Garage Demolition)","brief":"A&F Williams Street sued the New York Power Authority for more than $3 million, alleging vibration from demolition at NYPA's garage damaged the roof of its White Plains office building at 165 Main Street.","category":"premises-liability","status":"filed","date":"2026-09-15","jurisdiction":"Supreme Court of the State of New York, Westchester County","state":"NY","amount":"$3 million+ in demanded damages and repair costs","source":"live","sourceUrl":"https://westfaironline.com/latest-news/white-plains-landlord-sues-new-york-power-authority-for-3m/","summary":"A&F Williams Street LLC, owner of a five-story office building at 165 Main Street in White Plains, sued the New York Power Authority in Westchester County Supreme Court on September 15, 2026, Westfair Communications reported. The negligence and trespass suit alleges vibration from NYPA's demolition and construction project at its parking garage cracked the building's rooftop parapet and detached roofing membrane, and seeks more than $3 million and an order halting the work until the parties agree on access terms. The complaint says NYPA denied responsibility; NYPA told Westfair it does not comment on pending litigation.","significance":"The case shows how an access agreement with a neighbor, here one in which NYPA allegedly agreed to fix any damage, can become the basis of a damage claim once demolition causes harm. Owners next to demolition projects, and those doing the work, should look at how access agreements handle damage, repair and expiration.","judge":null,"parties":[{"name":"A&F Williams Street LLC","role":"Plaintiff"},{"name":"New York Power Authority","role":"Defendant"}],"amountUsd":3000000,"amountBasis":"damages sought","tags":["premises-liability","construction-damage","trespass","negligence","white-plains"],"hasFull":true},{"id":"live-193","addedDate":"2026-09-27","featured":true,"title":"Baltimore Residents Sue to Block MCB's $900M Harborplace Redevelopment","brief":"Seven Baltimore residents sued the city and an MCB Real Estate affiliate to void the 2023 bills behind the $900 million Harborplace redevelopment, alleging violations of the City Charter and Maryland Constitution.","category":"zoning-land-use","status":"filed","date":"2026-09-21","jurisdiction":"Circuit Court for Baltimore City, Maryland","state":"MD","amount":"$900 million redevelopment; suit seeks to void enabling zoning/Charter legislation","source":"live","sourceUrl":"https://baltimorefishbowl.com/stories/seven-residents-file-suit-to-block-mcb-real-estates-900m-plan-to-demolish-and-replace-baltimores-harborplace-pavilions/","summary":"Seven Baltimore residents sued the Mayor and City Council of Baltimore, the City Council, the Board of Estimates and MCB HP Baltimore LLC in the Circuit Court for Baltimore City on September 21, 2026, seeking to block MCB Real Estate's $900 million plan to demolish and replace the Harborplace pavilions, Baltimore Fishbowl reported. The 31-page complaint asks the court to declare void three 2023 City Council bills that changed zoning and removed height limits for the project, along with the city's March 31, 2023 lease with MCB. It alleges the bills are unconstitutional \"special laws\" and that the city granted MCB rights in public parkland without following the City Charter's franchise procedures. The city said it would reserve comment for court, and MCB had not responded to a request for comment.","significance":"The suit attacks the legal process behind the approvals rather than the design, targeting the enabling bills, the lease and the Charter's rules for granting rights in public parkland. If the court agreed, the project's enabling legislation would be void regardless of its political support.","judge":null,"parties":[{"name":"MCB HP Baltimore LLC","role":"Defendant/Developer"},{"name":"Mayor and City Council of Baltimore","role":"Defendant"},{"name":"City Council of Baltimore City","role":"Defendant"},{"name":"Board of Estimates of Baltimore City","role":"Defendant"}],"amountUsd":900000000,"amountBasis":"other","propertyType":"Mixed-Use","tags":["zoning","land use","harborplace","baltimore","waterfront redevelopment"],"hasFull":true},{"id":"live-194","addedDate":"2026-09-27","title":"7920 Riviera Beach Holdings LLC v. Riviera Beach Utility Special District (157% Water Impact Fee Suit)","brief":"A developer sued Riviera Beach's utility district, alleging a 157% water and wastewater impact-fee increase was applied to its pending 315-unit project, adding $1.6 million, the Palm Beach Post reported.","category":"zoning-land-use","status":"filed","date":"2026-09-18","jurisdiction":"Circuit Court of the 15th Judicial Circuit, Palm Beach County, Florida","state":"FL","amount":"$1.6 million in added impact fees at issue","source":"live","sourceUrl":"https://www.bocaratontribune.com/bocaratonnews/2026/09/developer-sues-city-says-water-fees-violates-florida-law/","summary":"7920 Riviera Beach Holdings LLC sued the Riviera Beach Utility Special District in Palm Beach County Circuit Court on Sept. 18, 2026, alleging the district is charging its 315-unit apartment project at 7880 N. Military Trail higher water and wastewater impact fees adopted after the developer submitted its permits, the Palm Beach Post reported. The suit says the combined fee rose from $3,940 to $10,126 per unit, which would cost the developer $2.6 million and raise the project's cost by $1.6 million. According to the suit, the district has asserted through counsel that the charges are water and sewer connection fees outside the Florida Impact Fee Act.","significance":"The case turns on whether Florida's Impact Fee Act, which bars new or increased impact fees from applying to pending permit applications, covers charges the district has since relabeled as capital charges. The answer decides which fee schedule applies to a project already in the permit process when the increase took effect.","judge":null,"parties":[{"name":"7920 Riviera Beach Holdings LLC","role":"Plaintiff/Developer"},{"name":"Riviera Beach Utility Special District","role":"Defendant"}],"amountUsd":1600000,"amountBasis":"claim","propertyType":"Multifamily","tags":["impact fees","zoning","multifamily development","florida","municipal law"],"hasFull":true},{"id":"live-196","addedDate":"2026-09-28","featured":true,"title":"Negligent Security Suit Over Northwoods Mall Food Court Stabbing (North Charleston, S.C.)","brief":"A woman stabbed in the Northwoods Mall food court in North Charleston sued the mall and security contractor Allied Universal, alleging security failed to stop an attacker carrying an open blade, WCSC reported.","category":"premises-liability","status":"filed","date":"2026-09-24","jurisdiction":"South Carolina Court of Common Pleas, Charleston County","state":"SC","amount":"Unspecified damages sought","source":"live","sourceUrl":"https://www.live5news.com/2026/09/25/lawsuit-woman-stabbed-northwoods-mall-sues-mall-owners-security/","summary":"A woman who was stabbed by a stranger in the food court of Northwoods Mall in North Charleston, South Carolina on March 4, 2026 has sued the mall and its security company, Allied Universal, alleging they failed to maintain reasonable security, WCSC Live 5 reported on September 24. The suit alleges that security did not stop the attacker, who walked in carrying an open blade, and that no one was patrolling the food court. A mall representative said the mall cannot comment on pending litigation, and Allied Universal had not responded to requests for comment.","significance":"Negligent-security suits against shopping-center owners often turn on whether an attack was foreseeable, and this complaint relies on the mall's history of police reports to argue it was. It adds to litigation over security at Northwoods Mall, where victims of a 2021 parking-lot shooting also sued.","judge":null,"parties":[{"name":"Northwoods Mall (owner entity not named in reporting)","role":"Defendant"},{"name":"Allied Universal","role":"Defendant"}],"amountUsd":null,"propertyType":"Retail","tags":["premises-liability","negligent-security","shopping-mall","south-carolina"],"hasFull":true},{"id":"live-197","addedDate":"2026-09-28","title":"SDCL Tennessee Propco LLC v. Bradley County (Data Center Zoning Ordinance Challenge)","brief":"Data center developer SDCL Tennessee Propco sued Bradley County, Tennessee to void rules confining data centers to one industrial district with a 3,000-foot setback, alleging skipped procedures.","category":"zoning-land-use","status":"filed","date":"2026-09-17","jurisdiction":"Bradley County Chancery Court, Tennessee","state":"TN","amount":"$19.9M land purchase underlying a challenge to the county's data-center zoning ordinance (no damages sought)","source":"live","sourceUrl":"https://www.timesfreepress.com/news/2026/sep/21/global-firm-sues-bradley-county-to-build-300-acre/","summary":"SDCL Tennessee Propco LLC, the developer of a planned data center campus called Project MidSpan, sued Bradley County, Tennessee in Chancery Court on Sept. 17, 2026, WTVC NewsChannel 9 reported. It asks a judge to declare invalid the county commission's April 2026 rules limiting data centers to the I-2 Special Impact Industrial District and barring them within 3,000 feet of an existing home, school or church, and to bar their enforcement against its roughly 306 acres in the Hiwassee River Industrial Park. The company, which says it paid $19,904,950 for the land, alleges the county did not follow required procedures and that the rules are arbitrary and discriminatory; Mayor Gary Davis said the county will defend them.","significance":"The case tests whether a county's data center restrictions can be undone for defects in how they were adopted, including planning-commission review, public notice and open-meetings requirements. It also raises whether a single eligible district combined with a 3,000-foot setback effectively excludes data centers from the unincorporated county.","judge":null,"parties":[{"name":"SDCL Tennessee Propco LLC","role":"Plaintiff"},{"name":"Bradley County, Tennessee","role":"Defendant"}],"amountUsd":19904950,"amountBasis":"purchase price","propertyType":"Data Center","tags":["data-center","zoning","land-use","tennessee"],"hasFull":true},{"id":"live-199","addedDate":"2026-09-28","featured":true,"title":"In re Brass Works Urban Renewal Company, LLC (Chapter 11 Dismissed After Preferred-Equity Investor Won Control of The Cliffs Lofts' Owner)","brief":"A New Jersey bankruptcy judge dismissed Brass Works' Chapter 11 on a motion by preferred-equity investor ASVRF, months after Delaware's Chancery Court upheld ASVRF's removal of Brass Works as manager.","category":"lending-foreclosure","status":"ruling","date":"2026-09-25","jurisdiction":"United States Bankruptcy Court, District of New Jersey","state":"NJ","propertyType":"Multifamily","amount":"ASVRF contributed $18 million for its preferred interest in the property-owning LLC","source":"live","sourceUrl":"https://www.law360.com/bankruptcy-authority/mid-cap/articles/2530821","summary":"U.S. Bankruptcy Judge Mark E. Hall dismissed the Chapter 11 case of Brass Works Urban Renewal Company, LLC in an order entered September 25, 2026, citing the harm to the creditor that sought dismissal, Law360 reported. The motion was brought by preferred-equity investor ASVRF Paterson Plank RD J-C, LLC and Paterson Plank RD J-C, LLC, the company that owns The Cliffs Lofts, a 120-unit residential building in Jersey City. Brass Works filed for Chapter 11 on May 22, 2026, about six months after Delaware's Court of Chancery ruled that ASVRF had validly removed it as that company's manager.","significance":"The case shows a sponsor turning to Chapter 11 to try to cure its default and reclaim management after losing a control fight, and a bankruptcy court ending the case on the investor's motion. Preferred-equity investors who win a removal remedy in one court may still face a follow-on bankruptcy filing before the dispute is over.","judge":"Mark E. Hall","parties":[{"name":"Brass Works Urban Renewal Company, LLC","role":"Debtor"},{"name":"ASVRF Paterson Plank RD J-C, LLC","role":"Preferred Equity Investor (Movant)"},{"name":"Paterson Plank RD J-C, LLC","role":"Property-Owning Company (Movant)"}],"amountUsd":18000000,"amountBasis":"other","documentUrl":"https://www.courtlistener.com/opinion/10740485/asvrf-paterson-plank-rd-j-c-llc-v-brass-works-urban-renewal-company-llc/","documentLabel":"Read the related Delaware Chancery opinion (ASVRF v. Brass Works)","tags":["chapter-11","preferred-equity","urban-renewal","new-jersey","dismissal"],"docketUrl":"https://www.courtlistener.com/docket/73382121/brass-works-urban-renewal-company-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-200","addedDate":"2026-09-28","title":"TerraWatt Developer v. City of St. Louis Board of Adjustment (Midtown Armory Data Center Zoning Cross-Suits)","brief":"A TerraWatt partner sued St. Louis' Board of Adjustment over renewable-energy and community-benefits conditions on a $3.1 billion data center permit that opponents are also challenging in court.","category":"zoning-land-use","status":"filed","date":"2026-09-16","jurisdiction":"Circuit Court of the City of St. Louis, Missouri","state":"MO","propertyType":"Data Center","amount":"$3.1 billion data center project (scale of underlying development)","source":"live","sourceUrl":"https://www.stlpr.org/news-briefs/2026-09-17/developer-st-louis-data-center-armory-files-lawsuit-against-city","summary":"St. Louis Public Radio reported that David Lambiaso, a partner in data center developer TerraWatt, sued the city's Board of Adjustment in mid-September 2026 over two conditions attached to the conditional use permit for a planned $3.1 billion, 120-megawatt data center in the former Famous-Barr warehouse on Market Street in Midtown. The suit says a requirement for 2.4 megawatts of renewable energy is \"practically impossible\" on the 11-acre site and that a requirement for Board of Aldermen approval of a community benefits agreement exceeds the board's authority. Separately, the Missouri Coalition for the Environment and other opponents sued on Aug. 28, 2026, arguing the city illegally granted the permit.","significance":"The two suits attack the same permit from opposite sides: opponents say it should not have been granted, and the developer says conditions attached to it go beyond the board's authority. The outcome may show how far a St. Louis zoning board can go in attaching energy and community-benefit conditions to a conditional use permit.","judge":null,"parties":[{"name":"TerraWatt","role":"Developer (petition filed by a TerraWatt partner)"},{"name":"City of St. Louis Board of Adjustment","role":"Respondent"},{"name":"City of St. Louis","role":"Respondent (opponents' suit)"},{"name":"Missouri Coalition for the Environment","role":"Petitioner (opponents' suit)"}],"amountUsd":null,"tags":["data-center","zoning","missouri","community-benefits-agreement","conditional-use-permit"],"hasFull":true},{"id":"live-201","addedDate":"2026-09-29","featured":true,"title":"U.S. Bank & Wells Fargo v. Wilmorite (Eastview Mall $210M Foreclosure and Eminent Domain Fight)","brief":"U.S. Bank and Wells Fargo, foreclosing on Eastview Mall's $210 million mortgage, call the Town of Victor's plan to take mall parcels by eminent domain a 'debt evasion scheme'; the town says the public needs the mall.","category":"lending-foreclosure","status":"pending","date":"2026-09-08","jurisdiction":"Supreme Court of the State of New York, New York County","state":"NY","amount":"$210 million mortgage in default","source":"live","sourceUrl":"https://rbj.net/2026/09/28/lenders-eminent-domain-plan-eastview-mall-debt-evasion/","summary":"U.S. Bank National Association and Wells Fargo Bank, which hold the $210 million mortgage on Eastview Mall in Victor, N.Y., filed a foreclosure action in state Supreme Court in New York County on September 8, 2026, the Rochester Business Journal reported. In a September 25 letter to the town, their counsel called the town's plan to take the mortgaged portions of the mall by eminent domain and sell them to a Wilmorite-owned entity a 'debt evasion scheme.' Town Supervisor Jack Marren says a healthy mall is in the public interest, and he and Wilmorite say special servicer Rialto Capital Advisors has held back funds needed to run it.","significance":"The dispute tests whether a town can use eminent domain to acquire a defaulted mall and pass it to an affiliate of the current owner while lenders pursue foreclosure. The lenders argue eminent domain 'is not an appropriate mechanism' for giving a borrower relief from its secured creditors.","tags":["foreclosure","eminent-domain","special servicing","shopping-mall","new-york"],"parties":[{"name":"U.S. Bank National Association","role":"Lender"},{"name":"Wells Fargo Bank, National Association","role":"Lender"},{"name":"Rialto Capital Advisors","role":"Special Servicer"},{"name":"Wilmorite Management Group, LLC","role":"Mall operator/owner"},{"name":"Victor 2040 LLC","role":"Proposed buyer (Wilmorite-owned)"},{"name":"Town of Victor, New York","role":"Eminent Domain Proponent"}],"judge":null,"amountUsd":210000000,"amountBasis":"loan","propertyType":"Retail","hasFull":true},{"id":"live-202","addedDate":"2026-09-29","title":"Dundon Capital Partners' 2100 Ross Avenue Dallas Office Tower Posted for Foreclosure on $98M Loan","brief":"2100 Ross Avenue, a 33-story downtown Dallas office tower owned by Dundon Capital Partners, was posted for an October 6, 2026 foreclosure auction over a $98 million Wells Fargo loan the owner allegedly defaulted on.","category":"lending-foreclosure","status":"pending","date":"2026-09-24","jurisdiction":"Dallas County, Texas (foreclosure posting)","state":"TX","amount":"$98 million loan alleged in default","source":"live","sourceUrl":"https://therealdeal.com/texas/2026/09/24/thomas-dundon-faces-foreclosure-on-downtown-dallas-tower/","summary":"2100 Ross Avenue, a 33-story, 840,000-square-foot office tower in downtown Dallas's Arts District, was listed for an October 6, 2026 foreclosure auction, The Real Deal reported, citing Roddy's Foreclosure Listing Service. The owner, Dallas billionaire Thomas Dundon's Dundon Capital Partners, allegedly defaulted on a $98 million loan Wells Fargo made in 2016. Pacific Elm Properties manages the building. The Real Deal noted that the owner could still reach a deal with the lender before the sale date.","significance":"A foreclosure posting makes a loan default public and fixes a sale date, which leaves the owner and lender a few weeks to negotiate before the auction. The tower's history also shows how one office building can go through foreclosure twice in about 15 years under different owners.","tags":["foreclosure","office","cmbs","dallas","receivership"],"parties":[{"name":"Dundon Capital Partners","role":"Owner/Borrower"},{"name":"Wells Fargo","role":"Lender"},{"name":"Pacific Elm Properties","role":"Property Manager"}],"judge":null,"amountUsd":98000000,"amountBasis":"loan","propertyType":"Office","hasFull":true},{"id":"live-203","addedDate":"2026-09-29","title":"Slate Property Group and The Carlyle Group v. MG Developer (Metro Parc South Construction Loan Foreclosure)","brief":"Slate Property Group and The Carlyle Group sued to foreclose on MG Developer's 347-unit Metro Parc South project in Hialeah, alleging a $31.1 million default under a $105 million construction financing.","category":"lending-foreclosure","status":"filed","date":"2026-09-22","jurisdiction":"Circuit Court of the 11th Judicial Circuit, Miami-Dade County, Florida","state":"FL","amount":"$31.1M alleged default on a $105M construction loan","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/09/28/mg-developers-metro-parc-south-in-hialeah-faces-foreclosure/","summary":"Slate Property Group and The Carlyle Group sued Coral Gables-based MG Developer on September 22, 2026 to foreclose on Metro Parc South, a 10-story, 347-unit apartment project in Hialeah, Florida. The lenders allege MG defaulted on $31.1 million of a $105 million construction financing by letting construction liens attach to the property, missing required reserve deposits and not paying its 2025 property taxes. They say they sent default notices in January, May and June 2026, and that a forbearance agreement with MG has since lapsed. MG told The Real Deal it is negotiating in good faith, including bringing in an additional investor.","significance":"The case shows that covenant breaches such as liens, unfunded reserves and unpaid taxes can be enough to push a construction loan into foreclosure. It is also a reminder that forbearance only buys time: both sides should track whether the underlying breaches are actually being cured before the agreement runs out.","tags":["construction loan","foreclosure","multifamily","florida","hialeah"],"parties":[{"name":"Slate Property Group","role":"Plaintiff/Lender"},{"name":"The Carlyle Group","role":"Plaintiff/Lender"},{"name":"MG Developer","role":"Defendant/Borrower"}],"judge":null,"amountUsd":31100000,"amountBasis":"loan","propertyType":"Multifamily","hasFull":true},{"id":"live-205","addedDate":"2026-09-30","title":"American Heavy Plate Solutions, LLC v. Bitdeer (Lease-Rights Fight Over Ohio Data Center Site)","brief":"AHP says Bitdeer's Monroe County, Ohio project violates rights under AHP's own port-authority lease; a judge denied Bitdeer's motion to disqualify AHP's law firm, JDJournal reported.","category":"lease-disputes","status":"pending","date":"2026-09-08","jurisdiction":"Court of Common Pleas, Monroe County, Ohio","state":"OH","amount":"Declaratory and injunctive relief sought; no dollar figure stated","source":"live","sourceUrl":"https://www.jdjournal.com/2026/09/13/quinn-emanuel-wins-data-center-case/","summary":"American Heavy Plate Solutions, LLC (AHP) sued the Monroe County Port Authority and Bitdeer entities Erie Creek LLC, Whitetail Creek LLC and Bitdeer, Inc. in the Monroe County, Ohio Court of Common Pleas, seeking declaratory and injunctive relief over leasehold rights at an industrial property where the port authority is landlord, according to Bitdeer's Feb. 5, 2026 SEC filing. On Sept. 8, 2026, Judge Julie Selmon denied Bitdeer's motion to disqualify AHP's law firm, which also represents Bitdeer in a separate New York federal case, JDJournal reported. The judge relied on an advance conflict waiver Bitdeer had signed and the firm's separation of its two teams, and weighed the time and cost new counsel would mean for AHP.","significance":"The dispute shows how an existing tenant's rights under its own lease can become an obstacle to a large power-intensive project on land leased from the same landlord; Bitdeer has said the case may affect power and construction timing at its Ohio site. The ruling keeps AHP's chosen counsel in place as the lease claims proceed.","judge":"Julie Selmon","parties":[{"name":"American Heavy Plate Solutions, LLC","role":"Plaintiff/Tenant"},{"name":"Bitdeer Inc.","role":"Defendant"},{"name":"Erie Creek LLC","role":"Defendant"},{"name":"Whitetail Creek LLC","role":"Defendant"},{"name":"Monroe County Port Authority","role":"Defendant/Landlord"}],"amountUsd":null,"propertyType":"Industrial","tags":["data-center","lease-rights","industrial-lease","ohio","port-authority"],"hasFull":true},{"id":"live-207","addedDate":"2026-09-30","title":"State of New Jersey v. RealPage, Inc. (Court Lets New Jersey Renew Antitrust Claims Against AvalonBay)","brief":"A federal judge let New Jersey file an amended complaint renewing antitrust claims against AvalonBay in its rent-pricing suit against RealPage and landlords, after a March 31, 2026 dismissal without prejudice.","category":"landlord-tenant","status":"ruling","date":"2026-09-29","jurisdiction":"U.S. District Court, District of New Jersey","state":"NJ","amount":"No specific dollar figure stated; rent-overcharge exposure across AvalonBay's New Jersey portfolio","source":"live","sourceUrl":"https://www.law360.com/real-estate-authority/commercial/articles/2531908","summary":"On September 29, 2026, U.S. District Judge Madeline Cox Arleo granted New Jersey leave to file an amended complaint renewing antitrust claims against AvalonBay Communities, Inc. in the state's suit accusing RealPage, Inc. and landlords of using RealPage's revenue-management software to fix rents, Law360 reported. Her March 31, 2026 opinion had found a price-fixing conspiracy adequately pleaded against RealPage and the other landlords but not against AvalonBay, whose contract limits how RealPage shares and uses its data. AvalonBay argued the new allegations were insufficient; the judge said that is a factual dispute for discovery, and she denied as moot AvalonBay's motion to reconsider a consumer-fraud ruling.","significance":"The order brings AvalonBay back into the antitrust claims in one of the state enforcement cases against RealPage and its landlord customers. It also shows that a landlord's contractual limits on data sharing may not end antitrust claims at the pleading stage when the plaintiff alleges the limits were worked around.","judge":"Madeline Cox Arleo","parties":[{"name":"State of New Jersey (Attorney General and Division of Consumer Affairs)","role":"Plaintiff"},{"name":"RealPage, Inc.","role":"Defendant"},{"name":"AvalonBay Communities, Inc.","role":"Defendant"},{"name":"Morgan Properties Management Company, LLC","role":"Defendant"},{"name":"The Kamson Corporation","role":"Defendant"},{"name":"LeFrak Estate, L.P.","role":"Defendant"},{"name":"Greystar Management Services, LLC","role":"Defendant"},{"name":"AION Management, LLC","role":"Defendant"},{"name":"Cammeby's Management Co. of N.J., L.P.","role":"Defendant"},{"name":"Veris Residential, Inc.","role":"Defendant"},{"name":"Bozzuto Management Company","role":"Defendant"},{"name":"Russo Development, LLC","role":"Defendant"},{"name":"Russo Property Management, LLC","role":"Defendant"}],"amountUsd":null,"tags":["realpage","avalonbay","antitrust","algorithmic-pricing","new-jersey"],"docketUrl":"https://www.courtlistener.com/docket/69929611/platkin-v-realpage-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-208","addedDate":"2026-10-01","featured":true,"title":"Investors Sue The Davis Companies Over UCC Sale of 345 Seventh Avenue, Allege $80M Fraud by Mike Kohan","brief":"Seventeen investors sued mezzanine lender The Davis Companies to stop a UCC sale of 345 Seventh Avenue, alleging Mike Kohan defrauded them of more than $80 million. Their restraining order was denied; Davis won with a credit bid.","category":"lending-foreclosure","status":"ruling","date":"2026-09-29","jurisdiction":"Supreme Court of the State of New York","state":"NY","amount":"$80M+ allegedly obtained from investors by Kohan; $73M loan alleged in default","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/09/29/davis-companies-wins-ucc-sale-for-kohans-345-seventh-avenue/","summary":"On September 29, 2026, 17 investors in an entity controlled by landlord Mike Kohan sued mezzanine lender The Davis Companies in New York State Supreme Court, alleging that its UCC foreclosure sale of 345 Seventh Avenue, a Garment District office building, was defective and could sell the property for less than it is worth. The same complaint alleges that Kohan obtained more than $80 million from the investors by promising them ownership stakes they never received. The investors' request for a temporary restraining order was denied, and Davis acquired an equity stake in the property with a credit bid, which its attorney said puts the firm on a path to control the building.","significance":"Investors who fund a sponsor's property entities depend on their stakes appearing in the documents lenders rely on. If those stakes are missing, the investors may have little power to stop a mezzanine lender's UCC sale. Mezzanine lenders, for their part, should expect a UCC sale to draw last-minute challenges from people claiming equity, even when a court declines to halt it.","judge":null,"parties":[{"name":"The Davis Companies","role":"Defendant/Mezzanine Lender"}],"amountUsd":80000000,"amountBasis":"claim","propertyType":"Office","tags":["office","fraud","ucc-foreclosure","mezzanine-loan","new-york"],"hasFull":true},{"id":"live-210","addedDate":"2026-10-01","title":"Rialto Capital Takes 580 Market Street, a San Francisco Financial District Office Building, in Foreclosure","brief":"Special servicer Rialto Capital took over 580 Market Street, a 35,000-square-foot Financial District office building, for $5 million after owner Paragon Company's $15.7 million loan matured unpaid.","category":"lending-foreclosure","status":"filed","date":"2026-09-30","jurisdiction":"San Francisco, California (trustee's sale)","state":"CA","propertyType":"Office","amount":"$17.5M unpaid debt; Rialto paid $5M","amountUsd":17500000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/san-francisco/2026/09/30/rialto-capital-takes-san-francisco-offices-in-foreclosure/","summary":"Special servicer Rialto Capital took control of 580 Market Street, a century-old, 35,000-square-foot office building next to San Francisco's Montgomery BART station, through foreclosure, The Real Deal reported, citing the San Francisco Business Times. Owner Paragon Company's $15.7 million loan matured in June 2025, and a notice of default was served in October 2025. A trustee's deed recorded in July 2026 showed $17.5 million in unpaid debt, and Rialto paid $5 million for the property.","significance":"The $5 million price, against a March appraisal of $9.9 million and a 2015 purchase price of $24.2 million, gives owners and lenders a current reference point for small Financial District office buildings. It also shows that a lender that takes back an office building may plan to hold and lease it for years rather than sell right away.","judge":null,"parties":[{"name":"Rialto Capital","role":"Special Servicer"},{"name":"Paragon Company","role":"Owner/Borrower"}],"tags":["office","foreclosure","special-servicer","san-francisco","cmbs"],"hasFull":true},{"id":"live-211","addedDate":"2026-10-01","title":"Criterion Real Estate Capital Affiliate Files Foreclosure Notice Against Judiciary Plaza LLC (450 Fifth St. NW, Washington, D.C.)","brief":"A Criterion Real Estate Capital affiliate filed a foreclosure notice for 450 Fifth St. NW, a D.C. office building slated for residential conversion, saying the owner owes $166.6 million.","category":"lending-foreclosure","status":"filed","date":"2026-09-28","jurisdiction":"Washington, D.C. (non-judicial deed of trust foreclosure)","state":"DC","propertyType":"Office","amount":"$166.6M owed on a $177.5M 2007 note","amountUsd":166600000,"amountBasis":"loan","source":"live","sourceUrl":"https://www.connectcre.com/stories/return-to-lender-week-of-oct-1-2026/","summary":"An affiliate of noteholder Criterion Real Estate Capital filed a foreclosure notice on September 28, 2026 for 450 Fifth St. NW, a 539,478-square-foot Brutalist office building near Judiciary Square in Washington, D.C., the Washington Business Journal reported, according to Connect CRE. The notice says the owner, Judiciary Plaza LLC, owes $166.6 million on a $177.5 million note from 2007, and sets an October 28, 2026 foreclosure auction at the D.C. office of Alex Cooper Auctioneers. The building had been slated for conversion into 500 residential units.","significance":"The notice puts an office building slated for a 500-unit residential conversion on a path to a foreclosure auction. Nearly two decades after the 2007 note, the notice says $166.6 million of the original $177.5 million is still owed.","judge":null,"parties":[{"name":"Criterion Real Estate Capital","role":"Noteholder"},{"name":"Judiciary Plaza LLC","role":"Borrower"}],"tags":["office","foreclosure","washington-dc","office-to-residential","deed-of-trust"],"hasFull":true},{"id":"live-212","addedDate":"2026-10-02","title":"Colorado Apartment Association v. Ryan (Federal Preemption Challenge to Denver and Colorado Building-Performance Standards)","brief":"A federal judge let four real estate trade groups pursue claims that federal appliance-efficiency law preempts Energize Denver and Colorado's Regulation 28, dismissing consumer-appliance claims as time-barred.","category":"zoning-land-use","status":"ruling","date":"2026-09-30","jurisdiction":"U.S. District Court, District of Colorado","state":"CO","amount":"No damages at issue; compliance-cost exposure for large buildings subject to Energize Denver and Regulation 28","amountUsd":null,"source":"live","docketUrl":"https://www.courtlistener.com/docket/68461369/colorado-apartment-association-v-ryan/","docketLabel":"CourtListener docket","sourceUrl":"https://www.law360.com/articles/2532921/colo-energy-rules-can-t-shake-federal-preemption-suit","summary":"On September 30, 2026, U.S. District Judge Regina M. Rodriguez adopted a magistrate judge's recommendation and let four real estate trade groups proceed with claims that Denver's Energize Denver program and Colorado's Regulation 28 are preempted by the federal Energy Policy and Conservation Act (EPCA), as Law360 reported. The court dismissed with prejudice the groups' claims concerning consumer appliances as barred by a two-year statute of limitations, and it rejected their argument that Regulation 28's greenhouse-gas intensity cap is preempted. The order rules only on the motions to dismiss and does not block either program.","significance":"The ruling keeps alive a federal challenge to building-performance standards that apply to large commercial and multifamily buildings in Denver and across Colorado. The court drew a line between rules that impose building-wide energy-use reductions, which it said could be preempted, and Regulation 28's greenhouse-gas intensity cap, which it found is not.","judge":"Regina M. Rodriguez","parties":[{"name":"Colorado Apartment Association","role":"Plaintiff"},{"name":"Apartment Association of Metro Denver","role":"Plaintiff"},{"name":"Colorado Hotel and Lodging Association","role":"Plaintiff"},{"name":"NAIOP Colorado Chapter","role":"Plaintiff"},{"name":"Colorado Department of Public Health and Environment (executive director, official capacity)","role":"Defendant"},{"name":"Colorado Air Pollution Control Division (director, official capacity)","role":"Defendant"},{"name":"Colorado Energy Office (executive director, official capacity)","role":"Defendant"},{"name":"City and County of Denver","role":"Defendant"},{"name":"Denver Office of Climate Action, Sustainability, and Resiliency","role":"Defendant"},{"name":"Coalition for Community Solar Access","role":"Intervenor-Defendant"},{"name":"Colorado Solar and Storage Association","role":"Intervenor-Defendant"},{"name":"Natural Resources Defense Council","role":"Intervenor-Defendant"},{"name":"Sierra Club","role":"Intervenor-Defendant"}],"tags":["zoning","preemption","building-emissions","denver","epca"],"hasFull":true},{"id":"live-213","addedDate":"2026-10-02","title":"Tri-State Insurance Co. of Minnesota v. Namdar Realty Group (Bangor Mall Sprinkler-Failure Default Judgment)","brief":"A Maine judge ruled that Bangor Mall owner Namdar Realty Group must pay just over $1.1 million to a furniture store's insurer after a burst sprinkler pipe destroyed stored inventory, the Bangor Daily News reported.","category":"premises-liability","status":"ruling","date":"2026-09-24","jurisdiction":"Penobscot County Superior Court, Maine","state":"ME","propertyType":"Retail","amount":"$1.1M default judgment entered","amountUsd":1100000,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.bangordailynews.com/2026/10/02/bangor/bangor-police-courts/bangor-mall-owner-must-pay-1-1m-in-another-lawsuit/","summary":"Penobscot County Judge Bruce Mallonee signed a decision on September 24, 2026 ordering Bangor Mall owner Namdar Realty Group to pay just over $1.1 million to Tri-State Insurance Company of Minnesota, the Bangor Daily News reported. The ruling followed Namdar's failure to respond to multiple letters and to appear at a September 23 hearing. The insurer had sued to recover what it paid Furniture, Mattresses & More for inventory destroyed by water at the mall; its claims against Maine Fire Protection Systems, which has appeared in the case, are expected to continue.","significance":"The ruling came after the mall owner did not respond to the suit, so the insurer's claims were never tested on the merits. It is the second seven-figure ruling against Namdar over the Bangor Mall this year, following the city's code-enforcement case.","judge":"Bruce Mallonee","parties":[{"name":"Tri-State Insurance Company of Minnesota","role":"Plaintiff"},{"name":"Namdar Realty Group","role":"Defendant"},{"name":"Maine Fire Protection Systems","role":"Defendant"}],"tags":["premises-liability","mall","default-judgment","subrogation","maine"],"hasFull":true},{"id":"live-214","addedDate":"2026-10-02","title":"Grand 1401 Owner v. City of Fresno (Downtown Parking Dispute)","brief":"The owner of Fresno's Grand 1401 building was set to go to a jury trial Oct. 12, 2026 on claims the city reneged on 100 promised free parking spaces; he says losses could top $7 million.","category":"zoning-land-use","status":"pending","date":"2026-10-02","jurisdiction":"Fresno County Superior Court, California","state":"CA","propertyType":"Office","amount":"$7M+ in potential losses cited by developer","amountUsd":7000000,"amountBasis":"damages sought","source":"live","sourceUrl":"https://gvwire.com/2026/10/02/tutelian-lawsuit-against-fresno-over-downtown-parking-set-for-jury-trial/","summary":"A commercial developer's lawsuit against the City of Fresno over 100 free parking spaces near his Grand 1401 building was set for a jury trial beginning October 12, 2026 before Fresno County Superior Court Judge D. Tyler Tharpe, GV Wire reported. He says the city, under then-Mayor Ashley Swearengin, promised the spaces to help bring anchor tenant Tutor Perini downtown; the city disputes that such an agreement existed. Construction of a new city parking garage has cut off access to the spaces, and he says losing Tutor Perini could cost him more than $7 million.","significance":"The case tests whether an informal inducement a city offered to attract an office tenant can be enforced years later, after a change in administration and a competing city project on the same site. For owners whose buildings rely on one anchor tenant, it shows how the loss of an amenity such as parking can become a lease-retention risk.","judge":"D. Tyler Tharpe","parties":[{"name":"City of Fresno","role":"Defendant"}],"tags":["zoning","parking","fresno","development-agreement","municipal"],"hasFull":true},{"id":"live-215","addedDate":"2026-10-02","title":"Oklahoma Department of Securities v. Vesta Realty, LLC (Subpoena Enforcement Action)","brief":"Oklahoma's securities regulator sued Vesta Realty on Aug. 24, 2026, alleging it failed to produce subpoenaed records on investors in its LLCs; CEO Marc Kulick said the company is hiring a lawyer.","category":"reit-securities","status":"pending","date":"2026-08-24","jurisdiction":"Oklahoma district court (county not stated in the source)","state":"OK","propertyType":"Multifamily","amount":"No damages sought; civil subpoena-enforcement action","amountUsd":null,"source":"live","sourceUrl":"https://oklahomawatch.org/2026/10/01/oklahoma-department-of-securities-sues-vesta-realty-for-failing-to-hand-over-subpoenaed-documents/","summary":"The Oklahoma Department of Securities sued Vesta Realty, LLC on August 24, 2026, alleging the Tulsa-based multifamily company failed to provide subpoenaed documents, including the identities of and communications with investors in some of the limited liability companies under the Vesta umbrella, Oklahoma Watch reported. The department has asked the district court to order the records produced. CEO Marc Kulick told Oklahoma Watch the company is 'in the process of engaging an attorney' and looks forward to resolving the matter.","significance":"The case is a civil subpoena-enforcement action, though the department's statute allows criminal referrals and information sharing with enforcement agencies. It adds a state regulator to the private suits already filed against Vesta and Kulick.","judge":null,"parties":[{"name":"Oklahoma Department of Securities","role":"Plaintiff"},{"name":"Vesta Realty, LLC","role":"Defendant"}],"tags":["securities","multifamily","oklahoma","subpoena-enforcement","vesta realty"],"hasFull":true},{"id":"live-219","addedDate":"2026-10-03","featured":true,"title":"N17 Development v. City of Menlo Park (Willow Park Housing-Law Suit)","brief":"N17 Development sued Menlo Park, alleging the city violated state housing laws in reviewing its 665-unit Willow Park project; the city says it followed state law. A writ hearing is set for Dec. 14.","category":"zoning-land-use","status":"filed","date":"2026-10-02","jurisdiction":"San Mateo County Superior Court","state":"CA","propertyType":"Mixed-Use","amount":"Roughly $300,000 in fees sought; fines of at least $6.65 million (KQED) and up to $33 million (The Registry) possible if the city loses","amountUsd":33000000,"amountBasis":"other","source":"live","sourceUrl":"https://news.theregistrysf.com/n17-sues-menlo-park-over-rejected-665-unit-willow-park-towers-putting-up-to-33mm-in-state-penalties-in-play/","summary":"N17 Development filed a complaint and petition for writ of mandate against the City of Menlo Park on October 2, 2026, alleging the city violated state housing laws by not processing its 665-unit Willow Park project at 80 Willow Road under AB 2011 and by denying it Builder's Remedy protections, according to the city and KQED. The suit followed a July 29, 2026 notice from the California Attorney General's office that the city had violated AB 2011 and the Housing Accountability Act. Menlo Park disputes the Attorney General's analysis and says it processed the application under state law.","significance":"KQED reported that under AB 712 a court ruling against the city must come with fines of $10,000 per housing unit, at least $6.65 million here, and The Registry's headline puts up to $33 million in state penalties in play. The case also tests the city's position that a project with a hotel does not qualify for the state's streamlined housing approvals.","judge":null,"parties":[{"name":"N17 Development","role":"Plaintiff/Developer"},{"name":"City of Menlo Park","role":"Defendant"}],"tags":["zoning","builders-remedy","housing-law","california","mixed-use-development"],"hasFull":true},{"id":"live-221","addedDate":"2026-10-04","title":"Republic Bank of Chicago v. Addison Ice, LLC (Ice Arena Receivership Over Alleged Fund Diversion)","brief":"A DuPage County judge put Addison Ice Arena under a receiver in Republic Bank of Chicago's $9.5 million foreclosure. The bank alleges rink funds were diverted; the owner's attorney says the defendants backed the receiver.","category":"lending-foreclosure","status":"pending","date":"2026-09-01","jurisdiction":"Circuit Court of DuPage County, Illinois","state":"IL","amount":"$9.5M loan alleged in default","amountUsd":9500000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/10/03/receiver-takes-over-addison-ice-arena-amid-10m-foreclosure/","summary":"Republic Bank of Chicago sued Addison Ice, LLC on September 1, 2026 to foreclose on a $9.5 million loan secured by Addison Ice Arena, a 73,000-square-foot, two-rink complex at 475 South Grace Street in Addison, Illinois. The bank alleges the owner moved more than $1 million in rink funds to family members while equipment broke down and the roof leaked. On September 30, 2026, Judge Robert G. Gibson placed the arena under receiver Matthew Brash of Newpoint Advisors Corporation. The defendants' attorney told The Real Deal they supported the receiver and had proposed speeding up the appointment by consent, while disputing the bank's account.","significance":"A receiver can take over a property's operations, repairs and sale efforts long before any foreclosure judgment, and a borrower may agree to that step rather than fight it. Lenders on owner-run specialty properties such as ice rinks often seek an early receiver on the basis of allegations about related-party payments and deferred maintenance.","judge":"Robert G. Gibson","parties":[{"name":"Republic Bank of Chicago","role":"Plaintiff"},{"name":"Addison Ice, LLC","role":"Defendant"},{"name":"Newpoint Advisors Corporation","role":"Receiver"}],"tags":["foreclosure","receivership","fund-diversion","recreational","illinois"],"hasFull":true},{"id":"live-222","addedDate":"2026-10-05","featured":true,"title":"In re American Hospitality Properties REIT, Inc. (Hotel REITs' Chapter 11 in N.D. Texas)","brief":"American Hospitality Properties REIT, REIT II and 14 affiliates filed Chapter 11 in Dallas, months after their former external manager settled SEC claims over about $86 million raised from investors.","category":"reit-securities","status":"filed","date":"2026-10-04","jurisdiction":"U.S. Bankruptcy Court, N.D. Texas","state":"TX","amount":"Petition lists estimated liabilities of $1,000,001-$10 million; SEC alleged the former manager raised about $86M from investors","amountUsd":86000000,"amountBasis":"other","source":"live","sourceUrl":"https://whatnow.com/news/trending/u-s-hotel-investment-company-files-for-chapter-11-alongside-15-affiliates/","summary":"American Hospitality Properties REIT, Inc., American Hospitality Properties REIT II, Inc. and 14 affiliated entities filed voluntary Chapter 11 petitions on October 4, 2026 in the U.S. Bankruptcy Court for the Northern District of Texas (No. 26-80071), WhatNow reported, citing PACER records. The chief restructuring officer signed the petition, and the REITs retained Vinson & Elkins as counsel and FTI Consulting as financial advisor. The filing follows a June 2026 SEC action, settled without admission, against the REITs' former external manager, Phoenix American Hospitality, LLC, and its president, and a September 2026 investor suit over the same offerings.","significance":"The case shows how an SEC case against a non-traded REIT's external manager can be followed by a bankruptcy of the REIT entities themselves. Hotel franchisors appear among the largest unsecured creditors, alongside the manager, a ground lessor and a bank lender.","judge":"Stacey G.C. Jernigan","parties":[{"name":"American Hospitality Properties REIT, Inc.","role":"Debtor"},{"name":"American Hospitality Properties REIT II, Inc.","role":"Debtor"},{"name":"Phoenix American Hospitality, LLC","role":"Former External Manager"},{"name":"Marriott International, Inc.","role":"Creditor (franchise fees)"},{"name":"Hilton Hotels Corporation","role":"Creditor (franchise fees)"}],"tags":["reit","chapter-11","hospitality","sec-fraud","securities"],"docketUrl":"https://www.courtlistener.com/docket/74914151/american-hospitality-properties-reit-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-223","addedDate":"2026-10-05","title":"Greater DC Diaper Bank v. WWDC Industrial Park, LLC (Industrial Warehouse Roof-Maintenance Breach Suit)","brief":"Greater DC Diaper Bank seeks more than $775,000 from its former warehouse landlord and manager over years of roof leaks; the landlord counterclaimed and the case moved to federal court in Maryland.","category":"lease-disputes","status":"pending","date":"2026-08-17","jurisdiction":"U.S. District Court for the District of Maryland","state":"MD","amount":"$775,000+ sought","amountUsd":775000,"amountBasis":"damages sought","source":"live","sourceUrl":"https://wjla.com/news/local/greater-dc-diaper-bank-sues-maryland-silver-spring-landlord-over-leaking-warehouse-roof-seeks-775k-wwdc-industrial-park-llc-donohoe-real-estate-services-inc-legal-court-cases","summary":"The Greater DC Diaper Bank is seeking more than $775,000 plus interest from WWDC Industrial Park, LLC and property manager Donohoe Real Estate Services, Inc., alleging they failed for years to fix a leaking roof at its warehouse on Monard Drive in Silver Spring, Maryland, WJLA/7News reported. The suit, first filed in D.C. Superior Court, was removed to federal court in Washington on August 17, 2026 and transferred to the District of Maryland in September. WWDC has counterclaimed against the Diaper Bank, and both defendants filed motions to dismiss before the transfer.","significance":"The case turns on a landlord's handling of a documented, recurring roof leak under a commercial warehouse lease, with the tenant claiming losses beyond repair costs. The landlord's counterclaim puts the tenant's own lease performance at issue.","judge":"Deborah K. Chasanow","parties":[{"name":"Greater DC Diaper Bank","role":"Plaintiff"},{"name":"WWDC Industrial Park, LLC","role":"Defendant/Landlord"},{"name":"Donohoe Real Estate Services, Inc.","role":"Defendant/Property Manager"}],"tags":["commercial-lease","industrial","breach-of-contract","maryland","property-maintenance"],"docketUrl":"https://www.courtlistener.com/docket/74860941/greater-dc-diaper-bank-v-wwdc-industrial-park-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-224","addedDate":"2026-10-06","featured":true,"title":"Federal National Mortgage Association v. Reserve Apartments, Ltd. (Reserve Square Foreclosure — City of Cleveland Intervention)","brief":"Cleveland moved to intervene in Fannie Mae's federal foreclosure case over downtown's Reserve Square apartments, saying the receiver isn't fixing 19 open code-violation notices, News 5 Cleveland reported.","category":"lending-foreclosure","status":"pending","date":"2026-09-28","jurisdiction":"U.S. District Court, Northern District of Ohio","state":"OH","propertyType":"Multifamily","amount":"More than $78 million in unpaid principal, interest and fees","amountUsd":78000000,"amountBasis":"loan","source":"live","sourceUrl":"https://www.news5cleveland.com/news/local-news/cleveland-tries-to-intervene-in-reserve-square-foreclosure-case-with-property-up-for-sale","summary":"The City of Cleveland moved on September 28, 2026 to intervene in Fannie Mae's foreclosure case over Reserve Square, a downtown apartment complex, in the U.S. District Court for the Northern District of Ohio, News 5 Cleveland reported. The city says the property is a public nuisance and that the court-appointed receiver is not doing enough about 19 open violation notices covering dozens of issues, including elevator outages, water damage and garage deterioration. Fannie Mae sued in July 2025 over more than $78 million in unpaid principal, interest and fees, and the docket shows the court entered a consent foreclosure judgment in April 2026 while the receivership continues and the property is marketed for sale.","significance":"The city is asking to be heard in the federal receivership itself, where the court controls the sale, rather than relying only on separate code enforcement. Its law director said the goal is to have every violation fixed and to keep future owners from neglecting the building.","judge":"Bridget Meehan Brennan","parties":[{"name":"Federal National Mortgage Association","role":"Plaintiff/Lender"},{"name":"Reserve Apartments, Ltd.","role":"Defendant/Borrower"},{"name":"Reserve Square Apartments, Ltd.","role":"Defendant"},{"name":"Cuyahoga County Fiscal Officer","role":"Defendant"},{"name":"City of Cleveland","role":"Proposed intervenor"}],"tags":["foreclosure","multifamily","municipal-intervention","receivership","code-enforcement"],"docketUrl":"https://www.courtlistener.com/docket/70867976/fannie-mae-v-reserve-apartments-ltd/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-226","addedDate":"2026-10-06","title":"Oak Land and Development LLC v. Simon Property Group Inc. (Penn Square Mall Antitrust Tying Suit)","brief":"Developers of Oklahoma City's OAK project sued Simon Property Group, alleging it tied lease deals elsewhere to steering tenants to Penn Square Mall; Simon calls the suit meritless and has moved to dismiss.","category":"lease-disputes","status":"pending","date":"2025-12-02","jurisdiction":"U.S. District Court, Western District of Oklahoma","state":"OK","amount":"Unspecified damages sought over alleged antitrust tying; jury demanded","amountUsd":null,"source":"live","sourceUrl":"https://www.news9.com/oklahoma-city-news/oak-developers-sue-penn-square-mall-owner-antitrust-claims","summary":"The owners and developers of OAK, a mixed-use project across the street from Penn Square Mall in Oklahoma City, sued Simon Property Group on December 2, 2025 in the U.S. District Court for the Western District of Oklahoma, News 9 reported. They allege Simon used threats involving leases at its properties in other cities to steer tenants to Penn Square or away from OAK, an illegal tying arrangement under the Sherman Act and Oklahoma law. Simon has called the suit \"meritless and fictional,\" and on June 2, 2026 it moved to dismiss the second amended complaint; the motion was fully briefed in August 2026.","significance":"The case tests whether a landlord's leverage across its national portfolio can support an antitrust tying claim in a single local leasing market. Simon argues that offering package deals on properties in other locations is ordinary competition, not an antitrust violation.","judge":"Patrick R. Wyrick","parties":[{"name":"Oak Land and Development LLC","role":"Plaintiff/Developer"},{"name":"Veritas Development LLC","role":"Plaintiff/Developer"},{"name":"Simon Property Group, Inc.","role":"Defendant"},{"name":"Simon Property Group, L.P.","role":"Defendant"},{"name":"Penn Square Mall, LLC","role":"Defendant"}],"tags":["antitrust","tying","shopping-mall","oklahoma","simon-property-group"],"docketUrl":"https://www.courtlistener.com/docket/71982156/oak-land-and-development-llc-v-simon-property-group-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-228","addedDate":"2026-10-07","title":"76 Commerce Center LLC v. BroadRange Logistics LLC (Denver-Area Industrial Lease Default)","brief":"Landlords at Brighton's 76 Commerce Center allege BroadRange Logistics owes $32 million after defaulting on what BusinessDen called the largest speculative lease in Colorado history.","category":"lease-disputes","status":"filed","date":"2026-05-29","jurisdiction":"Colorado District Court, Adams County","state":"CO","amount":"$32M sought: $8.9M back rent, $17.4M discretionary-allowance clawback, $3M rent-abatement repayment, plus interest and fees","amountUsd":32000000,"amountBasis":"damages sought","source":"live","sourceUrl":"https://businessden.com/logistics-firm-owes-32m-for-breaking-record-setting-lease-landlord-says/","summary":"Entities tied to Hyde Development and Mortenson Properties, 76 Commerce Center LLC and 76 Commerce Center 3 LLC, have sued BroadRange Logistics LLC in Colorado state court, alleging the Georgia third-party logistics company owes $32 million after defaulting on its lease of more than 1.1 million square feet at 76 Commerce Center in Brighton, BusinessDen reported. BusinessDen described the 2024 deal as the largest speculative lease in state history. The landlords allege BroadRange fell behind on rent in 2025 and that its leases were terminated on March 13, 2026.","significance":"The suit shows how quickly a record-setting industrial lease can turn into litigation, and how up-front landlord concessions such as tenant-improvement allowances and rent abatement can become part of a damages claim after a default. It is one of several landlord suits against BroadRange reported this year.","judge":null,"parties":[{"name":"76 Commerce Center LLC","role":"Plaintiff/Landlord"},{"name":"76 Commerce Center 3 LLC","role":"Plaintiff/Landlord"},{"name":"BroadRange Logistics LLC","role":"Defendant/Tenant"}],"propertyType":"Industrial","tags":["industrial","colorado","lease-default","logistics","landlord"],"hasFull":true},{"id":"live-229","addedDate":"2026-10-07","title":"KSG v. BroadRange Logistics (Mount Pocono Warehouse Tenant-Improvement Allowance Suit)","brief":"Warehouse owner KSG sued BroadRange Logistics to recover an $11 million improvement allowance for a 600,000-square-foot Mount Pocono, Pa. warehouse, alleging the tenant never built out the space. BroadRange denies the claims.","category":"lease-disputes","status":"filed","date":"2026-07-10","jurisdiction":"New York state court","state":"NY","amount":"$11M tenant-improvement allowance plus other costs","amountUsd":11000000,"amountBasis":"damages sought","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/07/10/ksg-sued-broadrange-for-11m-tenant-improvement-allowance/","summary":"KSG, owner of a 600,000-square-foot warehouse in Mount Pocono, Pennsylvania, sued BroadRange Logistics in New York state court in May 2026 to recover an $11 million tenant-improvement allowance it paid under a 20-year lease, plus other costs. KSG alleges BroadRange misrepresented its finances, never intended to improve the space and soon stopped paying rent. KSG funded the allowance partly from a $32 million CMBS loan from Ocean First Bank. BroadRange has denied the allegations in court filings and says the lease let it use the allowance for \"any other business purpose.\"","significance":"Paying a large improvement allowance up front, before a tenant has shown it can pay rent, leaves a landlord with little recourse if the money is not spent on the building. Landlords should tie allowance payments to completed work and make sure the lease says how unspent funds come back. KSG says its own lease attorney left out exactly that provision.","judge":null,"parties":[{"name":"KSG","role":"Plaintiff/Landlord"},{"name":"BroadRange Logistics","role":"Defendant/Tenant"}],"propertyType":"Industrial","tags":["industrial","tenant-improvement","pennsylvania","logistics","fraud-allegations"],"hasFull":true},{"id":"live-230","addedDate":"2026-10-07","title":"Eagan Capital v. City of Eagan (Minnesota Data Center Moratorium Challenge)","brief":"Data center owner Eagan Capital sued Eagan, Minnesota for $50,000, arguing state utility regulators, not the city, control electricity demand, so its one-year data center moratorium is invalid, MPR News reported.","category":"zoning-land-use","status":"filed","date":"2026-06-15","jurisdiction":"Minnesota District Court, Dakota County","state":"MN","amount":"$50,000 in damages sought; challenges a one-year moratorium on data centers using more than 20 megawatts within 500 feet of homes","amountUsd":50000,"amountBasis":"damages sought","source":"live","sourceUrl":"https://www.mprnews.org/story/2026/07/07/city-of-eagan-faces-lawsuit-over-data-center-moratorium","summary":"Data center owner Eagan Capital sued the City of Eagan, Minnesota in a complaint filed June 15, 2026, arguing the city lacked authority to adopt its February 2026 one-year moratorium on data centers using more than 20 megawatts of electricity within 500 feet of homes, MPR News reported. The complaint says the Minnesota Public Utilities Commission has exclusive authority over electricity demand in the state and seeks $50,000. The city says it will vigorously defend the moratorium and that it denied the company an interim use permit after unpermitted trailer-mounted chillers were installed and operated at the site.","significance":"The suit tests whether a Minnesota city can pause data center development based on electricity use, or whether that is a matter for state utility regulators. Eagan was the first Minnesota city to impose a hard pause on data centers, according to MPR News.","judge":null,"parties":[{"name":"Eagan Capital","role":"Plaintiff"},{"name":"City of Eagan","role":"Defendant"}],"propertyType":"Data Center","tags":["data-center","minnesota","zoning-moratorium","municipal-authority","electricity-regulation"],"hasFull":true},{"id":"live-231","addedDate":"2026-10-07","title":"DCB Nashville, LLC v. Metropolitan Government of Nashville and Davidson County (DC Blox Zoo-Area Data Center Moratorium Suit)","brief":"A federal judge dismissed DC Blox unit DCB Nashville's claims that Metro's moratorium targeted its data center site by the Nashville Zoo, letting it refile three; it filed an amended complaint.","category":"zoning-land-use","status":"ruling","date":"2026-10-06","jurisdiction":"U.S. District Court, Middle District of Tennessee","state":"TN","amount":"Site bought for about $23M; damages amount unspecified","amountUsd":23000000,"amountBasis":"purchase price","source":"live","sourceUrl":"https://www.axios.com/local/nashville/2026/08/11/dc-blox-sues-over-metros-data-center-moratorium","summary":"DCB Nashville, LLC, a subsidiary of DC Blox, sued the Metropolitan Government of Nashville and Davidson County in federal court on August 11, 2026, seeking to strike down Metro's data center moratorium as applied to its planned data center next to the Nashville Zoo, Axios Nashville reported. The company alleges the moratorium targeted its project. On October 6, 2026, U.S. District Judge Eli J. Richardson dismissed all nine counts in one form or another and denied a preliminary injunction as moot, while allowing the company 21 days to refile three constitutional counts. It filed an amended complaint on October 27.","significance":"The case tests whether a data center developer can challenge a municipal moratorium in federal court as a targeted act against one project. The court's ruling turned on the pleading of property interests and comparators and left the state-law vested-rights claims out of federal court for now.","judge":"Eli Jeremy Richardson","parties":[{"name":"DCB Nashville, LLC","role":"Plaintiff"},{"name":"Metropolitan Government of Nashville and Davidson County","role":"Defendant"}],"propertyType":"Data Center","tags":["data-center","tennessee","zoning-moratorium","vested-rights","constitutional-claims"],"docketUrl":"https://www.courtlistener.com/docket/74637961/dcb-nashville-llc-v-the-metropolitan-government-of-nashville-and-davidson/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-232","addedDate":"2026-10-07","title":"Fox Investments LLC v. City of Kaukauna (Wisconsin Direct-Action Contamination Cost-Recovery Suit)","brief":"Fox Investments sued the City of Kaukauna and three insurers it says covered the city, seeking $235,683.63 spent cleaning up contamination it ties to the city's 1967-1974 ownership of an apartment site.","category":"environmental","status":"filed","date":"2026-07-23","jurisdiction":"U.S. District Court, Eastern District of Wisconsin","state":"WI","amount":"$235,683.63 in investigation and remediation costs sought via Wisconsin's direct-action statute","amountUsd":235683.63,"amountBasis":"claim","source":"live","sourceUrl":"https://www.insurancebusinessmag.com/us/news/risk-compliance-legal/property-owner-pulls-three-insurers-into-sixfigure-site-cleanup-suit-583623.aspx","summary":"Fox Investments LLC sued the City of Kaukauna and insurers Sentry, The Travelers Indemnity Company and Employers Insurance Company of Wausau on July 23, 2026 in the U.S. District Court for the Eastern District of Wisconsin, seeking $235,683.63 it spent investigating and cleaning up contamination at the Fox Shore Apartments site, Insurance Business reported. Fox alleges the city owned the land from 1967 to 1974, when it was part of a former railyard, and spread contamination when it burned the structures in 1974. It brings CERCLA, negligence and unjust-enrichment claims and invokes Wisconsin's direct-action statute against the insurers.","significance":"The suit seeks to make a city, and insurers Fox says covered it decades ago, pay for a cleanup that a later owner was ordered to perform. The allegations have not been tested in court.","judge":null,"parties":[{"name":"Fox Investments LLC","role":"Plaintiff"},{"name":"City of Kaukauna","role":"Defendant"},{"name":"Sentry","role":"Defendant/Insurer"},{"name":"The Travelers Indemnity Company","role":"Defendant/Insurer"},{"name":"Employers Insurance Company of Wausau","role":"Defendant/Insurer"}],"tags":["environmental","wisconsin","contamination","direct-action-statute","insurance-coverage"],"propertyType":"Multifamily","hasFull":true},{"id":"live-235","addedDate":"2026-10-08","title":"Party Depot Owners v. City of Danbury (Connecticut Appellate Court Upholds $16.8M Reckless-Permitting Verdict)","brief":"Connecticut's Appellate Court upheld a $16.8 million verdict against Danbury over its approval of a Party Depot building addition, apart from a $280,000 remittitur. The city says it will ask the state Supreme Court to review.","category":"zoning-land-use","status":"ruling","date":"2026-03-17","jurisdiction":"Connecticut Appellate Court","state":"CT","propertyType":"Retail","amount":"$16,843,750 verdict affirmed (less a $280,000 remittitur), plus statutory interest","amountUsd":16843750,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.barclaydamon.com/press-releases/connecticut-appellate-court-upholds-168-million-jury-verdict-for-party-depot-owners","documentUrl":"https://www.leagle.com/decision/inctco20260317053","documentLabel":"Read the Appellate Court's opinion","summary":"On March 17, 2026, the Connecticut Appellate Court upheld a $16,843,750 jury verdict for the owners of Party Depot against the City of Danbury and one of its building officials, 238 Conn. App. 1 (2026). The court rejected the city's arguments except for a $280,000 remittitur for money received from a settling party, and remanded for that adjustment and for 10% statutory interest. Danbury's mayor's office said the city will ask the Connecticut Supreme Court to review the decision, Patch reported.","significance":"The jury found the city and its building official acted with reckless disregard for health and safety under Connecticut's municipal liability statute, General Statutes 52-557n, and the appellate panel left that finding in place. Danbury argues the ruling sets a dangerous precedent for municipalities statewide.","judge":null,"parties":[{"name":"Party Depot, Inc.","role":"Plaintiff"},{"name":"43 South Street LLC","role":"Plaintiff"},{"name":"City of Danbury","role":"Defendant"}],"tags":["municipal-liability","connecticut","building-permit","governmental-immunity","jury-verdict"],"hasFull":true},{"id":"live-236","addedDate":"2026-10-08","title":"Wixom Industrial One, LLC v. City of Wixom (Michigan Data Center Moratorium Suit)","brief":"Wixom Industrial One sued the City of Wixom in federal court, alleging the city used its site plan to draft rules that would block a 519,400-square-foot data center on 54 acres zoned for the use.","category":"zoning-land-use","status":"filed","date":"2026-08-07","jurisdiction":"U.S. District Court, Eastern District of Michigan","state":"MI","propertyType":"Data Center","amount":"54-acre site; three-building, 519,400 sq. ft. data center plan; damages amount unspecified","amountUsd":null,"source":"live","sourceUrl":"https://whmi.com/news/article/developer-sues-city-of-wixom-over-data-center-moratorium","summary":"Wixom Industrial One, LLC sued the City of Wixom, Michigan on August 7, 2026 in the U.S. District Court for the Eastern District of Michigan (No. 2:26-cv-12754), alleging the city violated Michigan's zoning act, WHMI reported, citing Crain's Detroit. The developer says the city used its rough site plan for a three-building, 519,400-square-foot data center campus on 54 acres on South Wixom Road to write restrictive ordinances. The city had adopted a six-month moratorium on data center development and in July rejected a proposed waiver.","significance":"The case tests whether a city can respond to opposition to one pending data center proposal with a moratorium and new rules for the use. The developer's claim rests on its allegation that the city drew the ordinances from its own site plan.","judge":"Robert J. White","parties":[{"name":"Wixom Industrial One, LLC","role":"Plaintiff"},{"name":"City of Wixom","role":"Defendant"}],"tags":["data-center","michigan","zoning-moratorium","municipal-authority","vested-rights"],"docketUrl":"https://www.courtlistener.com/docket/73737749/wixom-industrial-one-llc-v-wixom-city-of/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-237","addedDate":"2026-10-08","featured":true,"title":"Whitestone Uptown Tower, LLC v. Whitestone REIT Operating Partnership, L.P.: Fifth Circuit Denies Rehearing in Uptown Tower Subrogation Appeal","brief":"The Fifth Circuit denied rehearing en banc to Pillarstone subsidiary Whitestone Uptown Tower, leaving in place rulings that Whitestone REIT's operating partnership was subrogated to the lender's claim for its $13.6 million payment.","category":"reit-securities","status":"ruling","date":"2026-10-05","jurisdiction":"U.S. Court of Appeals for the Fifth Circuit","state":"TX","amount":"$13.6 million paid to Whitestone OP from Uptown Tower sale proceeds under the subrogation ruling","amountUsd":13600000,"source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/928953/000143774926032287/pscr20250630_10q.htm","summary":"On October 5, 2026, the Fifth Circuit denied Whitestone Uptown Tower, LLC's petition for rehearing en banc of its September 4, 2026 decision affirming a district court ruling in Whitestone Uptown Tower, LLC v. Whitestone REIT Operating Partnership, L.P., according to Pillarstone Capital REIT's Form 10-Q filed October 7, 2026. The bankruptcy court had ruled, over Uptown Tower's objection, that Whitestone OP was statutorily subrogated to the mortgage lender's secured claim for about $13.6 million it had mistakenly paid toward the Uptown Tower loan, and Uptown Tower paid that amount to Whitestone OP from the building's sale proceeds. Pillarstone says Uptown Tower, its indirect subsidiary, is considering its options.","significance":"The denial leaves the subrogation ruling in place in one of the last open parts of the Pillarstone-Whitestone dispute; Uptown Tower was not a party to the December 2025 settlement of Whitestone's claims in the other Pillarstone bankruptcy cases. The case shows a party that paid down a property loan without the borrower's authority recovering that payment through subrogation to the lender's secured claim.","judge":null,"parties":[{"name":"Whitestone Uptown Tower, LLC","role":"Appellant / Debtor (Pillarstone subsidiary)"},{"name":"Whitestone REIT Operating Partnership, L.P.","role":"Appellee"},{"name":"Pillarstone Capital REIT","role":"Related Party (indirect parent of appellant)"},{"name":"Whitestone REIT","role":"Related Party"}],"tags":["reit","bankruptcy-appeal","fifth-circuit","subrogation","texas"],"amountBasis":"other","propertyType":"Office","hasFull":true},{"id":"live-239","addedDate":"2026-10-08","title":"Cedar Realty Trust Preferred Stockholder Class Action Settlement (Montgomery County, Md.)","brief":"Cedar Realty Trust preferred stockholders reached a proposed $8.5 million cash settlement of a class action alleging Cedar's former directors breached duties to them through the Wheeler merger.","category":"reit-securities","status":"pending","date":"2026-06-10","jurisdiction":"Circuit Court for Montgomery County, Maryland","state":"MD","amount":"$8.5 million proposed cash settlement","amountUsd":8500000,"amountBasis":"settlement","source":"live","sourceUrl":"https://www.prnewswire.com/news-releases/levi--korsinsky-llp-and-wohl--fruchter-llp-announce-pendency-and-proposed-settlement-of-class-action-affecting-preferred-stockholders-of-cedar-realty-trust-inc-302838330.html","summary":"Holders of Cedar Realty Trust's Series B and Series C preferred stock reached a proposed $8.5 million cash settlement of a putative class action in the Circuit Court for Montgomery County, Maryland, against Cedar's former directors, including former CEO Bruce Schanzer, according to a court-ordered summary notice. Cedar's quarterly report says the suit alleges the directors breached their duties to preferred stockholders through Cedar's merger with Wheeler Real Estate Investment Trust. The stipulation is dated June 10, 2026, and a final approval hearing was set for October 8, 2026 before Judge Ronald B. Rubin.","significance":"The case is one of the disputes over how Cedar's preferred stockholders fared when Wheeler acquired the REIT. The proposed amount gives a reference point for resolving such a claim without trial.","judge":"Ronald B. Rubin","parties":[{"name":"Cedar Realty Trust, Inc.","role":"Settling Party"},{"name":"Wheeler Real Estate Investment Trust, Inc.","role":"Settling Party"}],"tags":["reit","preferred-stock","class-action","settlement","maryland"],"hasFull":true},{"id":"live-243","addedDate":"2026-10-09","featured":true,"title":"Puerto Rico Court Dismisses DBR Dorado's Bid to Block Hilton-Branded Hotel","brief":"A Puerto Rico court dismissed with prejudice DBR Dorado's suit to stop Casa Dorado, a 171-room Hilton-branded hotel, finding DBR waited more than five years to challenge it, El Nuevo Día reported.","category":"zoning-land-use","status":"ruling","date":"2026-10-06","jurisdiction":"Bayamón Court of First Instance, Puerto Rico","amount":"$48 million at stake, according to the developer","amountUsd":48000000,"amountBasis":"other","source":"live","sourceUrl":"https://www.elnuevodia.com/english/business/story/court-dismisses-lawsuit-seeking-to-block-hiltons-new-hotel-in-dorado/","summary":"The Bayamón Court of First Instance dismissed with prejudice a lawsuit by DBR Dorado Owner LLC seeking to halt construction of Casa Dorado, a 171-room hotel in Dorado being built under Hilton's Tapestry Collection brand, El Nuevo Día reported on October 6, 2026. DBR, which owns land where facilities of the Dorado Beach Resort and Ritz-Carlton Reserve are located, argued that deed restrictions on the site bar non-residential development and buildings over two stories. The judge concluded DBR had known of the development since 2020 and waited more than five years to challenge the restrictions.","significance":"The ruling turned on DBR's delay rather than on what the deed restrictions allow, so their meaning was left undecided. For owners holding rights under recorded restrictions, it shows that waiting years while a neighbor builds can end a challenge.","judge":null,"propertyType":"Hospitality","parties":[{"name":"DBR Dorado Owner LLC","role":"Plaintiff"},{"name":"The Dawn Hotel at Dorado LLC","role":"Defendant"},{"name":"Paseo San Antonio Inc.","role":"Defendant"}],"tags":["hotel-development","land-use-restrictions","puerto-rico","hilton","laches"],"hasFull":true},{"id":"live-250","addedDate":"2026-10-10","title":"White Sulphur Springs Holdings LLC v. Greenbrier Hotel Corporation (The Greenbrier Receivership Suit, Dismissed After New Financing)","brief":"TRT Holdings-backed White Sulphur Springs Holdings sought a federal receiver for The Greenbrier over defaulted loans; the case was dismissed with prejudice in August 2026 after a Kennedy Lewis deal.","category":"lending-foreclosure","status":"settled","date":"2026-08-14","jurisdiction":"U.S. District Court for the Southern District of West Virginia","state":"WV","amount":"More than $387 million owed to the lender, per court documents cited by The Intermountain; final payoff not disclosed","amountUsd":387000000,"amountBasis":"claim","source":"live","sourceUrl":"https://westvirginiawatch.com/2026/04/30/wv-sen-jim-justice-family-allege-conspiracy-by-bank-hotel-chain-to-snatch-the-greenbrier-resort/","summary":"White Sulphur Springs Holdings LLC, a company set up by TRT Holdings, the parent of Omni Hotels, sued Greenbrier Hotel Corporation, related Greenbrier entities and members of the Justice family in the U.S. District Court for the Southern District of West Virginia on April 9, 2026, seeking a receiver for The Greenbrier resort after acquiring the resort's loan debt previously held by Carter Bank & Trust. The Justice family countersued in Greenbrier County Circuit Court, alleging TRT and Carter Bank conspired to take the resort, which TRT called false. On August 14, 2026, after the family closed a joint venture with Kennedy Lewis Investment Management, the parties stipulated to dismiss the federal case with prejudice, and the state case was also dismissed, The Intermountain reported.","significance":"The case shows how a buyer of a hotel's defaulted debt can use a receivership motion to press for repayment, and how a borrower can respond with a state-court suit and a refinancing. Here the dispute ended with new capital and a change in majority ownership rather than a court-appointed receiver, and the casino license review shows how gaming regulators become part of a fight over a licensed resort.","judge":"Frank Volk","parties":[{"name":"White Sulphur Springs Holdings LLC","role":"Plaintiff/Lender"},{"name":"TRT Holdings, Inc.","role":"Parent of Plaintiff"},{"name":"Greenbrier Hotel Corporation","role":"Defendant/Borrower"},{"name":"Carter Bank & Trust","role":"Original Lender"},{"name":"Kennedy Lewis Investment Management","role":"New majority owner"}],"propertyType":"Hospitality","tags":["hospitality","receivership","west-virginia","loan-default","forbearance"],"docketUrl":"https://www.courtlistener.com/docket/73178455/white-sulphur-springs-holdings-llc-v-justice/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-251","addedDate":"2026-10-10","featured":true,"title":"Deutsche Bank Sues to Foreclose on Pembroke Lakes Mall Over $260M Loan","brief":"Deutsche Bank sued to foreclose on Pembroke Lakes Mall in Pembroke Pines, Florida, after the $260 million loan on the BGRE-owned mall went unpaid at maturity, and asked the court to appoint a receiver.","category":"lending-foreclosure","status":"filed","date":"2026-10-08","jurisdiction":"Circuit Court of the 17th Judicial Circuit, Broward County, Florida","state":"FL","amount":"$260M loan","amountUsd":260000000,"amountBasis":"loan","propertyType":"Retail","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/10/08/pembroke-lakes-mall-faces-260-million-foreclosure/","summary":"Deutsche Bank filed a foreclosure suit in September 2026 against the ownership of Pembroke Lakes Mall, a 748,800-square-foot shopping center at 11701 Pines Boulevard in Pembroke Pines, Florida, The Real Deal reported, citing the South Florida Business Journal. The lender alleges the owner did not repay the $260 million loan, issued in 2013, by its March 2025 maturity date, and it has asked the court to appoint Carmen Spinoso of Spinoso Real Estate Group as receiver. The mall is owned by BGRE, formerly Brookfield Properties, which was not named in the suit.","significance":"The mall still earns more than its debt payments, but its appraised value is now well below the loan, and its 3.6% rate is far below what a new loan would cost. That combination makes a maturity default hard to fix by refinancing. Owners with older CMBS loans coming due should expect lenders to ask for a receiver at the start of a foreclosure.","judge":null,"parties":[{"name":"Deutsche Bank","role":"Plaintiff/Lender"}],"tags":["cmbs","commercial-mortgage-foreclosure","retail","receivership","florida"],"hasFull":true},{"id":"live-256","addedDate":"2026-10-11","featured":true,"title":"H-E-B Slip-and-Fall Ruling: Texas Supreme Court Tightens Constructive-Notice Proof","brief":"The Texas Supreme Court reinstated summary judgment for H-E-B in a slip-and-fall suit, holding constructive notice needs evidence of how long the specific hazard existed, not leaks elsewhere in the store.","category":"premises-liability","status":"ruling","date":"2026-04-10","jurisdiction":"Supreme Court of Texas","state":"TX","amount":"N/A — summary judgment reinstated for defendant","amountUsd":null,"source":"live","sourceUrl":"https://www.jdsupra.com/legalnews/supreme-court-of-texas-reaffirms-strict-3738536","documentUrl":"https://www.leagle.com/decision/intxco20260410542","documentLabel":"Read the official opinion","summary":"The Supreme Court of Texas on April 10, 2026 reversed the Thirteenth Court of Appeals and reinstated the trial court's summary judgment for H-E-B, L.P. in a customer's suit over a fall on a puddle of clear liquid in a store's toy aisle. The court held that constructive notice requires evidence of how long the specific condition existed, and that roof leaks elsewhere in the store, speculation about the cause, the puddle's size and inspection practices did not supply it, according to a law-firm summary on JD Supra and the court's docket.","significance":"The ruling reinforces Texas's requirement of time-specific evidence for transient-hazard premises claims. Retailers and other commercial property owners can cite it when a plaintiff's notice evidence concerns a property's general condition rather than how long the specific hazard existed.","judge":"Jane N. Bland","propertyType":"Retail","parties":[{"name":"H-E-B, LP","role":"Defendant-Petitioner"}],"tags":["premises-liability","slip-and-fall","constructive-notice","texas","retail"],"hasFull":true},{"id":"live-257","addedDate":"2026-10-11","title":"Hexa Builders, LLC v. Mayor and Township Council of the Township of Monroe: Developer Challenges Data Center Ban","brief":"Hexa Builders sued Monroe Township, N.J. for $300 million after officials reversed a 2025 ordinance that had allowed data centers; the township removed the case to federal court.","category":"zoning-land-use","status":"pending","date":"2026-06-05","jurisdiction":"United States District Court, District of New Jersey","state":"NJ","amount":"$300 million sought in damages","amountUsd":300000000,"amountBasis":"claim","source":"live","sourceUrl":"https://newjerseymonitor.com/2026/08/20/nj-data-center-bans-courts/","summary":"Hexa Builders, LLC, a Princeton-based developer seeking to build a 1-million-square-foot data center and warehouse, sued Monroe Township in Gloucester County, New Jersey in June 2026 after local officials reversed a 2025 ordinance that had allowed data centers, the New Jersey Monitor reported. The 20-count complaint seeks $300 million and alleges violations of the Municipal Land Use Law, the township's own application procedures and the First Amendment. The township removed the case to federal court on July 6, 2026, where it is pending before Judge Edward S. Kiel.","significance":"The suit is one of at least three filed by developers in summer 2026 challenging New Jersey municipal data center bans, according to the New Jersey Monitor. It tests what claims a developer has when a town reverses a zoning change that had allowed the use it planned.","judge":"Edward S. Kiel","propertyType":"Data Center","parties":[{"name":"Hexa Builders, LLC","role":"Plaintiff"},{"name":"3043 Williamstown Urban Renewal, LLC","role":"Plaintiff"},{"name":"Mayor and Township Council of the Township of Monroe","role":"Defendant"},{"name":"Planning Board of the Township of Monroe","role":"Defendant"}],"tags":["data-center","zoning","land-use","new-jersey","municipal-ban"],"docketUrl":"https://www.courtlistener.com/docket/73580832/hexa-builders-llc-v-mayor-and-township-council-of-the-township-of-monroe/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-258","addedDate":"2026-10-11","title":"Cedar Christina Crossing Parking-Lot Ice Fall: Delaware Supreme Court Affirms Summary Judgment","brief":"Delaware's Supreme Court affirmed summary judgment for a shopping-center owner and its snow-removal contractor in a parking-lot black-ice fall, after security video showed the lot clear and dry.","category":"premises-liability","status":"ruling","date":"2026-03-23","jurisdiction":"Supreme Court of Delaware","state":"DE","amount":"N/A — summary judgment affirmed for defendants","amountUsd":null,"source":"live","sourceUrl":"https://www.jdsupra.com/legalnews/delaware-supreme-court-affirms-summary-7450947/","summary":"The Delaware Supreme Court on March 23, 2026 affirmed summary judgment for shopping-center owner Cedar Christina Crossing, LLC and its snow-removal contractor, Eastern LLC, in a suit by a man who said he slipped on black ice in the center's parking lot. He testified that he saw unplowed snow and someone plowing, but surveillance video showed the lot clear and dry with no snow removal under way, and the court held that self-contradictory testimony refuted by objective evidence cannot defeat summary judgment, according to a law-firm summary on JD Supra and the court's order.","significance":"The ruling confirms that Delaware shopping-center owners and their maintenance contractors can defeat weather-related slip-and-fall claims at summary judgment using objective video evidence, reinforcing the litigation-risk value of parking-lot camera coverage and routine snow-and-ice documentation for commercial landlords.","judge":"N. Christopher Griffiths","propertyType":"Retail","parties":[{"name":"Cedar Christina Crossing, LLC","role":"Defendant-Appellee"},{"name":"Eastern LLC","role":"Defendant-Appellee"}],"tags":["premises-liability","slip-and-fall","snow-and-ice","delaware","summary-judgment"],"hasFull":true},{"id":"live-259","addedDate":"2026-10-11","title":"Shareholder Class Action v. Franklin BSP Realty Trust, Inc.: Investors Sue Mortgage REIT Over Dividend Statements","brief":"A shareholder filed a putative class action alleging Franklin BSP Realty Trust and three officers overstated its ability to keep paying a $0.355 quarterly dividend before it was cut to $0.20 in February 2026. The company calls the suit without merit.","category":"reit-securities","status":"pending","date":"2026-02-26","jurisdiction":"United States District Court, Eastern District of New York","state":"NY","amount":"Putative class action; damages not yet quantified","amountUsd":null,"source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/1562528/000156252826000024/bsprt-20260630.htm","summary":"On February 26, 2026, a shareholder filed a putative securities class action in the Eastern District of New York against Franklin BSP Realty Trust, Inc. (NYSE: FBRT) and three of its officers. The complaint alleges they overstated the company's prospects and its ability to maintain a $0.355 quarterly dividend between November 5, 2024 and February 11, 2026, when the commercial mortgage REIT reported fourth-quarter 2025 results and reset the dividend to $0.20. The company says the suit is without merit; a related derivative suit filed in May 2026 has been stayed.","significance":"The case tests whether management's repeated statements of confidence in reaching dividend coverage can support securities-fraud claims once a REIT cuts its dividend. No court has ruled on the merits.","judge":"Gary R. Brown","parties":[{"name":"Franklin BSP Realty Trust, Inc.","role":"Defendant"}],"tags":["reit","securities-fraud","mortgage-reit","class-action","disclosure"],"docketUrl":"https://www.courtlistener.com/docket/72333596/moses-v-franklin-bsp-realty-trust-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-260","addedDate":"2026-10-11","title":"Port of Tacoma v. PQ LLC: Cleanup-Cost Suit Over Former Tideflats Sodium Silicate Plant","brief":"The Port of Tacoma sued PQ LLC under Washington's Model Toxics Control Act to recover more than $8 million it spent cleaning up a former sodium silicate plant on Port-owned Tideflats land; PQ has counterclaimed.","category":"environmental","status":"pending","date":"2026-02-20","jurisdiction":"United States District Court, Western District of Washington","state":"WA","amount":"More than $8 million in remedial costs incurred so far, plus future cleanup costs, sought","amountUsd":8000000,"amountBasis":"claim","source":"live","sourceUrl":"https://usaherald.com/port-of-tacoma-sues-chemical-manufacturer-pq-llc-over-alleged-environmental-contamination/","summary":"The Port of Tacoma sued PQ LLC in the U.S. District Court for the Western District of Washington on February 20, 2026, seeking to recover cleanup costs under Washington's Model Toxics Control Act and a declaratory judgment. The Port alleges PQ's predecessors released hazardous substances while making sodium silicate from 1941 to 2008 at 1114 and 1202 Taylor Way, property the Port bought in 2008, and says it has spent more than $8 million so far, with millions more expected. PQ filed an answer and counterclaim on March 26, 2026.","significance":"The case is a state-law cost-recovery claim by a public landowner against the successor to a site's former operator after an interim cost-sharing agreement ended. It shows how a buyer of a former industrial site can pursue the prior operator's successor for cleanup costs years after acquiring the land.","judge":null,"propertyType":"Industrial","parties":[{"name":"Port of Tacoma","role":"Plaintiff"},{"name":"PQ LLC","role":"Defendant"}],"tags":["environmental","contamination","successor-liability","remediation","industrial"],"docketUrl":"https://www.courtlistener.com/docket/72309125/port-of-tacoma-v-pq-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-262","addedDate":"2026-10-13","title":"Quantum Maryland LLC v. Frederick County (Data Center Moratorium Suit Over Former Eastalco Site)","brief":"Catellus-managed Quantum Maryland sued Frederick County to void a freeze on new data center applications; a judge denied an emergency restraining order and set a January hearing, the News-Post reported.","category":"zoning-land-use","status":"pending","date":"2026-10-08","jurisdiction":"Circuit Court for Frederick County, Maryland","state":"MD","amount":"Injunctive relief and damages; developer says a $500M+ land deal was derailed","source":"live","sourceUrl":"https://www.fredericknewspost.com/news/continuing_coverage/data_centers/data-center-developer-sues-frederick-county-over-moratorium/article_72bc73fc-8a81-5839-9b98-9a686c198167.html","propertyType":"Data Center","summary":"Quantum Maryland LLC, managed by Catellus Maryland, the master developer of the Frederick Digital Campus near Adamstown, sued Frederick County, County Executive Jessica Fitzwater and the county Planning Commission in Frederick County Circuit Court on October 8, 2026, the Frederick News-Post reported. The suit challenges an executive-order pause on new data center and substation applications, later extended to July 1, 2027, and asks the court to overturn it, let Quantum's applications proceed and award damages. Specially assigned Judge James Bonifant denied Quantum's emergency motion for a temporary restraining order in October and set a January 2027 hearing on a motion to dismiss and a preliminary injunction.","significance":"The case tests whether a county executive can pause applications under zoning legislation the county council adopted, which Quantum frames as a question of charter authority. The county's argument that a moratorium by the incoming council could make the suit moot may shape how far the case goes.","tags":["data center","moratorium","maryland","ultra vires","brownfield redevelopment"],"parties":[{"name":"Quantum Maryland LLC","role":"Plaintiff"},{"name":"Frederick County","role":"Defendant"},{"name":"Frederick County Planning Commission","role":"Defendant"}],"judge":"James Bonifant","amountUsd":null,"hasFull":true},{"id":"live-263","addedDate":"2026-10-13","title":"GWIP Land Company LLC v. Board of County Commissioners of Weld County: Neighboring Industrial Park Owner Seeks Reversal of GlobalAI Data Center Approval","brief":"Broe Cos. affiliates that own the Great Western Industrial Park sued to reverse Weld County's approval of GlobalAI Cloud's data center on the 438-acre former Carestream Health property.","category":"zoning-land-use","status":"filed","date":"2026-10-06","jurisdiction":"District Court, Weld County, Colorado","state":"CO","amount":"Judicial review and reversal of land-use approval","source":"live","sourceUrl":"https://bizwest.com/2026/10/08/landowner-alleges-weld-commissioners-bent-rules-for-data-center/","propertyType":"Data Center","summary":"Affiliates of Denver-based Broe Cos. that own the roughly 3,000-acre Great Western Industrial Park filed a 24-page complaint in Weld District Court (Case No. 2026CV31187) on October 6, 2026, BizWest reported. They ask the court to review and reverse the Weld County commissioners' September approval of a use-by-special-review permit for GlobalAI Cloud Inc.'s data center on the 438-acre former Carestream Health property. The suit alleges improper commissioner intervention, rule changes tailored to the project, open-meetings violations and unenforced stop-work orders.","significance":"Most data center land-use suits pit residents against a project or a developer against a moratorium; this one is a commercial neighbor, the owner of a major industrial park, using the land-use review process to challenge a competing user's approval. The complaint's focus on power and water capacity, a code amendment written in anticipation of the project and a negotiated non-enforcement of stop-work orders gives a roadmap for how approvals of power-hungry facilities can be attacked. Industrial landowners, data center sponsors and their lenders should expect approvals obtained on accelerated or customized tracks to draw this kind of challenge.","tags":["data center","special use permit","colorado","industrial park","open meetings"],"parties":[{"name":"GWIP Land Company LLC","role":"Plaintiff"},{"name":"Windsor Renewal I, LLC","role":"Plaintiff"},{"name":"GWIP, LLC","role":"Plaintiff"},{"name":"Board of County Commissioners for Weld County","role":"Defendant"},{"name":"GlobalaiColorado, LLC","role":"Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-264","addedDate":"2026-10-13","title":"Microsoft v. JLL: Tenant Sues Project Manager for Defense and Insurance Coverage Over Forklift Injury During 122 Fifth Avenue Office Build-Out","brief":"Microsoft sued JLL, alleging it failed to indemnify Microsoft and add it to a $10 million liability policy after a 2023 forklift injury during its 122 Fifth Ave. build-out, Bisnow reported.","category":"premises-liability","status":"filed","date":"2026-10-09","jurisdiction":"New York Supreme Court, New York County","state":"NY","amount":"Defense costs and indemnity; $10M liability policy at issue","source":"live","sourceUrl":"https://www.bisnow.com/news/new-york/office/microsoft-sues-jll-over-forklift-accident-inside-fifth-avenue-office","propertyType":"Office","summary":"Microsoft sued JLL in New York County Supreme Court on Oct. 9, 2026, alleging the firm broke promises to indemnify Microsoft against lawsuits tied to the build-out of its offices at 122 Fifth Ave. and to name it as an insured under JLL's $10 million liability policy, Bisnow reported. The suit stems from a construction worker's personal-injury case over a March 2023 forklift accident during the build-out, to which Microsoft was added as a defendant in June 2025. According to the complaint, JLL's counsel rejected Microsoft's claim on the grounds that the building's owner hired the forklift operator's company and that the worker was on a separate project.","significance":"The dispute turns on whether the worker's injury falls within the build-out JLL managed for Microsoft or a separate project in the building, which decides whether JLL's indemnity and insurance promises apply. It shows a tenant's coverage under a project manager's policy being fought over in a separate lawsuit years after the work.","tags":["indemnity","additional insured","office build-out","new york labor law","construction injury"],"parties":[{"name":"Microsoft","role":"Plaintiff"},{"name":"JLL","role":"Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-265","addedDate":"2026-10-13","title":"In re Southbridge Associates LLC: Wellsworth Hotel Owner Files Chapter 11 a Day Before Lender's Foreclosure Auction","brief":"The owner of the Wellsworth Hotel in Southbridge, Massachusetts filed Chapter 11 the day before lender X-Caliber's foreclosure sale and now proposes a $5 million sale to an affiliate.","category":"lending-foreclosure","status":"filed","date":"2026-10-06","jurisdiction":"U.S. Bankruptcy Court, District of Massachusetts","state":"MA","amount":"$13.25 million hotel loan","source":"live","sourceUrl":"https://www.courtlistener.com/docket/74927117/1/southbridge-associates-llc/","docketUrl":"https://www.courtlistener.com/docket/74927117/southbridge-associates-llc/","docketLabel":"CourtListener docket","propertyType":"Hospitality","summary":"Southbridge Associates LLC, which owns the Wellsworth Hotel and an adjoining office building at 14 Mechanic Street in Southbridge, Massachusetts, filed a Chapter 11 petition on October 6, 2026, the day before lender X-Caliber Rural Capital, LLC's scheduled October 7 foreclosure sale. X-Caliber, which lent the owner $13.25 million in November 2022, has moved for relief from the stay or dismissal, alleging a bad-faith filing; the debtor says it filed to stop the foreclosure and restructure. On November 2 the debtor moved to sell the property for $5 million to an affiliate, Lundgren Equity Partners, LLC, with a hearing set for November 19.","significance":"The case shows a hotel owner using a Chapter 11 filing to stop a scheduled foreclosure and then proposing a court-supervised sale to an affiliate, with higher offers invited, while the lender contests the filing. The court's November 19 hearings on the sale, the lender's motion and cash collateral will decide whether the property moves through the bankruptcy sale process or back toward the lender.","tags":["chapter 11","hotel","foreclosure auction","cash collateral","massachusetts"],"parties":[{"name":"Southbridge Associates LLC","role":"Debtor"},{"name":"Southbridge Associates II LLC","role":"Affiliated Debtor"},{"name":"X-Caliber Rural Capital, LLC","role":"Lender"},{"name":"Southbridge Conference Investors, LLC","role":"Interested Party (member of the debtor)"},{"name":"Lundgren Equity Partners, LLC","role":"Proposed Buyer (debtor affiliate)"}],"judge":"Elizabeth D. Katz","amountUsd":13250000,"amountBasis":"loan","hasFull":true},{"id":"live-266","addedDate":"2026-10-13","title":"In re Travis Property Owner LLC: Majority Owner of The Travis Apartments in Frisco Files Chapter 11; Lender ACORE Seeks Dismissal","brief":"The 75.86% owner of The Travis, a 354-unit Frisco, Texas apartment community, filed Chapter 11 on the day of a noticed foreclosure sale; lender ACORE, which says it is owed $74.7 million, seeks dismissal.","category":"lending-foreclosure","status":"filed","date":"2026-10-06","jurisdiction":"U.S. Bankruptcy Court, Northern District of Texas","state":"TX","amount":"About $74.7 million owed as of the petition date, according to lender ACORE; loan of up to $73.4 million made in June 2022","source":"live","sourceUrl":"https://www.law360.com/bankruptcy-authority/mid-cap/articles/2535210","docketUrl":"https://www.courtlistener.com/docket/74922581/travis-property-owner-llc/","docketLabel":"CourtListener docket","propertyType":"Multifamily","summary":"Travis Property Owner LLC, which owns a 75.86% tenant-in-common interest in The Travis apartment community at 900 Gordon Heights Lane in Frisco, Texas, filed for Chapter 11 on October 6, 2026 in the U.S. Bankruptcy Court for the Northern District of Texas, listing more than $50 million in debt, Law360 reported. Lender ACORE Capital Mortgage, LP, which says it is owed about $74.7 million, had noticed a foreclosure sale of the property for that day. The court let the debtor use cash collateral on an interim basis, and ACORE has moved to dismiss the case as unauthorized and filed in bad faith, and separately for relief from the automatic stay.","significance":"The case involves a 2022 acquisition financed with a three-year, interest-only loan that went into default, and an owner that filed Chapter 11 after a state court refused to stop the foreclosure. The court's rulings on ACORE's motions will determine whether the owner gets time to restructure or sell before the lender can foreclose.","tags":["chapter 11","multifamily","single asset real estate","acquisition loan","foreclosure","dallas-fort worth"],"parties":[{"name":"Travis Property Owner LLC","role":"Debtor"},{"name":"Acore Capital Mortgage, L.P.","role":"Creditor (administrative agent for the lenders)"},{"name":"The County of Denton, Texas","role":"Creditor"},{"name":"City of Frisco","role":"Creditor"},{"name":"Frisco ISD","role":"Creditor"}],"judge":"Mark X. Mullin","amountUsd":74734511,"amountBasis":"loan","hasFull":true},{"id":"live-267","addedDate":"2026-10-13","title":"Wilmington Trust v. Stradtman Park, LLC: Fourth Department Upholds Cut to CMBS Trust's Foreclosure Fees and Interest","brief":"New York's Fourth Department affirmed a ruling that cut a CMBS trust's foreclosure fee request from about $588,000 to $250,000 and denied $120,882.59 in note-rate interest on top of default interest.","category":"lending-foreclosure","status":"ruling","date":"2026-10-09","jurisdiction":"New York Supreme Court, Appellate Division, Fourth Department","state":"NY","amount":"$3.6 million CMBS loan; $588,000 fee request cut to $250,000","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_05883.shtml","summary":"On October 9, 2026, New York's Appellate Division, Fourth Department unanimously affirmed an Erie County amended order and judgment in a commercial mortgage foreclosure brought by the trustee of JPMBB Commercial Mortgage Securities Trust 2014-C24, acting through special servicer LNR Partners, LLC, against borrower Stradtman Park, LLC. The trust had sought about $588,000 in attorneys' fees and was awarded $250,000, and it was denied $120,882.59 in note-rate interest on top of the $583,938.25 in default-rate interest it received. The panel found both rulings supported by a fair interpretation of the evidence.","significance":"The court treated the foreclosure as an equitable proceeding in which contractual fee provisions are enforced only for reasonable fees for services actually rendered, measured against local rates. It also upheld refusing note-rate interest where the lender did not document how its default-interest figure was calculated.","tags":["cmbs","special servicer","attorneys fees","default interest","foreclosure"],"parties":[{"name":"Wilmington Trust, National Association, as Trustee for the benefit of the registered holders of JPMBB Commercial Mortgage Securities Trust 2014-C24, Commercial Mortgage Pass-Through Certificates, Series 2014-C24","role":"Plaintiff-Appellant (Lender/Trustee)"},{"name":"LNR Partners, LLC","role":"Special Servicer"},{"name":"Stradtman Park, LLC","role":"Defendant-Respondent (Borrower)"},{"name":"KeyBank National Association","role":"Original Lender (nonparty)"}],"judge":"Emilio Colaiacovo","amountUsd":3600000,"amountBasis":"loan","hasFull":true},{"id":"live-268","addedDate":"2026-10-13","title":"Long Street Associates, LLP v. YMCA of Central Ohio: Ohio Appeals Court Upholds Tenant's Lease Termination Over $1.04M Build-Out Budget","brief":"An Ohio appeals court upheld the YMCA of Central Ohio's termination of its Columbus lease after the build-out budget came to $1,036,697.38, above the lease's roughly $523,100 termination threshold.","category":"lease-disputes","status":"ruling","date":"2026-10-06","jurisdiction":"Ohio Court of Appeals, Tenth Appellate District","state":"OH","amount":"$1.04 million tenant-improvement budget vs. ~$523,100 termination threshold","source":"live","sourceUrl":"https://www.supremecourt.ohio.gov/rod/docs/pdf/10/2026/2026-Ohio-3942.pdf","summary":"On October 6, 2026, Ohio's Tenth District Court of Appeals affirmed summary judgment for the Young Men's Christian Association of Central Ohio in a suit by landlord Long Street Associates, LLP over the YMCA's 2020 termination of its lease at 31-55 West Long Street in Columbus. The lease let the tenant walk away once if the construction budget for its improvements exceeded a fixed threshold of roughly $523,100, and the budget delivered came to $1,036,697.38. The court held the landlord's own complaint admitted the final plans were agreed and the budget was the one the lease contemplated, and that an oral offer to absorb the overage could not defeat the termination right.","significance":"Budget-based termination options are common in leases of unfinished or historic space, and this decision shows how literally courts will read them: once the triggering budget is delivered, the option is live, whatever the landlord calls the document. Landlords also learn that statements in their own pleadings can be treated as binding admissions, and that a no-oral-modification clause will block a phone-call fix to a cost overrun. Tenants gain confidence that a clearly drafted cost-overrun exit will be enforced.","tags":["commercial lease","termination option","tenant improvements","judicial admission","historic building"],"parties":[{"name":"Long Street Associates, LLP","role":"Plaintiff-Appellant (Landlord)"},{"name":"The Young Men's Christian Association of Central Ohio","role":"Defendant-Appellee (Tenant)"}],"judge":"Mentel","amountUsd":null,"hasFull":true},{"id":"live-269","addedDate":"2026-10-13","title":"Tenant v. ESRT Empire State Building LLC: First Department Enforces Lease Waiver of Constructive Eviction","brief":"New York's First Department affirmed dismissal of a commercial tenant's suit against ESRT Empire State Building LLC, holding the tenant waived constructive eviction in its lease and identified no lease provision that was breached.","category":"lease-disputes","status":"ruling","date":"2026-10-06","jurisdiction":"New York Supreme Court, Appellate Division, First Department","state":"NY","amount":"Dismissal affirmed","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_05723.shtml","summary":"On October 6, 2026, New York's Appellate Division, First Department unanimously affirmed the dismissal of a commercial tenant's suit against its landlord, ESRT Empire State Building LLC. The court held that the tenant had expressly waived its constructive eviction rights in the lease, and that even without the waiver it had not shown the substantial loss of use the claim requires. Its breach-of-lease claim also failed because it identified no lease provision that was breached.","significance":"The decision applies First Department precedent enforcing a commercial tenant's express lease waiver of constructive eviction, and it did so on a motion to dismiss. It also shows that a breach-of-lease claim must identify the specific provision the landlord is said to have violated.","tags":["constructive eviction","lease waiver","office lease","manhattan","motion to dismiss"],"parties":[{"name":"ESRT Empire State Building LLC","role":"Defendant-Respondent (Landlord)"}],"judge":"Lyle E. Frank","amountUsd":null,"hasFull":true},{"id":"live-270","addedDate":"2026-10-13","title":"5 Beekman Property Owner, LLC v. Henick-Lane, Inc.: Plaintiffs Ordered to Return $850,000 Insurer Paid on a Settlement That Never Closed","brief":"New York's First Department affirmed an $850,000 judgment, plus interest, ordering 5 Beekman's owner and Broadway Construction Group to return money an HVAC contractor's insurer paid on a settlement that was never finalized.","category":"construction-defect","status":"ruling","date":"2026-10-06","jurisdiction":"New York Supreme Court, Appellate Division, First Department","state":"NY","amount":"$850,000 judgment plus prejudgment interest","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_05712.shtml","summary":"On October 6, 2026, New York's Appellate Division, First Department unanimously affirmed an $850,000 judgment, plus prejudgment interest, against 5 Beekman Property Owner, LLC and Broadway Construction Group, LLC. One of HVAC contractor Henick-Lane, Inc.'s insurers had paid them $850,000, apparently believing their defective-HVAC suit had settled, when no full settlement agreement was in place. The court also upheld a civil contempt finding against the plaintiffs for failing to return the money.","significance":"The court held that an insurer's payment made in the mistaken belief that a settlement existed is not a voluntary payment the recipient may keep, even though the check was labeled a settlement payment. It also confirmed that contempt was available to enforce the return order because no money judgment had yet been entered when the contempt order issued.","tags":["hvac defect","mechanics lien","settlement","contempt","insurer payment"],"parties":[{"name":"5 Beekman Property Owner, LLC","role":"Plaintiff-Appellant (Owner)"},{"name":"Broadway Construction Group, LLC","role":"Plaintiff-Appellant"},{"name":"Henick-Lane, Inc.","role":"Defendant-Respondent (HVAC Contractor)"}],"judge":"Andrew Borrok","amountUsd":850000,"amountBasis":"judgment","hasFull":true},{"id":"live-271","addedDate":"2026-10-13","title":"Computershare Trust (BMO 2024-5C5) v. Starwood Mortgage Capital: $46.85M CMBS Loan Repurchase Suit Removed to Federal Court Over Undisclosed Senior Lien","brief":"A CMBS trustee sued Starwood Mortgage Capital to force repurchase of a $46.85M loan on two Harris County, Texas properties, alleging an earlier-recorded deed of trust was foreclosed and wiped out its lien.","category":"lending-foreclosure","status":"pending","date":"2026-10-09","jurisdiction":"U.S. District Court, Southern District of New York (removed from New York Supreme Court, New York County)","state":"NY","amount":"$46.85 million mortgage loan","source":"live","sourceUrl":"https://www.mpamag.com/us/specialty/commercial/trust-sues-starwood-over-4685m-loan-with-hidden-lien/593173","summary":"Computershare Trust Company, as trustee for the BMO 2024-5C5 Mortgage Trust, sued Starwood Mortgage Capital LLC in New York state court on September 4, 2026, and Starwood removed the case to the Southern District of New York on October 9, Mortgage Professional America reported. The trust says Starwood sold it a $46.85 million loan on The Pointe and Oak Shadows in Harris County, Texas, represented as a first lien, although a $27.601 million deed of trust held by Thistle Creek Partners, LP was already recorded. It alleges Thistle Creek foreclosed and wiped out the trust's liens, and it seeks repurchase or damages of at least the repurchase price.","significance":"The trust's claim rests on a recorded senior lien that, it says, Starwood's lien-priority representations did not account for. Starwood's own SEC repurchase report lists the demand as in dispute, and the same report shows a second pending repurchase suit against Starwood Mortgage Capital filed in March 2026.","tags":["cmbs","repurchase","rep and warranty","lien priority","starwood"],"parties":[{"name":"Computershare Trust Company, National Association, as Trustee, on behalf of the Registered Holders of BMO 2024-5C5 Mortgage Trust, Commercial Mortgage Pass-Through Certificates, Series 2024-5C5","role":"Plaintiff"},{"name":"Starwood Mortgage Capital LLC","role":"Defendant (loan seller)"},{"name":"CWCapital Asset Management LLC","role":"Special Servicer"},{"name":"Thistle Creek Partners, LP","role":"Alleged senior lienholder (non-party)"}],"judge":"Edgardo Ramos","amountUsd":46850000,"amountBasis":"loan","docketUrl":"https://www.courtlistener.com/docket/74945850/computershare-trust-company-national-association-as-trustee-v-starwood/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-272","addedDate":"2026-10-13","title":"Southridge Mall Foreclosure: Milwaukee County Court Approves Sale of Simon-Affiliated Mall to Receiver-Linked Buyer Assuming $101.9M Loan","brief":"A Milwaukee County judge approved the sale of Southridge Mall from a Simon affiliate to a receiver-linked buyer assuming the $101.9 million loan and paying $7 million in cash, ending a CMBS foreclosure.","category":"lending-foreclosure","status":"ruling","date":"2026-10-06","jurisdiction":"Wisconsin Circuit Court, Milwaukee County","state":"WI","amount":"$101.9 million loan assumption plus $7 million cash","source":"live","sourceUrl":"https://dailyreporter.com/2026/10/12/after-southridge-mall-sale-demolition-soon-for-boston-store/","propertyType":"Retail","summary":"On October 6, 2026, Milwaukee County Circuit Judge William Pocan entered an order approving the sale of Southridge Mall in Greendale, Wisconsin, ending a foreclosure that began in December 2020, the Milwaukee Journal Sentinel reported. The mall, excluding its separately owned department store anchors, is being sold by a Simon Property Group affiliate to Southridge Mall Member LLC, a newly formed buyer tied to court-appointed receiver Spinoso Management Group. The buyer will assume the mall's $101.9 million loan and pay $7 million in cash, according to court documents cited by the paper.","significance":"The case shows how long a contested regional-mall foreclosure can take: almost six years from complaint to an approved sale, even after the borrower agreed to a foreclosure judgment in 2021. The structure is also notable. A receiver's affiliate buys the asset by assuming the securitized debt instead of the lender taking title or holding an open auction, which gives CMBS holders and special servicers a model for exiting long-stalled retail loans.","tags":["cmbs","mall foreclosure","receivership","loan assumption","retail"],"parties":[{"name":"Southridge LP","role":"Borrower/Defendant (Seller)"},{"name":"Simon Property Group Inc.","role":"Borrower's Parent"},{"name":"Southridge Mall Member LLC","role":"Buyer"},{"name":"Spinoso Management Group LLC","role":"Receiver"},{"name":"Spinoso Real Estate Group LLC","role":"Buyer Joint Venture Member"},{"name":"Wynkoop Financial","role":"Buyer Joint Venture Member"},{"name":"Barclays Bank PLC","role":"Original Lender"}],"judge":"William Pocan","amountUsd":101900000,"amountBasis":"loan","hasFull":true},{"id":"live-273","addedDate":"2026-10-13","title":"Stop 65, LLC v. Beach Park Railway, LLC: Ohio Appeals Court Upholds Shopping-Center Eviction of Museum Tenant Over Unapproved Sublease","brief":"An Ohio appeals court upheld a shopping-center owner's eviction of a museum tenant, holding that letting a motorcycle-repair operation occupy space was an unauthorized sublease and no 30-day notice was needed.","category":"landlord-tenant","status":"ruling","date":"2026-10-05","jurisdiction":"Ohio Court of Appeals, Ninth Appellate District","state":"OH","amount":"Possession of a 15,000 sq. ft. space renting for $583 a month","source":"live","sourceUrl":"https://www.supremecourt.ohio.gov/rod/docs/pdf/9/2026/2026-Ohio-3908.pdf","propertyType":"Retail","summary":"On October 5, 2026, Ohio's Ninth District Court of Appeals affirmed an Avon Lake Municipal Court judgment evicting Beach Park Railway, LLC, a state-funded museum operator, from shopping-center space owned by Stop 65, LLC. The court held that letting an outside motorcycle-repair operation occupy dedicated space in the premises was an unauthorized sublease, not a mere license, and that a commercial landlord needed no separate 30-day termination notice before its statutory three-day notice to vacate.","significance":"The decision gives commercial landlords a clear test for when a tenant's informal side arrangement becomes a sublease that breaches an anti-subletting clause, and it confirms that Ohio's residential 30-day termination rule does not apply to commercial leases. It also shows how a non-disturbance agreement with a public funder can add notice-of-default conditions that complicate a tenant's own damages counterclaims.","tags":["commercial eviction","sublease","shopping center","ohio","non-disturbance agreement"],"parties":[{"name":"Stop 65, LLC","role":"Plaintiff-Appellee / Landlord"},{"name":"Beach Park Railway, LLC","role":"Defendant-Appellant / Tenant"},{"name":"Ohio Facilities Commission","role":"Non-disturbance agreement party (originally named, dismissed by stipulation)"}],"judge":"Carol Ann Robb","amountUsd":null,"hasFull":true},{"id":"live-274","addedDate":"2026-10-13","title":"Landlord Sues Physical Intelligence Over 2000 Folsom Street Holdover; Anthropic Reported as Next Tenant","brief":"The owners of 2000 Folsom Street in San Francisco sued robotics startup Physical Intelligence, alleging it stayed past its September lease end, and seek holdover damages of more than $13,000 a day.","category":"lease-disputes","status":"filed","date":"2026-10-06","jurisdiction":"San Francisco County Superior Court","state":"CA","amount":"Holdover damages of more than $13,000/day sought; a June lease amendment set rent at $160,000/month for an expanded footprint through September","source":"live","sourceUrl":"https://sfstandard.com/2026/10/06/physical-intelligence-anthropic-mission-lawsuit/","propertyType":"Industrial","summary":"The owners of a 98,000-square-foot industrial building at 2000 Folsom Street in San Francisco's Mission District sued robotics startup Physical Intelligence in San Francisco Superior Court, alleging it would not leave after its lease ended in September, The San Francisco Standard reported on October 6, 2026. The landlords seek possession and holdover damages of more than $13,000 a day, and say a new tenant wants to move in; The Standard reported that sources confirmed that tenant is Anthropic. Physical Intelligence had not responded to the complaint, and neither company nor the landlords' attorney responded to The Standard's requests for comment.","significance":"The case shows how a lease amendment that drops a month-to-month option and sets a fixed end date can leave a tenant that stays on exposed to daily holdover damages once a replacement tenant is lined up. It also reflects the competition The Standard describes among AI and robotics companies for San Francisco industrial space suited to building and testing robots.","tags":["lease dispute","holdover","industrial","san francisco","ai"],"parties":[{"name":"Physical Intelligence","role":"Tenant/Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-275","addedDate":"2026-10-13","title":"City of San Antonio v. U.S. Department of Homeland Security: City Sues Under NEPA to Halt Conversion of 640,000-SF East Side Warehouse Into ICE Detention Center","brief":"San Antonio sued DHS and ICE under NEPA to halt conversion of a nearly 640,000-square-foot East Side warehouse, bought for $66.1 million, into a detention center for up to 1,500 people.","category":"environmental","status":"filed","date":"2026-10-13","jurisdiction":"U.S. District Court, Western District of Texas","state":"TX","amount":"Injunctive relief; warehouse bought for $66.1 million","source":"live","sourceUrl":"https://www.tpr.org/government-politics/2026-10-13/san-antonio-takes-dhs-ice-to-court-over-planned-eastside-detention-facility","docketUrl":"https://www.courtlistener.com/docket/74952112/city-of-san-antonio-v-mullin-secretary-of-us-department-of-homeland/","docketLabel":"CourtListener docket","propertyType":"Industrial","summary":"The City of San Antonio sued the U.S. Department of Homeland Security and U.S. Immigration and Customs Enforcement in federal court in San Antonio on Oct. 13, 2026 (No. 5:26-cv-06542), seeking to halt conversion of a nearly 640,000-square-foot East Side warehouse into an immigration detention and processing facility for up to 1,500 people, the San Antonio Report reported. The city argues the agencies have not done the environmental review the National Environmental Policy Act requires and asks the court to bar development until they do. On Oct. 22, Judge Jason K. Pulliam held the city's request for injunctive relief in abeyance and ordered the parties to file an update by Nov. 30, 2026.","significance":"The case tests whether a city can use NEPA review to slow a federal agency's conversion of a private industrial building it has bought. For industrial owners and lenders, it shows that a sale to a federal user can lead to litigation over the site's reuse after closing.","tags":["nepa","industrial","federal property","warehouse conversion","texas"],"parties":[{"name":"City of San Antonio","role":"Plaintiff"},{"name":"United States Department of Homeland Security","role":"Defendant"},{"name":"U.S. Immigration and Customs Enforcement","role":"Defendant"}],"judge":"Jason K. Pulliam","amountUsd":null,"hasFull":true},{"id":"live-276","addedDate":"2026-10-13","title":"Silver Fox 606 LLC v. Village of Indiantown: Data Center Developer Sues Over Appeal of Its Plat Approval","brief":"Data center developer Silver Fox 606 sued the Village of Indiantown, Florida, alleging officials are unlawfully blocking its $25 million project; a judge has since blocked a zoning appeals hearing.","category":"zoning-land-use","status":"filed","date":"2026-10-07","jurisdiction":"Florida Circuit Court, Nineteenth Judicial Circuit, Martin County","state":"FL","amount":"Declaratory and injunctive relief and a writ of prohibition; CBS12 describes a $25 million project","source":"live","sourceUrl":"https://cbs12.com/news/local/data-center-developer-sues-indiantown-alleges-village-is-illegally-blocking-25m-project-indiantown-martin-county-data-center-silver-fox-606-llc-data-center-lawsuit-25-million-project-village-of-indiantown-village-council-planning-board-data","propertyType":"Data Center","summary":"Silver Fox 606 LLC has sued the Village of Indiantown, its village council and its planning, zoning and appeals board, filing a complaint and verified petition for a writ of prohibition that alleges local officials are illegally derailing its $25 million data center project on more than 600 acres, CBS12 reported on October 12, 2026. The developer argues the board has no jurisdiction to hear a resident's appeal of the village's administrative approval of its plat. A Martin County circuit judge later issued an injunction blocking a planned zoning appeals hearing while the case proceeds, CBS12 reported.","significance":"The case tests whether a local board can revisit an administratively approved plat after a change in local leadership, and whether a pending appeal can stall a project the zoning code allows by right. For owners of by-right industrial land, it shows how a post-approval appeal can put a project on hold until a court steps in.","tags":["data center","plat approval","vested rights","sunshine law","florida"],"parties":[{"name":"Silver Fox 606 LLC","role":"Plaintiff/Petitioner"},{"name":"Village of Indiantown","role":"Defendant"},{"name":"Indiantown Village Council","role":"Defendant"},{"name":"Village of Indiantown Planning, Zoning and Appeals Board","role":"Respondent"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-277","addedDate":"2026-10-13","title":"In re AZ 175th Street LLC: Queens Mixed-Use Owner Files Second Chapter 11 After First Case Was Dismissed With a Refiling Bar","brief":"The owner of a Jamaica, Queens mixed-use building filed a second Chapter 11 case, reporting $14 million in assets and $12.6 million in liabilities, after its 2025 case was dismissed with a refiling bar.","category":"lending-foreclosure","status":"filed","date":"2026-10-10","jurisdiction":"U.S. Bankruptcy Court, Eastern District of New York","state":"NY","amount":"$12.6 million in reported liabilities against $14 million in reported assets","source":"live","sourceUrl":"https://bondoro.com/az-175th-street-filing-alert/","docketUrl":"https://www.courtlistener.com/docket/74948724/az-175th-street-llc/","docketLabel":"CourtListener docket","propertyType":"Mixed-Use","summary":"AZ 175th Street LLC, owner of a mixed-use building in Jamaica, Queens, filed a voluntary Chapter 11 petition in the Eastern District of New York on October 10, 2026 (Case No. 26-44763), listing $14 million in assets and $12.6 million in liabilities, Bondoro reported. It is the company's second case. The first, filed May 23, 2025 and designated a single-asset real estate case, drew a motion to dismiss from creditor UC 175th Street Apartments Holder, LLC and ended with an October 9, 2025 order dismissing the case and barring the debtor from refiling, according to the court docket.","significance":"A second filing after a dismissal with a refiling bar puts the automatic stay back in place against the owner's creditors. The history of the first case can be raised in any new motion to dismiss or for stay relief.","tags":["chapter 11","single asset real estate","repeat filing","queens","mixed-use"],"parties":[{"name":"AZ 175th Street LLC","role":"Debtor"},{"name":"UC 175th Street Apartments Holder, LLC","role":"Creditor (movant in prior case)"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-278","addedDate":"2026-10-13","title":"Merchants Bank of Indiana v. GRV Jackson Park LLC: $6.4M Foreclosure on Three South Side Chicago Apartment Buildings","brief":"Merchants Bank of Indiana filed to foreclose on three South Side Chicago apartment buildings over $6.4 million in two loan facilities and seeks to hold the venture's two principals liable as guarantors.","category":"lending-foreclosure","status":"filed","date":"2026-10-10","jurisdiction":"Circuit Court of Cook County, Illinois","state":"IL","amount":"$6.4 million in two loan facilities","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/10/10/merchants-bank-files-suit-against-patel-wolkowicki/","propertyType":"Multifamily","summary":"Merchants Bank of Indiana has filed a foreclosure complaint, reported on October 10, 2026 as filed earlier in October, in Cook County Circuit Court against borrower GRV Jackson Park LLC, seeking to foreclose on three apartment buildings in Chicago's South Shore and Jackson Park areas. The suit covers two loan facilities totaling $6.4 million made in June 2024, on which the borrower allegedly stopped making monthly payments in March 2025. The complaint also names the venture's two principals under their unconditional guaranties and seeks to hold them liable for any deficiency.","significance":"A lender's collateral can lose value quickly when the owners of a building fall out with each other. Protective advances for items like boilers keep a building running but raise the amount a sale has to recover, and guarantors who are suing each other may be slow to pay.","tags":["foreclosure","multifamily","chicago","guaranty","cook county"],"parties":[{"name":"Merchants Bank of Indiana","role":"Plaintiff/Lender"},{"name":"GRV Jackson Park LLC","role":"Defendant/Borrower"}],"judge":null,"amountUsd":6400000,"amountBasis":"loan","hasFull":true},{"id":"live-279","addedDate":"2026-10-13","title":"Pacific Collective, LLC v. TGS CC Ventures, LLC: California Appeals Court Holds Build-to-Suit Landlord's Slow Land Purchase Let Jushi Unit Rescind Culver City Dispensary Lease","brief":"A California appeals court held a build-to-suit developer's delay in buying the land let a Jushi unit rescind its Culver City dispensary lease, defeating claims of more than $20 million.","category":"lease-disputes","status":"ruling","date":"2026-10-12","jurisdiction":"California Court of Appeal, Second Appellate District, Division Three","state":"CA","amount":"Damages alleged to exceed $20 million; $4.2 million land purchase","source":"live","sourceUrl":"https://www4.courts.ca.gov/opinions/nonpub/B339582.PDF","propertyType":"Retail","summary":"On October 12, 2026, a California Court of Appeal panel affirmed a judgment for cannabis retailer TGS CC Ventures, LLC and its parent and lease guarantor Jushi, Inc. in a suit by developer Pacific Collective, LLC over a 15-year build-to-suit lease for a dispensary at 3800 Sepulveda Boulevard in Culver City. The court held that the lease implicitly required Pacific to buy the land from ExxonMobil within a reasonable time, and that substantial evidence supported the referee's finding that its delay justified TGS's February 2020 rescission. Pacific had alleged damages of more than $20 million against the tenant and guarantor.","significance":"The decision is a warning to build-to-suit developers who sign a lease before they control the land: if the lease sets no outside date for acquiring title, California courts will imply a reasonable time, and strategic delay to save financing costs can hand the tenant a rescission right. It also shows that a tenant's guaranty falls with the lease when the landlord is the party in material breach.","tags":["build-to-suit","lease rescission","guaranty","cannabis","california"],"parties":[{"name":"Pacific Collective, LLC","role":"Plaintiff/Appellant (Landlord)"},{"name":"TGS CC Ventures, LLC","role":"Defendant/Respondent (Tenant)"},{"name":"Jushi, Inc.","role":"Defendant/Respondent (Guarantor)"}],"judge":"Ashworth","amountUsd":null,"hasFull":true},{"id":"live-280","addedDate":"2026-10-13","title":"First Department Affirms $1.2 Million Jury Verdict for Preschool Tenant Against Bohemian Brethren Presbyterian Church Over Uncleared Building Violations","brief":"New York's First Department affirmed a $1,216,177.36 jury verdict for a preschool tenant against its church landlord, which failed to cooperate on city approvals the tenant needed to run the school.","category":"lease-disputes","status":"ruling","date":"2026-10-13","jurisdiction":"New York Supreme Court, Appellate Division, First Department","state":"NY","amount":"$1,216,177.36 judgment","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_05909.shtml","summary":"On October 13, 2026, the Appellate Division, First Department unanimously affirmed a $1,216,177.36 jury judgment for a preschool operator, Ordinary Faces LLC, and its founder against their landlord, Bohemian Brethren Presbyterian Church. The evidence supported findings that the church breached lease provisions requiring it to cooperate in obtaining the approvals the school needed and to act expeditiously and diligently on a fire alarm system. The court upheld the lost-profits award, held that a rent abatement was not the tenant's only remedy, and ruled that a clause limiting recovery to the landlord's interest in the building did not bar the award after the church sold the building.","significance":"The court held that a landlord's lease duty to cooperate with a tenant's approvals required it to cure building violations on areas outside the leased premises, and that the breach could support lost-profits damages. It also held that a clause limiting the tenant to the landlord's interest in the building reaches the proceeds of a later sale, and that a landlord can lose a jury waiver by raising it too late.","tags":["commercial lease","lost profits","building violations","jury waiver","new york"],"parties":[{"name":"Ordinary Faces LLC","role":"Plaintiff-Respondent (Tenant)"},{"name":"Bohemian Brethren Presbyterian Church","role":"Defendant-Appellant (Landlord)"}],"judge":"Joel M. Cohen","amountUsd":1216177.36,"amountBasis":"judgment","hasFull":true},{"id":"live-281","addedDate":"2026-10-13","title":"Recycled Properties, LLC v. City Council of the City of Chesapeake: Virginia Appeals Court Upholds Denial of Warehouse and Office Site Plan as Expansion of Nonconforming Landfill Use","brief":"A Virginia appeals court upheld Chesapeake's refusal to approve a warehouse and office site plan at Recycled Properties' construction-debris landfill as an expansion of a nonconforming use.","category":"zoning-land-use","status":"ruling","date":"2026-10-13","jurisdiction":"Court of Appeals of Virginia","state":"VA","amount":"Site plan approval; statutory damages claim dismissed","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/13/recycled_properties_llc_v._the_city_council_of_the_city_of_chesapeake.pdf","propertyType":"Industrial","summary":"On October 13, 2026, the Court of Appeals of Virginia affirmed a circuit court order sustaining the City of Chesapeake's demurrer to Recycled Properties, LLC's challenge to the city's disapproval of a site plan for a warehouse and office building at its construction-debris landfill. The city had found the buildings would expand a legally nonconforming use and asked for more information and a conditional use permit. The court held that the owner's complaint, read with the city's denial letter attached to it, did not plead facts showing the denial was arbitrary, capricious or outside the zoning ordinance.","significance":"The ruling shows that a Virginia locality may refuse a site plan for new buildings that would support a legally nonconforming use, and may ask for more information before approving one. It also shows that a denial letter attached to a complaint can defeat a site plan appeal at the pleading stage when the complaint does not factually dispute the letter's stated grounds.","tags":["nonconforming use","site plan","zoning","industrial","virginia"],"parties":[{"name":"Recycled Properties, LLC","role":"Appellant (Property Owner)"},{"name":"City Council of the City of Chesapeake","role":"Appellee"},{"name":"City of Chesapeake","role":"Appellee"}],"judge":"Kevin M. Duffan","amountUsd":null,"hasFull":true},{"id":"live-282","addedDate":"2026-10-13","title":"In re 374 Square Feet in the City of Bradford (Appeal of DewBoi Properties, LLC): Pennsylvania Commonwealth Court Enforces $30,000 Condemnation Settlement for Bus Station Alley","brief":"Pennsylvania's Commonwealth Court enforced a $30,000 settlement for Bradford's taking of an alley strip for a bus station, rejecting the owner's bid to back out over a utility pole moved onto its lot.","category":"eminent-domain","status":"ruling","date":"2026-10-13","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"$30,000 condemnation settlement","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/13/in_re_374_square_feet_more_or_less_in_the_city_of_bradford_at_pin.pdf","summary":"On October 13, 2026, the Commonwealth Court of Pennsylvania affirmed a McKean County order enforcing a settlement between the City of Bradford and property owner DewBoi Properties, LLC over the city's taking of 374 square feet of an alley behind DewBoi's property for a new bus station. The owner had accepted $30,000 and the city's promise to relocate two utility poles, then balked when one pole was to be moved elsewhere on its lot, citing lost parking for its tenants and their customers. The court held the signed agreement unambiguously allowed relocation onto DewBoi's property and rejected the owner's mutual mistake defense.","significance":"Owners negotiating partial-taking settlements should pin down where relocated utilities and other site features will go, because the court enforced the signed terms even though the effect on tenant parking became clear only later. The opinion is a non-precedential memorandum.","tags":["eminent domain","condemnation settlement","parking","utility easement","pennsylvania"],"parties":[{"name":"DewBoi Properties, LLC","role":"Appellant (Condemnee/Property Owner)"},{"name":"City of Bradford","role":"Appellee (Condemnor)"}],"judge":"Lori A. Dumas","amountUsd":30000,"amountBasis":"settlement","hasFull":true},{"id":"live-283","addedDate":"2026-10-13","title":"Trustees Main/270, LLC v. ApplianceSmart, Inc.: Sixth Circuit Holds Shopping-Center Landlord Could Reject Replacement Tenants Tied to Its Defaulting Tenant","brief":"The Sixth Circuit affirmed a Columbus shopping-center landlord's judgment against big-box tenant ApplianceSmart and guarantor JanOne, holding it could reject replacement tenants tied to the defaulting tenant.","category":"lease-disputes","status":"ruling","date":"2026-10-07","jurisdiction":"U.S. Court of Appeals for the Sixth Circuit (on appeal from the U.S. District Court, Southern District of Ohio)","state":"OH","amount":"$1,346,579.31 in rent, charges and broker fees, plus interest (district court judgment affirmed)","source":"live","sourceUrl":"https://www.opn.ca6.uscourts.gov/opinions.pdf/26a0394n-06.pdf","propertyType":"Retail","summary":"A Sixth Circuit panel affirmed a judgment for Trustees Main/270, LLC, owner of a Columbus, Ohio shopping center, against its former big-box tenant ApplianceSmart, Inc. and the lease guarantor JanOne, Inc. The defendants argued the landlord had failed to mitigate its damages by turning down two replacement tenants that the guarantor and an affiliated company had proposed. The court held that Ohio law does not make a commercial landlord deal with replacement tenants that carry an undue risk of another default, and that the landlord's multi-year search, which ended in an AutoZone lease, was a reasonable effort to mitigate.","significance":"The panel applied the Ohio Supreme Court's Frenchtown Square decision and Restatement section 350 to hold that a landlord's duty to mitigate does not require it to accept replacement tenants that carry an undue risk of another default, including affiliates of the defaulting tenant and its guarantor. It also held that conditions such as prepaying arrears and a nonrefundable deposit were a reasonable response to that risk.","tags":["mitigation of damages","retail lease","lease guaranty","big-box","ohio law"],"parties":[{"name":"Trustees Main/270, LLC","role":"Plaintiff-Appellee / Landlord"},{"name":"ApplianceSmart, Inc.","role":"Defendant-Appellant / Tenant"},{"name":"JanOne, Inc.","role":"Defendant-Appellant / Guarantor"}],"judge":"John B. Nalbandian","amountUsd":1346579.31,"amountBasis":"judgment","docketUrl":"https://www.courtlistener.com/docket/72225132/trustees-main270-llc-v-appliancesmart-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-284","addedDate":"2026-10-13","title":"Conroe WM LLC v. HREF Senior Worthington LLC: Delaware Supreme Court Affirms Preferred-Equity Lender's Takeover of Texas Assisted-Living Project","brief":"Delaware's Supreme Court affirmed that preferred-equity investor HREF took control of the holding company behind a 117-bed Conroe, Texas assisted-living facility after missed payments on its $4.5 million investment.","category":"lending-foreclosure","status":"ruling","date":"2026-10-08","jurisdiction":"Delaware Supreme Court (appeal from the Delaware Court of Chancery)","state":"DE","amount":"$4.5 million preferred-equity investment; control of the project's holding company","source":"live","sourceUrl":"https://courts.delaware.gov/opinions/download.aspx?id=401990","propertyType":"Senior Living","summary":"On October 8, 2026, the Delaware Supreme Court affirmed a Court of Chancery judgment holding that HREF Senior Worthington LLC is now the sole manager of the holding company that controls a 117-bed assisted-living facility in Conroe, Texas. The Supreme Court issued a short order adopting the reasons in the Chancery memorandum opinion of January 12, 2026. That opinion found that HREF's contractual step-in right had been triggered when the holding company stopped making monthly payments on HREF's $4.5 million investment. The sponsor-side entities had argued that HUD approval rules on the project's mortgage-insured loan blocked the change of control. The courts rejected that argument.","significance":"The ruling shows a preferred-equity investor's step-in right at the holding-company level enforced in a summary proceeding under Section 18-110 of the Delaware LLC Act, even though the property-owning subsidiary carries a HUD-insured Section 232 loan with its own approval rules. The Court of Chancery held those HUD consent requirements bound the borrower, not the upstream holding company, and the Supreme Court adopted its reasoning.","tags":["senior living","preferred equity","step-in rights","hud section 232","delaware llc act"],"parties":[{"name":"HREF Senior Worthington LLC","role":"Appellee (Plaintiff Below)"},{"name":"SL1 B LLC","role":"Co-Plaintiff (Court of Chancery)"},{"name":"Conroe WM LLC","role":"Appellant (Defendant Below)"},{"name":"WM Property Holdings LLC","role":"Appellant (Defendant Below)"},{"name":"WM Conroe Property Holdings LLC","role":"Nominal Defendant"}],"judge":"N. Christopher Griffiths","amountUsd":4500000,"amountBasis":"other","hasFull":true},{"id":"live-285","addedDate":"2026-10-13","title":"Concerned Citizens of Spartanburg County v. Spartanburg County: Judge Dismisses Zoning Challenge to Valara Holdings' $2.8B Data Center","brief":"A Spartanburg County judge dismissed neighbors' challenge to the 'minor' permit review of Valara Holdings' $2.8 billion data center for lack of standing and failure to appeal first; the group plans to appeal.","category":"zoning-land-use","status":"ruling","date":"2026-10-06","jurisdiction":"South Carolina Court of Common Pleas, Seventh Judicial Circuit (Spartanburg County)","state":"SC","amount":"$2.8 billion data center project; declaratory and injunctive relief only, no damages sought","source":"live","sourceUrl":"https://sclawyersweekly.com/news/2026/10/08/judge-dismisses-lawsuit-challenging-spartanburg-data-center/","propertyType":"Data Center","summary":"On October 6, 2026, Judge J. Derham Cole Jr. of the Seventh Judicial Circuit dismissed a suit by Concerned Citizens of Spartanburg County claiming the county should have reviewed Valara Holdings' $2.8 billion data center on South Pine Street, at the former Kohler plant, as a 'major' rather than a 'minor' land development. FOX Carolina reported that the judge found the group had not shown it was specially damaged and had not first appealed to the county Board of Zoning Appeals, and that he called a challenge to a second, still-pending permit premature. The ruling did not decide whether the project was correctly classified, and the group's lawyers say they will appeal; Valara has said it followed all state and local permitting requirements.","significance":"The ruling turned on procedure, not the merits: standing and the county's zoning-appeal process decided the case before the court reached the classification question. For developers relying on staff-level approvals it shows the weight of short administrative appeal windows, while the planned appeal and separate regulatory challenges keep this project's approvals contested.","tags":["data center","zoning","standing","exhaustion","south carolina"],"parties":[{"name":"Concerned Citizens of Spartanburg County","role":"Plaintiff"},{"name":"Spartanburg County","role":"Defendant"},{"name":"Valara Holdings","role":"Developer"}],"judge":"J. Derham Cole Jr.","amountUsd":null,"hasFull":true},{"id":"live-286","addedDate":"2026-10-13","title":"Hetley Associates v. Lemoyne Borough Zoning Hearing Board: Pennsylvania Commonwealth Court Rejects Strip-Center Owner's Use Variance for Overflow Parking on Adjacent Residential Lots","brief":"Pennsylvania's Commonwealth Court upheld denial of a use variance letting the Hetley Plaza strip-center owner replace three houses on residential lots with overflow parking, finding no hardship tied to those lots.","category":"zoning-land-use","status":"ruling","date":"2026-10-09","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"Use variance to demolish three houses and build a parking lot (no dollar figure at stake)","source":"live","sourceUrl":"https://www.pacourts.us/assets/opinions/Commonwealth/out/1306CD25_10-9-26.pdf","propertyType":"Retail","summary":"On October 9, 2026, the Commonwealth Court of Pennsylvania affirmed the denial of a use variance sought by Hetley Associates, owner of the Hetley Plaza strip shopping center in Lemoyne Borough. The owner wanted to demolish three houses it owns in the borough's Urban Residential District and replace them with parking for the center, which has fewer spaces than its commercial zoning requires. The court held that the claimed hardship belonged to the separate commercial parcel and to the owner, not to the residential lots that needed the variance. That failure alone defeated the request.","significance":"Following its Bawa Muhaiyaddeen decision, the court held that a use variance must rest on hardship to the parcel for which relief is sought, not on the needs of a separate commercial parcel under the same ownership. The opinion is unreported, and a footnote leaves open whether consolidating the lots through a reverse subdivision would change the analysis.","tags":["use variance","parking","shopping center","pennsylvania","unnecessary hardship"],"parties":[{"name":"Hetley Associates","role":"Appellant"},{"name":"Lemoyne Borough Zoning Hearing Board","role":"Appellee"}],"judge":"Christine Fizzano Cannon","amountUsd":null,"hasFull":true},{"id":"live-287","addedDate":"2026-10-13","title":"Lenox Mortgage IX LLC v. San Francisco Care Center, L.P.: Ninth Circuit BAP Limits Lender's Fee Recovery Under Old HUD Loan Documents After Assisted-Living Facility Sale","brief":"The Ninth Circuit BAP held old HUD loan documents barred lender Lenox Mortgage IX from recovering some of its $419,266.94 fee demand after a San Francisco assisted-living facility's bankruptcy sale.","category":"lending-foreclosure","status":"ruling","date":"2026-10-09","jurisdiction":"U.S. Bankruptcy Appellate Panel of the Ninth Circuit (appeal from U.S. Bankruptcy Court, Northern District of California)","state":"CA","amount":"$419,266.94 in disputed lender attorneys' fees on a $19.8 million payoff demand","source":"live","sourceUrl":"https://cdn.ca9.uscourts.gov/datastore/bap/2026/10/09/25-1201.pdf","propertyType":"Senior Living","summary":"On October 9, 2026, the Ninth Circuit Bankruptcy Appellate Panel ruled on a fee dispute that followed the bankruptcy sale of a San Francisco assisted-living and memory-care facility. Lender Lenox Mortgage IX LLC had demanded $419,266.94 in attorneys' fees on top of its payoff. The panel agreed with the bankruptcy court that the old HUD-era loan documents did not allow Lenox to recover fees from the earlier defaults and state-court litigation. It reversed as to the fees Lenox incurred in the bankruptcy case itself and the payoff fight, and it vacated the borrower's prevailing-party fee award for reconsideration. The memorandum decision is not for publication and has no precedential value.","significance":"The nonprecedential decision shows that whether a lender can add legal fees to a secured claim under Bankruptcy Code section 506(b) turns on the exact wording of the loan documents. Here, clauses tied to a court's fee award or to foreclosure-sale proceeds did not reach fees from earlier defaults and a state-court suit once the property was sold under section 363. The panel also held that a payoff dispute cannot be an action on the contract for the borrower's section 1717 fee claim but not for the lender's own fees.","tags":["bankruptcy","attorneys fees","senior living","section 506(b)","hud loan"],"parties":[{"name":"Lenox Mortgage IX LLC","role":"Appellant/Lender"},{"name":"San Francisco Care Center, L.P.","role":"Appellee/Debtor"},{"name":"Pacific Commonwealth Mortgage Company","role":"Original Lender"},{"name":"United States Department of Housing and Urban Development","role":"Prior Loan Holder"}],"judge":"Dennis Montali","amountUsd":419266.94,"amountBasis":"claim","hasFull":true},{"id":"live-288","addedDate":"2026-10-13","title":"In re Duplex at Sleepy Hollow, LLC: Ninth Circuit BAP Upholds Retroactive Stay Annulment That Validated Enterprise Bank's Nine Laguna Beach Foreclosures","brief":"The Ninth Circuit BAP upheld retroactive annulment of the automatic stay, validating Enterprise Bank's nine Laguna Beach foreclosure sales after bad-faith involuntary Chapter 11 petitions were filed minutes earlier.","category":"lending-foreclosure","status":"ruling","date":"2026-10-07","jurisdiction":"U.S. Bankruptcy Appellate Panel of the Ninth Circuit (appeal from U.S. Bankruptcy Court, Central District of California)","state":"CA","amount":"Roughly $80 million first-lien debt on ten Laguna Beach properties","source":"live","sourceUrl":"https://cdn.ca9.uscourts.gov/datastore/bap/2026/10/07/25-1256.pdf","summary":"On October 7, 2026, the Ninth Circuit Bankruptcy Appellate Panel affirmed a bankruptcy court order that retroactively annulled the automatic stay. The order validated nine nonjudicial foreclosure sales that Enterprise Bank and Trust held on October 15, 2025 for Laguna Beach properties owned by ten single-asset entities. Involuntary Chapter 11 petitions had been filed against the owners minutes before the sales began. A prospective bidder appealed, arguing all the sales should be re-noticed. The panel found no abuse of discretion, given the bankruptcy court's finding that the filings were made in bad faith. The memorandum decision is not for publication and has no precedential value.","significance":"Although nonprecedential, the decision shows the panel upholding a retroactive annulment that validated foreclosure sales held minutes after involuntary petitions were filed, where the bankruptcy court found bad faith and the lender had no notice and already held stay relief from an earlier bankruptcy. The panel also said a bidder who knew of the filings but neither told the trustee nor bid had weakened his own claim of prejudice.","tags":["bankruptcy","automatic stay","foreclosure","involuntary petition","bad faith filing"],"parties":[{"name":"Enterprise Bank and Trust","role":"Appellee/Lender"},{"name":"Duplex at Sleepy Hollow, LLC","role":"Debtor"},{"name":"777 at Laguna, LLC","role":"Debtor"},{"name":"Cliff Drive Properties DE, LLC","role":"Debtor"},{"name":"Laguna Festival Center, LLC","role":"Debtor"},{"name":"694 NCH Apartments, LLC","role":"Debtor"},{"name":"Retreat at Laguna Villas, LLC","role":"Debtor"},{"name":"891 Laguna Canyon Road, LLC","role":"Debtor"},{"name":"Heisler Laguna, LLC","role":"Debtor"},{"name":"Sunset Cove Villas, LLC","role":"Debtor"},{"name":"Laguna Art District Complex, LLC","role":"Debtor"},{"name":"Vierergruppe Management, Inc.","role":"Petitioning Creditor"},{"name":"Coastline Santa Monica Investments, LLC","role":"Appellee (named in notice of appeal)"},{"name":"Special Assets Laguna, LLC","role":"Proposed Purchaser"}],"judge":"Scott C. Clarkson","amountUsd":null,"hasFull":true},{"id":"live-289","addedDate":"2026-10-13","title":"Braemar Hotels & Resorts Settles With Largest Stockholder Al Shams Investments: $40M Payout Ends Proxy Fight, Securities and Defamation Claims, and Texas Pre-Suit Petition","brief":"Hotel REIT Braemar settled with its largest stockholder, Al Shams, agreeing to pay $25 million plus $15 million in expenses to end a proxy fight, threatened claims and a Texas pre-suit petition; Braemar expects a $4M-$6M net cost.","category":"reit-securities","status":"settled","date":"2026-10-06","jurisdiction":"Out-of-court settlement (resolves a pending Texas Rule 202 pre-suit deposition petition; the filing does not name the court)","state":"TX","amount":"$40 million settlement payment ($25M for claims plus $15M expense reimbursement); Braemar expects its net cost to be $4M-$6M after insurance and Ashford's share","source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/1574085/000110465926114691/tm2627010d1_ex10-1.htm","propertyType":"Hospitality","summary":"On October 6, 2026, luxury hotel REIT Braemar Hotels & Resorts Inc., Ashford Hospitality Trust, Inc. and Ashford Inc. signed a Cooperation and Settlement Agreement with Braemar's largest stockholder, Al Shams Investments Limited. Under the deal Braemar pays $25 million to settle the disputed claims plus $15 million to reimburse Al Shams's expenses, in three installments. In return Al Shams withdraws its slate of director nominees and its Texas Rule 202 petition seeking pre-suit depositions of two former Braemar directors. It also accepts a 10-year standstill, a voting commitment and broad releases. Braemar disclosed the deal in an 8-K filed October 8.","significance":"The settlement resolved threatened securities, defamation and derivative claims and a Texas Rule 202 pre-suit discovery petition before any suit was filed. Its terms tie each installment to the stockholder's continued compliance, with a full clawback after a finding of material breach, and Braemar expects insurance and Ashford's share to bring its own cost to $4 million to $6 million.","tags":["activist investor","hotel reit","settlement","rule 202","proxy contest"],"parties":[{"name":"Braemar Hotels & Resorts Inc.","role":"Settling Party (Company)"},{"name":"Ashford Hospitality Trust, Inc.","role":"Settling Party"},{"name":"Ashford Inc.","role":"Settling Party"},{"name":"Al Shams Investments Limited","role":"Settling Party (Stockholder/Claimant)"}],"judge":null,"amountUsd":40000000,"amountBasis":"settlement","hasFull":true},{"id":"live-290","addedDate":"2026-10-14","title":"Schell Road, LLC v. Vanderford: Michigan Appeals Court Rejects Gravel Mine Mandamus Bid and Upholds Township's Amended Mining Ordinance","brief":"A Michigan appeals court held Schell Road's gravel mine application was incomplete, so no hearing could be compelled, and found Grant Township did not amend its mining ordinance in bad faith.","category":"zoning-land-use","status":"ruling","date":"2026-10-13","jurisdiction":"Michigan Court of Appeals","state":"MI","amount":"Not stated in the opinion","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/13/schell_road_llc_v._steve_vanderford.pdf","propertyType":"Land/Development","summary":"On October 13, 2026, the Michigan Court of Appeals affirmed a Grand Traverse Circuit Court ruling against Schell Road, LLC in its suit over a special land use application to operate a gravel mine on 80 acres it bought in Grant Township in 2022. The unpublished per curiam opinion held that the application was incomplete under the township's pre-amendment zoning ordinance, so the company had no clear legal right to the public hearing it sought through mandamus. The panel also held that the township did not amend its mining ordinance in bad faith while the case was pending and that the amended ordinance is consistent with the state statute on mining, MCL 125.3205.","significance":"The decision shows that a Michigan court can decide on summary disposition whether a special land use application was complete, and that an incomplete application defeats a mandamus claim to force a hearing. It also shows that a township may amend its zoning ordinance while an applicant's suit is pending when the record supports a general reason for the change, here updating mining rules unchanged since 1998 after a 2011 change in state law.","tags":["zoning","mandamus","gravel mine","special land use","michigan"],"parties":[{"name":"Schell Road, LLC","role":"Plaintiff-Appellant"},{"name":"Grant Township","role":"Defendant-Appellee"},{"name":"Grant Township Planning Commission","role":"Defendant-Appellee"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-291","addedDate":"2026-10-14","title":"C&B Development, LLC v. Maxatawny Township Zoning Hearing Board: Commonwealth Court Holds Warehouse Access Road Subject to 500-Foot Residential Setback","brief":"Pennsylvania's Commonwealth Court upheld rulings that the only access road to C&B Development's planned 709,000-square-foot Maxatawny Township warehouse is subject to a 500-foot residential setback, and that no variance was warranted.","category":"zoning-land-use","status":"ruling","date":"2026-10-14","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"Dimensional variance and zoning interpretation (no dollar figure)","source":"live","sourceUrl":"https://www.pacourts.us/assets/opinions/Commonwealth/out/982CD25_10-14-26.pdf","propertyType":"Industrial","summary":"On October 14, 2026, the Commonwealth Court of Pennsylvania affirmed a Berks County trial court ruling against C&B Development, LLC. The developer wants to build a 709,000-square-foot warehouse and a commercial building on a 75.5-acre tract in Maxatawny Township, near Kutztown University. The Maxatawny Township Zoning Hearing Board ruled that the private road the warehouse needs is a related impervious surface, so the ordinance's 500-foot setback from homes applies to it. The board also refused a dimensional variance, and the appellate panel upheld both rulings.","significance":"The court read a warehouse setback that covers \"all related impervious surfaces\" to include the private access road a warehouse needs, not just the building. It also held that a dimensional variance requires hardship arising from the property, so an owner whose district allows other uses cannot claim hardship from being unable to build its preferred one.","tags":["warehouse","setback","variance","pennsylvania","conditional use"],"parties":[{"name":"C&B Development, LLC","role":"Appellant"},{"name":"Maxatawny Township Zoning Hearing Board","role":"Appellee"},{"name":"Maxatawny Township Board of Supervisors","role":"Appellee"},{"name":"State System of Higher Education","role":"Appellee"},{"name":"Kutztown University","role":"Appellee"}],"judge":"Patricia A. McCullough","amountUsd":null,"hasFull":true},{"id":"live-292","addedDate":"2026-10-14","title":"865 East 49th Street Associates LLC v. Valdo Auto Sales Corp.: Florida Appeals Court Affirms Zero Damages on Landlord's Fraud and Unjust Enrichment Claims","brief":"A Florida appeals court affirmed a landlord's $76,199.37 rent judgment against Valdo Auto Sales but zero damages on its fraud and unjust enrichment claims, which showed no separate loss.","category":"lease-disputes","status":"ruling","date":"2026-10-07","jurisdiction":"Florida Third District Court of Appeal","state":"FL","amount":"$76,199.37 past-due rent judgment; $0 on fraud and unjust enrichment","source":"live","sourceUrl":"https://flcourts-media.flcourts.gov/content/download/2496352/opinion/Opinion_2025-2523.pdf","summary":"On October 7, 2026, Florida's Third District Court of Appeal affirmed a Miami-Dade circuit court ruling in a commercial landlord's suit against its tenant, Valdo Auto Sales Corp. The landlord, 865 East 49th Street Associates LLC, had won liability on all of its claims, including fraud and unjust enrichment. But the trial court awarded only $76,199.37 in past-due rent for breach of the commercial lease and nothing on the other claims. The appeals court held that the landlord never showed any damages on the fraud and unjust enrichment claims that were separate from the rent award, so a zero award on those claims stands.","significance":"The decision applies Florida's rule against double recovery: a landlord that wins liability on fraud and unjust enrichment counts alongside a lease claim still needs proof of damages separate from the contract award. It also shows the cost of an incomplete record, since without hearing transcripts the court would not assume the agreed liability judgment preserved any damages claim.","tags":["commercial lease","fraud","unjust enrichment","damages","florida"],"parties":[{"name":"865 East 49th Street Associates LLC","role":"Appellant/Landlord"},{"name":"Valdo Auto Sales Corp.","role":"Appellee/Tenant"}],"judge":"Valerie R. Manno Schurr","amountUsd":76199.37,"amountBasis":"judgment","hasFull":true},{"id":"live-293","addedDate":"2026-10-14","title":"Dunnavant Valley Dining LLC v. PRG Valley Post: $7.19 Million Default Judgment for Unpaid Rent at Chelsea, Alabama's Valley Post Dining Development","brief":"A Shelby County judge entered a $7.19 million default judgment for the Valley Post landlord against a Pihakis Restaurant Group affiliate that leased all four restaurant buildings, covering unpaid rent and fees.","category":"lease-disputes","status":"ruling","date":"2026-10-07","jurisdiction":"Alabama Circuit Court, Shelby County","state":"AL","amount":"$7.19 million default judgment (unpaid rent, attorney fees and costs)","source":"live","sourceUrl":"https://www.al.com/news/2026/10/developer-awarded-72-million-in-unpaid-rent-from-pihakis-restaurant-collapse.html","propertyType":"Retail","summary":"A Shelby County Circuit Court judge has entered a $7.19 million default judgment for Dunnavant Valley Dining LLC, the landlord of Valley Post, against PRG Valley Post, the Pihakis Restaurant Group affiliate that leased all four restaurant buildings at the dining development off Dunnavant Valley Road in Chelsea, Alabama. AL.com reported the judgment on October 7, 2026. It covers unpaid rent plus attorney fees and court costs.","significance":"The judgment is a large court result from the Pihakis Restaurant Group closures, which began in April 2026. It shows the exposure a developer takes on when one restaurant operator leases an entire dining project. Collection is the open question, since the tenant is a project-level affiliate.","tags":["restaurant lease","default judgment","unpaid rent","alabama","tenant collapse"],"parties":[{"name":"Dunnavant Valley Dining LLC","role":"Plaintiff / Landlord"},{"name":"PRG Valley Post","role":"Defendant / Tenant"}],"judge":null,"amountUsd":7190000,"amountBasis":"judgment","hasFull":true},{"id":"live-294","addedDate":"2026-10-14","title":"CRG Acquisition, LLC v. Planning Board of Holliston: Massachusetts Appeals Court Rules 800,000-Square-Foot Warehouse Is Not a Permitted-as-of-Right Use","brief":"The Massachusetts Appeals Court reversed a Land Court win for CRG Acquisition, holding its approximately 800,000-square-foot Holliston warehouse needs a special permit the planning board denied in 2021.","category":"zoning-land-use","status":"ruling","date":"2026-10-14","jurisdiction":"Massachusetts Appeals Court","state":"MA","amount":"Approximately 800,000-square-foot warehouse project (no dollar figure stated)","source":"live","sourceUrl":"https://www.mass.gov/doc/crg-acquisition-llc-v-planning-board-of-appeals-of-holliston-ac-w25p915/download","propertyType":"Industrial","summary":"On October 14, 2026, the Massachusetts Appeals Court reversed a Land Court judgment declaring that CRG Acquisition, LLC's proposed 800,000-square-foot warehouse and distribution facility in Holliston was allowed as of right. The panel gave no deference to the town's reading of its bylaw but agreed with it on the merits: the as-of-right category for a 'wholesale office or showroom, including warehouse facilities' covers warehouse space that is part of an office or showroom, not a standalone warehouse. A standalone warehouse is a general industrial use that needs a special permit, which the planning board had denied in 2021.","significance":"The panel read the phrase 'including warehouse facilities' as describing an accessory part of a wholesale office or showroom, not a separate standalone use, so the defined term 'warehouse' elsewhere in the bylaw did not make large distribution buildings as-of-right. It also held that a planning board that never decided whether a special permit was required gets no deference on that question in a declaratory-judgment case.","tags":["warehouse","zoning","special permit","massachusetts","industrial"],"parties":[{"name":"CRG Acquisition, LLC","role":"Plaintiff-Appellee"},{"name":"New Hopping Brook Realty Trust (through its trustee)","role":"Plaintiff-Appellee (landowner)"},{"name":"Planning Board of Holliston","role":"Defendant-Appellant"},{"name":"Town of Holliston","role":"Defendant-Appellant"}],"judge":"Robert E. Toone, Jr.","amountUsd":null,"hasFull":true},{"id":"live-295","addedDate":"2026-10-14","title":"GSD Contracting, LLC v. All American Builders & Debris Removal, Inc.: Florida Appeals Court Affirms $71,582.98 Retainage After Mold Dispute on Hotel Project","brief":"A Florida appeals court held GSD Contracting wrongly withheld a $71,582.98 retainage from a hotel subcontractor it terminated after a mold dispute, but reversed a $45,300 award for unperformed work.","category":"construction-defect","status":"ruling","date":"2026-10-14","jurisdiction":"District Court of Appeal of Florida, Fourth District","state":"FL","amount":"$71,582.98 retainage affirmed; $45,300 unperformed-work award reversed","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/14/gsd_contracting_llc_v._all_american_builders__debris_removal_inc..pdf","propertyType":"Hospitality","summary":"On October 14, 2026, Florida's Fourth District Court of Appeal affirmed a Broward County judgment that GSD Contracting, LLC breached its subcontract with All American Builders & Debris Removal, Inc. by not paying a $71,582.98 retainage on a five-story hotel project. The court reversed $45,300 the trial court had also awarded for work All American never performed, because All American had not sought that amount and the subcontract barred recovery for unperformed work. It remanded for entry of a judgment consistent with the opinion.","significance":"The decision shows a Florida court enforcing a subcontract's retainage clause as written: once the holdback period after final completion ran, the retainage was payable, and without a termination-for-cause clause or similar provision the contractor had no contractual basis to keep it over an alleged default. It also shows a trial court cannot award damages the plaintiff did not seek and the contract bars.","tags":["construction","subcontractor","retainage","mold","hotel"],"parties":[{"name":"GSD Contracting, LLC","role":"Appellant"},{"name":"All American Builders & Debris Removal, Inc.","role":"Appellee"}],"judge":"Spencer D. Levine","amountUsd":71582.98,"amountBasis":"judgment","hasFull":true},{"id":"live-297","addedDate":"2026-10-15","title":"CFS Enterprises, Inc. v. CG & J Realty, LLC (Queens Mechanic's Lien Bond Dispute)","brief":"New York's Second Department upheld denial of CG & J Realty's motion to vacate a lien bond on its Queens property, holding a NYSCEF filing did not satisfy Lien Law §59's service requirement.","category":"construction-defect","status":"ruling","date":"2026-10-14","jurisdiction":"Supreme Court of the State of New York, Appellate Division, Second Judicial Department","state":"NY","amount":"Lien amount not stated in the decision; dispute over a Lien Law §19 bond posted to discharge a mechanic's lien on Queens property","source":"live","sourceUrl":"http://www.nycourts.gov/reporter/current/3dseries/2026/2026_05929.shtml","summary":"On October 14, 2026, the Appellate Division, Second Department, affirmed a Queens County order denying CG & J Realty, LLC's motion to vacate a Lien Law §19 bond and dismiss CFS Enterprises, Inc.'s cause of action to foreclose a mechanic's lien on CG & J Realty's Queens property. The court held that CG & J Realty only filed its order to show cause on NYSCEF and did not serve it on the lienor personally or at its last known place of residence, as Lien Law §59 requires. It also denied CFS Enterprises' request for appellate attorneys' fees, finding CFS had not shown the appeal was frivolous.","significance":"The decision applies the rule that mechanic's liens exist only by statute, so New York courts require strict compliance with Lien Law procedure and have no discretion to excuse a shortfall. A party seeking to vacate a lien or discharge bond under Lien Law §59 cannot rely on electronic filing alone to give the lienor notice.","tags":["mechanics-lien","lien-law","construction-payment","new-york","queens"],"parties":[{"name":"CFS Enterprises, Inc.","role":"Plaintiff-Respondent"},{"name":"CG & J Realty, LLC","role":"Defendant-Appellant"},{"name":"Century Construction Group Corp.","role":"Filed Lien Law §37 bond"}],"judge":"Francesca E. Connolly (presiding justice of the panel)","amountUsd":null,"hasFull":true},{"id":"live-298","addedDate":"2026-10-15","title":"Zecorra Enterprises, LLC v. Redford Township (Commercial Property Tax Valuation Appeal)","brief":"A Michigan appeals court affirmed a $525,000 true cash value for a Redford Township former bowling alley being converted for a Dollar General, rejecting the owner's bid for a larger renovation deduction.","category":"zoning-land-use","status":"ruling","date":"2026-10-14","jurisdiction":"Michigan Court of Appeals","state":"MI","amount":"$525,000 true cash value determination affirmed","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11034145/zecorra-enterprises-llc-v-redford-township/","summary":"On October 14, 2026, the Michigan Court of Appeals affirmed the Michigan Tax Tribunal's determination that a Redford Township commercial property, a former bowling alley being converted for a Dollar General store, had a true cash value of $525,000 for the 2023 tax year. The panel rejected owner Zecorra Enterprises, LLC's argument that the tribunal should have deducted its full renovation costs of about $797,783 instead of adopting the township appraiser's $525,000 deduction, and held the tribunal was not required to accept the property's $200,000 sale price as its value.","significance":"The decision shows Michigan courts deferring to the Tax Tribunal's choice between competing appraisal adjustments when the chosen one is supported by the record, and treating a renovation deduction as a market calculation rather than a pass-through of actual construction costs. It also shows that a purchase price is not presumed to be true cash value when the tribunal finds it did not reflect the market.","tags":["property-tax","tax-tribunal","commercial-property","michigan","retail-conversion"],"parties":[{"name":"Zecorra Enterprises, LLC","role":"Petitioner-Appellant"},{"name":"Redford Township","role":"Respondent-Appellee"}],"judge":null,"amountUsd":525000,"amountBasis":"other","propertyType":"Retail","hasFull":true},{"id":"live-299","addedDate":"2026-10-15","title":"Orchard BJK Company, LLC v. Coolbaugh Township Board of Supervisors (Challenge to Wetland Buffer Amendments Dismissed as Unripe)","brief":"Pennsylvania's Commonwealth Court held developers' challenge to Coolbaugh Township's wider wetland buffers was premature because their waiver request for a Lot 2 warehouse was still pending.","category":"zoning-land-use","status":"ruling","date":"2026-10-15","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"Not a monetary claim; developer sought a declaratory judgment voiding stormwater buffer ordinance amendments as unconstitutional and invalid special legislation","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/15/orchard_bjk_co._llc__pocono_mountains_industries_inc._v._coolbaugh_twp..pdf","summary":"On October 15, 2026, the Commonwealth Court of Pennsylvania affirmed the dismissal of a suit by Orchard BJK Company, LLC and Pocono Mountains Industries, Inc. challenging Coolbaugh Township's August 2023 stormwater ordinance amendments, which raised minimum wetland buffers from 50 to 150 feet and from 100 to 150 feet. The developers sued while their own petition asking the township's Board of Supervisors to waive the new buffers for a planned warehouse on Lot 2 was still pending before the Board. The court held the claims were not ripe because the Board could still grant the waiver.","significance":"The ruling shows that a Pennsylvania court may treat a challenge to a land-use ordinance as premature while the ordinance's own waiver process remains available and an application under it is pending before the same body. It also shows that a local government's preliminary objections asserting no actual controversy are enough to preserve a ripeness defense.","tags":["zoning","stormwater-ordinance","warehouse-development","ripeness","pennsylvania"],"parties":[{"name":"Orchard BJK Company, LLC","role":"Appellant (Developer/Property Owner)"},{"name":"Pocono Mountains Industries, Inc.","role":"Appellant (Developer/Property Owner)"},{"name":"Coolbaugh Township Board of Supervisors","role":"Appellee"},{"name":"Citizens for Pennsylvania's Future","role":"Appellee"},{"name":"Tobyhanna Creek/Tunkhannock Creek Watershed Association","role":"Appellee"},{"name":"Tobyhanna Conservation Association, Inc.","role":"Appellee"}],"judge":"Lori A. Dumas","amountUsd":null,"propertyType":"Industrial","hasFull":true},{"id":"live-300","addedDate":"2026-10-16","title":"Waterworks Operating Co., LLC v. 514 W. 24th Owner LLC (Liability Affirmed; Mechanic's-Lien Judgment Vacated for New Damages Calculation)","brief":"New York's First Department upheld liability but vacated a $1,396,058.74 mechanic's-lien judgment for supplier Waterworks against a Chelsea project owner, ordering damages recalculated.","category":"construction-defect","status":"ruling","date":"2026-10-15","jurisdiction":"Appellate Division of the Supreme Court of the State of New York, First Department","state":"NY","amount":"$1,396,058.74 judgment vacated and remitted for recalculation of damages","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11035230/waterworks-operating-co-llc-v-514-w-24th-owner-llc/","summary":"On October 15, 2026, New York's Appellate Division, First Department, upheld summary judgment on liability but vacated a $1,396,058.74 judgment that bathroom-fixtures supplier Waterworks Operating Company, LLC won against 514 West 24th Owner LLC over materials delivered for the owner's redevelopment of a Chelsea building. The court held the owner ratified disputed change orders by accepting the materials without objection, but found Waterworks' initial motion proved delivery of only $2,340,098 of the $2,577,166.99 contract, because its proof for the remaining $237,069 came in a reply affidavit. It remitted the case to Supreme Court on damages only.","significance":"The decision shows a New York court finding implied ratification of change orders when an owner accepts the delivered goods without objection, even if its construction manager lacked written authority to approve them. It also shows that proof first offered in reply papers will be disregarded on summary judgment, which here cost the supplier its judgment pending a new damages determination.","tags":["mechanics-lien","construction-payment","change-orders","chelsea","new-york"],"parties":[{"name":"Waterworks Operating Company, LLC","role":"Plaintiff-Respondent (Supplier/Lien Claimant)"},{"name":"514 West 24th Owner LLC","role":"Defendant-Appellant (Owner)"},{"name":"Sunrise Construction, LLC","role":"Project's original construction manager"}],"judge":null,"amountUsd":1396058.74,"amountBasis":"judgment","hasFull":true},{"id":"live-301","addedDate":"2026-10-16","title":"Wrongful-Death Suit Against Mall of Louisiana LLC, Brookfield Properties Retail and Marksman Security (Food Court Shooting)","brief":"The parents of a 17-year-old killed in the April 23, 2026 Mall of Louisiana food court shooting sued the mall owner, operator Brookfield Properties Retail and its security contractor for wrongful death.","category":"premises-liability","status":"filed","date":"2026-10-07","jurisdiction":"19th Judicial District Court, East Baton Rouge Parish, Louisiana","state":"LA","amount":"Unspecified; suit says damages exceed the threshold for a jury trial","source":"live","sourceUrl":"https://www.wafb.com/2026/10/07/parents-teen-killed-mall-louisiana-shooting-sue-mall-security-company/","summary":"The parents of a 17-year-old killed in an April 23, 2026 shooting in the food court of the Mall of Louisiana in Baton Rouge filed a wrongful-death and negligence suit on Oct. 7, 2026 in the 19th Judicial District Court, Acadiana News First reported. The defendants are Mall of Louisiana LLC, Brookfield Properties Retail Inc. and Marksman Security LLC, described as the mall's owner, its operator/manager and its security contractor, along with the person accused of the shooting. Four people who were with the teen, two of whom were shot, joined as plaintiffs.","significance":"The suit relies on the property's history of earlier violent incidents to argue that the shooting was foreseeable and that security was inadequate. It names the security contractor directly, alongside the owner and the operator.","tags":["premises-liability","mall-security","wrongful-death","louisiana","retail"],"parties":[{"name":"Mall of Louisiana LLC","role":"Defendant (Owner)"},{"name":"Brookfield Properties Retail Inc.","role":"Defendant (Operator/Manager)"},{"name":"Marksman Security LLC","role":"Defendant (Security Contractor)"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-302","addedDate":"2026-10-16","title":"Commercial Properties, Inc. v. Montgomery Civic Ballet, Inc. (Commercial Lease Default, Indemnity and Untimely Opposition)","brief":"Alabama's Supreme Court upheld the striking of a ballet school's late response in its landlord's rent and indemnity case, but reversed an order that had dismissed the whole case.","category":"lease-disputes","status":"ruling","date":"2026-10-16","jurisdiction":"Supreme Court of Alabama","state":"AL","amount":"$65,827.50 in unpaid rent sought in the landlord's partial summary-judgment motion, which was granted; damages owed remain to be determined","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11036870/commercial-properties-inc-v-ourania-charalambidou-dionysios-mitsios/","summary":"The Alabama Supreme Court on October 16, 2026, affirmed a Montgomery trial court's orders striking as untimely the response that Montgomery Civic Ballet, Inc. and two individual plaintiffs filed to their landlord's motion for partial summary judgment. That motion, left unopposed, sought $65,827.50 in unpaid rent and a ruling that the Ballet owes Commercial Properties, Inc. defense and indemnity on mold-related injury claims. On the landlord's cross-appeal, the court affirmed the trial court's Rule 54(b) certification of the partial summary judgment but reversed its statement that the whole case was dismissed, because the individual plaintiffs' claims and the landlord's damages are still pending.","significance":"The opinion turns on deadline arithmetic: under Alabama's Rules 56(c)(2) and 6(a), a response due two days before a Monday hearing was due the prior Thursday, so a Friday filing was late, and the tenant never asked for more time under Rule 56(f) or Rule 6(b). It also holds that an order cannot certify a partial judgment as final while declaring dismissed claims that remain pending.","tags":["commercial-lease","summary-judgment","indemnification","alabama","retail"],"parties":[{"name":"Commercial Properties, Inc.","role":"Landlord"},{"name":"Montgomery Civic Ballet, Inc., d/b/a Montgomery Ballet Studios","role":"Tenant"}],"judge":"Will Sellers","amountUsd":65827.5,"amountBasis":"claim","propertyType":"Retail","hasFull":true},{"id":"live-303","addedDate":"2026-10-16","title":"Ex parte City of Fairhope Planning Commission and City of Fairhope (Developer's Negligence Claim Over Denied Apartment Applications Barred by Immunity)","brief":"Alabama's Supreme Court held Fairhope and its planning commission immune from a developer's negligence claim over denied apartment applications; its arbitrary-and-capricious and due-process claims remain pending.","category":"zoning-land-use","status":"ruling","date":"2026-10-16","jurisdiction":"Supreme Court of Alabama","state":"AL","amount":"Unspecified negligence damages claim over denial of two apartment-development applications; no dollar figure stated in the opinion","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11036868/in-re-68v-btr-holdings-llc-v-city-of-fairhope-planning-commission-and/","summary":"On October 16, 2026, the Alabama Supreme Court granted a writ of mandamus directing the Baldwin Circuit Court to enter summary judgment for the City of Fairhope and its Planning Commission on developer 68V BTR Holdings, LLC's negligence claim over the denial of two townhome apartment applications. The main opinion held that the volunteer commissioners and the city staff who advised them were immune, so the city and commission could not be liable for their acts; three justices joined it and five concurred only in the result. 68V's arbitrary-and-capricious and state substantive-due-process claims remain pending in the trial court.","significance":"The decision bars a negligence suit for damages over a planning commission's denial of development applications, while leaving open a mandamus petition to challenge the denial itself. Because only four of the nine justices joined the main opinion's reasoning, and a concurrence questioned extending substantive immunity to planning staff, the breadth of that reasoning may be tested in later cases.","tags":["zoning","land-use","municipal-immunity","alabama","multifamily-development"],"parties":[{"name":"68V BTR Holdings, LLC","role":"Plaintiff-Respondent"},{"name":"City of Fairhope","role":"Defendant-Petitioner"},{"name":"City of Fairhope Planning Commission","role":"Defendant-Petitioner"}],"judge":"Parker","amountUsd":null,"hasFull":true},{"id":"live-304","addedDate":"2026-10-16","featured":true,"title":"Straus Group v. Antheus Capital (Lake Meadows Investor Buyout Dispute)","brief":"Straus Group affiliates sued Antheus Capital, claiming it is blocking a put option to buy out their $30.5 million stake in Chicago's 1,869-unit Lake Meadows complex, Bisnow reported.","category":"reit-securities","status":"filed","date":"2026-10-06","jurisdiction":"Circuit Court of Cook County, Illinois","state":"IL","amount":"$30.5 million original investment; stake now claimed worth ~$70 million","source":"live","sourceUrl":"https://www.chicagobusiness.com/real-estate/commercial/ccb-lake-meadows-lawsuit-20261015/","summary":"Two companies affiliated with The Straus Group, which invested $30.5 million in the entity that owns Chicago's 1,869-unit Lake Meadows apartment complex, sued in Cook County Circuit Court on Oct. 6, 2026, claiming owner Antheus Capital is blocking their exit, Bisnow and Crain's Chicago Business reported. They allege a put option was triggered because emptying the buildings for renovation is no longer part of the business plan; a lawyer for the Antheus affiliate responded that neither trigger had occurred. The plaintiffs seek a court-ordered valuation and damages equal to the fair market value of their stake, which a document filed with the suit puts at $70 million as of June.","significance":"The case turns on how the put option's trigger language applies when the owner keeps renovating with residents in place rather than emptying buildings. The answer decides whether the investors can force a buyout or sale before the agreement's 10-year date.","tags":["multifamily","investor-dispute","put-option","chicago","antheus-capital"],"parties":[{"name":"Straus Group affiliates","role":"Plaintiffs/Investors"},{"name":"Antheus Capital","role":"Defendant/Sponsor"},{"name":"Lake Meadows Holdings LLC","role":"Antheus affiliate; property owner"}],"judge":null,"amountUsd":70000000,"amountBasis":"claim","hasFull":true},{"id":"live-305","addedDate":"2026-10-18","title":"Quinlan Development Group v. Maple 1 Farley Owner LLC (Penn Plaza Life-Sciences Site Foreclosure)","brief":"Quinlan Development Group, which bought the loan from Bank of China, sued to foreclose on a stalled Penn Station-area life-sciences site, alleging a $54M mortgage now totals $65.9M owed, Bisnow reported.","category":"lending-foreclosure","status":"filed","date":"2026-10-13","jurisdiction":"Supreme Court of the State of New York, New York County","state":"NY","amount":"$65.9 million claimed owed (including accrued and default interest) on an original $54 million mortgage","source":"live","sourceUrl":"https://www.bisnow.com/news/new-york/office/foreclosure-cannon-hill-quinlan-development-life-sciences","summary":"Quinlan Development Group sued in New York County Supreme Court on October 13, 2026 to foreclose on the leasehold at 320 West 31st Street, a planned lab and office site near Moynihan Train Hall, alleging owner Maple 1 Farley Owner LLC defaulted on a $54 million mortgage, Bisnow reported, citing PincusCo. The complaint says $65.9 million is now owed with accrued and default interest. Quinlan acquired the loan from Bank of China in September 2026, named developer Cannon Hill Capital Partners as a recourse guarantor, and is seeking a receiver.","significance":"Because Cannon Hill is named as a recourse guarantor, Quinlan has reserved the right to pursue it for any shortfall a foreclosure sale leaves. The filing came less than a month after Quinlan bought the loan.","tags":["foreclosure","life-sciences","office","manhattan","loan-default"],"parties":[{"name":"Quinlan Development Group","role":"Plaintiff/Lender"},{"name":"Maple 1 Farley Owner LLC","role":"Defendant/Borrower-Owner"},{"name":"Cannon Hill Capital Partners","role":"Defendant/Guarantor"}],"judge":null,"amountUsd":65900000,"amountBasis":"loan","hasFull":true},{"id":"live-306","addedDate":"2026-10-18","featured":true,"title":"514 That Way LLC v. Freddie Mac (Edgewater Apartments Post-Foreclosure Rent Dispute)","brief":"A federal magistrate judge called a Nord Group affiliate's rent collection at the foreclosed Edgewater Apartments in Lake Jackson, Texas \"pretty damn egregious\" in its suit against Freddie Mac, Bisnow reported.","category":"lending-foreclosure","status":"pending","date":"2026-05-26","jurisdiction":"U.S. District Court, Southern District of Texas (Galveston Division)","state":"TX","amount":"Freddie Mac alleges the former owner kept more than $200K a month in rent after default; loan balance not reported","source":"live","sourceUrl":"https://www.bisnow.com/news/houston/multifamily/nord-group","summary":"At a May 26, 2026 hearing in the Southern District of Texas, U.S. Magistrate Judge Andrew M. Edison called it \"pretty damn egregious\" that 514 That Way LLC, a Nord Group affiliate, was still collecting rent at the 228-unit Edgewater Apartments in Lake Jackson, Texas after Freddie Mac foreclosed in May, Bisnow reported on October 15, 2026. The LLC had sued Freddie Mac in March, disputing that it had defaulted; Freddie Mac says it stopped paying the mortgage in November 2024 but kept collecting more than $200,000 a month in rent. Edison declined to rule on procedural grounds; Nord's counsel says the company denies all allegations.","significance":"The dispute turns on whether a foreclosing lender must still bring a separate forcible detainer suit under Texas law before taking possession, as the former owner argues. Bisnow reports similar lender claims of rent collection and false insurance records across other Nord properties, which Nord denies.","tags":["multifamily","foreclosure","rent-collection","texas","freddie-mac"],"parties":[{"name":"514 That Way LLC (Nord Group affiliate)","role":"Plaintiff/Former Owner"},{"name":"Federal Home Loan Mortgage Corporation (Freddie Mac)","role":"Defendant/Lender"}],"judge":"Andrew M. Edison","amountUsd":null,"hasFull":true},{"id":"live-307","addedDate":"2026-10-19","title":"Acore Capital Declares Default on GPI Companies' West End Office Campus in West Los Angeles","brief":"Acore Capital recorded a notice of default against GPI Companies on West End, a 235,000-square-foot West Los Angeles office campus that appears to be fully vacant; The Real Deal reported that GPI owes $82.5 million.","category":"lending-foreclosure","status":"filed","date":"2026-10-12","jurisdiction":"Los Angeles County, California (non-judicial trustee's sale)","state":"CA","propertyType":"Office","amount":"$82.5M reported owed on a $97.6M loan made in 2024","amountUsd":82500000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/la/2026/10/12/gpi-defaults-on-loan-faces-foreclosure-of-west-la-office-campus/","summary":"Acore Capital recorded a notice of default and election to sell against GPI Companies in September 2026 over West End, a 235,000-square-foot creative office campus at 10730 West Pico Boulevard in West Los Angeles, The Real Deal reported. The notice claims GPI missed payments on a $97.6 million loan signed in 2024, and the article says GPI owes $82.5 million. The campus, built on the site of a former Macy's at the old Westside Pavilion and completed in 2022, appears never to have been leased.","significance":"A building with no tenants has no income to pay its loan, however new it is. Owners of vacant office space nearing a payment or maturity date should start workout talks early, because in California a recorded notice of default starts the clock toward a trustee's sale.","tags":["office","notice-of-default","foreclosure","los-angeles","creative-office"],"parties":[{"name":"GPI Companies","role":"Borrower"},{"name":"Acore Capital","role":"Lender"}],"judge":null,"hasFull":true},{"id":"live-308","addedDate":"2026-10-19","title":"KU Education Affiliate Defaults on $80M Jefferies LoanCore Loan on Archer Aviation's San Jose Headquarters Campus","brief":"An affiliate of KU Education was served a notice of default on an $80 million Jefferies LoanCore loan on a 287,370-square-foot North San Jose office campus that houses Archer Aviation's headquarters.","category":"lending-foreclosure","status":"filed","date":"2026-10-13","jurisdiction":"Santa Clara County, California (non-judicial trustee's sale)","state":"CA","propertyType":"Office","amount":"$80M loan matured unpaid","amountUsd":80000000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/san-francisco/2026/10/13/north-san-jose-office-campus-falls-into-default/","summary":"An affiliate of real estate investment firm KU Education was served with a notice of default on an $80 million loan from Jefferies LoanCore, made in 2016, on a three-building, 287,370-square-foot office campus at 190, 210 and 230 West Tasman Drive in North San Jose, The Real Deal reported on October 13, 2026, citing the Mercury News. The loan matured in August 2026 and was not paid in full. Air-taxi maker Archer Aviation leases the 190 and 210 buildings and has its headquarters at 190 West Tasman.","significance":"A loan on a building with a growing anchor tenant can still default when it comes due, if the owner cannot refinance or repay it at maturity. Anchor tenants in buildings like this should check how their lease would be treated if the lender takes over the property.","tags":["office","notice-of-default","foreclosure","san-jose","archer-aviation"],"parties":[{"name":"KU Education","role":"Borrower"},{"name":"Jefferies LoanCore","role":"Lender"},{"name":"Archer Aviation","role":"Tenant"}],"judge":null,"hasFull":true},{"id":"live-309","addedDate":"2026-10-19","title":"Deutsche Bank Plans Foreclosure on Former eBay Campus in North San Jose","brief":"Deutsche Bank plans to foreclose on a four-building North San Jose office campus once used by eBay, after its owners defaulted on an $88.1 million loan whose unpaid balance has reportedly grown to $98.4 million.","category":"lending-foreclosure","status":"filed","date":"2026-10-15","jurisdiction":"Santa Clara County, California (non-judicial trustee's sale)","state":"CA","propertyType":"Office","amount":"$88.1M loan; unpaid balance reported at $98.4M","amountUsd":98400000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/san-francisco/2026/10/15/buyers-eye-san-jose-office-campus-in-default/","summary":"Deutsche Bank AG's New York Branch filed an initial notice of default in July 2026 on an $88.1 million loan to Hana Asset Management and Ocean West Capital Partners, owners of a four-building office campus at 2515-2545 North First Street in North San Jose that eBay once occupied. The Real Deal reported on October 15, 2026, citing the Mercury News, that the unpaid balance has grown to $98.4 million and that the bank plans a full foreclosure. The owners paid $132.5 million for the campus in 2018, and Morningstar data put its value at $54.7 million this summer.","significance":"The campus is now valued at well under the debt against it, which leaves the owners little reason to put in new money and the lender little reason to extend. Buyers interested in a property like this should be clear about whether they are buying the loan, buying from the lender after foreclosure, or making a deal with the owners, since each carries different risks.","tags":["office","notice-of-default","foreclosure","san-jose","ebay"],"parties":[{"name":"Ocean West Capital Partners","role":"Borrower/Owner"},{"name":"Hana Asset Management","role":"Borrower/Owner"},{"name":"Deutsche Bank AG, New York Branch","role":"Lender"}],"judge":null,"hasFull":true},{"id":"live-310","addedDate":"2026-10-19","title":"Abu Ali Cafe, LLC v. 2020 Harwin 59 Shopping Centers, Ltd. (Restaurant Lease Repair and Sublease Dispute)","brief":"A Houston appeals court affirmed summary judgment for a shopping-center landlord on a restaurant's repair, sublease, fraud and DTPA claims, along with $23,580 in trial and $15,000 in appellate fees.","category":"lease-disputes","status":"ruling","date":"2026-10-16","jurisdiction":"Court of Appeals of Texas, First District (Houston)","state":"TX","propertyType":"Retail","amount":"$23,580 trial attorney's fees plus $15,000 appellate fees awarded to landlord","amountUsd":38580,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11038073/mahmoud-salha-and-ali-cafe-v-2020-harwin-59-shopping-centers-ltd-harwin/","summary":"On October 16, 2026, Texas's First Court of Appeals in Houston affirmed summary judgment for 2020 Harwin 59 Shopping Centers, Ltd., Harwin Exchange Center, Inc. and Harwin Exchange's president on claims by a restaurant operator and its owner over repairs and a refused sublease. The court held the lease assigned electrical, plumbing and HVAC upkeep to the tenant, that there was no evidence of the written notice the lease required for roof repairs, and that an oral promise to consent to a sublease was barred by the statute of frauds. It also held the DTPA did not apply because base rent of $8,700 a month for 60 months totaled $522,000, above the statute's $500,000 cutoff, and upheld fee awards of $23,580 for the trial court and $15,000 for appeal.","significance":"The opinion applies the lease's maintenance split and written-notice requirement as written, leaving the tenant without a breach claim for systems the lease assigned to it. It also shows a commercial lease's total base rent can take a tenant outside the DTPA once it passes $500,000.","tags":["lease-dispute","retail","dtpa","sublease","texas"],"parties":[{"name":"Abu Ali Cafe, LLC","role":"Restaurant/Appellant"},{"name":"2020 Harwin 59 Shopping Centers, Ltd.","role":"Landlord by assignment/Appellee"},{"name":"Harwin Exchange Center, Inc.","role":"Original landlord/Appellee"}],"judge":"Clint Morgan","hasFull":true},{"id":"live-311","addedDate":"2026-10-19","title":"62 Wooster, LLC v. TML N.Y. Inc. (Good Guy Guaranty Surrender Dispute)","brief":"New York's First Department held the guarantors of a SoHo retail lease were released when the tenant surrendered on Sept. 30, 2020, construing conflicting guaranty clauses against the landlord that drafted them.","category":"lease-disputes","status":"ruling","date":"2026-10-01","jurisdiction":"Appellate Division, First Department, New York","state":"NY","propertyType":"Retail","amount":"Landlord sought approximately $307,577.08 in unpaid rent plus liquidated damages and enforcement costs","amountUsd":307577,"amountBasis":"claim","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_05591.shtml","summary":"On October 1, 2026, the Appellate Division, First Department unanimously affirmed dismissal of a SoHo landlord's claims against the individual guarantors of a retail lease at 476 Broome Street, including $307,577.08 in rent for July through October 2021. The court found the guaranties ambiguous because a surrender clause ending liability once the tenant vacated conflicted with a good guy clause tying liability to a defined 'Surrender Date.' Because the landlord's counsel drafted the documents, the court construed the conflict against the landlord and held the guarantors' liability ended on September 30, 2020, when the tenant returned the keys and vacated.","significance":"When a guaranty's own clauses conflict, the First Department will treat it as ambiguous and, as a last resort, construe it against the landlord that drafted it. A landlord seeking to keep guarantors liable past move-out needs language that does not collide with a surrender-based release.","tags":["guaranty","retail","good-guy-clause","lease-dispute","new-york"],"parties":[{"name":"62 Wooster, LLC","role":"Landlord/Plaintiff-Appellant"},{"name":"TML New York Inc.","role":"Tenant/Defendant"}],"judge":null,"hasFull":true},{"id":"live-312","addedDate":"2026-10-19","title":"Shadowbox Studios, LLC v. DeKalb County, Georgia (Data Center Moratorium Takings Suit)","brief":"Shadowbox Studios sued DeKalb County, Georgia, saying its data center moratorium blocks a project on a nearly 200-acre site that planning staff said was allowed and cut the land's value by $200 million.","category":"zoning-land-use","status":"filed","date":"2026-08-05","jurisdiction":"Superior Court of DeKalb County, Georgia","state":"GA","propertyType":"Land/Development","amount":"Lawsuit cites more than $30 million spent on the project and alleges the moratorium cut the property's value by $200 million","amountUsd":30000000,"amountBasis":"claim","source":"live","sourceUrl":"https://www.wabe.org/dekalb-county-sued-over-moratorium-on-new-data-centers/","summary":"Shadowbox Studios and affiliated real estate company Henrico 183 sued DeKalb County, Georgia in DeKalb County Superior Court on Aug. 5, 2026, asking a judge to declare the county's data center moratorium invalid and let them build a data center on a nearly 200-acre site at 3600 International Park Drive, Decaturish reported. The suit says the companies spent more than $30 million on the project after county planning officials told them a data center would be allowed, and that the moratorium has cut the property's value by $200 million. It also seeks \"just compensation\" and attorneys' fees; the county has said the planning letters were not legally binding.","significance":"The case tests whether written assurances from planning staff that a use is allowed can support claims for relief once a moratorium blocks the project. It also puts at issue the procedure the county used to adopt and extend its data center moratorium.","tags":["zoning","data-center","moratorium","takings","georgia"],"parties":[{"name":"Shadowbox Studios, LLC","role":"Plaintiff"},{"name":"Henrico 183","role":"Plaintiff"},{"name":"DeKalb County, Georgia","role":"Defendant"}],"judge":null,"hasFull":true},{"id":"live-313","addedDate":"2026-10-19","title":"State ex rel. Sommers Development Group, L.L.C. v. Cuyahoga County Board of Elections (Zoning Initiative Challenge)","brief":"Ohio's Supreme Court refused to remove a citizen initiative from the Mayfield Heights ballot that would undo a council rezoning for Sommers Development Group's planned townhome community.","category":"zoning-land-use","status":"ruling","date":"2026-10-19","jurisdiction":"Supreme Court of Ohio","state":"OH","propertyType":"Land/Development","amount":"Not a monetary claim; dispute over whether a zoning referendum stays on the ballot, with no dollar figure stated in the opinion","source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/19/state_ex_rel._sommers_dev._group_l.l.c._v._cuyahoga_cty._bd._of_elections.pdf","summary":"On October 19, 2026, the Ohio Supreme Court denied writs of prohibition and mandamus sought by developer Sommers Development Group, L.L.C. to remove a citizen-initiated ordinance from the November 3, 2026 Mayfield Heights ballot. The initiative would return a Rockwell Automation-owned parcel, which the city council rezoned in May 2026 for Sommers' planned townhome community, to its prior office-park zoning. The court rejected a laches defense raised against Sommers but held Sommers failed to show the Cuyahoga County Board of Elections abused its discretion or clearly disregarded the law in placing the initiative on the ballot and denying Sommers' protest.","significance":"The decision shows that in an Ohio charter city, voters may use an initiative to propose reversing a council rezoning after the charter's 30-day referendum window has closed, although the rezoning stays in effect unless voters adopt the initiative. It also shows the court declining to fault a board of elections for following a city charter's initiative timeline rather than the 90-day certification deadline in state law.","tags":["zoning","initiative","entitlement","ohio","developer"],"parties":[{"name":"Sommers Development Group, LLC","role":"Relator"},{"name":"Cuyahoga County Board of Elections","role":"Respondent"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-314","addedDate":"2026-10-20","title":"The Waffle, LLC v. Tucker Investment Group, LLC (Westwood Restaurant Lease Arbitration Affirmed)","brief":"A California appeals court affirmed a judgment confirming an arbitration win, including about $2.2 million in fees, for Westwood landlord Tucker Investment Group in a restaurant tenant's grease-interceptor suit.","category":"lease-disputes","status":"ruling","date":"2026-10-19","jurisdiction":"California Court of Appeal, Second Appellate District, Division Seven (Los Angeles County Superior Court No. SC129215)","state":"CA","amount":"About $2.2 million in attorneys' fees and costs awarded to the Tucker defendants in arbitration; judgment confirming the award affirmed","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11038356/the-waffle-v-tucker-investment-group-ca27/","summary":"On October 19, 2026, California's Second Appellate District affirmed a judgment confirming an arbitration award for landlord Tucker Investment Group, LLC (TIG) and its managing member in a lease dispute with restaurant tenant The Waffle, LLC over a 3,000-gallon grease interceptor TIG agreed to install at a Westwood property. The Waffle alleged it was fraudulently induced to sign the lease. After a bench trial went to TIG on the contract claim and a jury deadlocked on most misrepresentation claims, the parties stipulated to binding arbitration, and the arbitrator ruled for the Tucker defendants and awarded them about $2.2 million in fees and costs. The unpublished opinion rejected The Waffle's arguments that the arbitrator exceeded his powers, failed to issue a reasoned award and improperly awarded fees tied to settled co-defendants.","significance":"The opinion shows how little room a court has to revisit an award the parties agreed would be binding: the fee challenge was treated as a claim of legal error, which is not reviewable. It also sets out what a 'reasoned award' requires under the ADR Services rules, which the court said no California decision had defined: the arbitrator's basic reasoning on the central issues, not a response to every argument.","judge":"Feuer","parties":[{"name":"The Waffle, LLC","role":"Restaurant tenant/Plaintiff-Appellant"},{"name":"Tucker Investment Group, LLC","role":"Landlord (master lessee)/Defendant-Respondent"},{"name":"Coastline Construction Management, Inc.","role":"Defendant (settled in 2024)"}],"amountUsd":2200000,"propertyType":"Retail","tags":["lease-dispute","arbitration","california","restaurant","construction-work-letter"],"amountBasis":"award","hasFull":true},{"id":"live-315","addedDate":"2026-10-20","title":"Elizon DB Transfer Agent LLC v. Hungerford Building Owner (Rochester Mixed-Use Foreclosure Appeal)","brief":"The Hungerford Building's foreclosure auction, set for Oct. 29, 2026, is on hold after the owner appealed a judgment based on a referee's report finding $10,490,036.37 owed to lender Elizon DB.","category":"lending-foreclosure","status":"appeal","date":"2026-10-15","jurisdiction":"New York Supreme Court, Monroe County (notice of appeal filed to the Appellate Division, Fourth Department)","state":"NY","propertyType":"Mixed-Use","amount":"$10,490,036.37 owed per the court-confirmed referee's report","amountUsd":10490036,"amountBasis":"judgment","source":"live","sourceUrl":"https://rbj.net/2026/10/15/appeal-filed-hungerford-building-foreclosure-rochester/","summary":"The scheduled auction of Rochester's Hungerford Building is on hold after the attorney for the building's owner and affiliated LLCs appealed the foreclosure judgment, the Rochester Business Journal reported on October 15, 2026. The appeal argues Monroe County Supreme Court Justice Daniel J. Doyle erred in granting summary judgment because he relied on a flawed referee's report, which found $10,490,036.37 owed to mortgage holder Elizon DB Transfer Agent. Doyle approved the report and granted the foreclosure judgment on September 2, 2026, after rejecting the defendants' earlier challenge to the calculations.","significance":"The appeal has put the sale on hold even though the trial court had already rejected the same challenge to the referee's figures. The owner has also said he intends to pay off the debt with a construction loan, which would end the foreclosure without an auction.","tags":["foreclosure","appeal","mixed-use","new york","referee-report"],"parties":[{"name":"Elizon DB Transfer Agent LLC","role":"Plaintiff/Lender"},{"name":"The Hungerford Building LLC","role":"Defendant/Borrower"}],"judge":"Daniel J. Doyle","hasFull":true},{"id":"live-316","addedDate":"2026-10-20","title":"State ex rel. Bristolville 25 Developer, L.L.C. v. Village of Lordstown (Ohio Supreme Court Denies Data-Center Site-Plan Mandamus)","brief":"Ohio's Supreme Court denied Bristolville 25 Developer's bid to force Lordstown to review its site plan for a reported $3.6 billion data center, holding the village's moratorium leaves it no clear duty to act.","category":"zoning-land-use","status":"ruling","date":"2026-10-20","jurisdiction":"Supreme Court of Ohio","state":"OH","propertyType":"Data Center","amount":"$3.6 billion proposed data-center campus, as reported by The Vindicator and The Business Journal; no damages at issue in this mandamus action","amountUsd":3600000000,"amountBasis":"other","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11039801/state-ex-rel-bristolville-25-developer-llc-v-lordstown/","summary":"The Ohio Supreme Court on October 20, 2026 unanimously denied a writ of mandamus sought by Bristolville 25 Developer, L.L.C. and landowner BHGH Properties, L.L.C. to make the Village of Lordstown review Bristolville's data-center site plan under the zoning rules in effect on October 20, 2025. The court held that while the village's moratorium on data-center permits and applications is in effect, the village has no clear legal duty to proceed, and that Bristolville had no vested right to the earlier rules because it had not completed site-plan review or applied for a permit. The village had passed an outright ban days after Bristolville's submission, repealed it before it took effect, and replaced it with a 180-day moratorium that it later extended through 2026.","significance":"The decision holds that Ohio's vested-rights rule from Gibson v. Oberlin protects a developer only once it has met all the legislative requirements for a permit, and a site-plan submission is not enough. While a duly enacted moratorium is in place, mandamus will not force a village to keep reviewing a project, and the court said the remedy for the developer's policy concerns lies with the legislature.","judge":"Per curiam (unanimous)","parties":[{"name":"Bristolville 25 Developer, L.L.C.","role":"Relator"},{"name":"BHGH Properties, L.L.C.","role":"Relator"},{"name":"Village of Lordstown","role":"Respondent"}],"tags":["zoning","data-center","moratorium","ohio","mandamus"],"hasFull":true},{"id":"live-317","addedDate":"2026-10-21","title":"513 West 26th Realty LLC v. George Billis Galleries, Inc. (Guaranty Law Contracts Clause Ruling)","brief":"New York's First Department, 4-1, upheld the city's pandemic-era guaranty law against a Contracts Clause challenge and dismissed a landlord's claims against the individual guarantor of a gallery's lease.","category":"lease-disputes","status":"ruling","date":"2026-10-20","jurisdiction":"Appellate Division, First Department, New York","state":"NY","propertyType":null,"amount":"No dollar figure stated in the opinion","amountUsd":null,"source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11040695/513-w-26th-realty-llc-v-george-billis-galleries-inc/","summary":"New York's Appellate Division, First Department held on October 20, 2026, in a 4-1 decision, that New York City's pandemic-era guaranty law (Administrative Code § 22-1005), which barred enforcement of certain personal guaranties of commercial leases for defaults between March 7, 2020 and June 30, 2021, does not violate the Contracts Clause of the U.S. Constitution. The court reversed a Supreme Court, New York County order that had declared the law unconstitutional and reinstated landlord 513 West 26th Realty LLC's claims against the individual guarantor of tenant George Billis Galleries, Inc., and it granted the guarantor's and the City's motions to dismiss. Justice David Friedman dissented.","significance":"The ruling gives New York's trial courts a state appellate holding that the guaranty law is constitutional, after a federal district court ruling the other way was vacated on standing grounds in Bochner v. City of New York. The majority stressed that the law left the debt enforceable against the tenant itself, and the dissent shows the question divided the panel.","tags":["guaranty-law","contracts-clause","commercial-lease","covid-19","new-york"],"parties":[{"name":"513 West 26th Realty LLC","role":"Landlord/Plaintiff-Respondent"},{"name":"George Billis Galleries, Inc.","role":"Tenant/Defendant-Appellant"},{"name":"City of New York","role":"Intervenor-Defendant-Appellant"}],"judge":"Llinét M. Rosado","hasFull":true},{"id":"live-318","addedDate":"2026-10-21","title":"Grandview Heights Neighborhood Association v. Palm Beach County (Sunshine Law Challenge to $26M Convention Center Hotel Deal)","brief":"Two West Palm Beach neighborhood groups sued to void Palm Beach County's approval of a $26 million advance for a 400-room convention center hotel, saying the 715-page deal file came out 90 minutes before the meeting.","category":"zoning-land-use","status":"filed","date":"2026-10-14","jurisdiction":"Circuit Court of the 15th Judicial Circuit, Palm Beach County, Florida","state":"FL","propertyType":"Hospitality","amount":"$26 million sale-leaseback financing commitment challenged as void","amountUsd":26000000,"amountBasis":"other","source":"live","sourceUrl":"https://www.wptv.com/news/local-news/our-community/west-palm-beach/residents-file-lawsuit-in-palm-beach-county-over-26-million-convention-center-hotel-deal","summary":"Two West Palm Beach neighborhood groups sued Palm Beach County, Related Ross affiliates, The Related Companies, the CityPlace Community Development District, the City of West Palm Beach and its Community Redevelopment Agency on October 14, 2026, WPTV reported. They seek to void the county commission's September 29 approval of a 34-part deal under which the county would advance $26 million toward a 400-room convention center hotel, buy the finished hotel and lease it back to Related Ross. The suit alleges a Sunshine Law violation because the 715-page transaction file was released 90 minutes before the meeting.","significance":"The case tests whether Florida's open-meetings law demands more than the minimum statutory notice when a government votes on a large, complex transaction. If the court grants the relief sought, the county could not execute or fund the hotel deal until the commission reconsiders it at a properly noticed meeting.","judge":null,"parties":[{"name":"Grandview Heights Neighborhood Association","role":"Plaintiff"},{"name":"West Palm Beach Neighborhood Alliance","role":"Plaintiff"},{"name":"Palm Beach County","role":"Defendant"},{"name":"Related Ross affiliates","role":"Defendant"},{"name":"The Related Companies, L.P.","role":"Defendant"},{"name":"CityPlace Community Development District","role":"Defendant"},{"name":"City of West Palm Beach","role":"Defendant"},{"name":"West Palm Beach Community Redevelopment Agency","role":"Defendant"}],"tags":["sunshine-law","hotel","public-private-partnership","zoning","florida"],"hasFull":true},{"id":"live-319","addedDate":"2026-10-22","title":"VK Dental Group, Inc. v. Tender Touch Physical Therapy, PLLC (NY Appellate Division Revives $1M Sublease Rent Dispute)","brief":"New York's Second Department reversed a $1,004,426.20 sublease rent judgment for VK Dental Group, finding the sublessees' claim that VK breached on utilities and gas service raised a triable issue.","category":"lease-disputes","status":"ruling","date":"2026-10-21","jurisdiction":"Appellate Division, Second Department, New York","state":"NY","propertyType":null,"amount":"$1,004,426.20 judgment reversed","amountUsd":1004426.2,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11042103/vk-dental-group-inc-v-tender-touch-physical-therapy-pllc/","summary":"New York's Appellate Division, Second Department on October 21, 2026 reversed a $1,004,426.20 judgment that sublessor VK Dental Group, Inc. had won against Tender Touch Physical Therapy, PLLC and the other sublessees for unpaid rent. The court held that VK Dental showed the rent went unpaid, but the sublessees raised a triable issue of fact with their principal's affidavit stating that VK Dental failed to pay 50% of utilities as the subleases required and had the gas service disconnected. It denied VK Dental's motion for summary judgment.","significance":"A breach-of-contract plaintiff in New York must prove its own performance, and here a sworn statement that the sublessor failed its own sublease obligations was enough to defeat summary judgment on a seven-figure rent claim. The court did not decide whether the sublessor actually breached; it held only that the factual dispute precluded summary judgment.","tags":["commercial-lease","sublease","summary-judgment","new-york","medical-office"],"parties":[{"name":"VK Dental Group, Inc.","role":"Sublessor/Plaintiff-Respondent"},{"name":"Tender Touch Physical Therapy, PLLC","role":"Sublessee/Defendant-Appellant"}],"judge":"Dillon, J.P., Wooten, Love and Goldberg Velazquez, JJ. (decision and order)","hasFull":true},{"id":"live-320","addedDate":"2026-10-22","title":"Trucks Rx, Inc. v. Padilla Investments, LLC (Michigan Appeals Court Affirms $411K Lease Arbitration Award)","brief":"A Michigan appeals court affirmed a $411,131.50 judgment on an arbitration award for landlord Padilla Investments after tire-shop tenants left a Detroit building over a sprinkler requirement.","category":"landlord-tenant","status":"ruling","date":"2026-10-21","jurisdiction":"Michigan Court of Appeals","state":"MI","propertyType":"Retail","amount":"$411,131.50 arbitration award affirmed","amountUsd":411131.5,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11042130/trucks-rx-inc-v-padilla-investments-llc/","summary":"The Michigan Court of Appeals on October 21, 2026 affirmed a $411,131.50 judgment confirming an arbitration award for landlord Padilla Investments, LLC against tenants Trucks Rx, Inc. and Jana Trucking Line, Inc. and the two owners who personally guaranteed their lease. The tenants stopped paying rent and left a Detroit building, formerly a hardware store, after city correction orders; the chief problem was that the building lacked an automatic sprinkler system needed to store tires. The arbitrator found the as-is lease made the tenants responsible for complying with the law to run their business, and the unpublished per curiam opinion held he neither exceeded his authority nor made an error of law.","significance":"Michigan courts reviewing an arbitration award look only for an error of law evident on the face of the award, and the panel found none in the arbitrator's reading of an as-is lease with a tenant compliance clause. The opinion also rejected impossibility and mutual-mistake defenses, relying on Lenawee County Board of Health v. Messerly, where an as-is clause put the risk of a property's condition on the buyer.","tags":["commercial-lease","landlord-tenant","arbitration","michigan","retail"],"parties":[{"name":"Trucks Rx, Inc.","role":"Tenant/Plaintiff-Appellant"},{"name":"Jana Trucking Line, Inc.","role":"Tenant/Plaintiff"},{"name":"Padilla Investments, LLC","role":"Landlord/Defendant-Appellee"}],"judge":"Per curiam (Patel, P.J., M. J. Kelly and Garrett, JJ.)","hasFull":true},{"id":"live-321","addedDate":"2026-10-22","title":"Alecko Lending v. Conlon (Judgment Over Chicago's Former Rainforest Cafe Building)","brief":"A Cook County judge ordered investor Sean Conlon to pay Alecko Lending $11,508,950 plus legal fees over an $8.3 million bridge loan on the former Rainforest Cafe site at 605 N. Clark St.","category":"lending-foreclosure","status":"ruling","date":"2026-10-20","jurisdiction":"Circuit Court of Cook County, Illinois","state":"IL","propertyType":"Retail","amount":"$11,508,950 judgment plus legal fees on an $8.3 million bridge loan","amountUsd":11508950,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.chicagobusiness.com/real-estate/commercial/ccb-rainforest-cafe-lawsuit-judgment-20261020/","summary":"Cook County Circuit Judge Jerry Esrig ruled for Alecko Lending on October 20, 2026 and ordered Chicago real estate investor Sean Conlon to pay $11,508,950 plus legal fees, the Chicago Sun-Times reported; Crain's Chicago Business put the amount at $10 million in its headline. Alecko's October 2025 breach-of-contract suit alleged Conlon failed to repay an $8.3 million bridge loan on the former Rainforest Cafe property at 605 N. Clark St. in River North. A separate Alecko suit seeking to foreclose on the property is still pending, according to the Sun-Times.","significance":"The ruling is a money judgment against Conlon, separate from Alecko's pending effort to foreclose on the building itself. It also shows how far a lender's claim can grow past a loan's face amount: the complaint sought about $9.2 million including interest and forbearance fees on an $8.3 million loan, and the judgment came to about $11.5 million plus fees.","tags":["foreclosure","bridge-loan","chicago","retail","loan-default"],"parties":[{"name":"Alecko Lending","role":"Plaintiff/Lender"}],"judge":"Jerry A. Esrig","hasFull":true},{"id":"live-322","addedDate":"2026-10-22","title":"Joseph F. Farivar Investment Group, Inc. v. HPC Vineburn, LLC (Groundwater Contamination Judgment Reversed)","brief":"A California appeals court reversed a $12,245,108.42 groundwater contamination judgment against the current and former owners of a Los Angeles industrial property over a 1,4-dioxane plume.","category":"environmental","status":"ruling","date":"2026-10-22","jurisdiction":"California Court of Appeal, Second Appellate District, Division One","state":"CA","propertyType":"Industrial","amount":"$12,245,108.42 judgment (including $273,221.42 in prejudgment interest) reversed on appeal","amountUsd":12245108.42,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11043246/joseph-f-farivar-investment-group-v-hpc-vineburn-ca21/","summary":"California's Second Appellate District on October 22, 2026 reversed a $12,245,108.42 judgment against HPC Vineburn, LLC, the current owner of an industrial property at 1919 Vineburn Avenue in Los Angeles, and former owner Meruelo Maddux Properties-1919 Vineburn Street, LLC. The trial court had granted summary adjudication to neighboring owner Joseph F. Farivar Investment Group, Inc. and its tenant, Bordan Shoe Company, Inc., on negligence, continuing nuisance, continuing trespass and declaratory relief claims over 1,4-dioxane contamination that migrated from the Vineburn property, where a manufacturer operated before 1989. In an unpublished opinion, the court held the plaintiffs did not prove breach of a duty of care as a matter of law, used a damages measure continuing torts do not allow, and should not have obtained partial summary adjudication of declaratory relief.","significance":"The opinion holds that damages for a continuing nuisance or continuing trespass are limited to injury suffered before the suit was filed, so 20-year projections of cleanup costs and lost use could not support summary adjudication of those claims. It also holds that a consultant's report showing contamination migrated from a neighboring site does not by itself establish that the current or former owner breached its duty of care.","tags":["environmental","groundwater-contamination","industrial","california","successor-liability"],"parties":[{"name":"Joseph F. Farivar Investment Group, Inc.","role":"Plaintiff and Respondent (owner, 4335 Valley Boulevard)"},{"name":"Bordan Shoe Company, Inc.","role":"Plaintiff and Respondent (tenant)"},{"name":"HPC Vineburn, LLC","role":"Defendant and Appellant (current owner)"},{"name":"Meruelo Maddux Properties-1919 Vineburn Street, LLC","role":"Defendant and Appellant (former owner)"}],"judge":"Bendix","hasFull":true},{"id":"live-323","addedDate":"2026-10-22","title":"Crocker Park, L.L.C. v. City of Westlake, Ohio (Right of First Refusal Waived for One Sale, Kept for Future Offers)","brief":"On reconsideration, an Ohio appeals court held Crocker Park waived its right of first refusal on Westlake's $2.6 million Market Square sale by adding conditions, but kept the right for future offers.","category":"lease-disputes","status":"ruling","date":"2026-10-22","jurisdiction":"Ohio Court of Appeals, Eighth Appellate District","state":"OH","propertyType":"Mixed-Use","amount":"Right of first refusal over Market Square, which a third-party buyer later purchased for $2.6 million","amountUsd":2600000,"source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11043112/crocker-park-llc-v-westlake/","summary":"On October 22, 2026, Ohio's Eighth District Court of Appeals, on reconsideration, vacated its July 30, 2026 decision and issued a new one in Crocker Park's dispute with the City of Westlake over Market Square, a city-owned parcel inside the Crocker Park development. The court affirmed summary judgment against the city's slander-of-title and abuse-of-process claims. It held that Crocker Park waived its right of first refusal as to the city's sale to E&C Sports Group, L.L.C., because its $2.6 million matching offer added conditions and so was a counteroffer, but that the right continues for future offers. The July decision had held the right waived without that limit.","significance":"Under a price-only right of first refusal, the holder can exercise the right by matching the third party's price, but adding non-price conditions makes the response a counteroffer and the right lapses for that offer. The reconsidered opinion also reads the agreement's wording as a continuing right, so a waiver as to one buyer does not end it for later offers.","tags":["right-of-first-refusal","mixed-use","ccr-declaration","ohio","municipal-co-owner"],"parties":[{"name":"Crocker Park, L.L.C.","role":"Plaintiff-Appellee (Declarant)"},{"name":"CP Commercial Delaware, L.L.C.","role":"Plaintiff-Appellee (filed the lien)"},{"name":"Crocker Park Management, L.L.C.","role":"Third-Party Defendant-Appellee"},{"name":"City of Westlake, Ohio","role":"Defendant-Appellant"}],"judge":"Eileen T. Gallagher","amountBasis":"purchase price","hasFull":true},{"id":"live-324","addedDate":"2026-10-23","title":"Lot 2 SBO, LLC v. Twitter, Inc. n/k/a X Corp.: Colorado Appeals Court Reverses $8.2M Boulder Office Rent Judgment Over Tenant-Improvement Rent Credit","brief":"The Colorado Court of Appeals reversed an $8.2 million rent judgment against X Corp. (formerly Twitter) over its Boulder office lease, holding the tenant-improvement rent credit applied automatically.","category":"lease-disputes","status":"ruling","date":"2026-10-22","jurisdiction":"Colorado Court of Appeals (appeal from Boulder County District Court)","state":"CO","amount":"$8.2 million judgment reversed","source":"live","sourceUrl":"https://www.courthousenews.com/colorado-appeals-court-voids-landlord-win-in-lease-dispute-with-twitter/","propertyType":"Office","summary":"On October 22, 2026, a unanimous Colorado Court of Appeals panel reversed the Boulder County judgment that had held Twitter, now X Corp., liable to landlord Lot 2 SBO, LLC for about $8.2 million in unpaid rent and expenses on a 64,557-square-foot office building in Boulder. The panel held that the lease's tenant-improvement rent credit took effect automatically once the build-out reached the lease threshold and the tenant gave written notice, whether or not the landlord had yet received lien-clearing draw documents. It did not enter judgment for X. It sent the case back to the trial court with directions.","significance":"The ruling shows how a lease's tenant-improvement allowance mechanics can decide whether a tenant who holds back rent is in default or is simply using a credit it earned. Landlords who make TI credits depend on lien waivers or draw packages need to say clearly that the paperwork is a condition of the credit, not only of the cash payout. Tenants get a reminder that applying a disputed credit against rent can lead to eviction and an eight-figure trial judgment before an appeals court sides with them.","tags":["office lease","tenant improvement allowance","rent credit","appeal","boulder"],"parties":[{"name":"Lot 2 SBO, LLC","role":"Plaintiff-Appellee / Landlord"},{"name":"Twitter, Inc., n/k/a X Corp.","role":"Defendant-Appellant / Tenant"}],"judge":"Karl Schock","amountUsd":8200000,"amountBasis":"judgment","hasFull":true},{"id":"live-325","addedDate":"2026-10-23","title":"USPA City Center, LLC v. Law Offices of Jason W. Estavillo, P.C.: California Court Publishes Ruling Upholding $1.2M Future-Rent Award on Oakland Office Lease","brief":"A California appeals court published its ruling upholding $1,219,015.63 in future rent for the landlord of 555 12th Street in Oakland against a defaulted law-firm office tenant.","category":"lease-disputes","status":"ruling","date":"2026-10-19","jurisdiction":"California Court of Appeal, First Appellate District, Division Two","state":"CA","amount":"$1,219,015.63 future-rent award (plus $350,677.82 back rent and holdover)","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11038242/uspa-city-center-llc-v-law-offices-of-jason-w-estavillo-pc/","propertyType":"Office","summary":"On October 19, 2026, the California Court of Appeal ordered its September 21 opinion in USPA City Center, LLC v. Law Offices of Jason W. Estavillo, P.C. published, which makes it binding precedent. The opinion affirmed an Alameda County judgment giving the landlord of 555 12th Street in downtown Oakland $350,677.82 in back rent and holdover damages and $1,219,015.63 in future rent, discounted to present value, against a law-firm tenant that defaulted months into a 66-month office lease. The court rejected the tenant's arguments that the future-rent award lacked evidence, was a penalty, and paid the landlord twice.","significance":"There is now published California authority that a landlord can recover several years of future rent under Civil Code section 1951.2 when it proves, through broker testimony and vacancy data, that the space cannot realistically be re-let. The record describes the downtown Oakland office market as weak, which gives landlords in similar markets a model for proving rental losses the tenant could not have avoided. The court also held that a stipulated judgment for future rent is not a penalty when it only restates what the lease and the Civil Code already allow.","tags":["future rent","office lease","oakland","civil code 1951.2","mitigation"],"parties":[{"name":"USPA City Center, LLC","role":"Plaintiff/Respondent (Landlord)"},{"name":"Law Offices of Jason W. Estavillo, P.C.","role":"Defendant/Appellant (Tenant)"}],"judge":"Richman","amountUsd":1219015.63,"amountBasis":"judgment","hasFull":true},{"id":"live-326","addedDate":"2026-10-23","title":"Metropolitan Milwaukee Association of Commerce v. City of Port Washington: Judge Dismisses Business and CRE Groups' Challenge to Voter-Approval Rule for Large TIF Districts","brief":"An Ozaukee County judge dismissed business and commercial real estate groups' challenge to Port Washington's voter-approved rule requiring a referendum for tax incremental districts over $10 million.","category":"zoning-land-use","status":"ruling","date":"2026-10-19","jurisdiction":"Wisconsin Circuit Court, Ozaukee County","state":"WI","amount":"Declaratory and injunctive relief; ordinance covers TIDs above $10 million","source":"live","sourceUrl":"https://wislawjournal.com/2026/10/20/judge-upholds-port-washington-data-center-ordinance","summary":"On October 19, 2026, Ozaukee County Circuit Judge Adam Gerol dismissed a suit by the Metropolitan Milwaukee Association of Commerce and other business, contractor and commercial real estate groups against the City of Port Washington, the Wisconsin Law Journal reported. The suit challenged a voter-approved ordinance requiring a referendum before the city creates a new tax incremental district above $10 million in project cost or base value. In an oral ruling, the judge found the groups had not shown actual or sufficiently imminent injury, and he also concluded the ordinance is consistent with state law and not too vague to apply.","significance":"The ordinance arose from opposition to the $458 million in local incentives for Vantage Data Centers' $15 billion campus and was described as the first U.S. ballot initiative aimed at restricting future data center development. While it stands, large TIF packages in Port Washington need voter approval as well as council action. MMAC has said further review in higher courts is warranted.","tags":["tax incremental financing","data centers","referendum","wisconsin","development incentives"],"parties":[{"name":"Metropolitan Milwaukee Association of Commerce","role":"Plaintiff"},{"name":"Associated General Contractors of Greater Milwaukee","role":"Plaintiff"},{"name":"Building Advantage","role":"Plaintiff"},{"name":"Commercial Association of REALTORS Wisconsin","role":"Plaintiff"},{"name":"Commercial Real Estate Development Association of Wisconsin (NAIOP Wisconsin)","role":"Plaintiff"},{"name":"Wisconsin REALTORS Association","role":"Plaintiff"},{"name":"Sid's Sealants LLC","role":"Plaintiff"},{"name":"City of Port Washington","role":"Defendant"},{"name":"Great Lakes Neighbors United","role":"Intervenor"}],"judge":"Adam Gerol","amountUsd":null,"hasFull":true},{"id":"live-327","addedDate":"2026-10-23","title":"Sierra Club v. Wisconsin Department of Natural Resources: Settlement Leaves Vantage's $15 Billion Port Washington Data Center Permits Intact and Has Vantage Fund a Statewide Data Center Impact Study","brief":"The Sierra Club settled its suit over permits for Vantage's $15 billion Port Washington data center campus; the permits stand and Vantage will fund a statewide data center impact study.","category":"environmental","status":"settled","date":"2026-10-16","jurisdiction":"Wisconsin Circuit Court, Ozaukee County","state":"WI","amount":"Non-monetary settlement; developer funds statewide environmental analysis","source":"live","sourceUrl":"https://www.wpr.org/news/wisconsin-environmental-cost-of-data-centers-lawsuit-settlement","propertyType":"Data Center","summary":"The Sierra Club, the Wisconsin Department of Natural Resources and Vantage Data Centers settled on October 16, 2026 the Sierra Club's suit over the DNR's decision to permit Vantage's $15 billion Lighthouse data center campus in Port Washington without an environmental impact statement, WPR reported. The permits remain valid and no further environmental review of them is required. In return, the DNR will complete a statewide analysis of AI data center build-out and its effects by January 31, 2028, paid for by Vantage, with the DNR keeping sole control of the study.","significance":"The settlement leaves the permits for one of Wisconsin's largest data center projects in place while moving the environmental debate to a statewide study. That study's findings could shape how regulators and opponents approach the next large campus that seeks permits, though the deal does not pause permitting while it is under way.","tags":["data centers","environmental review","wepa","wisconsin","settlement"],"parties":[{"name":"Sierra Club","role":"Plaintiff"},{"name":"Wisconsin Department of Natural Resources","role":"Defendant"},{"name":"Vantage Data Centers","role":"Developer (settlement signatory)"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-328","addedDate":"2026-10-23","title":"State v. 101 Franklin Derry, LLC: New Hampshire Jury Upholds Eminent Domain Takings of Developer's Land for I-93 Exit 4A","brief":"A New Hampshire jury unanimously upheld the state's eminent domain takings of two development companies' land in Derry for I-93 Exit 4A, the Attorney General's office announced.","category":"eminent-domain","status":"ruling","date":"2026-10-20","jurisdiction":"New Hampshire state court (jury trial; reporting does not name the court)","state":"NH","amount":"Validity of the state's takings for the I-93 Exit 4A project; no compensation figure reported","source":"live","sourceUrl":"https://indepthnh.org/2026/10/20/department-of-justice-secures-jury-verdict-in-support-of-construction-of-exit-4a-on-i-9/","summary":"After a four-day trial, a New Hampshire jury unanimously found that the state's eminent domain takings from two development companies for the planned Exit 4A interchange on Interstate 93 in Derry serve a public use, are reasonably necessary and will produce a net public benefit, according to an Attorney General's office release republished by InDepthNH. The condemnees, 101 Franklin Derry, LLC and S&L Elm Street Holdings, LLC, had argued the project mainly serves the private Woodmont Commons development in Londonderry. The release, dated October 20, 2026, says the judge will issue an order consistent with the verdict.","significance":"The verdict shows how hard a public-use and necessity challenge can be when a highway project has a long planning history behind it, even where a private development stands to benefit. For owners whose land is taken for infrastructure that also serves private growth, the remaining fight is often over compensation rather than the state's right to take.","tags":["eminent domain","public use","highway taking","new hampshire","jury verdict"],"parties":[{"name":"State of New Hampshire","role":"Condemnor"},{"name":"New Hampshire Department of Transportation","role":"Condemnor"},{"name":"101 Franklin Derry, LLC","role":"Condemnee"},{"name":"S&L Elm Street Holdings, LLC","role":"Condemnee"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-329","addedDate":"2026-10-23","title":"Whidbey Environmental Action Network v. City of Oak Harbor: Washington Appeals Court Revives SEPA Challenge to Park-Land Ordinance Passed for a 107-Room Home2 Suites Hotel","brief":"A Washington appeals court held that Oak Harbor's ordinance easing the sale of park land for a 107-room Home2 Suites hotel parking lot needed environmental review under SEPA.","category":"zoning-land-use","status":"ruling","date":"2026-10-19","jurisdiction":"Washington Court of Appeals, Division One","state":"WA","amount":"Declaratory relief (SEPA review of Ordinance 1999)","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11038320/whidbey-enviromental-action-network-v-city-of-oak-harbor/","propertyType":"Hospitality","summary":"On October 19, 2026, Washington's Court of Appeals, Division One, reversed a summary judgment for the City of Oak Harbor and revived an environmental group's challenge to Ordinance 1999. The ordinance dropped the voter-approval requirement for selling developed park land when the city approves a qualifying development agreement. The city adopted it to accommodate Sound Development Group LLC's proposed four-story, 107-room Home2 Suites by Hilton hotel, whose parking lot would take part of Hal Ramaley Memorial Park. The court held the ordinance is a nonproject action that is not categorically exempt from State Environmental Policy Act (SEPA) review.","significance":"Developers whose projects depend on a city changing its code, especially to free up public land, should expect that legislation to need its own environmental review under SEPA. The ruling says review must happen at the earliest stage, so an ordinance that puts conditions on how land will be used is not exempt just because it reads as procedural. The opinion is unpublished, but it shows how Washington courts may treat project-driven code amendments.","tags":["sepa","hotel development","park land","oak harbor","washington"],"parties":[{"name":"Whidbey Environmental Action Network","role":"Plaintiff/Appellant"},{"name":"City of Oak Harbor","role":"Defendant/Respondent"}],"judge":"Acting Chief Judge Bowman","amountUsd":null,"hasFull":true},{"id":"live-330","addedDate":"2026-10-23","title":"BSC Realty Services, LLC v. Valcourt Building Services of Georgia, L.C.: Georgia Appeals Court Revives Building Manager's Indemnity Claim Over Rooftop Cooling-Tower Fall","brief":"A Georgia appeals court revived building manager BSC Realty Services' indemnity claim against contractor Valcourt over a rooftop cooling-tower accident, finding fact issues on causation.","category":"premises-liability","status":"ruling","date":"2026-10-19","jurisdiction":"Court of Appeals of Georgia, Fourth Division","state":"GA","amount":"Contractual defense and indemnity","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11038260/bsc-realty-services-llc-v-valcourt-building-services-of-georgia-lc/","summary":"On October 19, 2026, the Court of Appeals of Georgia reversed a summary judgment that had released exterior-maintenance contractor Valcourt Building Services of Georgia, L.C. from its duty to indemnify building manager BSC Realty Services, LLC. The underlying claim comes from a worker hurt when a cooling-tower fan he was pressure washing on top of a commercial building began turning and knocked him off a ladder. The contract excused indemnity only for liability arising from the 'sole negligence' of the owner or manager. Because the evidence conflicts on whether the fan was re-energized, the court held that fact issues prevent summary judgment.","significance":"Owners and managers often rely on contractor indemnity clauses that exclude only their own 'sole negligence.' This ruling shows that a contractor cannot escape the clause on summary judgment when circumstantial evidence leaves the cause of an accident disputed. It also shows how lost records hurt: the building-automation logs that would have shown when power was cut were not kept, and that led to a spoliation ruling in the injury case.","tags":["indemnification","building manager","contractor","premises liability","georgia"],"parties":[{"name":"BSC Realty Services, LLC","role":"Third-Party Plaintiff/Appellant (Building Manager)"},{"name":"Valcourt Building Services of Georgia, L.C.","role":"Third-Party Defendant/Appellee (Contractor)"}],"judge":"Presiding Judge McFadden","amountUsd":null,"hasFull":true},{"id":"live-333","addedDate":"2026-10-24","title":"Industrial Park Center LLC v. Great Northern Insurance Co. (Arizona Fortuity-Doctrine Coverage Ruling)","brief":"The Ninth Circuit vacated summary judgment for Great Northern Insurance on a $2.7 million claim for water and salt damage to an Arizona commercial building, applying the Arizona Supreme Court's new fortuity test.","category":"construction-defect","status":"ruling","date":"2026-10-16","jurisdiction":"U.S. Court of Appeals for the Ninth Circuit","state":"AZ","amount":"$2.7M","source":"live","sourceUrl":"https://www.businessinsurance.com/arizona-high-court-sets-new-test-for-fortuitous-insurance-losses/","summary":"Industrial Park Center LLC, doing business as Mainspring Capital Group, sued Great Northern Insurance Co., a Chubb unit, after the insurer denied a $2.7 million claim for years of water and salt damage to a commercial building leased to fish processor Star Fisheries, Business Insurance reported. Answering a question certified by the Ninth Circuit, the Arizona Supreme Court held on Sept. 1, 2026 that a loss is fortuitous unless the insured knew, when coverage attached, that it had occurred, was in progress or was certain to occur. On Oct. 16, 2026, the Ninth Circuit vacated the district court's summary judgment for Great Northern and its fee award and sent the case back.","significance":"Arizona now asks what the insured actually knew when coverage began, not whether a loss was reasonably foreseeable, the test the district court had used. The case returns to the district court, which must also decide Great Northern's wear-and-tear and settling exclusion defenses.","tags":["insurance coverage","property insurance","arizona","fortuity doctrine","ninth circuit"],"parties":[{"name":"Industrial Park Center LLC (d/b/a Mainspring Capital Group)","role":"Plaintiff-Appellant"},{"name":"Great Northern Insurance Company","role":"Defendant-Appellee"}],"judge":null,"amountUsd":2700000,"amountBasis":"claim","docketUrl":"https://www.courtlistener.com/docket/63600354/industrial-park-center-llc-v-great-northern-insurance-company/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-334","addedDate":"2026-10-26","title":"Illinois Center Foreclosure: Cook County Judge Orders Nov. 12 Sheriff's Sale of AmTrust's Chicago Towers","brief":"A Cook County judge entered a foreclosure judgment against AmTrust RE over Chicago's Illinois Center and set a Nov. 12, 2026 sheriff's auction, after a default on $260 million in CMBS debt.","category":"lending-foreclosure","status":"ruling","date":"2026-10-19","jurisdiction":"Circuit Court of Cook County, Illinois","state":"IL","amount":"$260M CMBS loan; balance $285.7M as of June 2026; complex appraised at $66.5M in March","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/10/19/amtrusts-illinois-center-set-for-foreclosure-auction/","summary":"Cook County Judge Edward Robles entered a foreclosure judgment against AmTrust RE over Illinois Center, the two-tower, 2.1 million-square-foot office complex at 111 East Wacker Drive and 233 North Michigan Avenue in Chicago's East Loop, and set a sheriff's auction for Nov. 12, 2026, The Real Deal reported on October 19, citing Crain's Chicago Business. Special servicer LNR Partners, which represents the bondholders on the property's CMBS debt, is positioned to bid for and take title. According to Crain's, the debt balance stood at $285.7 million as of June, a March appraisal valued the complex at $66.5 million, and AmTrust paid $376 million for it in 2015.","significance":"The March appraisal puts the complex at less than a quarter of its debt balance, a gap no ordinary refinancing can close. Once an owner stops opposing foreclosure, a Cook County case can move from summary judgment to a sheriff's sale quickly, and the special servicer can take title for the bondholders.","tags":["cmbs foreclosure","chicago office","special servicing","sheriff's sale","amtrust"],"parties":[{"name":"AmTrust RE","role":"Borrower/Owner"},{"name":"LNR Partners","role":"Special Servicer for the CMBS bondholders"}],"judge":"Edward Robles","amountUsd":260000000,"amountBasis":"loan","hasFull":true},{"id":"live-335","addedDate":"2026-10-26","title":"Goochland County Data Center Overlay Suit: Judge Weighs Dismissal","brief":"A Goochland County, Virginia judge took under advisement the county's bid to dismiss four residents' suit over a data center zoning overlay after an Oct. 20 hearing, Richmond BizSense reported.","category":"zoning-land-use","status":"pending","date":"2026-10-20","jurisdiction":"Goochland County Circuit Court, Virginia","state":"VA","amount":"4,400-acre Technology Overlay District; $250,000 county legal defense budget","source":"live","sourceUrl":"https://www.dailysignal.com/2026/10/17/goochland-data-center-court/","summary":"Four Goochland County, Virginia property owners sued the county, its Board of Supervisors and its Planning Commission in December 2025 to void the Technology Overlay District, a roughly 4,400-acre overlay approved in November 2025 that allows data centers and other uses by right in most of the district. At an October 20, 2026 hearing on the county's demurrer, Circuit Judge Timothy Sanner took the motion to dismiss under advisement, Richmond BizSense reported. The plaintiffs dropped four more claims at the hearing; the county said three of the nine original claims remain, including that it violated advertising, notice and public hearing requirements.","significance":"The case tests whether a data center zoning overlay can be undone over how it was noticed and adopted, rather than over the land use itself. The county's argument that the residents have not shown particularized harm could end the case before the merits are reached.","tags":["data center","zoning","virginia","west creek","land use"],"parties":[{"name":"Goochland County, Virginia","role":"Defendant"},{"name":"Goochland County Board of Supervisors","role":"Defendant"},{"name":"Goochland County Planning Commission","role":"Defendant"}],"judge":"Timothy Sanner","amountUsd":null,"hasFull":true},{"id":"live-336","addedDate":"2026-10-27","title":"Illinois Appeals Court: Landlord Proved Conversion of Its Billboard Structures, But Gets Only Nominal Damages","brief":"An Illinois appeals court found Link Media Midwest converted billboard structures on Michelmann's Quincy lot but allowed only nominal damages, and upheld a $19,907.97 rent judgment.","category":"lease-disputes","status":"ruling","date":"2026-10-26","jurisdiction":"Appellate Court of Illinois, Fourth District","state":"IL","amount":"$19,907.97 past-due rent judgment affirmed; nominal damages for conversion (fair market value of the removed billboard structures not proven)","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11045963/michelmann-steel-construction-co-v-link-media-midwest-llc/","summary":"In a nonprecedential order filed October 26, 2026, the Illinois Appellate Court, Fourth District, held that Link Media Midwest, LLC converted billboard structures it removed in April 2019 from a Quincy lot owned by Michelmann Steel Construction Company, reversing the Adams County circuit court on that count. Because Michelmann offered no evidence of the structures' fair market value, the court directed an award of nominal damages only. It otherwise affirmed, including the $19,907.97 judgment against Link Media for rent from May 2018 through April 2024.","significance":"The order applies the Illinois rule that, unless a lease allows removal after termination, a tenant must remove its fixtures while it remains in possession as a tenant or they become the landlord's property. It also shows that proving a conversion does not produce a damages award without evidence of fair market value, and that a landlord's election to treat a holdover occupant as a tenant carries the old lease's renewal terms forward.","tags":["lease dispute","billboard lease","conversion","illinois","ground lease"],"parties":[{"name":"Michelmann Steel Construction Company","role":"Plaintiff-Appellee/Cross-Appellant (Landlord)"},{"name":"Link Media Midwest, LLC","role":"Defendant-Appellant/Cross-Appellee (Tenant/Assignee)"}],"judge":"Peter C. Cavanagh","amountUsd":19907.97,"amountBasis":"judgment","hasFull":true},{"id":"live-337","addedDate":"2026-10-27","title":"Alexandria Real Estate Equities v. New York City Health + Hospitals and EDC: Ground-Lease Option and Default-Notice Fights","brief":"Alexandria's subsidiary is suing NYC Health + Hospitals and the EDC over its option on a Manhattan campus parcel, with $185.9 million invested, and separately lost a bid for a Yellowstone injunction over a lease default notice.","category":"lease-disputes","status":"pending","date":"2026-05-12","jurisdiction":"Supreme Court of the State of New York, New York County (Commercial Division)","state":"NY","amount":"$185.9 million pre-construction investment tied to the disputed option parcel (potential loss of zero to that amount, per Alexandria); agencies counterclaim for at least $3.8 million and a $5.0 million deposit","source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/1035443/000103544326000076/are-20260930.htm","summary":"Alexandria Real Estate Equities disclosed in its quarterly report filed October 26, 2026 that its subsidiary ARE-East River Science Park, LLC is in two lawsuits with New York City Health + Hospitals Corporation and the New York City Economic Development Corporation. In federal court, it seeks a declaration that its 2006 option to add an adjacent parcel to the ground lease for the Alexandria Center for Life Science campus remains valid; its fraud and implied-covenant claims were dismissed in March 2026, and the agencies counterclaimed. In a separate state-court action filed May 12, 2026 over a default notice on the existing towers, the court denied a Yellowstone injunction, and the subsidiary's appeal is pending.","significance":"Alexandria says its $185.9 million investment in pre-construction costs for the option parcel is at stake, with potential losses ranging from zero to that amount depending on the outcome. The state case also shows the limits of a Yellowstone injunction: the court declined to toll the cure period on the agencies' default notice.","tags":["ground lease","life science","reit","new york city","yellowstone injunction"],"parties":[{"name":"Alexandria Real Estate Equities, Inc.","role":"Plaintiff"},{"name":"ARE-East River Science Park, LLC","role":"Plaintiff"},{"name":"New York City Health + Hospitals Corporation","role":"Defendant"},{"name":"New York City Economic Development Corporation","role":"Defendant"}],"judge":null,"amountUsd":185900000,"amountBasis":"other","docketUrl":"https://www.courtlistener.com/docket/69018926/are-east-river-science-park-llc-v-new-york-city-health-and-hospitals/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-338","addedDate":"2026-10-27","title":"Thor Equities, LLC v. City of Urbana, Ohio (Data Center Moratorium and Rezoning Suit)","brief":"Thor Equities and four affiliates sued Urbana, Ohio in federal court after the city paused data center development and rezoned Thor's land; Thor says it spent $19.6 million on the project.","category":"zoning-land-use","status":"pending","date":"2026-06-19","jurisdiction":"U.S. District Court for the Southern District of Ohio","state":"OH","amount":"$1 billion proposed data center project; Thor says it spent $19.6 million in preliminary costs before the moratorium","source":"live","sourceUrl":"https://www.datacenterdynamics.com/en/news/thor-equities-files-lawsuit-against-ohios-urbana-after-data-center-moratorium-disrupts-project/","summary":"Thor Equities, LLC and four affiliated property companies sued the City of Urbana, Ohio, its City Council and its Building and Zoning Appeals Board in the U.S. District Court for the Southern District of Ohio on June 19, 2026, the court docket shows. DatacenterDynamics reported that the city passed a 12-month emergency moratorium on data centers in March and in June rezoned Thor's land as unsuitable for them, after Thor had submitted a site plan in February for a $1 billion, 460,000-square-foot facility. The city has answered the complaint, and the court sent the case to mediation in September.","significance":"The suit tests what protection a developer has when a city changes its rules after a complete application is filed. Nearby landowners have asked to join the case and have objected to a consent decree, so any resolution between Thor and the city may face a challenge of its own.","tags":["data center","zoning","moratorium","vested rights","ohio"],"parties":[{"name":"Thor Equities, LLC","role":"Plaintiff"},{"name":"Urbana Owner LLC","role":"Plaintiff"},{"name":"Urbana Owner I LLC","role":"Plaintiff"},{"name":"Urbana Owner II LLC","role":"Plaintiff"},{"name":"Highland55 Investments LLC","role":"Plaintiff"},{"name":"City of Urbana, Ohio","role":"Defendant"},{"name":"Urbana City Council","role":"Defendant"},{"name":"Urbana Building and Zoning Appeals Board","role":"Defendant"}],"judge":"Michael J. Newman","amountUsd":19600000,"amountBasis":"other","docketUrl":"https://www.courtlistener.com/docket/73509496/thor-equities-llc-v-city-of-urbana-ohio/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-339","addedDate":"2026-10-27","title":"ECO TIP West, LLC v. Chatham County, North Carolina (Data Center Moratorium Vested-Rights Ruling)","brief":"A Chatham County, N.C. judge granted summary judgment to data center developer Eco TIP West, letting its project near Moncure proceed despite the county's data center moratorium.","category":"zoning-land-use","status":"ruling","date":"2026-09-17","jurisdiction":"Superior Court of Chatham County, North Carolina","state":"NC","amount":"$11 million spent on the project, per the developer; damages reserved for further proceedings","source":"live","sourceUrl":"https://ncnewsline.com/2026/09/22/judge-rules-chatham-county-data-center-can-proceed-despite-moratorium/","summary":"Chatham County Superior Court Judge John Morris granted summary judgment to Eco TIP West, LLC in mid-September 2026, allowing its planned 750-megawatt data center at the Triangle Innovation Point West site near Moncure to proceed despite the county's year-long moratorium on new data centers, NC Newsline and the Carolina Journal reported. The developer sued in April 2026, arguing its project was already under way when the moratorium was adopted. The Carolina Journal reported that the judge also awarded attorney's fees and reserved damages for further proceedings; the county had argued the company never obtained a development approval for a data center.","significance":"The ruling exempts one project from a local data center moratorium at a time when at least 30 North Carolina local governments have adopted similar bans, according to NC Newsline. The order as reported does not spell out its legal basis, so its reach for other projects is unclear.","tags":["data center","zoning","moratorium","vested rights","north carolina"],"parties":[{"name":"ECO TIP West, LLC","role":"Plaintiff"},{"name":"Chatham County, North Carolina","role":"Defendant"}],"judge":"John Morris","amountUsd":11000000,"amountBasis":"other","hasFull":true},{"id":"live-340","addedDate":"2026-10-27","title":"In re Jon Peter Venetos: Creditors File Involuntary Chapter 7 Petition Against Lurin Capital Founder","brief":"Six creditors, including Vista Bank, filed an involuntary Chapter 7 petition against Lurin Capital founder Jon Venetos in Texas federal bankruptcy court; The Real Deal reported that the filing cites $33.7 million in judgments against him.","category":"lending-foreclosure","status":"filed","date":"2026-09-17","jurisdiction":"U.S. Bankruptcy Court for the Southern District of Texas","state":"TX","amount":"$33.7M in judgments cited in the petition, per The Real Deal","source":"live","sourceUrl":"https://therealdeal.com/texas/2026/09/30/jon-venetos-creditors-file-involuntary-chapter-7-bankruptcy/","summary":"Six creditors filed an involuntary Chapter 7 bankruptcy petition on September 17, 2026, against Jon Peter Venetos, founder of Dallas-based multifamily firm Lurin Capital, in the U.S. Bankruptcy Court for the Southern District of Texas, the court docket shows. The Real Deal reported that the filing cites $33.7 million in judgments against Venetos personally, about $30.8 million of it held by three lenders: Silver Point Finance ($22.7 million, for breach of a promissory note), and Vista Bank ($3.1 million) and NexPoint Real Estate Finance ($5 million) on his personal guaranties. The case is assigned to Judge Eduardo V. Rodriguez.","significance":"Once several lenders turn a sponsor's personal guaranties into court judgments, the sponsor's own assets become the next target, separate from any bankruptcy of the company. An involuntary Chapter 7 puts those assets under a trustee for all creditors at once, but a judgment is no promise of a meaningful recovery.","tags":["involuntary bankruptcy","personal guaranty","multifamily","chapter 7","syndicator collapse"],"parties":[{"name":"Vista Bank, a division of NBH Bank","role":"Petitioning Creditor"},{"name":"NREF Center Point, LLC","role":"Petitioning Creditor"},{"name":"SCF II Group Holdings","role":"Petitioning Creditor"},{"name":"Really High Places LLC","role":"Petitioning Creditor"},{"name":"Sespe Investment Group Fund I, LP","role":"Petitioning Creditor"},{"name":"Red Elephant Design + Architectural Signage","role":"Petitioning Creditor"},{"name":"Silver Point Finance, LLC","role":"Judgment Creditor"},{"name":"Acore Capital Mortgage","role":"Judgment Creditor (not in petition)"},{"name":"Lurin Capital","role":"Related Company"}],"judge":"Eduardo V. Rodriguez","amountUsd":33700000,"amountBasis":"judgment","docketUrl":"https://www.courtlistener.com/docket/74810397/jon-peter-venetos/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-341","addedDate":"2026-10-28","title":"Renaissance Midtown W. LLC v. Lividini & Co., LLC: Appeals Court Affirms Dismissal of Landlord's Unpaid-Rent and Guaranty Claims","brief":"A New York appeals court affirmed dismissal of Renaissance Midtown West's suit against former tenant Lividini & Company, holding the landlord had to give lease-required notice before reentering and reletting.","category":"lease-disputes","status":"ruling","date":"2026-10-27","jurisdiction":"Appellate Division of the Supreme Court of the State of New York, First Department","state":"NY","amount":"Unpaid rent for balance of lease term (amount not stated in opinion)","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11046209/renaissance-midtown-w-llc-v-lividini-co-llc/","summary":"On October 27, 2026, the Appellate Division, First Department unanimously affirmed dismissal of Renaissance Midtown West LLC's amended complaint against former tenant Lividini & Company, LLC and the tenant's principal. The court held that once the tenant vacated, the lease's conditional-limitation clause required the landlord to give notice before reentering and reletting, which the landlord acknowledged it did not do. It also affirmed dismissal of the guaranty claim, because the guaranty form attached to the lease was blank and unsigned, and of the veil-piercing claim against the principal.","significance":"The ruling holds a landlord to the notice steps in its own lease after a tenant leaves early, and it distinguishes a case where the landlord told the tenant, on accepting the surrender, that it reserved its claim for unpaid rent. It also applies New York's statute of frauds to an unsigned guaranty form and the Cortlandt Street standard to a bare veil-piercing allegation.","tags":["commercial lease","landlord-tenant","guaranty","veil piercing","surrender"],"parties":[{"name":"Renaissance Midtown West LLC","role":"Plaintiff-Appellant"},{"name":"Lividini & Company, LLC","role":"Defendant-Respondent"}],"judge":"Lyle E. Frank","amountUsd":null,"hasFull":true},{"id":"live-342","addedDate":"2026-10-28","title":"GRE Downtowner LLC v. City of Seattle: Washington Appeals Court Revives Affordable-Housing Owner's Takings Claims Over Tenant-Protection Ordinances","brief":"A Washington appeals court reinstated GRE Downtowner's takings claims against Seattle over its tenant-protection ordinances, holding the owner of Addison on Fourth pleaded enough to proceed.","category":"eminent-domain","status":"ruling","date":"2026-10-26","jurisdiction":"Washington Court of Appeals, Division One","state":"WA","amount":"Alleged cumulative operating losses of nearly $6 million through 2023 on a $39 million affordable-housing investment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11045942/gre-downtowner-llc-dba-addison-on-fourth-v-city-of-seattle/","summary":"On October 26, 2026, Washington's Court of Appeals, Division One, reversed the dismissal of GRE Downtowner LLC's inverse condemnation suit against the City of Seattle over a series of rental housing ordinances adopted since 2018. In a published opinion by Judge David S. Mann, the court held that the company pleaded enough facts to support both a partial regulatory takings claim and a per se takings claim at Addison on Fourth, its low-income apartment complex. It also held that a six-year limitations period applies to the partial takings claim, making it timely.","significance":"The decision is a pleading-stage ruling: it lets the takings claims go forward but does not decide whether a taking occurred. Its holdings that Seattle's Roommate Ordinance can support a per se takings claim and that a six-year limitations period governs partial regulatory takings claims in Washington are points multifamily owners and cities will watch.","tags":["regulatory takings","inverse condemnation","multifamily","affordable housing","washington"],"parties":[{"name":"GRE Downtowner LLC","role":"Plaintiff-Appellant"},{"name":"City of Seattle","role":"Defendant-Respondent"}],"judge":"David S. Mann","amountUsd":null,"hasFull":true},{"id":"live-344","addedDate":"2026-10-28","title":"Copper Mill Sues Joint-Venture Partners POB Capital and Pactolus Over Collapsed Dorchester Development Deal","brief":"Copper Mill sued its joint-venture partners POB Capital and Pactolus, alleging fraud in the collapse of a deal for a 754-unit Dorchester project, including secret marketing of the site at $82.5M, Bisnow reported.","category":"zoning-land-use","status":"filed","date":"2026-10-15","jurisdiction":"Suffolk County Superior Court, Massachusetts","state":"MA","amount":"$67.5 million purchase price for a 754-unit Dorchester development site; partners allegedly pitched the site to third parties at an $82.5 million valuation","source":"live","sourceUrl":"https://www.bisnow.com/news/boston/multifamily/copper-mill-sues-partners-collapsed-deal-750-unit-dorchester-project","summary":"Boston-based Copper Mill sued POB Capital and Pactolus Private Wealth Management in Suffolk County Superior Court on October 15, 2026, alleging fraud in their dealings over a planned 754-unit project at 75 Morrissey Boulevard in Dorchester, Bisnow reported, citing Banker & Tradesman. Copper Mill had agreed to buy the site from the two firms for $67.5 million before the parties formed a joint venture; the suit alleges the firms undermined the venture, secretly marketed the property at an $82.5 million valuation, and then sent a termination notice on June 30, 2026. None of the parties immediately responded to Bisnow.","significance":"The suit turns on whether the site owners' termination of the venture was legitimate or, as Copper Mill alleges, the result of a pretextual financing effort while they shopped the property at a higher price. The dispute could affect an approved 754-unit housing project on the site.","tags":["joint venture dispute","development site","dorchester","boston","multifamily"],"parties":[{"name":"Copper Mill","role":"Plaintiff"},{"name":"POB Capital","role":"Defendant"},{"name":"Pactolus Private Wealth Management","role":"Defendant"}],"judge":null,"amountUsd":67500000,"amountBasis":"purchase price","hasFull":true},{"id":"live-345","addedDate":"2026-10-29","title":"111 West 57th Investment LLC v. ACREFI Mortgage LLC (No-Consideration Fund Transfer Claim)","brief":"An AmBase subsidiary filed a summons with notice against ACREFI Mortgage LLC and its parent, Apollo Commercial Real Estate Finance, alleging ACREFI transferred funds to the parent for no consideration or equivalent value.","category":"lending-foreclosure","status":"filed","date":"2026-10-19","jurisdiction":"Supreme Court of the State of New York, New York County","parties":[{"name":"111 West 57th Investment LLC","role":"Plaintiff"},{"name":"111 West 57th Partners LLC","role":"Nominal Plaintiff"},{"name":"111 West 57th Mezz 1 LLC","role":"Nominal Plaintiff"},{"name":"ACREFI Mortgage LLC","role":"Defendant"},{"name":"Apollo Commercial Real Estate Finance, Inc.","role":"Defendant"}],"amountUsd":null,"judge":null,"state":"NY","amount":"unspecified — alleged no-consideration fund transfer from ACREFI to its parent","source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/20639/000114036126041028/ef20080523_10q.htm","summary":"AmBase Corporation disclosed in its Form 10-Q filed October 28, 2026 that its subsidiary 111 West 57th Investment LLC, for itself and derivatively for 111 West 57th Partners LLC and 111 West 57th Mezz 1 LLC, filed a summons with notice on October 19, 2026 in New York Supreme Court, New York County (Index No. 655919/2026) against ACREFI Mortgage LLC and Apollo Commercial Real Estate Finance, Inc. The action concerns the alleged improper transfer of funds by ACREFI to ARI, its indirect parent, for no consideration or equivalent value. It is separate from the long-running Lender Action over the 2017 strict foreclosure of the AmBase entities' interest in the 111 West 57th Street project.","significance":"The filing adds another case to AmBase's litigation over the 111 West 57th Street development, this one aimed at money moved between an Apollo lending entity and its parent. AmBase's disclosure gives no amount and no further detail about the claim.","tags":["mezzanine debt","fraudulent transfer","111 west 57th","apollo","strict foreclosure"],"hasFull":true},{"id":"live-346","addedDate":"2026-10-29","title":"Federal National Mortgage Association v. SYS Augusta LLC (Multifamily Loan Default and Acceleration Suit)","brief":"Fannie Mae sued the owner of Falcon Crest Apartments in Augusta, Georgia, alleging missed payments on a $21.45 million loan, unpaid repairs and vendor liens, and asked for a receiver, Mortgage Professional America reported.","category":"lending-foreclosure","status":"filed","date":"2026-10-22","jurisdiction":"U.S. District Court for the Southern District of Georgia","parties":[{"name":"Federal National Mortgage Association (Fannie Mae)","role":"Plaintiff / Lender"},{"name":"SYS Augusta LLC","role":"Defendant / Borrower"},{"name":"Greystone Servicing Company LLC","role":"Loan Servicer"}],"amountUsd":21450000,"amountBasis":"loan","judge":"J. Randal Hall","state":"GA","amount":"$21.45 million","source":"live","sourceUrl":"https://www.mpamag.com/us/mortgage-industry/market-updates/fannie-mae-moves-to-seize-augusta-apartment-complex-over-21m-default/594810","summary":"Fannie Mae sued SYS Augusta LLC, the company formed to own Falcon Crest Apartments in Augusta, on October 22, 2026 in the U.S. District Court for the Southern District of Georgia, Mortgage Professional America reported. The complaint alleges the borrower paid late in July 2026, missed payments of about $103,138.75 for August through October, and let vendor liens and safety repairs go unaddressed, and that Fannie Mae accelerated the $21.45 million loan on September 1. Fannie Mae asks the court to appoint a receiver and for a breach-of-contract judgment. The allegations have not been tested in court.","significance":"The complaint combines a payment default with alleged non-monetary defaults, including recorded vendor liens, unmade repairs and missing financial reports, as grounds for a receiver. It also alleges that the borrower kept collecting rents after its right to do so ended on default.","tags":["multifamily","lending-foreclosure","fannie mae","receivership","acceleration"],"docketUrl":"https://www.courtlistener.com/docket/75007687/fannie-mae-v-sys-augusta-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-347","addedDate":"2026-10-29","title":"RJ's International Trading, LLC v. Crown Castle South, LLC (Florida Supreme Court: Easement Attorney's-Fee Clauses Don't Run With the Land)","brief":"Answering an Eleventh Circuit question, Florida's Supreme Court held an easement's prevailing-party attorney's-fee clause does not run with the land, so it does not bind a successor like Crown Castle.","category":"zoning-land-use","status":"ruling","date":"2026-10-29","jurisdiction":"Supreme Court of Florida","state":"FL","amount":"$40,001 jury verdict ($1 for breach of easement, $40,000 for trespass); the attorney's-fee amount actually in dispute is not stated in the opinion","amountUsd":40001,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11049068/rjs-international-trading-llc-v-crown-castle-south-llc/","summary":"On October 29, 2026, the Florida Supreme Court answered no to a question certified by the U.S. Court of Appeals for the Eleventh Circuit: a prevailing-party attorney's-fee provision in an easement agreement does not run with the land. The court held the provision too attenuated from the use, occupation or enjoyment of the land to touch and concern it, so it does not bind successors such as Crown Castle South, LLC, which had lost trespass and easement-breach claims to RJ's International Trading, LLC. The case returns to the Eleventh Circuit.","significance":"The decision sets Florida's test for whether a covenant touches and concerns land, asking whether the obligation is sufficiently connected to how the land is used, occupied or enjoyed, and declines to extend Hayslip v. U.S. Home Corp. to fee-shifting clauses. Two justices concurred in the result only and would tie the test to the physical use of the land.","judge":"Jamie Grosshans","parties":[{"name":"RJ's International Trading, LLC","role":"Appellant"},{"name":"Crown Castle South, LLC","role":"Appellee"}],"tags":["easement","attorney's fees","real covenant","florida","telecom"],"hasFull":true},{"id":"live-348","addedDate":"2026-10-29","title":"Seneca Ins. Co. Inc. v. Cobleskill Enter., LLP (Smoke-Detector Warranty Breach Voids Hotel Fire Coverage)","brief":"New York's Third Department ruled Seneca Insurance owes no coverage for a 2018 fire at a Cobleskill hotel and bowling-alley complex, finding the owner breached the policy's smoke-detector warranty.","category":"premises-liability","status":"ruling","date":"2026-10-29","jurisdiction":"Appellate Division, Third Department, New York","state":"NY","propertyType":"Hospitality","amount":"Coverage dispute over fire damage to a hotel, restaurant and bowling-alley complex; no dollar figure for the loss is stated in the opinion","amountUsd":null,"source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11049454/seneca-ins-co-inc-v-cobleskill-enter-llp/","summary":"On October 29, 2026, New York's Appellate Division, Third Department, reversed a Schoharie County order and declared that Seneca Insurance Company Inc. is not obligated to cover a December 2018 fire at a hotel and restaurant complex owned by Cobleskill Enterprise, LLP in the Town of Cobleskill. The court held that the owner breached, as a matter of law, the policy's protective safeguards endorsement requiring operational smoke detectors in units and common areas, and that the breach materially increased the risk of loss under Insurance Law § 3106. It also dismissed Seneca's fraud and negligent-misrepresentation claims against broker Links Insurance Services, LLC and the owner's third-party claims against Links.","significance":"The decision enforces a protective safeguards endorsement by its plain terms: detectors that would not sound an alarm were treated as not operational, and a public space such as a bowling alley was clearly a common area. Because coverage was denied on that ground, the owner's claims against its broker, which were tied to other grounds for denial, also failed.","judge":"Stan L. Pritzker","parties":[{"name":"Seneca Insurance Company Inc.","role":"Plaintiff-Appellant-Respondent"},{"name":"Cobleskill Enterprise, LLP","role":"Defendant"},{"name":"Links Insurance Services, LLC","role":"Respondent-Appellant"}],"tags":["insurance coverage","hotel","fire","protective safeguards","new york"],"hasFull":true},{"id":"live-349","addedDate":"2026-10-29","title":"Portage Township of St. Joseph County, Indiana v. City of South Bend (Eminent Domain in Redevelopment Areas Requires Council Authorization)","brief":"Indiana's Court of Appeals reversed a ruling for South Bend in a condemnation case, holding only a city's legislative body, not its mayor, can authorize eminent domain in a redevelopment project area.","category":"eminent-domain","status":"ruling","date":"2026-10-29","jurisdiction":"Indiana Court of Appeals","state":"IN","propertyType":null,"amount":"Not stated; dispute concerns authority to condemn, not a damages or compensation figure","amountUsd":null,"source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11049277/portage-township-of-st-joseph-county-indiana-v-city-of-south-bend/","summary":"On October 29, 2026, the Court of Appeals of Indiana held that Indiana Code section 36-7-14-20 gives a unit's legislative body exclusive authority to use eminent domain in a redevelopment project area. The City of South Bend, at its mayor's direction, had filed a condemnation complaint in October 2024 over property then owned by Argos 316, LLC without authorization from the South Bend Common Council. The court reversed the Marshall Circuit Court's order overruling the objection raised by Portage Township, which completed its purchase of the property shortly after the suit was filed, and 350 Columbia Street, LLC, which held easements on it.","significance":"The ruling makes a legislative-body resolution a prerequisite for condemnation inside an Indiana redevelopment project area, even though other local officials generally hold broad eminent-domain power. Chief Judge Tavitas concurred in the result but questioned the majority's finding that the statute is ambiguous.","judge":"Nancy H. Vaidik","parties":[{"name":"Portage Township of St. Joseph County, Indiana","role":"Appellant-Intervenor Defendant"},{"name":"350 Columbia Street, LLC","role":"Appellant-Intervenor Defendant"},{"name":"City of South Bend","role":"Appellee-Plaintiff"},{"name":"Argos 316, LLC","role":"Owner of the property when the condemnation complaint was filed"}],"tags":["eminent domain","condemnation","redevelopment","indiana","municipal authority"],"hasFull":true},{"id":"live-350","addedDate":"2026-10-29","title":"Commercial Painting Company Inc. v. The Weitz Company LLC (Punitive Damages for Contractor Fraud Survive Contractual Waiver)","brief":"Tennessee's Court of Appeals upheld $3.9 million in punitive damages against general contractor Weitz on its drywall subcontractor's misrepresentation claim, holding the subcontract's damages waiver does not bar them.","category":"construction-defect","status":"ruling","date":"2026-10-28","jurisdiction":"Court of Appeals of Tennessee","state":"TN","propertyType":"Senior Living","amount":"$3.9 million punitive damages award affirmed (part of an $8,359,863.83 award after the October 2018 jury trial)","amountUsd":3900000,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11049652/commercial-painting-company-inc-v-the-weitz-company-llc/","summary":"On October 28, 2026, the Tennessee Court of Appeals affirmed the Shelby County Chancery Court's judgment on the $3.9 million punitive damages award against general contractor The Weitz Company, LLC on subcontractor Commercial Painting Company, Inc.'s intentional-misrepresentation claim. On a narrow remand from the Tennessee Supreme Court, the court held that the subcontract's limitation-of-damages clause does not bar punitive damages tied to the tort claim because it does not specifically waive damages for fraud or misrepresentation. The case was before the Court of Appeals for the fifth time.","significance":"The court applied Tennessee decisions holding that a general contractual waiver does not reach fraud without specific language, finding the damages clause addressed contract remedies, not tort. Its earlier ruling that the same clause bars punitive damages on the contract claim stands.","judge":"Jeffrey Usman","parties":[{"name":"Commercial Painting Company, Inc.","role":"Plaintiff-Appellee"},{"name":"The Weitz Company, LLC","role":"Defendant-Appellant"},{"name":"Federal Insurance Company","role":"Defendant-Appellant (Weitz's surety)"},{"name":"St. Paul Fire & Marine Insurance Company","role":"Defendant-Appellant (Weitz's surety)"},{"name":"Liberty Mutual Insurance Company","role":"Appellee"}],"tags":["construction fraud","punitive damages","subcontractor","tennessee","contractual waiver"],"hasFull":true},{"id":"live-351","addedDate":"2026-10-30","title":"PMC Property Group, Inc. v. Apogee Enterprises, Inc. (New Minnesota Alter-Ego Suit Follows Dismissal From Philadelphia Glass-Defect Case)","brief":"PMC Property Group sued Apogee Enterprises in Minnesota federal court, seeking to hold it liable for subsidiaries Wausau and Viracon after a Pennsylvania judge dismissed Apogee from PMC's glass-breakage suit.","category":"construction-defect","status":"filed","date":"2026-10-27","jurisdiction":"U.S. District Court, District of Minnesota","state":"MN","propertyType":"Multifamily","amount":"PMC says it paid Wausau about $50 million for the window systems at the three towers; the complaint does not state a total damages figure","amountUsd":50000000,"amountBasis":"other","source":"live","sourceUrl":"https://www.usglassmag.com/apogee-faces-new-lawsuit-over-allegedly-defective-philadelphia-glass/","summary":"PMC Property Group, Inc. and three affiliated property entities sued Apogee Enterprises, Inc. in the U.S. District Court for the District of Minnesota on Oct. 27, 2026, seeking to hold it responsible for allegedly defective glass at three Philadelphia residential towers, USGlass magazine reported. The complaint asserts unjust enrichment and seeks declarations that subsidiaries Wausau Group and Viracon are Apogee's alter egos, so that judgments against them could be enforced against Apogee. It follows an August ruling in PMC's earlier Pennsylvania federal suit that dismissed several claims, including those against Apogee for lack of personal jurisdiction.","significance":"The filing moves PMC's parent-company theory to a new federal court after a jurisdictional dismissal in Pennsylvania. Whether the alter-ego claims succeed will decide whether Apogee itself can be reached for any judgment against its subsidiaries over the glass breakage.","judge":null,"parties":[{"name":"PMC Property Group, Inc.","role":"Plaintiff"},{"name":"60 North 23rd Street Associates, LP","role":"Plaintiff"},{"name":"200 North 16th Street Associates, LP","role":"Plaintiff"},{"name":"30 North 23rd Street Associates, LLC","role":"Plaintiff"},{"name":"Apogee Enterprises, Inc.","role":"Defendant"}],"tags":["construction defect","alter ego","unjust enrichment","pennsylvania","minnesota"],"docketUrl":"https://www.courtlistener.com/docket/75029856/pmc-property-group-inc-v-apogee-enterprises-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-352","addedDate":"2026-10-30","title":"Third Department Upholds Site Plan for Accord, LLC's Granary Adaptive-Reuse Project Over Neighbors' Challenge","brief":"New York's Third Department upheld site plan approval for Accord, LLC's mixed-use granary redevelopment in the Town of Rochester, rejecting two neighbors' challenge over plan changes and restaurant parking.","category":"zoning-land-use","status":"ruling","date":"2026-10-29","jurisdiction":"Appellate Division, Third Department, New York","state":"NY","propertyType":"Mixed-Use","amount":"Not a monetary dispute; challenge to a conditional site plan approval for an adaptive-reuse development","amountUsd":null,"source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11049475/matter-of-bruck-v-town-of-rochester-planning-bd/","summary":"On October 29, 2026, New York's Appellate Division, Third Department, affirmed dismissal of an Article 78 challenge by two neighboring property owners to the Town of Rochester Planning Board's conditional site plan approval for Accord, LLC's redevelopment of a historic granary and seed mill complex in the Hamlet of Accord. The court held the Planning Board rationally found the scaled-back project in substantial conformance with the conceptual plan the Town Board approved, and that it properly adopted the Town Board's restaurant parking determination without referring the parking formula for interpretation.","significance":"The decision turns on the town's Economic Enterprise Overlay rules, which allow some deviation from an approved conceptual plan and make the general parking standards guidelines in that district. Changes that dropped a use and reduced square footage did not require a return to the Town Board.","judge":"Christine M. Clark","parties":[{"name":"Accord, LLC","role":"Respondent (Developer)"},{"name":"Town of Rochester Planning Board","role":"Respondent"}],"tags":["zoning","site plan","adaptive reuse","parking","new york"],"hasFull":true},{"id":"live-353","addedDate":"2026-10-30","title":"Lampton Securities Partnership, LLP v. Louisville-Jefferson County Metro Government (Reverse Condemnation Ripeness Ruling)","brief":"Kentucky's Court of Appeals affirmed dismissal of Lampton Securities' reverse condemnation suit over an Ohio River floodplain tract, holding the claim wasn't ripe because Lampton never sought a variance from the floodplain board.","category":"eminent-domain","status":"ruling","date":"2026-10-30","jurisdiction":"Court of Appeals of Kentucky","state":"KY","amount":"Reverse condemnation claim over a 2-acre tract Lampton bought for $800,000 in 1998; the opinion states no damages figure sought","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11050336/lampton-securities-partnership-llp-v-louisville-jefferson-county-metro/","propertyType":"Land/Development","summary":"Lampton Securities Partnership, LLP sued Louisville-Jefferson County Metro Government and the Louisville and Jefferson County Metropolitan Sewer District for reverse (inverse) condemnation, alleging that 1997 floodplain ordinances stripped all economically beneficial use from a roughly two-acre Ohio River tract it bought for $800,000 in 1998. On October 30, 2026, the Kentucky Court of Appeals affirmed summary judgment for the government defendants, holding that Lampton's claim was not ripe because it never applied to the Metro Sewer District's Floodplain Board for a variance -- relief the ordinance made available and that the Board had granted to other landowners.","significance":"The decision applies federal takings ripeness rules, through Kentucky Supreme Court precedent, to a floodplain restriction: a claim is not ripe until the landowner has a final decision from the authority that can grant a variance. A staff lawyer's opinion that development was barred did not show that applying would be futile.","tags":["eminent domain","inverse condemnation","floodplain","ripeness","kentucky"],"parties":[{"name":"Lampton Securities Partnership, LLP","role":"Appellant"},{"name":"Louisville-Jefferson County Metro Government","role":"Appellee"},{"name":"Louisville and Jefferson County Metropolitan Sewer District","role":"Appellee"}],"judge":"Lisa Payne Jones","amountUsd":null,"hasFull":true},{"id":"live-354","addedDate":"2026-10-30","title":"District of Columbia v. RealPage, Inc. (JBG Smith and MAA's $9.3M Consent Judgments)","brief":"JBG Smith agreed to pay $8.1 million and Mid-America Apartments $1.2 million to resolve the D.C. Attorney General's claims that they used RealPage software to coordinate apartment rents, without admitting liability.","category":"landlord-tenant","status":"settled","date":"2026-09-14","jurisdiction":"Superior Court of the District of Columbia","state":"DC","amount":"$9.3 million combined ($8.1 million JBG Smith / $1.2 million MAA)","source":"live","sourceUrl":"https://oag.dc.gov/release/attorney-general-schwalb-secures-93-million-two-dc","summary":"D.C. Attorney General Brian Schwalb announced on September 14, 2026 that JBG Associates, L.L.C. (JBG Smith) and Mid-America Apartments, L.P. (MAA) will pay a combined $9.3 million under separate consent judgments resolving the District's antitrust claims against them in District of Columbia v. RealPage, Inc., No. 2023-CAB-006762 in D.C. Superior Court. The District alleged that JBG Smith used RealPage's revenue-management software to set rents at multiple District properties and MAA at one. JBG Smith will pay $8.1 million and MAA $1.2 million; both accepted limits on such software, and neither admitted liability.","significance":"The consent judgments show the District resolving claims against a landlord whose alleged software use was limited to one property, with the payment differing by the scale of alleged use. The orders pair the payments with multi-year conduct limits, 10 years for JBG and eight for MAA, and a monitor the District can appoint if it suspects noncompliance.","tags":["realpage","antitrust","rent-setting software","reit","washington dc"],"parties":[{"name":"District of Columbia","role":"Plaintiff"},{"name":"RealPage, Inc.","role":"Defendant"},{"name":"JBG Associates, L.L.C.","role":"Defendant (settled)"},{"name":"Mid-America Apartments, L.P.","role":"Defendant (settled)"}],"judge":"Shana Frost Matini","amountUsd":9300000,"amountBasis":"settlement","hasFull":true},{"id":"live-355","addedDate":"2026-10-30","featured":true,"title":"637 Arnold, LLC v. Arnold Shores, LLC (NJ Appellate Division Affirms Mixed-Use Hotel-Restaurant-Spa Zoning Approval)","brief":"New Jersey's Appellate Division affirmed a zoning board's approval letting a historic Point Pleasant Beach building be converted into a restaurant, spa, and boutique hotel, rejecting a neighboring owner's repeat variance challenge.","category":"zoning-land-use","status":"ruling","date":"2026-10-30","jurisdiction":"Superior Court of New Jersey, Appellate Division","state":"NJ","propertyType":"Mixed-Use","amount":"no damages at issue; dispute over use variances for a mixed hotel/restaurant/spa redevelopment of a historic downtown building","amountUsd":null,"source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/10/30/637_arnold_llc_v._arnold_shores_llc.pdf","documentUrl":"https://storage.courtlistener.com/pdf/2026/10/30/637_arnold_llc_v._arnold_shores_llc.pdf","documentLabel":"Read the official opinion","summary":"The Appellate Division of New Jersey's Superior Court affirmed a trial court's dismissal of a neighboring commercial property owner's prerogative-writs challenge to use variances the Point Pleasant Beach Zoning Board of Adjustment granted for a mixed-use redevelopment of the historic Gottlieb Building. The Board had unanimously approved a restaurant and spa on the ground floor and a previously approved boutique hotel use on the second floor; objector 637 Arnold, LLC argued the public notice was deficient and the Board misapplied New Jersey's variance standards, but the per curiam panel found no basis to disturb the trial court's reasoning and affirmed.","significance":"The ruling shows New Jersey appellate courts deferring to a zoning board's findings on particular suitability and the negative criteria when the board expressly adopts detailed planner testimony. It also shows that a board may take a building's prior approvals into account when reviewing a new application for the same property, provided it reviews the project anew.","judge":null,"parties":[{"name":"637 Arnold, LLC","role":"Plaintiff-Appellant"},{"name":"Arnold Shores, LLC","role":"Defendant-Respondent"},{"name":"Hollston Hills, LLC","role":"Defendant-Respondent"},{"name":"Hollston Realty Group, LLC","role":"Defendant-Respondent"},{"name":"Borough of Point Pleasant Beach","role":"Defendant-Respondent"},{"name":"Borough of Point Pleasant Beach Zoning Board of Adjustment","role":"Defendant-Respondent"}],"tags":["zoning","variance","new-jersey","hotel","mixed-use"],"hasFull":true},{"id":"live-356","addedDate":"2026-10-31","title":"Stay Lifted in Mechanics'-Lien Fight Over Monarch Casino's Black Hawk Expansion","brief":"A Gilpin County, Colorado judge lifted a 2021 stay in PCL Construction's mechanics' lien foreclosure suit over Monarch Casino's Black Hawk expansion; a related $74.6 million judgment for PCL is on appeal.","category":"construction-defect","status":"ruling","date":"2026-09-01","jurisdiction":"District Court, Gilpin County, Colorado","state":"CO","propertyType":"Hospitality","amount":"Lien amount not disclosed; related Denver judgment of $74,627,657 for PCL is on appeal","amountUsd":null,"amountBasis":null,"source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/907242/000110465926120630/mcri-20260930x10q.htm","summary":"Monarch Casino & Resort, Inc. disclosed in its Form 10-Q filed October 30, 2026 that on September 1, 2026 the judge in PCL Construction Services, Inc.'s mechanics' lien foreclosure case in Gilpin County District Court granted a lien claimant's motion to lift the stay, effective September 16, 2026, and then set a case management conference for January 22, 2027. The case, No. 2021CV30006, had been stayed since October 2021 pending the outcome of PCL's separate Denver contract suit, in which the court entered a net judgment of $74.6 million for PCL in February 2025 that Monarch has appealed.","significance":"The order puts lien claims against the casino property itself back on an active docket while the money judgment over the same project is still on appeal. Monarch says it cannot yet estimate the outcome.","judge":null,"parties":[{"name":"PCL Construction Services, Inc.","role":"Plaintiff/Lien Claimant"},{"name":"Monarch Growth Inc.","role":"Defendant"},{"name":"Monarch Casino & Resort, Inc.","role":"Defendant"},{"name":"Monarch Black Hawk, Inc.","role":"Defendant"}],"tags":["mechanics-lien","construction","hospitality","colorado","casino"],"hasFull":true},{"id":"live-357","addedDate":"2026-10-31","featured":true,"title":"Bondholder Trustee Files $310 Million Foreclosure Suit Over Third Millennium's 540 W. Madison","brief":"A trustee for bondholders sued to foreclose on 540 W. Madison, Third Millennium Group's 1.1 million-square-foot, 81%-leased West Loop office tower, after the loan went unpaid at its September 2026 maturity.","category":"lending-foreclosure","status":"filed","date":"2026-10-27","jurisdiction":"Circuit Court of Cook County, Illinois","state":"IL","propertyType":"Office","amount":"$310M foreclosure suit; $325M senior loan and $75M mezzanine loan made in 2016","amountUsd":310000000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/10/27/west-loop-office-tower-with-faces-310m-foreclosure/","summary":"A trustee representing bondholders filed a $310 million foreclosure suit in Cook County Circuit Court against an entity led by Boca Raton, Florida-based Third Millennium Group over 540 W. Madison Street, a 1.1 million-square-foot West Loop office tower, The Real Deal reported on October 27, 2026, citing Crain's Chicago Business. The suit alleges the debt was not repaid at its September 2026 maturity. The tower is 81% leased and produced over $18 million in net cash flow against $5.3 million in senior-loan debt service, so this is a maturity default rather than a failure to cover payments.","significance":"A building can be well leased and earn more than its debt payments and still face foreclosure if its loan comes due when its value no longer supports refinancing the old balance. Owners with loans maturing soon should test whether a refinancing is possible well before the date, and lenders should expect more maturity defaults on buildings that are otherwise performing.","judge":null,"parties":[{"name":"Third Millennium Group","role":"Owner (through an affiliated borrower entity)"}],"tags":["cmbs","office","foreclosure","chicago","maturity-default"],"hasFull":true},{"id":"live-358","addedDate":"2026-10-31","title":"Old Second National Bank Sues to Foreclose River North Building, Pursues $2.9M Personal Guaranty Claim","brief":"Old Second National Bank sued to foreclose a River North retail building over a roughly $9 million defaulted loan and to collect $2.9 million under the investor's personal guaranty; the investor says a loan restructuring is in the works.","category":"lending-foreclosure","status":"filed","date":"2026-10-26","jurisdiction":"Circuit Court of Cook County, Illinois, Chancery Division","state":"IL","propertyType":"Retail","amount":"$9 million foreclosure suit, including a separate $2.9 million personal guaranty claim","amountUsd":9000000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/10/29/lender-sues-to-foreclose-on-river-north-building/","summary":"Old Second National Bank sued in Cook County Circuit Court on October 26, 2026 to foreclose on a River North retail building at 400 N. State Street, saying borrower Great Street LLC owed about $9 million as of October 21. The bank also seeks $2.9 million from investor Marc Bushala under his personal guaranty and names MAB Capital Management and WFB Gift as defendants. Bushala told The Real Deal the owner is in advanced talks to recapitalize the property and restructure the loan.","significance":"Suing on the property and the guaranty at the same time gives a lender a second source of recovery that does not depend on the sale price, and pushes the guarantor to negotiate early. Sponsors who signed personal guaranties should expect a default to reach them directly, not just the borrowing entity.","judge":null,"parties":[{"name":"Old Second National Bank","role":"Plaintiff/Lender"},{"name":"Great Street LLC","role":"Defendant/Borrower"},{"name":"MAB Capital Management","role":"Defendant"},{"name":"WFB Gift","role":"Defendant"}],"tags":["foreclosure","personal-guaranty","river-north","chicago","retail"],"hasFull":true},{"id":"live-359","addedDate":"2026-10-31","title":"Texas Appeals Court: Dental Tenant's Square-Footage Fraud Claim Against Former Landlord Is Time-Barred","brief":"A Texas appeals court ruled a dental practice's fraud and overcharge claims against its former shopping-center landlord Brixmor were filed too late, affirming summary judgment.","category":"lease-disputes","status":"ruling","date":"2026-10-29","jurisdiction":"Thirteenth Court of Appeals, Corpus Christi-Edinburg, Texas","state":"TX","propertyType":"Retail","amount":"Unspecified rent-overcharge and fraud damages (space leased as ~1,863 sq ft; tenant alleged true size was ~1,500 sq ft)","amountUsd":null,"source":"live","sourceUrl":"https://search.txcourts.gov/SearchMedia.aspx?MediaVersionID=8f1cbc83-0bb6-4419-8e05-2db94d5fdcde&coa=coa13&DT=Opinion&MediaID=340214cb-92d7-4b12-857d-2eae315e87e8","summary":"The Thirteenth Court of Appeals affirmed summary judgment for Brixmor GA Apollo II TX LP against Veena Dental PA, which sued in 2024 alleging that its Northshore Plaza space in Portland, Texas, was leased as about 1,863 square feet but measured about 1,500. The court held all of Veena's claims barred by limitations: Veena had not pleaded the discovery rule for its contract and fraud claims, and its fraud and DTPA claims accrued in 2013 because its own 2013 construction plans showed the smaller size. The court did not reach Brixmor's argument that it was released when it sold the center in 2018.","significance":"The ruling shows that a tenant's own construction documents can establish when a square-footage claim should have been discovered, starting the limitations clock at lease signing. Because the court decided the case on limitations alone, it left open Brixmor's defense that the lease released it after the 2018 sale.","judge":"Ysmael D. Fonseca","parties":[{"name":"Veena Dental PA","role":"Appellant/Tenant"},{"name":"Brixmor GA Apollo II TX LP","role":"Appellee/Landlord"}],"tags":["lease-dispute","shopping-center","statute-of-limitations","fraud","retail"],"docketUrl":"https://www.courtlistener.com/opinion/11051718/veena-dental-pa-v-brixmor-ga-apollo-ii-tx-lp/","docketLabel":"CourtListener opinion","hasFull":true},{"id":"live-360","addedDate":"2026-11-01","title":"Kansas Court Orders Sheriff's Sale of Stalled Mission Gateway Site After $46.24M Judgment","brief":"After Aryeh Realty missed an Oct. 16 deadline to pay a $46.24 million judgment, Metropolitan Commercial Bank sought and a Kansas court ordered a sheriff's sale of the vacant Mission Gateway site.","category":"lending-foreclosure","status":"ruling","date":"2026-10-30","jurisdiction":"Johnson County District Court, Kansas (10th Judicial District)","state":"KS","propertyType":"Land/Development","amount":"$46.24 million final judgment for loan default and unpaid property taxes, on a $26M loan dating to 2019","amountUsd":46240000,"amountBasis":"judgment","source":"live","sourceUrl":"https://www.kctv5.com/2026/10/28/bank-requests-sheriff-sale-mission-gateway-site-over-46m-debt/","summary":"Metropolitan Commercial Bank, which sued owner Aryeh Realty LLC in 2023 over a defaulted $26 million loan on the Mission Gateway site in Mission, Kansas, obtained a $46.24 million final judgment on Oct. 2, 2026 covering the loan default and unpaid property taxes, KCTV5 reported. After Aryeh missed an Oct. 16 payoff deadline, the bank asked the court on Oct. 26 for a sheriff's sale, and a Johnson County judge ordered the sale in court documents filed Oct. 30. No sale date had been set.","significance":"The case shows the steps between a foreclosure judgment and a change of ownership on a long-stalled redevelopment site: a payoff deadline, a sale request, a sheriff's sale order and the sale itself. The City of Mission's agreement with a prospective buyer depends on how that process ends.","judge":"Robert Wonnell","parties":[{"name":"Metropolitan Commercial Bank","role":"Plaintiff/Lender"},{"name":"Aryeh Realty LLC","role":"Defendant/Borrower"}],"tags":["foreclosure","sheriff-sale","redevelopment","kansas","stalled-project"],"hasFull":true},{"id":"live-361","addedDate":"2026-11-01","title":"Fannie Mae and Freddie Mac Lender Walker & Dunlop Pursue Foreclosures Against Chaim Bialostozky Entities in Three States","brief":"Walker & Dunlop, for Freddie Mac, accuses Lakewood, N.J., investor Chaim Bialostozky of using back-to-back sales to obtain oversized loans; Fannie Mae has filed its own Chicago foreclosures. About $44 million is in foreclosure.","category":"lending-foreclosure","status":"pending","date":"2026-09-22","jurisdiction":"Circuit Court of Cook County, Illinois (with related foreclosure suits in Waterbury, Connecticut, and Tulsa, Oklahoma)","state":"IL","propertyType":"Multifamily","amount":"Nearly $44 million in mortgage debt in foreclosure across Illinois, Connecticut and Oklahoma","amountUsd":44000000,"amountBasis":"loan","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/09/22/alleged-mortgage-fraud-fallout-worsens-for-bialostozky/","summary":"Lenders backed by Fannie Mae and Freddie Mac are foreclosing on apartment properties tied to Lakewood, New Jersey-based investor Chaim Bialostozky in Illinois, Connecticut and Oklahoma, with nearly $44 million of mortgage debt in court, The Real Deal reported on September 22, 2026. In the Connecticut, Chicago and Tulsa cases, the lenders allege he used back-to-back purchases through an intermediary to obtain loans larger than his real costs. Fannie Mae's newest suit, a $6.2 million Cook County foreclosure against Yellow Portfolio Holdings LLC, does not allege fraud. Court records showed no appearance or response by Bialostozky in any of the foreclosure cases, according to the publication.","significance":"The lenders are using orders from one state to seek fast receiverships in another, treating one borrower's defaults as a single pattern rather than as separate workouts. For multifamily owners with agency debt, a default or an unanswered complaint on one property can quickly bring scrutiny and receivership requests across every property under common control.","judge":null,"parties":[{"name":"Federal National Mortgage Association (Fannie Mae)","role":"Plaintiff/Lender (Cook County)"},{"name":"Walker & Dunlop","role":"Plaintiff/Lender, acting for Freddie Mac (Connecticut)"},{"name":"Federal Home Loan Mortgage Corporation (Freddie Mac)","role":"Loan Backer"},{"name":"Yellow Portfolio Holdings LLC","role":"Defendant/Borrower (Cook County)"},{"name":"Courtyard Apt Holdings LLC","role":"Defendant (Waterbury, Conn.)"},{"name":"Tower View Apt LLC","role":"Defendant (Waterbury, Conn.)"}],"tags":["mortgage-fraud","multifamily","foreclosure","fannie-mae","freddie-mac"],"hasFull":true},{"id":"live-362","addedDate":"2026-11-02","title":"NFI Apartment Management, L.L.C. v. Third Coast Insurance Company (Fifth Circuit Affirms Time-Barred Hail Coverage Claim)","brief":"The Fifth Circuit affirmed summary judgment for Third Coast Insurance against a San Antonio apartment owner's hail claim, holding the owner's 2024 suit came after the limitations period ran.","category":"premises-liability","status":"ruling","date":"2026-10-20","jurisdiction":"U.S. Court of Appeals for the Fifth Circuit (W.D. Tex.)","state":"TX","propertyType":"Multifamily","amount":"About $1 million demanded in NFI's 2022 pre-suit notice; insurer's estimates of $37,058.29 and $61,839.72 fell below the $359,856.60 deductible","amountUsd":1000000,"amountBasis":"claim","source":"live","sourceUrl":"https://www.ca5.uscourts.gov/opinions/unpub/25/25-50953.0.pdf","summary":"On October 20, 2026, the Fifth Circuit affirmed summary judgment for Third Coast Insurance Company against NFI Apartment Management, L.L.C. over a May 2020 hailstorm claim on a San Antonio apartment complex. Third Coast's July 21, 2020 letter said it could not pay because the covered loss, estimated at $37,058.29, did not exceed the policy's $359,856.60 deductible, and it closed the claim on July 28, 2021, after a reinspection estimate of $61,839.72. The court held NFI's claims accrued no later than the file closing, so its July 2024 suit was untimely under the policy's two-years-and-one-day limit and the two-year statutory periods.","significance":"The decision holds that under Texas law an insurer's below-deductible determination is a denial of coverage that starts the limitations period, even though the insurer acknowledges some covered damage. It also holds that later reinspections and correspondence did not restart the clock or bar the insurer's limitations defense where the insurer stood by its decision and reserved its rights.","judge":"Per curiam (Elrod, C.J.; Richman and Ramirez, JJ.)","parties":[{"name":"NFI Apartment Management, L.L.C.","role":"Plaintiff-Appellant"},{"name":"Third Coast Insurance Company","role":"Defendant-Appellee"}],"tags":["insurance coverage","hail damage","multifamily","limitations period","fifth circuit"],"docketUrl":"https://www.courtlistener.com/docket/69463265/nfi-apartment-management-llc-v-third-coast-insurance-company/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-363","addedDate":"2026-11-03","title":"Sinmier, LLC v. Everest Indemnity Insurance Co. (Sixth Circuit Affirms Lender's Insurance Claims Died With Its Own Settlement)","brief":"The Sixth Circuit held lender Sinmier's deed-in-lieu settlement with borrower Vintro extinguished its insurable mortgagee interest, defeating its claims against the resort's insurance broker and insurers.","category":"lending-foreclosure","status":"ruling","date":"2026-11-02","jurisdiction":"U.S. Court of Appeals for the Sixth Circuit (N.D. Ohio)","state":"OH","propertyType":"Hospitality","amount":"$7 million loan; Vintro's property claim drew a $350,000 advance and a $775,000 settlement; Vintro and its owner agreed to pay Sinmier $627,375, which the court said Sinmier apparently has not fully recovered","amountUsd":7000000,"amountBasis":"loan","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11052174/sinmier-llc-v-everest-indemnity-ins-co/","summary":"On November 2, 2026, the Sixth Circuit affirmed summary judgment against commercial real estate lender Sinmier, LLC in its suit against the insurance broker, insurer and underwriter of its former borrower, Vintro Hotels and Resorts Ohio LLC, over the Maui Sands Resort and Waterpark in Sandusky, Ohio. The court held that Sinmier's October 2019 settlement, under which Vintro's deed in lieu of foreclosure was \"considered payment in full\" of its loan obligations, extinguished Sinmier's insurable interest as mortgagee, and every claim depended on that interest.","significance":"Applying Ohio law, the court treated a mortgagee's insurable interest as lasting only as long as the debt: once a settlement fully releases the debt, claims premised on the mortgagee interest fall away. The court also held that Sinmier forfeited several arguments by not raising them in the district court.","judge":"Jeffrey S. Sutton","parties":[{"name":"Sinmier, LLC","role":"Plaintiff-Appellant"},{"name":"Everest Indemnity Insurance Company","role":"Defendant-Appellee"},{"name":"Bearing Insurance Group, LLC","role":"Defendant-Appellee"},{"name":"EverSports & Entertainment Insurance, Inc.","role":"Defendant-Appellee"},{"name":"Vintro Hotels and Resorts Ohio LLC","role":"Borrower (non-party on appeal)"}],"tags":["insurance coverage","deed in lieu of foreclosure","mortgagee interest","hotel","sixth circuit"],"docketUrl":"https://www.courtlistener.com/docket/72333986/sinmier-llc-v-everest-indemnity-insurance-company/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-364","addedDate":"2026-11-03","title":"Norhaven Partners, LLC v. Bartow County (Georgia Court of Appeals Affirms County's Industrial Conditional Use Permit Over Developer's Zoning Challenge)","brief":"Georgia's Court of Appeals upheld Bartow County's permit for a waste-processing expansion beside Norhaven's planned 97-unit townhome site, holding a 1,000-foot buffer covers only built dwellings.","category":"zoning-land-use","status":"ruling","date":"2026-11-02","jurisdiction":"Court of Appeals of Georgia","state":"GA","propertyType":"Industrial","amount":null,"amountUsd":null,"source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11052005/norhaven-partners-llc-v-bartow-county/","summary":"On November 2, 2026, the Court of Appeals of Georgia affirmed the denial of Norhaven Partners, LLC and Peeples Owner LLC's petition for review of the Bartow County Commissioner's grant of a conditional use permit to Rice Commercial Investments, Inc. and its owner. The permit lets Rice expand its heavy-industrial site next to Norhaven's planned 97-unit townhome community to add a recovered-materials processing and solid-waste handling facility for construction and demolition materials. The court held that the county's 1,000-foot buffer between waste handling areas and residential dwellings covers only dwellings actually built at the time of the application, and none had been built.","significance":"The ruling reads the buffer rule to protect existing buildings, not approved but unbuilt residential lots, so a developer's approved site plan alone did not trigger it. The court also found that the trial court erred in confining its review to the hearing transcript, but held the error harmless.","judge":"Sara L. Doyle","parties":[{"name":"Norhaven Partners, LLC","role":"Petitioner-Appellant"},{"name":"Peeples Owner LLC","role":"Petitioner-Appellant"},{"name":"Bartow County","role":"Respondent-Appellee"},{"name":"Rice Commercial Investments, Inc.","role":"Respondent-Appellee (permit holder)"}],"tags":["zoning","conditional use permit","industrial","land use","georgia"],"hasFull":true},{"id":"live-365","addedDate":"2026-11-03","title":"PowerHouse Hillwood Holding LLC v. Commonwealth Edison Co. ($1 Letter of Credit Dispute Puts $20B Joliet Data Center on Hold)","brief":"Hillwood's $20 billion Joliet data center plans are on hold after it offered ComEd a $1 letter of credit against a $587 million guarantee demand and ComEd scrapped the deal; Hillwood's suit is pending in federal court in Chicago.","category":"zoning-land-use","status":"pending","date":"2026-07-26","jurisdiction":"U.S. District Court for the Northern District of Illinois","state":"IL","amount":"$20 billion data center campus; ComEd sought a $587 million guarantee, Hillwood offered a $1 letter of credit","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/11/02/1-offer-threatens-20b-joliet-data-center-deal-from-hillwood/","summary":"PowerHouse Hillwood's plan for a $20 billion, roughly 800-acre data center campus in Joliet is on hold, The Real Deal reported on November 2, 2026, citing Crain's. Commonwealth Edison sought a financial guarantee that Crain's put at $587 million. Hillwood offered a $1 letter of credit, arguing that the full amount is not due until power reaches the site around 2029, and ComEd scrapped the deal and the related electricity agreement. Hillwood's suit against ComEd is pending in the U.S. District Court for the Northern District of Illinois, where the judge declined to reinstate the retail electricity agreement because that question belongs to the Illinois Commerce Commission.","significance":"The case shows that the credit-support terms in a utility power agreement, often treated as boilerplate, can stall a multibillion-dollar data center before construction starts. Developers, lenders and equity partners on large data center sites should pin down when, and how much, security is owed before relying on a power commitment.","judge":"Sara L. Ellis","parties":[{"name":"PowerHouse Hillwood Holding LLC","role":"Plaintiff"},{"name":"Commonwealth Edison Company","role":"Defendant"}],"amountUsd":null,"propertyType":"Data Center","tags":["data center","illinois","ferc","utility dispute","joliet"],"docketUrl":"https://www.courtlistener.com/docket/73673010/powerhouse-hillwood-holding-llc-v-commonwealth-edison-company/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-366","addedDate":"2026-11-03","title":"Wells Fargo Bank, N.A. v. Tech Park Owner LLC (Rochester Tech Park $96.9M Foreclosure)","brief":"Wells Fargo seeks summary judgment in its foreclosure on Rochester Tech Park, a 288-acre office and industrial complex in Gates, alleging the owner and guarantors owe $96.9 million in principal.","category":"lending-foreclosure","status":"pending","date":"2026-10-22","jurisdiction":"Supreme Court of the State of New York, Monroe County","state":"NY","amount":"$96.9 million in principal alleged owed, plus interest and fees","source":"live","sourceUrl":"https://rbj.net/2026/10/22/wells-fargo-summary-judgment-rochester-tech-park-foreclosure/","summary":"Wells Fargo Bank, N.A., which provided just over $110 million in loans on Rochester Tech Park in 2017, has asked a Monroe County court for summary judgment in its 18-month-old foreclosure against Tech Park Owner LLC, the Rochester Business Journal reported on October 22, 2026. The lender alleges the owner and two guarantors defaulted and owe $96.9 million in principal plus interest, and it also details $2.356 million it paid Rochester Gas & Electric in 2024 to restore and keep power at the property. Justice Daniel J. Doyle is scheduled to hear arguments on January 12, 2027.","significance":"The lender's emergency utility payments show how a borrower's unpaid operating bills can be added to what a lender claims. A receiver has run the property for more than a year, and close to two dozen tenants remain.","judge":"Daniel J. Doyle","parties":[{"name":"Wells Fargo Bank, N.A.","role":"Lender"},{"name":"Tech Park Owner LLC","role":"Borrower"}],"amountUsd":96900000,"amountBasis":"loan","propertyType":"Mixed-Use","tags":["foreclosure","receivership","new york","industrial","rochester"],"hasFull":true},{"id":"live-368","addedDate":"2026-11-04","title":"Resident Sues Botetourt County Over Closed-Session Approval of Google Data Center Agreement","brief":"A Botetourt County resident sued to void the county's performance agreement for Google's data center campus, alleging supervisors agreed to it in a closed meeting and approved it without disclosing its substance.","category":"zoning-land-use","status":"filed","date":"2026-11-02","jurisdiction":"Botetourt County Circuit Court, Virginia","state":"VA","amount":"Performance agreement that set in motion Google's $14 million purchase of 312 acres","source":"live","sourceUrl":"https://cardinalnews.org/2026/11/02/lawsuit-claims-botetourt-countys-data-center-agreement-with-google-is-invalid/","summary":"A Botetourt County, Virginia resident filed suit in Botetourt County Circuit Court on November 2, 2026, asking the court to invalidate the county's June 2025 economic development performance agreement with Helio Capital LLC, the company behind Google's data center project at the Botetourt Center at Greenfield, Cardinal News reported. The suit alleges the Board of Supervisors discussed the agreement in a closed meeting on June 24, 2025 that its published agenda did not disclose, then approved it 5-0 without discussion after adding it as a walk-on item, in violation of Virginia's Freedom of Information Act. The county said it would not comment on pending litigation.","significance":"The case tests whether an open-meetings defect in how a locality approved an incentive agreement can unwind the approvals that followed, including expedited permits, for a data center campus already under construction. Developers negotiating performance agreements with local governments have reason to watch how the court treats the closed-session record.","judge":null,"parties":[{"name":"Botetourt County Board of Supervisors","role":"Defendant"},{"name":"Botetourt County","role":"Defendant"},{"name":"Botetourt County Economic Development Authority","role":"Defendant"},{"name":"Helio Capital LLC","role":"Defendant"}],"amountUsd":14000000,"amountBasis":"purchase price","propertyType":"Data Center","tags":["data-center","zoning-land-use","foia","virginia","google"],"hasFull":true},{"id":"live-369","addedDate":"2026-11-04","featured":true,"title":"Phoenix Must Show Data-Center Rules Protect Public Health or Face $54M Prop 207 Claim, Judge Rules","brief":"A Texas developer suing Phoenix over its data-center permit rules kept alive its Proposition 207 claim for more than $54 million in lost property value; the city must justify the ordinance at a Nov. 17 hearing.","category":"zoning-land-use","status":"ruling","date":"2026-10-28","jurisdiction":"Maricopa County Superior Court, Arizona","state":"AZ","amount":"More than $54 million in lost property value claimed","source":"live","sourceUrl":"https://www.kjzz.org/politics/2026-10-28/court-phoenix-must-prove-data-center-rules-are-a-necessary-protection-or-face-54m-lawsuit","summary":"A Maricopa County Superior Court judge ruled earlier in October 2026 that the City of Phoenix must prove at a full evidentiary hearing that its 2025 data-center ordinance is necessary to guard public health, or face a claim by Texas developer West Buckeye Road L.P. (WBR) for more than $54 million in lost property value under Arizona's Proposition 207, KJZZ reported. The judge rejected WBR's separate claim that the ordinance itself lets a developer sue the city for compensation. The hearing is set for Nov. 17, 2026.","significance":"The ruling puts Phoenix's special-permit requirement for data centers to a test under Proposition 207, which requires compensation when a new land-use law lowers property values unless the rule falls within an exemption such as protecting public health. The city will have to make that showing with evidence rather than win dismissal outright.","judge":null,"parties":[{"name":"West Buckeye Road L.P.","role":"Plaintiff"},{"name":"City of Phoenix","role":"Defendant"}],"amountUsd":54000000,"amountBasis":"claim","propertyType":"Industrial","tags":["zoning","data-center","proposition-207","takings","arizona"],"hasFull":true},{"id":"live-370","addedDate":"2026-11-05","featured":true,"title":"Ameream LLC v. Borough of East Rutherford (Tax Court Freezes American Dream Mall's 2025 Assessment for 2026)","brief":"New Jersey's Tax Court held the Freeze Act binds East Rutherford to the American Dream Mall's $1.65 billion 2025 assessment for tax year 2026, rejecting arguments from the borough and the bondholder trustee.","category":"lending-foreclosure","status":"ruling","date":"2026-10-30","jurisdiction":"New Jersey Tax Court","state":"NJ","amount":"$1,653,960,000 assessment frozen for tax year 2026; borough had assessed $1,899,992,100","source":"live","sourceUrl":"https://www.njcourts.gov/court-opinion/ameream-llc-v-borough-of-east-rutherford-published-tax","summary":"On October 30, 2026, New Jersey Tax Court Judge Michael J. Gilmore granted American Dream Mall owner Ameream LLC's motion under the state's Freeze Act, holding that the court's July 31, 2025 judgment setting the properties' cumulative assessment at $1,653,960,000 binds the Borough of East Rutherford for tax year 2026. The borough had raised the assessment to $1,899,992,100. The court rejected arguments by the borough and amicus US Bank and Trust Company, trustee for the bondholders, that the mall's payment-in-lieu-of-taxes arrangement, a change in value, or the borough's yearly reassessment defeated the freeze.","significance":"The court held that a PILOT property whose payments are set from its assessed value can invoke the Freeze Act, and that a municipality's routine yearly reassessment is not the 'complete reassessment' that ends a freeze. The ruling also confirms that unquantified evidence of market improvement does not prove a change in value.","judge":"Michael J. Gilmore","parties":[{"name":"Ameream LLC","role":"Plaintiff (owner and developer)"},{"name":"Borough of East Rutherford","role":"Defendant"},{"name":"US Bank and Trust Company","role":"Amicus curiae (bondholder trustee)"}],"amountUsd":1899992100,"amountBasis":"other","propertyType":"Retail","tags":["property-tax","freeze-act","pilot-bonds","new-jersey","mall"],"hasFull":true},{"id":"live-371","propertyType":"Office","addedDate":"2026-11-05","title":"Wells Fargo Bank v. 250 Livingston Owner LLC, Clipper Realty Inc. and Clipper Realty L.P. (CMBS Foreclosure)","brief":"Wells Fargo, as trustee for a CMBS trust, sued to foreclose the $125 million loan on Clipper Realty's 250 Livingston Street in Brooklyn after city agencies vacated; a court appointed a temporary receiver in April 2026.","category":"lending-foreclosure","status":"ruling","date":"2026-04-29","jurisdiction":"Supreme Court of the State of New York, Kings County","state":"NY","amount":"$125 million CMBS loan in default","source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/1649096/000143774926034925/clpr20260930_10q.htm","summary":"Wells Fargo Bank, National Association, as trustee for GS Mortgage Securities Trust 2019-GC40, sued 250 Livingston Owner LLC, Clipper Realty Inc. and Clipper Realty L.P. in Kings County Supreme Court on March 25, 2026 over defaults on the $125 million mortgage loan secured by 250 Livingston Street in Brooklyn, according to Clipper's Form 10-Q filed November 4, 2026. The court granted the lender's request for a temporary receiver on April 29, 2026. Under a consent and cooperation agreement effective June 4, 2026, the parties agreed to jointly market the loan for sale, after which the lender may foreclose or take a deed in lieu; Clipper reported that as of November 4 the lender had done neither.","significance":"The filing traces how the loss of a single government tenant led to a CMBS default and a court-appointed receiver within months. It also shows that a consent agreement giving the borrower a marketing period and a right to bid for its own loan can delay, but not remove, the lender's foreclosure rights.","judge":null,"parties":[{"name":"Wells Fargo Bank, National Association","role":"Plaintiff/Trustee"},{"name":"250 Livingston Owner LLC","role":"Defendant/Borrower"},{"name":"Clipper Realty Inc.","role":"Defendant/Guarantor"},{"name":"Clipper Realty L.P.","role":"Defendant/Guarantor"}],"amountUsd":125000000,"amountBasis":"loan","tags":["cmbs","foreclosure","receivership","office","brooklyn"],"hasFull":true},{"id":"live-372","propertyType":"Land/Development","addedDate":"2026-11-05","title":"JZ Investments, Inc. v. Belpointe PREP, LLC (Mansfield, Conn. Development Stake Dispute)","brief":"JZ Investments sued Belpointe PREP, two related entities and a former partner, alleging fraud and a settlement cost it its stake in a planned 262-unit development near UConn; Belpointe disputes liability.","category":"reit-securities","status":"pending","date":"2026-04-24","jurisdiction":"Connecticut Superior Court, Stamford","state":"CT","amount":"Restoration of JZ's preferred equity interest, declaratory relief and damages (amount not reported)","source":"live","sourceUrl":"https://hartfordbusiness.com/article/ct-investor-sues-over-alleged-fraud-in-stalled-housing-project-near-uconns-main-campus/","summary":"JZ Investments, Inc. sued Belpointe PREP, LLC, BPOZ Storrs Holding, LLC, CMC Storrs SPV, LLC and a former business partner in Connecticut Superior Court on April 24, 2026, according to Belpointe's quarterly SEC filings. JZ alleges the former partner acted fraudulently and Belpointe negligently in connection with a settlement agreement that it says cost it its preferred equity interest in the venture behind a planned 262-unit development at 497-501 Middle Turnpike in Mansfield, near UConn's main campus. Belpointe says it disputes any liability and has moved to dismiss.","significance":"The dispute shows how an investor in a development joint venture can lose its stake through a settlement it says it never authorized, and how the sponsor that ends up controlling the project can be drawn into the fight. Belpointe's pending motion to dismiss will determine whether the claims against it move forward.","judge":null,"parties":[{"name":"JZ Investments, Inc.","role":"Plaintiff"},{"name":"Belpointe PREP, LLC","role":"Defendant"},{"name":"BPOZ Storrs Holding, LLC","role":"Defendant"},{"name":"CMC Storrs SPV, LLC","role":"Defendant"}],"amountUsd":null,"amountBasis":null,"tags":["joint-venture","opportunity-zone","connecticut","multifamily","development"],"hasFull":true},{"id":"live-373","addedDate":"2026-11-06","title":"Columbus v. Ohio Wholesale Auto Sales, L.L.C. (Ohio Appeals Court Revives Lender's Claim in Condemnation Case)","brief":"Ohio's Tenth District held that a foreclosure suit dismissed after the lender never served the owner was not a ruling on the merits, so it could not bar the lender's mortgage claim in Columbus's eminent domain case.","category":"eminent-domain","status":"ruling","date":"2026-11-05","jurisdiction":"Ohio Court of Appeals, Tenth Appellate District (Franklin County)","state":"OH","amount":"$4,014 condemnation payment at issue; mortgage interest's share yet to be determined on remand","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11055776/columbus-v-ohio-wholesale-auto-sales-llc/","summary":"The Tenth District Court of Appeals of Ohio reversed a Franklin County judgment that had barred mortgagee Wiltshire Capital Partners, LP from asserting any interest in the City of Columbus's appropriation of part of a property owned by Ohio Wholesale Auto Sales, LLC. The trial court had treated the 2018 dismissal of Wiltshire's own foreclosure suit, entered for failure to prosecute, as res judicata. The appellate court held that because Wiltshire never obtained service on the owner in that suit, the dismissal was not an adjudication on the merits, and it remanded so Wiltshire can press its claim. The court made no finding on whether Wiltshire's mortgage is valid.","significance":"The decision limits how far a condemnation court can rely on a lender's abandoned foreclosure case to shut it out of an appropriation award. It leaves the remaining questions, including whether the mortgage is valid and enforceable, for the trial court on remand.","judge":"Dingus, J. (Edelstein and Leland, JJ., concurring)","parties":[{"name":"City of Columbus","role":"Petitioner-Appellee"},{"name":"Ohio Wholesale Auto Sales, LLC","role":"Respondent-Appellee"},{"name":"Wiltshire Capital Partners, LP","role":"Respondent-Appellant"}],"amountUsd":4014,"amountBasis":"award","tags":["eminent-domain","mortgage","res-judicata","ohio","condemnation"],"hasFull":true},{"id":"live-374","addedDate":"2026-11-06","title":"Ritz-Carlton Development Co. Loses Appeal Over Eagle County Valuation of Bachelor Gulch Fractional Units","brief":"Colorado's Court of Appeals upheld Eagle County's doubled valuation of 54 fractionally owned units at the Ritz-Carlton Bachelor Gulch, rejecting Ritz-Carlton Development Co.'s appeal.","category":"zoning-land-use","status":"ruling","date":"2026-11-05","jurisdiction":"Colorado Court of Appeals","state":"CO","amount":"Eagle County assessor's valuation, which doubled the prior value, affirmed; dollar figures not reported in the source","source":"live","sourceUrl":"https://news.bloombergtax.com/daily-tax-report-international/ritz-carlton-timeshares-tax-value-maintained-by-colorado-court","summary":"The Colorado Court of Appeals on November 5, 2026 upheld the Eagle County Assessor's valuation of 54 fractionally owned condominium units attached to the Ritz-Carlton Bachelor Gulch Hotel and Spa in Beaver Creek, Bloomberg Tax reported. Ritz-Carlton Development Co., a division of Marriott International, had argued the assessor was wrong to double the units' previous valuation. In an unpublished opinion, the court sided with the county and rejected RCDC's argument based on a two-step analysis.","significance":"The result leaves in place a county valuation of fractional resort units that doubled their prior assessed value. Because the opinion is unpublished, it is not binding precedent in other Colorado cases.","judge":null,"parties":[{"name":"Ritz-Carlton Development Co.","role":"Taxpayer"},{"name":"Eagle County","role":"Assessor"}],"amountUsd":null,"amountBasis":null,"tags":["property tax","timeshare","fractional ownership","hospitality","colorado"],"hasFull":true},{"id":"live-375","addedDate":"2026-11-06","title":"Torchlight Sues Prime Group to Halt LaSalle Street Office Conversion Above JW Marriott Chicago","brief":"Torchlight Loan Services, special servicer for the JW Marriott Chicago's bondholders, sued Prime Group to stop an apartment conversion above the hotel, saying the work cut the hotel's phones and internet on a sold-out day.","category":"lending-foreclosure","status":"filed","date":"2026-10-30","jurisdiction":"Circuit Court of Cook County, Illinois, Chancery Division","state":"IL","amount":"Injunctive relief sought; no damages figure stated","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/11/04/torchlight-sues-reschkes-firm-to-stop-loop-conversion/","summary":"Torchlight Loan Services, special servicer for the CMBS bondholders who took the 610-key JW Marriott Chicago through foreclosure, sued Prime Group in Cook County Circuit Court on October 30, 2026. The complaint says a Prime electrical subcontractor cut power to the hotel's phone and internet equipment on October 27, a sold-out day, and that a 2014 easement agreement requires the hotel's consent for work that disrupts shared systems. Torchlight wants the conversion work stopped until Prime has that consent. Prime's Mike Reschke said he was surprised by the suit because the two sides had been meeting regularly about construction, The Real Deal reported.","significance":"Office-to-apartment conversions in buildings shared with hotels depend on easement and consent terms as much as on construction budgets. A lender that takes over a hotel in such a building can use those terms to stop work that disrupts operations, so developers should line up consents and plan shutdowns of shared systems before demolition begins.","judge":null,"parties":[{"name":"Torchlight Loan Services","role":"Plaintiff / Special Servicer"},{"name":"Prime Group","role":"Defendant / Developer"}],"amountUsd":null,"tags":["cmbs","chicago","hotel-conversion","special-servicer","lasalle-street"],"hasFull":true},{"id":"live-376","addedDate":"2026-11-07","featured":true,"propertyType":"Office","title":"CommunityAmerica Credit Union v. Liberty 35 Wacker LLC (Leo Burnett Building Foreclosure)","brief":"CommunityAmerica Credit Union sued in Cook County to foreclose the $220 million loan on 35 West Wacker Drive, the Leo Burnett Building, saying borrower Liberty 35 Wacker LLC, an entity of Shaya Prager's Opal Holdings, owes $236 million.","category":"lending-foreclosure","status":"filed","date":"2026-11-03","jurisdiction":"Circuit Court of Cook County, Illinois, Chancery Division","state":"IL","amount":"$236 million claimed due on a $220 million loan","source":"live","sourceUrl":"https://therealdeal.com/chicago/2026/11/05/shaya-pragers-35-west-wacker-faces-236m-foreclosure-suit/","summary":"CommunityAmerica Credit Union filed suit in Cook County Circuit Court on November 3, 2026 to foreclose the $220 million loan on 35 West Wacker Drive, the 50-story Leo Burnett Building, claiming $236 million is due from borrower Liberty 35 Wacker LLC, an entity of Shaya Prager's Opal Holdings. The complaint cites unpaid property taxes, missed loan payments since July, and a default triggered when a bankruptcy case against Prager, who guaranteed the loan, was not dismissed within 90 days. The credit union says it will separately ask the court to appoint a receiver. Prager and Opal did not immediately respond to The Real Deal's requests for comment.","significance":"A well-occupied tower can still end up in foreclosure when the sponsor's wider finances trigger loan defaults, here through unpaid taxes and a clause tied to a bankruptcy case against the guarantor. Lenders and co-investors should read guaranty and bankruptcy-default provisions closely, because a pending case against a guarantor can both trigger a default and delay collection from that guarantor.","judge":null,"parties":[{"name":"CommunityAmerica Credit Union","role":"Plaintiff"},{"name":"Liberty 35 Wacker LLC","role":"Defendant / Borrower"},{"name":"Liberty 35 Wacker Member LLC","role":"Defendant / Guarantor"}],"amountUsd":236000000,"amountBasis":"loan","tags":["cmbs-style-foreclosure","chicago","office","receivership","personal-guaranty"],"hasFull":true},{"id":"live-377","addedDate":"2026-11-07","propertyType":"Retail","title":"Fountain Place, LLC v. City of Logan Development Authority (Tax-Rebate Development Agreement Dismissal Affirmed)","brief":"West Virginia's Intermediate Court of Appeals affirmed dismissal of a shopping center owner's suit over a 57% business-tax rebate the City of Logan stopped paying in 2021 under a 1997 annexation deal.","category":"zoning-land-use","status":"ruling","date":"2026-11-06","jurisdiction":"Intermediate Court of Appeals of West Virginia","state":"WV","amount":"Ongoing 57% share of the shopping center's business-and-occupancy tax revenue (no total dollar figure stated)","source":"live","sourceUrl":"https://www.courtswv.gov/sites/default/pubfilesmnt/2026-11/25-ICA-334%20Opinion.pdf","summary":"West Virginia's Intermediate Court of Appeals on November 6, 2026 affirmed the dismissal of Fountain Place, LLC's breach-of-contract suit against the City of Logan and the dissolved City of Logan Development Authority over a 1997 agreement that paid the shopping center's owner 57% of the city's business-and-occupancy taxes collected at the center in exchange for not opposing annexation. The court held that a state statute makes a development authority's debts its own, not the city's, that the authority's liabilities did not pass to the city when it dissolved, and that the city was not estopped by years of payments. It remanded for the city's pending counterclaims.","significance":"The court held that a city does not inherit a dissolved development authority's payment obligations under West Virginia's development-authority statutes, and that estoppel generally does not run against a city acting in a governmental capacity. It did not decide whether the agreement was unconstitutional municipal debt never put to voters, the ground the circuit court reached first.","judge":"Ryan White","parties":[{"name":"Fountain Place, LLC","role":"Petitioner"},{"name":"City of Logan Development Authority","role":"Respondent"},{"name":"City of Logan, West Virginia","role":"Respondent"},{"name":"Fountain Place Realty, LLC","role":"Respondent"},{"name":"Namdar DG Realty, LLC","role":"Respondent"}],"amountUsd":null,"tags":["tax-incentive","development-agreement","municipal-immunity","west-virginia","shopping-center"],"hasFull":true},{"id":"live-378","addedDate":"2026-11-07","propertyType":"Industrial","title":"City of Chicago Dept. of Public Health v. City of Chicago Dept. of Administrative Hearings (Southeast Side Recycling Permit Denial Reinstated)","brief":"An Illinois appeals court reinstated Chicago's 2022 denial of a large recycling facility permit for RMG affiliate General III on the Southeast Side, reversing a hearing officer who had vacated it.","category":"environmental","status":"ruling","date":"2026-11-06","jurisdiction":"Appellate Court of Illinois, First District","state":"IL","amount":"No damages at issue; General III says it spent about $80 million building the facility","amountUsd":null,"source":"live","sourceUrl":"https://storage.courtlistener.com/pdf/2026/11/06/city_of_chicago_department_of_public_health_v._city_of_chicago_department.pdf","summary":"On November 6, 2026, the Appellate Court of Illinois, First District, affirmed a Cook County circuit court order that reversed an administrative law judge and reinstated the Chicago Department of Public Health's February 2022 denial of a large recycling facility permit for General III, LLC. General III, 80% owned by Reserve Management Group entities, sought to operate the facility at RMG's site at 116th Street and Burley Avenue on the city's Southeast Side. The court held the department was authorized to rely on a health impact assessment and on the compliance history of affiliated entities, and rejected General III's claim of a vested right to the permit.","significance":"The decision holds that Chicago's public health commissioner may use a health impact assessment, a tool not named in the city code, under the department's general public-health and study powers when deciding an industrial permit. It also holds that a zoning approval and spending on construction before a permit is granted did not give the applicant a vested right to the permit.","judge":"Pucinski (Hyman and Evans, JJ., concurring)","parties":[{"name":"City of Chicago Department of Public Health","role":"Plaintiff-Appellee"},{"name":"City of Chicago Department of Administrative Hearings","role":"Defendant"},{"name":"General III, LLC","role":"Defendant-Appellant"}],"tags":["environmental-justice","recycling-facility","chicago","industrial-permit","zoning"],"hasFull":true},{"id":"live-379","addedDate":"2026-11-07","title":"ZOM Holding Files Chapter 11 After $308.6M Arizona Judgment in Gray Development Dispute","brief":"ZOM Holding Inc. and two affiliates filed Chapter 11 in Florida after a $308.6 million Arizona judgment for Gray Development Group. The debtors plan an asset sale and want ZOM's appeal of the judgment to continue.","category":"lending-foreclosure","status":"filed","date":"2026-10-30","jurisdiction":"U.S. Bankruptcy Court, Middle District of Florida","state":"FL","amount":"$308.6M judgment plus interest; about $541M in estimated unsecured claims across the debtors","amountUsd":308600000,"amountBasis":"judgment","source":"live","sourceUrl":"https://therealdeal.com/miami/2026/11/03/zom-living-files-for-bankruptcy-after-308-million-judgment/","summary":"ZOM Holding Inc., ZOM Associates and ZH Development I, affiliates of Winter Park, Florida-based developer ZOM Living, filed Chapter 11 petitions on October 30, 2026 in the U.S. Bankruptcy Court for the Middle District of Florida, where the cases are jointly administered. The filing follows a $308.6 million judgment, plus interest, entered in May by a Maricopa County court after a unanimous jury verdict for Gray Development Group, which alleged ZOM took its proprietary project information and then pursued the Arizona projects on its own. ZOM is appealing, and the debtors have asked the bankruptcy court to let that appeal continue while they run a sale of substantially all of their assets, with non-debtor affiliate ZOM Holding LP as the proposed stalking horse and lender.","significance":"The case shows how a joint venture that never closes can still produce damages measured by the profits of a whole project pipeline when the developer signed a non-circumvention agreement. It also shows a judgment debtor using Chapter 11 to keep its property-owning affiliate out of bankruptcy, keep its appeal alive and run a sale on its own timetable, which creditors and prospective partners should expect after a large verdict.","judge":"Grace E. Robson","parties":[{"name":"ZOM Holding, Inc.","role":"Debtor"},{"name":"ZOM Associates","role":"Debtor"},{"name":"ZH Development I","role":"Debtor"},{"name":"ZOM Holding LP","role":"Non-Debtor Affiliate / Proposed DIP Lender and Stalking Horse"},{"name":"Gray Development Group","role":"Judgment Creditor"}],"tags":["chapter-11","joint-venture","non-circumvention","multifamily","appeal"],"docketUrl":"https://www.courtlistener.com/docket/75047315/zom-holding-inc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-380","addedDate":"2026-11-09","featured":true,"propertyType":"Multifamily","title":"AB Realty, LLC v. Scott Lane (Eighth Circuit Affirms Dismissal of Apartment Owner's Claims Over Omaha Code-Enforcement Closure)","brief":"The Eighth Circuit affirmed dismissal of AB Realty's civil-rights suit over Omaha's 2018 closure of the Yale Park Apartment Complex, holding the inspection warrant was supported even without the disputed statements.","category":"zoning-land-use","status":"ruling","date":"2026-11-06","jurisdiction":"U.S. Court of Appeals for the Eighth Circuit","state":"NE","amount":"No dollar figure stated","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11056715/ab-realty-llc-v-scott-lane/","documentUrl":"https://ecf.ca8.uscourts.gov/opndir/26/11/252082P.pdf","documentLabel":"Read the official opinion","summary":"The Eighth Circuit affirmed dismissal of the federal civil-rights suit that AB Realty, LLC, owner of the Yale Park Apartment Complex in Omaha, and two individual plaintiffs brought against the City of Omaha, city housing officials and two housing advocates over the city's September 2018 closure of the complex for code violations. The court held that the inspection warrant application established probable cause even without the statements the plaintiffs said were false, that the due-process claims did not identify what protected interests were at stake or who violated them, and that neither a per se nor a regulatory taking was pleaded.","significance":"The ruling shows that an owner challenging an administrative inspection warrant must show the application fails even after the disputed statements are set aside, and that a state-law consent requirement does not by itself support a federal claim. It also shows that due-process and takings claims arising from a code-enforcement closure must identify the specific interest and the type of taking alleged.","judge":"Jonathan A. Kobes","parties":[{"name":"AB Realty, LLC","role":"Plaintiff-Appellant"},{"name":"City of Omaha","role":"Defendant-Appellee"}],"amountUsd":null,"tags":["multifamily","code-enforcement","fourth-amendment","takings","omaha"],"docketUrl":"https://www.courtlistener.com/docket/14669317/ab-realty-llc-v-lane/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-381","addedDate":"2026-11-09","propertyType":"Industrial","title":"Bethlehem Landfill Co. v. Lower Saucon Twp. (Pennsylvania Court Quashes Landfill Operator's Appeal in Sunshine Act Suit)","brief":"Pennsylvania's Commonwealth Court quashed Bethlehem Landfill Company's appeal in its suit over Lower Saucon Township's reversal on a landfill expansion, because the trial court let some claims be amended and its order was not final.","category":"zoning-land-use","status":"ruling","date":"2026-11-06","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"No dollar figure stated","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11056652/bethlehem-landfill-co-v-lower-saucon-twp/","documentUrl":"https://www.pacourts.us/assets/opinions/Commonwealth/out/737CD25_11-6-2026.pdf","documentLabel":"Read the official opinion","summary":"Bethlehem Landfill Company sued Lower Saucon Township, its council, three council members and the township solicitor in May 2024, alleging Sunshine Act violations after the township, under a new council majority, switched sides in neighbors' litigation challenging the 2023 rezoning for the landfill's expansion. The Northampton County Court of Common Pleas dismissed several counts but gave the company leave to amend its conflict-of-interest claims against one council member. On November 6, 2026, the Commonwealth Court granted the township's motion to quash the company's appeal, holding the order was interlocutory because the company neither filed an amended complaint nor asked the trial court to enter a final dismissal.","significance":"The ruling shows the step a party must take before appealing an order that dismisses some claims and allows others to be amended: let the amendment period run and ask the trial court to dismiss, or seek a determination of finality. Because the appeal was quashed, the dispute over the township's change of position returns to the trial court with the merits undecided.","judge":"Anne E. Covey","parties":[{"name":"Bethlehem Landfill Company","role":"Appellant"},{"name":"Lower Saucon Township","role":"Appellee"},{"name":"Lower Saucon Township Council","role":"Appellee"}],"amountUsd":null,"tags":["landfill","rezoning","sunshine-act","pennsylvania","industrial"],"hasFull":true},{"id":"live-382","addedDate":"2026-11-09","featured":true,"title":"Illinois Appellate Court Holds Commercial Landlords May Assign Claims for Tenants' Unpaid Rent","brief":"An Illinois appellate court held that a landlord's claim for a tenant's past-due, unpaid rent can be assigned, reversing a Cook County dismissal for lack of standing in a suit against a Chicago commercial tenant.","category":"lease-disputes","status":"ruling","date":"2026-11-09","jurisdiction":"Appellate Court of Illinois, First District","state":"IL","amount":"No dollar figure stated","source":"live","sourceUrl":"https://www.illinoiscourts.gov/resources/1c390993-0f1d-4885-a638-bb93fbb2a028/file","documentUrl":"https://www.illinoiscourts.gov/resources/1c390993-0f1d-4885-a638-bb93fbb2a028/file","documentLabel":"Read the official opinion","summary":"The Appellate Court of Illinois, First District, held on November 9, 2026 that a landlord may assign its claim for past-due, unpaid rent, reversing a Cook County circuit court that had dismissed the assignees' suit against a Chicago commercial tenant for lack of standing. The circuit court had relied on an 1872 Illinois Supreme Court decision holding that rents in arrears are not assignable and on a 2018 First District opinion that quoted it. The panel found that rule inconsistent with the Supreme Court's modern view that assignability is the rule, and remanded for the circuit court to consider the tenant's other grounds for dismissal.","significance":"The opinion separates a claim for rent already owed, which stays with the landlord to whom it was owed and does not pass to a later buyer of the property, from the right to future rent, which runs with the land. It holds the former can be assigned, so a former landlord's assignee may sue for it in Illinois.","judge":"David W. Ellis","parties":[{"name":"Affordable Portables, Inc., d/b/a Philips Interiors","role":"Tenant/Defendant-Appellee"},{"name":"2600 N. Clark Street, LLC","role":"Former landlord; assignor of the rent claim (non-party)"}],"amountUsd":null,"tags":["commercial-lease","unpaid-rent","assignment","illinois","standing"],"hasFull":true},{"id":"live-383","addedDate":"2026-11-10","propertyType":"Industrial","title":"Lineage, Inc. v. Altus Power, Inc. (Cold-Storage REIT Sues Solar Companies Over Boyle Heights Warehouse Fire)","brief":"Lineage sued Altus Power and contractor Pearce Services, alleging they re-energized rooftop solar panels against its request before the June 2026 fire at its Boyle Heights warehouse. Both companies dispute the claims.","category":"premises-liability","status":"filed","date":"2026-09-10","jurisdiction":"Superior Court of California, County of Los Angeles","state":"CA","amount":"Damages not reported; Lineage estimates the fire will cost it more than $1B in all","source":"live","sourceUrl":"https://www.bisnow.com/news/los-angeles/industrial/lineage-suing-solar-contractor-altus-power-boyle-heights-warehouse-fire","summary":"Cold-storage REIT Lineage sued Altus Power, Altus subsidiary Los Palos Street Operating LLC and contractor Pearce Services LLC in Los Angeles County Superior Court on September 10, 2026, blaming them for the June 17, 2026 fire at its leased Boyle Heights warehouse, Bisnow reported. Lineage alleges it asked the companies not to re-energize the rooftop solar panels until safety tests were done and that they did so anyway. Pearce says it disputes causing the fire and that the investigation is ongoing, and an Altus subsidiary called Lineage's statement \"riddled with misinformation.\"","significance":"The case will test who bears responsibility when a fire is blamed on a third-party rooftop solar system at a commercial warehouse. Lineage estimates the fire will cost it more than $1 billion in all, and it faces separate resident and customer suits.","judge":null,"parties":[{"name":"Lineage, Inc.","role":"Plaintiff"},{"name":"Altus Power, Inc.","role":"Defendant"},{"name":"Pearce Services, LLC","role":"Defendant"},{"name":"Los Palos Street Operating LLC","role":"Defendant"}],"amountUsd":null,"amountBasis":null,"tags":["cold-storage","industrial","solar","fire","premises-liability"],"hasFull":true},{"id":"live-384","addedDate":"2026-11-10","featured":true,"propertyType":"Industrial","title":"GSL Holdings, LLC v. Charter Township of Lyon, Michigan (Sixth Circuit Rejects Developer's Civil-Rights Claims Over Permitting Delay)","brief":"The Sixth Circuit affirmed summary judgment for Lyon Township, Michigan, and its supervisor on a developer's civil-rights claims over the township's refusal to issue building permits before a county septic permit.","category":"zoning-land-use","status":"ruling","date":"2026-11-09","jurisdiction":"U.S. Court of Appeals for the Sixth Circuit","state":"MI","amount":"No dollar figure stated","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11057877/gsl-holdings-llc-v-charter-twp-of-lyon-twp-mich/","documentUrl":"https://storage.courtlistener.com/pdf/2026/11/09/gsl_holdings_llc_v._charter_twp._of_lyon_twp._mich..pdf","documentLabel":"Read the official opinion","summary":"The Sixth Circuit, in a published opinion by Judge Andre B. Mathis filed November 9, 2026, affirmed summary judgment for the Charter Township of Lyon and Township Supervisor John Dolan on GSL Holdings, LLC's equal-protection, due-process and First Amendment retaliation claims. GSL had agreed to build a facility for Moba Americas, Inc. on its industrial-park parcel by October 1, 2021, but the township would not issue building permits until GSL obtained a septic permit from the Oakland County Health Division, which required GSL to first combine two lots. The court held the township had a rational basis for its position, GSL had no protected property interest in the permits, and the township's request that GSL stop emailing the entire board was a permissible content-neutral restriction.","significance":"The ruling shows how hard it is to turn a permitting dispute into a federal civil-rights claim: one earlier permit granted to a neighbor, which the township called a mistake, did not show irrational treatment, and Michigan's vested-rights rule requires substantial construction under a permit. It also illustrates how a requirement held by a separate county agency can control a build-to-suit timeline.","judge":"Andre B. Mathis","parties":[{"name":"GSL Holdings, LLC","role":"Plaintiff-Appellant"},{"name":"Charter Township of Lyon, Michigan","role":"Defendant-Appellee"}],"amountUsd":null,"tags":["zoning","permitting","section-1983","michigan","industrial"],"docketUrl":"https://www.courtlistener.com/docket/70439189/gsl-holdings-llc-v-charter-twp-of-lyon-twp-mi/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-385","addedDate":"2026-11-10","propertyType":null,"title":"First Citizens Community Bank v. SA Living Fund LLC (Pennsylvania Court Upholds Confessed Judgment on $3.85 Million Loan)","brief":"Pennsylvania's Superior Court affirmed the denial of a borrower's and its guarantors' petition to strike or open a bank's confessed judgment on a $3.85 million loan secured by 827 Spring Garden Street in Philadelphia.","category":"lending-foreclosure","status":"ruling","date":"2026-11-09","jurisdiction":"Superior Court of Pennsylvania","state":"PA","amount":"$3.85 million loan; judgment amount to be reassessed after the bank conceded calculation errors","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11057832/first-citizens-community-bank-v-sa-living-fund/","documentUrl":"https://storage.courtlistener.com/pdf/2026/11/09/first_citizens_community_bank_v._sa_living_fund.pdf","documentLabel":"Read the official opinion","summary":"In a non-precedential memorandum by Judge Maria C. McLaughlin filed November 9, 2026, the Superior Court of Pennsylvania affirmed a Philadelphia County order denying SA Living Fund LLC's and its two individual guarantors' petition to strike or open a confessed judgment entered for First Citizens Community Bank on a $3.85 million loan secured by 827 Spring Garden Street. The court held that the trial court erred by looking beyond the record as it stood when judgment was entered, but that the error was harmless because the complaint adequately averred a default. It also held that an error in the bank's damages figures, which the bank conceded, was not a meritorious defense, and that the borrower's good-faith-and-fair-dealing argument was waived and would fail anyway.","significance":"The decision applies the narrow review that governs a petition to strike a confessed judgment and treats a miscalculated amount as something to fix by reassessing damages rather than by opening the judgment. It also restates that a lender's unwillingness to renegotiate or grant more accommodations is not, by itself, bad faith.","judge":"Maria C. McLaughlin","parties":[{"name":"First Citizens Community Bank","role":"Appellee/Lender"},{"name":"SA Living Fund LLC","role":"Appellant/Borrower"}],"amountUsd":3850000,"amountBasis":"loan","tags":["confessed-judgment","commercial-mortgage","guaranty","pennsylvania","philadelphia"],"hasFull":true},{"id":"live-386","addedDate":"2026-11-10","propertyType":"Mixed-Use","title":"Rubicon Real Estate Holdings, LLC v. City of Pontiac, Michigan (Supreme Court Denies Review of Developer's Permitting-Delay Suit)","brief":"The Supreme Court denied certiorari, leaving in place a Sixth Circuit ruling that Pontiac, Michigan's delays in approving a cannabis redevelopment of a 20-acre former shopping plaza did not violate the developer's constitutional rights.","category":"zoning-land-use","status":"ruling","date":"2026-11-09","jurisdiction":"Supreme Court of the United States","state":"MI","amount":"Damages figure not stated in the court opinions","source":"live","sourceUrl":"https://www.supremecourt.gov/orders/courtorders/110926zor_ap6c.pdf","documentUrl":"https://www.courtlistener.com/opinion/10622431/rubicon-real-estate-holdings-llc-v-pontiac-city-of/","documentLabel":"Read the Sixth Circuit opinion","summary":"The U.S. Supreme Court denied certiorari on November 9, 2026 in Rubicon Real Estate Holdings, LLC v. City of Pontiac, Michigan (No. 26-359), leaving in place the Sixth Circuit's published June 18, 2026 decision affirming summary judgment for the city and its city clerk. Rubicon had planned to redevelop a derelict 20-acre former shopping plaza on Glenwood Avenue with a grocery store and medical marijuana growing and processing facilities, and claimed that delays in zoning and licensing approvals drove away its prospective tenants and lender. The Sixth Circuit held the record showed, at worst, lagging discretionary approvals rather than a constitutional violation.","significance":"The denial leaves standing a published Sixth Circuit decision holding that slow discretionary zoning and licensing approvals, even when a project collapses, do not by themselves amount to a due process, takings or equal protection violation. Developers who depend on discretionary local approvals bear that timing risk unless they can show intentional discrimination or a municipal policy behind the harm.","judge":null,"parties":[{"name":"Rubicon Real Estate Holdings, LLC","role":"Petitioner/Plaintiff"},{"name":"City of Pontiac, Michigan","role":"Respondent/Defendant"}],"amountUsd":null,"amountBasis":null,"tags":["zoning","cannabis","michigan","section-1983","scotus"],"hasFull":true},{"id":"live-387","addedDate":"2026-11-10","featured":true,"propertyType":"Retail","title":"Bluetriton Brands, Inc. v. Washington Township Zoning Hearing Board and Weis Markets, Inc. (Pennsylvania Court Splits on Shopping Center Gas Station Fight)","brief":"Pennsylvania's Commonwealth Court held Weis Markets did not need a site plan for its proposed Bangor Plaza fuel station and remanded Bluetriton Brands' remaining challenges to the zoning board's special exception.","category":"zoning-land-use","status":"appeal","date":"2026-11-10","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"No dollar figure stated; dispute over adding a fuel station to a 20.3-acre shopping center","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11058438/bluetriton-brands-inc-v-washington-twp-zhb-and-weis-markets-inc/","documentUrl":"https://storage.courtlistener.com/pdf/2026/11/10/bluetriton_brands_inc._v._washington_twp._zhb_and_weis_markets_inc..pdf","documentLabel":"Read the official opinion","summary":"In a memorandum opinion by President Judge Renée Cohn Jubelirer filed November 10, 2026, the Commonwealth Court of Pennsylvania reversed a Northampton County Court of Common Pleas order that had overturned the Washington Township Zoning Hearing Board's approval of a Weis Gas-N-Go fuel station at Bangor Plaza. The court held the ordinance is ambiguous on whether a site plan was required and resolved that in Weis's favor, but also held Weis was bound by the zoning officer's unappealed ruling that a special exception was needed. Because common pleas never addressed objector Bluetriton Brands, Inc.'s other arguments, including its groundwater-contamination evidence, the court remanded for a new opinion within 60 days.","significance":"The decision shows that an applicant who does not appeal a zoning officer's ruling within 30 days is bound by it later, even when it recasts the issue as one of jurisdiction. It also applies the rule that ambiguous zoning language is read in the landowner's favor, while leaving the objector's environmental arguments to be decided on remand.","judge":"Renée Cohn Jubelirer","parties":[{"name":"Bluetriton Brands, Inc.","role":"Objector/Appellee"},{"name":"Weis Markets, Inc.","role":"Appellant/Applicant"},{"name":"Washington Township Zoning Hearing Board","role":"Appellee"}],"amountUsd":null,"tags":["zoning","special-exception","shopping-center","groundwater","pennsylvania"],"hasFull":true},{"id":"live-389","addedDate":"2026-11-11","title":"Hinds County, Mississippi Solar Farm and Battery Storage Permits (Soul City Storage, LLC and Soul City Energy, LLC): Court of Appeals Affirms","brief":"Mississippi's en banc Court of Appeals affirmed 6-4 Hinds County's permits for a 5,800-acre solar farm and battery storage project, holding the Board's order and incorporated application met the ordinance.","category":"zoning-land-use","status":"appeal","date":"2026-11-10","jurisdiction":"Court of Appeals of Mississippi","state":"MS","amount":"Not a damages matter (conditional use permit appeal)","source":"live","sourceUrl":"https://courts.ms.gov/Images/Opinions/CO197122.pdf","documentUrl":"https://courts.ms.gov/Images/Opinions/CO197122.pdf","documentLabel":"Read the official opinion","summary":"On November 10, 2026, the Mississippi Court of Appeals, sitting en banc, voted 6-4 to affirm the Hinds County Board of Supervisors' approval of conditional use permits for Soul City Storage, LLC and Soul City Energy, LLC to build a solar farm and battery storage facility on about 5,800 acres of undeveloped land stretching from Bolton to north of the Natchez Trace. A resident who opposed the project argued the Board had not issued the written decision certifying compliance that the county zoning ordinance requires. The majority held that the Board's order and minutes, which incorporated Soul City's application, site plan and supplemental materials, satisfied that requirement and that substantial evidence supported the permits. Four judges dissented.","significance":"The majority opinion indicates that, under this ordinance, a Mississippi county board can meet a written-certification requirement by incorporating a detailed application into its order, and that conditions an applicant volunteers can count as part of what the board approved. The 6-4 split, with the dissent reading the ordinance to require a specific written certification, shows the question was closely contested.","judge":"Amy Lassitter St. Pé","parties":[{"name":"Hinds County Mississippi Board of Supervisors","role":"Appellee"},{"name":"Soul City Storage, LLC","role":"Appellee"},{"name":"Soul City Energy, LLC","role":"Appellee"}],"amountUsd":null,"tags":["zoning","solar","battery-storage","mississippi","conditional-use-permit"],"hasFull":true},{"id":"live-390","addedDate":"2026-11-11","title":"Goldman-Affiliated CMBS Trust Takes Pittsburgh's Chamber of Commerce Building at No-Bid Foreclosure Sale","brief":"A Goldman Sachs-affiliated CMBS trust took over Pittsburgh's 1900-vintage Chamber of Commerce Building after its $1.4 million opening bid drew no competing bids at a Nov. 2 sheriff's sale.","category":"lending-foreclosure","status":"ruling","date":"2026-11-02","jurisdiction":"Allegheny County Court of Common Pleas, Pennsylvania","state":"PA","amount":"$1.4M opening bid by the lender; no competing bids","source":"live","sourceUrl":"https://www.connectcre.com/stories/return-to-lender-week-of-nov-5-2026/#chamber-of-commerce-building","summary":"A commercial mortgage-backed securities trust organized by a Goldman Sachs affiliate took over Pittsburgh's Chamber of Commerce Building at 411 Seventh Ave. after its $1.4 million opening bid drew no competing bids at the November 2, 2026 sheriff's sale, the Pittsburgh Business Times reported, according to Connect CRE. The trust, the plaintiff and holder of the loan, became the owner after foreclosure against the prior owner, 411 Seventh Avenue Associates LP.","significance":"With no outside bidders, the lender's own $1.4 million opening bid set the price at which the building changed hands, and the trust now owns the property it had lent against. It is one data point on outside demand at auction for an older downtown office building.","tags":["foreclosure","office","cmbs","pennsylvania","sheriff-sale"],"parties":[{"name":"411 Seventh Avenue Associates LP","role":"Defendant"}],"judge":null,"amountUsd":1400000,"amountBasis":"purchase price","hasFull":true},{"id":"live-391","addedDate":"2026-11-12","title":"Stockholder Suits v. Sunrise Realty Trust, Inc. (Southern Realty Trust Merger Proxy Disclosures)","brief":"Two Sunrise Realty Trust stockholders sued in New York state court claiming the proxy for its merger with Southern Realty Trust omitted material information; Sunrise denies the claims but filed supplemental disclosures.","category":"reit-securities","status":"pending","date":"2026-09-23","jurisdiction":"Supreme Court of the State of New York, New York County","state":"NY","amount":"Unspecified (disclosure-based claims; no damages figure stated)","source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/2012706/000162828026072825/suns-20260930.htm","summary":"Two purported Sunrise Realty Trust, Inc. stockholders sued the company and its board in New York Supreme Court on September 23, 2026 (Index No. 655415/2026) and September 24, 2026 (Index No. 655426/2026), according to Sunrise's Form 10-Q filed November 10, 2026. Sunrise says the suits, along with stockholder demand letters, generally allege omissions or misstatements in the proxy statement for its merger with Southern Realty Trust Inc. Sunrise denies the allegations but made supplemental proxy disclosures on October 13, 2026; stockholders approved the deal on October 23 and it closed on November 5, 2026.","significance":"The suits follow a pattern common in public-company stock mergers: disclosure claims filed after the proxy goes out, followed by supplemental disclosures the company says it made to avoid delay rather than because they were required. Sunrise's filing reports no ruling, dismissal or settlement in either case.","tags":["reit-securities","merger-litigation","proxy-disclosure","stockholder-suit"],"parties":[{"name":"Sunrise Realty Trust, Inc.","role":"Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-393","addedDate":"2026-11-12","title":"First Care Therapy, LLC v. Congress Ave Boynton, LLC (Commercial Lease Default Damages Reversed)","brief":"A Florida appeals court affirmed a landlord's default judgment on liability against a commercial tenant and its guarantor but reversed the $85,782.80 damages award because no properly noticed damages trial was held.","category":"lease-disputes","status":"ruling","date":"2026-11-12","jurisdiction":"District Court of Appeal of Florida, Fourth District","state":"FL","amount":"$85,782.80 damages award reversed and remanded for a properly noticed damages trial","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11060078/first-care-therapy-llc-and-loodhinssy-lafaille-paul-v-congress-ave/","documentUrl":"https://flcourts-media.flcourts.gov/content/download/2498030/opinion/Opinion_2025-2466.pdf","documentLabel":"Read the official opinion","summary":"Florida's Fourth District Court of Appeal affirmed a Palm Beach County judgment holding tenant First Care Therapy, LLC and an individual guarantor liable to landlord Congress Ave Boynton, LLC for breaching a commercial lease and guaranty in Boynton Beach. It reversed the $85,782.80 damages award because the damages were unliquidated and were fixed at a non-evidentiary summary judgment hearing rather than at a damages trial noticed under Florida Rule of Civil Procedure 1.440(d), and remanded for that trial.","significance":"Under the Fourth District's precedent, a default establishes liability but not unliquidated damages, and an affidavit of indebtedness does not make them liquidated. The court noted that Florida's district courts of appeal are divided on whether summary judgment can fix such damages, and the landlord did not ask it to revisit its rule.","tags":["commercial-lease","guaranty","default-judgment","florida","unliquidated-damages"],"parties":[{"name":"First Care Therapy, LLC","role":"Tenant/Appellant"},{"name":"Congress Ave Boynton, LLC","role":"Landlord/Appellee"}],"judge":"Alan O. Forst","amountUsd":85782.8,"amountBasis":"judgment","hasFull":true},{"id":"live-394","addedDate":"2026-11-12","title":"Shareholder Suit Against Arbor Realty Trust, Inc. Over Problem-Loan Disclosures (E.D.N.Y.)","brief":"A shareholder sued Arbor Realty Trust and its CEO and CFO, alleging they misled investors about resolving roughly $1.25 billion in nonperforming loans and foreclosed properties, InvestmentNews reported.","category":"reit-securities","status":"filed","date":"2026-11-09","jurisdiction":"United States District Court, Eastern District of New York","state":"NY","amount":"About $1.25B in nonperforming loans and real-estate-owned property described in the complaint; no damages figure reported","source":"live","sourceUrl":"https://www.investmentnews.com/regulation-legal-compliance/investor-alleges-arbor-realty-trust-misled-market-on-125b-loan-mess/268963","summary":"A shareholder sued mortgage REIT Arbor Realty Trust, Inc. (NYSE: ABR) and its chief executive and chief financial officers on Nov. 9, 2026 in the U.S. District Court for the Eastern District of New York, InvestmentNews reported. The complaint alleges violations of Section 10(b) of the Exchange Act and SEC Rule 10b-5, plus control-person claims under Section 20(a), and says Arbor's 2026 statements about resolving its nonperforming loans and foreclosed properties were misleading as those assets grew to about $1.25 billion. No court has ruled on the claims.","significance":"The suit is built on specific, dated projections a mortgage REIT gave investors about working out problem loans, and on later results that diverged from them. It will test whether that gap supports a securities-fraud claim; the allegations have not been tested in court.","tags":["reit-securities","mortgage-reit","bridge-loans","securities-fraud","new-york"],"parties":[{"name":"Arbor Realty Trust, Inc.","role":"Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-395","addedDate":"2026-11-12","title":"Kaanapali Land Management Corp. v. Newport Hospital Corporation (Maui Infrastructure Contribution Lien Foreclosure)","brief":"Kaanapali Land's KLMC subsidiary filed to foreclose a lien on Newport Hospital Corporation's 14.9-acre West Maui site over an unpaid sewer-line receivable. NHC, which claims KLMC caused delays and wants the agreement voided, moved to stay or dismiss.","category":"lending-foreclosure","status":"pending","date":"2026-09-29","jurisdiction":"Circuit Court of the Second Circuit, State of Hawaii","state":"HI","amount":"About $1.1 million receivable and accrued interest (fully reserved by Kaanapali Land as of September 30, 2026)","source":"live","sourceUrl":"https://www.sec.gov/Archives/edgar/data/1230058/000107997326001461/kaa10q-926final.htm","summary":"Kaanapali Land, LLC disclosed in its Form 10-Q filed November 12, 2026 that its subsidiary, Kaanapali Land Management Corp. (KLMC), filed a complaint in Maui on September 29, 2026 to foreclose a lien on a 14.9-acre West Maui site it sold to Newport Hospital Corporation (NHC) in 2014. KLMC says NHC failed to repay sewer-line costs owed under an Infrastructure Improvement Agreement; NHC moved to stay or dismiss on November 5, 2026. NHC has a pending arbitration claiming KLMC caused delays and cost increases and seeking to void the agreement.","significance":"The foreclosure and NHC's arbitration test the same 2014 infrastructure agreement from opposite directions: KLMC seeks to collect under it, while NHC seeks to have it declared void or reformed. Kaanapali Land has fully reserved the receivable and says there is no assurance it will prevail or collect.","tags":["foreclosure","land-development","hawaii","infrastructure-lien","master-development"],"parties":[{"name":"Kaanapali Land Management Corp.","role":"Plaintiff"},{"name":"Kaanapali Land, LLC","role":"Parent Company"},{"name":"Newport Hospital Corporation","role":"Defendant"}],"judge":null,"amountUsd":1094000,"amountBasis":"claim","propertyType":"Land/Development","hasFull":true},{"id":"live-396","addedDate":"2026-11-13","title":"Lamar Obie Company Appeal (Oregon Court of Appeals Affirms $1.24 Million Judgment Over Portland Wall-Sign Permit)","brief":"Oregon's Court of Appeals affirmed a $1,237,191.92 judgment against Lamar Obie Company for breaching the implied duty of good faith by turning in the ODOT permit for a Portland building's wall sign after its lease ended.","category":"lease-disputes","status":"ruling","date":"2026-11-12","jurisdiction":"Court of Appeals of the State of Oregon","state":"OR","amount":"$1,237,191.92 judgment (damages plus costs), affirmed on appeal","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11060193/atwood-v-lamar-obie-co-llc/","summary":"On November 12, 2026, the Oregon Court of Appeals affirmed a $1,237,191.92 judgment against billboard company Lamar Obie Company, LLC for breaching the implied duty of good faith and fair dealing in its lease of an exterior wall sign on a West Burnside building in Portland. The owners, an individual, his trust and his company, J.A. Atwood Corporation, had consented to an Oregon Department of Transportation permit for the sign on condition that it name them, but ODOT issued it only to the broker then holding the lease and later transferred it to Lamar. When the lease ended in 2019, Lamar refused to sell or transfer the permit and turned it in to ODOT for a relocation credit it could not use, ending the owners' ability to display commercial advertising on the wall.","significance":"The court held that the implied duty can limit how a tenant handles a government permit tied to the leased use even though the lease never mentions the permit, because the duty fills gaps the parties did not address. It also held that future lost revenue was not too speculative for the jury even though the owners' separate challenges against ODOT were still pending at trial.","tags":["lease-disputes","billboard","oregon","good-faith-and-fair-dealing","permit-transfer"],"parties":[{"name":"J.A. Atwood Corporation","role":"Plaintiff-Respondent (owner)"},{"name":"Lamar Obie Company, LLC","role":"Defendant-Appellant"},{"name":"OnDisplay Advertising, LLC","role":"Defendant (settled)"}],"judge":"Darleen Ortega","amountUsd":1237191.92,"amountBasis":"judgment","hasFull":true},{"id":"live-398","addedDate":"2026-11-13","title":"Deutsche Finance America LLC v. Bayerische Versorgungskammer (Delaware Contract and Defamation Suit Over $2B US CRE Portfolio)","brief":"Deutsche Finance sued German pension fund BVK in Delaware, alleging BVK mismanaged a nearly $2B US property portfolio and blamed Deutsche Finance for losses of up to €853M. BVK calls the claims baseless.","category":"reit-securities","status":"pending","date":"2026-08-31","jurisdiction":"U.S. District Court for the District of Delaware (removed from Delaware Superior Court)","parties":[{"name":"Deutsche Finance America LLC","role":"Plaintiff"},{"name":"DF Deutsche Finance Holding AG","role":"Plaintiff"},{"name":"Bayerische Versorgungskammer","role":"Defendant"}],"judge":null,"amountUsd":1000000000,"amountBasis":"other","amount":"~$2B US property portfolio; BVK has flagged potential losses of up to €853M","source":"live","sourceUrl":"https://www.bisnow.com/news/national/commercial-real-estate/deutsche-finance-alleges-bvk-responsible-cre-portfolio-losing-1b-dollars-new-lawsuit","summary":"Deutsche Finance America LLC and its parent, DF Deutsche Finance Holding AG, sued Bayerische Versorgungskammer (BVK), Germany's largest pension fund, in Delaware Superior Court on August 31, 2026, alleging breach of contract, defamation, deceptive trade practices and other claims over a nearly $2 billion US commercial real estate portfolio, Bisnow reported. Deutsche Finance alleges BVK controlled leasing, financing and capital decisions, mismanaged the portfolio, and then blamed Deutsche Finance for losses BVK has said could reach €853 million. BVK calls the allegations baseless and removed the case to federal court on October 16, 2026. In November, Munich prosecutors searched both firms' offices in a separate corruption probe, IPE reported.","significance":"The case turns on which side actually controlled decisions on the jointly built portfolio. A separate criminal corruption inquiry in Germany covers the same investments, though prosecutors say breach-of-trust claims over the losses are not part of it.","tags":["reit-securities","pension-fund","joint-venture","delaware","cross-border"],"docketUrl":"https://www.courtlistener.com/docket/74975703/deutsche-finance-america-llc-v-bayerische-versorgungskammer/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-399","addedDate":"2026-11-14","title":"Ms. Audrey's Crafting Emporium, LLC v. Ghasem Properties, Inc. (Kentucky Appeals Court Upholds Retail Tenant's Liability, Reverses Future-Rent and 8% Interest Award)","brief":"Kentucky's Court of Appeals upheld a retail tenant's and its guarantor's liability to landlord Ghasem Properties but reversed the award of unaccrued future rent and 8% prejudgment interest, directing a new judgment at 6%.","category":"lease-disputes","status":"ruling","date":"2026-11-13","jurisdiction":"Court of Appeals of Kentucky","state":"KY","amount":"$131,855.91 judgment reversed in part; new judgment limited to rent and fees accrued as of Sept. 30, 2024, with 6% prejudgment interest; guaranty capped at $155,124.60","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11061735/audrey-lynn-arcelli-v-ghasem-properties-inc/","documentUrl":"https://storage.courtlistener.com/pdf/2026/11/13/audrey_lynn_arcelli_v._ghasem_properties_inc..pdf","documentLabel":"Read the official opinion","summary":"In an unpublished opinion by Judge Lisa Payne Jones rendered November 13, 2026, the Court of Appeals of Kentucky affirmed a Jefferson Circuit Court summary judgment holding retail tenant Ms. Audrey's Crafting Emporium, LLC and its individual guarantor liable to landlord Ghasem Properties, Inc. for defaulting on a 62-month lease. It reversed the $131,855.91 award to the extent it covered rent and maintenance fees for the rest of the lease term, because the lease had no acceleration clause, and reversed the 8% prejudgment interest rate. The circuit court must enter a new judgment for rent and fees accrued as of the September 30, 2024 judgment, with 6% prejudgment interest.","significance":"The decision applies Kentucky's rule that, without an acceleration clause, a landlord may recover rent only as it comes due, and the court raised that issue itself although the tenant had not. It also holds that a party who ignores a summary judgment motion cannot use a post-judgment motion to raise objections it could have made earlier.","judge":"Lisa Payne Jones","parties":[{"name":"Ms. Audrey's Crafting Emporium, LLC","role":"Tenant/Appellant"},{"name":"Ghasem Properties, Inc.","role":"Landlord/Appellee"}],"amountUsd":131855.91,"amountBasis":"judgment","tags":["commercial-lease","guaranty","retail","kentucky","lease-default"],"hasFull":true},{"id":"live-400","addedDate":"2026-11-15","title":"McCormick County Residents Sue Over 678-Acre Data Center Rezoning","brief":"McCormick County, S.C. residents sued the county over its September 10 vote to rezone land for a 678-acre data center, alleging it skipped required procedures and conflicts with its comprehensive plan.","category":"zoning-land-use","status":"filed","date":"2026-11-06","jurisdiction":"South Carolina (court not identified in reporting)","state":"SC","amount":"678-acre rezoning challenged","source":"live","sourceUrl":"https://www.wrdw.com/2026/11/11/residents-sue-mccormick-county-over-data-center-rezoning/","summary":"A group of McCormick County, South Carolina residents sued the county on November 6, 2026 over the county council's September 10 approval of a rezoning for a 678-acre data center near downtown McCormick, WRDW/WAGT reported. The suit alleges the county failed to follow required zoning procedures, did not adequately evaluate effects on infrastructure and neighboring properties, approved a rezoning inconsistent with its comprehensive plan, and did not give the public required notice and an equal opportunity to comment.","significance":"The suit attacks the rezoning on procedural and planning grounds after the council approved it, so the land use approval the project depends on remains contested. The county's own planning commission had recommended denying the rezoning.","judge":null,"parties":[{"name":"McCormick County","role":"Defendant"}],"amountUsd":null,"tags":["zoning","data-center","south-carolina","rezoning","land-use"],"propertyType":"Data Center","hasFull":true},{"id":"live-401","addedDate":"2026-11-16","title":"1440 Broadway Foreclosure: SL Green Special Servicer Sues Over $399M CMBS Loan on Amazon-Anchored Times Square Tower","brief":"An SL Green special servicing unit has sued to foreclose on 1440 Broadway, the 745,000-square-foot Times Square office building owned by StepStone and anchored by Amazon, over a $399 million CMBS loan, The Real Deal reported, citing Crain's.","category":"lending-foreclosure","status":"filed","date":"2026-11-11","jurisdiction":"New York Supreme Court, New York County","state":"NY","amount":"$399 million CMBS mortgage","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/11/12/stepstone-faces-foreclosure-threat-at-1440-broadway/","propertyType":"Office","summary":"A division of SL Green, acting as special servicer of a $399 million CMBS loan, filed a foreclosure suit in Manhattan Supreme Court over 1440 Broadway the week of November 9, 2026, The Real Deal reported, citing Crain's. StepStone has owned the building since a 2023 loan modification; CIM Group and QSuper, which bought it in 2017, were the previous owners. The ownership allegedly defaulted on the mortgage about two years ago, and the suit came a day after Morningstar DBRS raised concerns about Amazon's 2029 lease expiration.","significance":"The suit shows that a building can be mostly leased to a top-credit occupier and still land in foreclosure when the loan matures before the capital markets will refinance it. Amazon occupies roughly three quarters of the tower, yet the loan went back to special servicing on a maturity default with weak debt service coverage, and the tenant's lease runs out in 2029. Owners with single-asset CMBS debt and a dominant tenant should read it as a warning about rollover concentration and about how long a servicer's patience lasts.","tags":["cmbs","foreclosure","office","special servicing","manhattan"],"parties":[{"name":"SL Green (special servicing division)","role":"Plaintiff / Special Servicer"},{"name":"StepStone","role":"Owner (since 2023)"}],"judge":null,"amountUsd":399000000,"amountBasis":"loan","hasFull":true},{"id":"live-402","addedDate":"2026-11-16","title":"Hotel Hayden Foreclosure: Judge Denies Summary Judgment Because $44M Note and Mortgage Were Not Properly Attached","brief":"A loan buyer foreclosing on the 122-room Hotel Hayden in Manhattan was denied summary judgment on a $44 million mortgage after the judge found the original lender's note and mortgage were not properly attached.","category":"lending-foreclosure","status":"ruling","date":"2026-11-11","jurisdiction":"New York Supreme Court","state":"NY","amount":"$44 million hotel mortgage","source":"live","sourceUrl":"https://therealdeal.com/new-york/2026/11/12/morris-moinian-foreclosure-stalled-in-staple-case/","propertyType":"Hospitality","summary":"On November 11, 2026, New York Supreme Court Justice Francis Kahn denied summary judgment to 109Co, the loan buyer foreclosing on Fortuna Realty's Hotel Hayden at 127 West 28th Street. The judge found that the note and mortgage from Morgan Stanley's 2018 refinancing were not properly attached, leaving the plaintiff's standing to be proven at trial. The borrower's default itself is not in dispute, because the owner's principal signed a forbearance agreement admitting it.","significance":"Buying a defaulted loan does not guarantee a quick foreclosure in New York: the buyer must prove how and when it got the note, and a gap in the original lender's paperwork can defeat summary judgment even when the borrower has admitted default. As banks sell more commercial loans, note buyers should check the collateral file before closing, and borrowers should expect to test it.","tags":["foreclosure","standing","note sale","hotel","new york"],"parties":[{"name":"109Co","role":"Plaintiff"},{"name":"Fortuna Realty","role":"Borrower"},{"name":"Morgan Stanley Private Bank","role":"Original Lender"}],"judge":"Francis Kahn","amountUsd":44000000,"amountBasis":"loan","hasFull":true},{"id":"live-403","addedDate":"2026-11-16","title":"Prologis v. City of Trenton, Ohio: Developer Files Federal Suit Over Voter-Approved Data Center Ban","brief":"Prologis sued Trenton, Ohio, in federal court nine days after voters capped data centers at 25 megawatts, arguing the cap cannot reach its permitted, nearly 1 million square foot project.","category":"zoning-land-use","status":"filed","date":"2026-11-12","jurisdiction":"U.S. District Court in Ohio (district not named in reporting)","state":"OH","amount":"More than $42 million spent on the project, per the developer; declaratory and injunctive relief sought","source":"live","sourceUrl":"https://www.wvxu.org/politics/2026-11-13/developer-sues-trenton-over-voter-approved-data-center-ban","propertyType":"Data Center","summary":"Prologis filed a federal lawsuit against the City of Trenton, Ohio, on November 12, 2026, challenging a charter amendment that voters approved on November 3, WVXU reported. The amendment prohibits data centers larger than 25 megawatts inside city limits. Prologis asks the court to declare the ban unconstitutional and to bar the city from using it to stop a nearly 1 million square foot data center at Kennel and Woodsdale roads, saying the city issued zoning certificates and building permits months before the vote.","significance":"This is a direct test of whether a ballot-box land use restriction can be applied to a project that already holds permits and is under construction. Developers and lenders on entitled sites in other towns face the same risk as local data center opposition shifts from council votes to charter amendments and referenda. The outcome will bear on how much protection issued permits and money spent give against a later change in local law.","tags":["data center","charter amendment","vested rights","ohio","zoning"],"parties":[{"name":"Prologis","role":"Plaintiff"},{"name":"City of Trenton, Ohio","role":"Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-404","addedDate":"2026-11-16","title":"Holmwood Capital Advisors, LLC v. HC Government Realty Holdings, L.P.: Delaware Chancery Rules Government-Lease REIT Owes Ousted Manager a 3x Termination Fee","brief":"After a three-day trial, the Court of Chancery held a REIT that owns federally leased buildings underpaid its terminated external manager by using a 1.5x fee multiplier instead of 3x, but awarded the REIT $517,463.35 for an unconsented CMBS transfer.","category":"reit-securities","status":"ruling","date":"2026-11-13","jurisdiction":"Delaware Court of Chancery","state":"DE","amount":"Termination fee to be recalculated at a 3x multiplier ($1,645,453 was paid at 1.5x); $517,463.35 awarded to the REIT on its counterclaim","source":"live","sourceUrl":"https://courts.delaware.gov/opinions/download.aspx?id=403380","docketUrl":"https://www.courtlistener.com/opinion/11060925/holmwood-capital-advisors-llc-and-holmwood-capital-llc-v-hc-government/","docketLabel":"CourtListener opinion","summary":"On November 13, 2026, the Delaware Court of Chancery issued a post-trial opinion in the fee dispute between HC Government Realty Trust, Inc., a REIT that owns properties leased to the federal government, and its former external manager, Holmwood Capital Advisors, LLC. The court held that the REIT wrongly reduced its stockholders' equity by booking an estimate of the termination fee as a liability, and that a 3.0x multiplier, not the 1.5x the REIT used, governs the fee. The REIT won on other points: it could pay fees in common stock, the manager must absorb offering costs above a 15% cap, and Holmwood Capital, LLC owes $517,463.35 for breaching a no-default representation tied to a CMBS loan. The parties were told to confer on a recalculated fee and a form of order.","significance":"External-management agreements with multi-year termination fees are standard in non-traded and small-cap REITs, and this opinion shows how a fee keyed to 'stockholders' equity' is litigated line by line when a new investor takes control. The court enforced the contract's own equity definition over GAAP presentation, and held the REIT to the calculation method it had used when it paid the fee. It also construed ambiguous fee terms against the founders who drafted both sides of the agreement before selling shares to outside investors. For lenders and sponsors, the CMBS ruling is a reminder that moving even the economic interest in a borrower without lender consent can be a default that costs real money years later.","tags":["reit","management agreement","termination fee","cmbs","delaware chancery"],"parties":[{"name":"Holmwood Capital Advisors, LLC","role":"Plaintiff/Counterclaim Defendant"},{"name":"Holmwood Capital, LLC","role":"Plaintiff/Counterclaim Defendant"},{"name":"HC Government Realty Trust, Inc.","role":"Defendant/Counterclaim Plaintiff"},{"name":"HC Government Realty Holdings, L.P.","role":"Defendant/Counterclaim Plaintiff"}],"judge":"Bonnie W. David","amountUsd":517463.35,"amountBasis":"award","hasFull":true},{"id":"live-405","addedDate":"2026-11-16","title":"HCJV 115 & 135 Hoyt Avenue Owner, LLC v. Project Veritas: Appeals Court Affirms $114,099 Rent Judgment Over Unsigned Lease Termination","brief":"Project Veritas left its Mamaroneck commercial space in December 2023 without signing the landlord's termination agreement. The Second Department affirmed a $114,098.96 judgment, finding no enforceable oral lease modification.","category":"lease-disputes","status":"ruling","date":"2026-11-12","jurisdiction":"New York Supreme Court, Appellate Division, Second Department","state":"NY","amount":"$114,098.96 judgment","source":"live","sourceUrl":"https://www.nycourts.gov/reporter/current/3dseries/2026/2026_06699.shtml","summary":"On November 12, 2026, the Appellate Division, Second Department, affirmed a Westchester County judgment of $114,098.96 for landlord HCJV 115 & 135 Hoyt Avenue Owner, LLC against Project Veritas for breach of a five-year commercial lease in Mamaroneck. The tenant told the landlord in December 2023 that it needed to terminate and vacate, but never signed or returned the termination agreement the landlord sent. The court held that the lease's written-modification clause controlled and that the tenant's claimed part performance was not 'unequivocally referable' to any oral deal.","significance":"The decision applies New York's rule that a lease requiring signed, written modifications cannot be changed orally unless part performance is unequivocally referable to the claimed change. Paying rent due and forfeiting a security deposit on default were things the lease already required, so they did not prove a termination deal.","tags":["commercial lease","lease termination","statute of frauds","rent judgment","westchester"],"parties":[{"name":"HCJV 115 & 135 Hoyt Avenue Owner, LLC","role":"Landlord/Respondent"},{"name":"Project Veritas","role":"Tenant/Appellant"}],"judge":"William J. Giacomo","amountUsd":114098.96,"amountBasis":"judgment","hasFull":true},{"id":"live-406","addedDate":"2026-11-16","title":"H&R Block Eastern Enterprises, Inc. v. Hallwood Plaza LLC (Casualty Clause Puts Fire Rebuild on Shopping-Center Landlord, Bars Double Rent)","brief":"A federal judge held that a Flint shopping-center lease's fire-casualty clause made landlord Hallwood Plaza LLC responsible for rebuilding H&R Block's burned-out store, and threw out the landlord's damages counterclaims.","category":"lease-disputes","status":"ruling","date":"2026-11-09","jurisdiction":"U.S. District Court, Eastern District of Michigan","state":"MI","amount":"Repair costs and rent abatement (no figure stated)","source":"live","sourceUrl":"https://www.courtlistener.com/opinion/11058226/hr-block-eastern-enterprises-inc-v-hallwood-plaza-llc/","propertyType":"Retail","summary":"On November 9, 2026, Judge Laurie J. Michelson ruled on cross-motions for partial summary judgment in a lease dispute that began when a car crashed into the Hallwood Plaza shopping center in Flint in August 2023 and started a fire in H&R Block's unit. The court held that the lease's \"Fire or Other Casualty\" section, not the general repair clauses, governs, and that it requires the landlord to rebuild the premises. H&R Block won summary judgment on the landlord's four damages counterclaims, and the landlord's declaratory counterclaim was dismissed. H&R Block's own breach and constructive-eviction claims go forward, though its request for legal fees was dismissed.","significance":"The ruling shows how a specific casualty clause overrides a lease's general split of repair duties between landlord and tenant. It also holds that a landlord who keeps a lease alive after a fire and supplies temporary space cannot bill full rent on both the damaged unit and the temporary one. Retail landlords and tenants should read their casualty, abatement and temporary-space provisions together before a loss, because the party that guesses wrong about who rebuilds can face a breach claim and a constructive-eviction theory.","tags":["casualty clause","rent abatement","constructive eviction","shopping center","summary judgment"],"parties":[{"name":"H&R Block Eastern Enterprises, Inc.","role":"Plaintiff/Counter-Defendant (Tenant)"},{"name":"Hallwood Plaza LLC","role":"Defendant/Counter-Plaintiff (Landlord)"}],"judge":"Laurie J. Michelson","amountUsd":null,"docketUrl":"https://www.courtlistener.com/docket/68996234/hr-block-eastern-enterprises-inc-v-hallwood-plaza-llc/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-407","addedDate":"2026-11-16","title":"National Hairston Clan v. Stokes County: Community Groups File Second Suit to Void 1,850-Acre Project Delta Data Center Rezoning","brief":"Four community groups and 16 residents sued Stokes County, N.C., to void its second rezoning of about 1,850 acres on the Dan River for the Project Delta data center, 11 days before a development agreement vote.","category":"zoning-land-use","status":"filed","date":"2026-11-12","jurisdiction":"North Carolina Superior Court, Stokes County","state":"NC","amount":"Order voiding the rezoning and injunctive relief","source":"live","sourceUrl":"https://southerncoalition.org/residents-community-groups-sue-again-over-stokes-county-data-center-rezoning/","propertyType":"Data Center","summary":"On November 12, 2026, four community organizations and 16 residents, represented by two public-interest legal groups, sued Stokes County in Superior Court over the Board of Commissioners' 3-2 vote on September 14 to rezone about 1,850 acres along the Dan River near Walnut Cove for a data center campus known as Project Delta. According to their lawyers' announcement, the suit alleges the approval rested on a rushed analysis that appears to have been generated by AI without independent verification, and asks the court to void the rezoning and bar the county from relying on it. The county voided an earlier rezoning of the same land in April after many of the same plaintiffs sued over the process in March, and a court formally voided it in August on the parties' joint motion.","significance":"The suit shows that re-voting after a flawed process does not end the litigation risk on a large rezoning; the second challenge targets the quality of the record behind the decision. It also bears on a pending 15-year development agreement that, according to the plaintiffs, would exempt the site from any future data center moratorium. Developers, landowners and lenders should treat the entitlement as contested while the suit is pending.","tags":["data center","rezoning","north carolina","development agreement","land use"],"parties":[{"name":"National Hairston Clan","role":"Plaintiff"},{"name":"CleanAIRE NC","role":"Plaintiff"},{"name":"Dan River Basin Association","role":"Plaintiff"},{"name":"7 Directions of Service","role":"Plaintiff"},{"name":"Stokes County","role":"Defendant"}],"judge":null,"amountUsd":null,"hasFull":true},{"id":"live-408","addedDate":"2026-11-16","title":"Harpers Ferry Residents v. West Virginia Department of Commerce Officials (Supreme Court Upholds Tourism District Law Exempting $138M Hill Top House Hotel From Local Zoning)","brief":"West Virginia's high court rejected residents' constitutional challenge to the 2020 law exempting large tourism projects in small towns from municipal zoning and building codes. The Hill Top House Hotel redevelopment is the only approved district.","category":"zoning-land-use","status":"ruling","date":"2026-11-13","jurisdiction":"Supreme Court of Appeals of West Virginia","state":"WV","amount":"Hotel redevelopment the developer says will cost more than $138 million","source":"live","sourceUrl":"https://www.courtswv.gov/sites/default/pubfilesmnt/2026-11/24-373%20Signed%20Opinion.pdf","propertyType":"Hospitality","summary":"On November 13, 2026, the Supreme Court of Appeals of West Virginia affirmed the dismissal of a suit by Harpers Ferry residents challenging the Tourism Development District Act, W. Va. Code § 5B-1-9. The 2020 statute lets state commerce officials designate districts in which qualifying tourism projects are exempt from municipal zoning, historic preservation, building permitting and other local rules. The only district approved so far covers SWaN Hill Top House, LLC's redevelopment of the Hill Top House Hotel, which the developer says will cost more than $138 million. The court held the Act is not an unconstitutional special law, does not violate equal protection, and does not infringe any right to local self-rule or to vote.","significance":"The court treated the Act as a general law even though only one project has used it, applying a deferential, rational-basis review to its population, cost and five-district limits. The ruling leaves in place a state-level route that takes a qualifying tourism project out of municipal zoning, historic review and permitting in West Virginia's smallest towns.","tags":["zoning preemption","hotel redevelopment","tourism development district","special legislation","west virginia"],"parties":[{"name":"West Virginia Department of Commerce","role":"Respondent (through its Secretary)"},{"name":"West Virginia Division of Economic Development","role":"Respondent (through its Acting Executive Director)"},{"name":"SWaN Hill Top House, LLC","role":"Developer (non-party)"}],"judge":"William R. Wooton","amountUsd":null,"hasFull":true},{"id":"live-409","addedDate":"2026-11-16","title":"First Tech Federal Credit Union Sets Foreclosure Auction of Westborough Shopping Center Over $32.4M Mortgage","brief":"A credit union lender has scheduled a Dec. 8 foreclosure auction of the 33.5-acre, Stop & Shop- and Staples-anchored Westborough Shopping Center on Route 9, citing a breach of a mortgage last amended to $32.375 million in July 2025.","category":"lending-foreclosure","status":"pending","date":"2026-11-11","jurisdiction":"Massachusetts mortgagee's foreclosure sale by public auction (Worcester County); no court case reported","state":"MA","amount":"$32.375 million mortgage","source":"live","sourceUrl":"https://www.yahoo.com/news/articles/westborough-shopping-center-headed-foreclosure-212449980.html","propertyType":"Retail","summary":"First Technology Federal Credit Union, formerly Digital Federal Credit Union, has scheduled a mortgagee's foreclosure auction of the Westborough Shopping Center on Route 9 in Westborough, Massachusetts, for December 8, 2026 at 11 a.m., MassLive reported. Registry records cited by MassLive show owner Colangelo Massachusetts Real Estate LLC took a $30.75 million mortgage from the credit union in December 2022 that was updated to $32.375 million on July 1, 2025. The lender's notice of sale says the owner breached the mortgage's conditions.","significance":"The center is anchored by a Stop & Shop grocery store, and the mortgage debt exceeds the roughly $28.71 million at which the town assesses its two parcels. The sale is proceeding under the mortgage's power of sale rather than through a foreclosure lawsuit.","tags":["foreclosure auction","grocery-anchored retail","credit union lender","massachusetts","power of sale"],"parties":[{"name":"First Technology Federal Credit Union (formerly Digital Federal Credit Union)","role":"Mortgagee"},{"name":"Colangelo Massachusetts Real Estate LLC","role":"Mortgagor (owner)"}],"judge":null,"amountUsd":32375000,"amountBasis":"loan","hasFull":true},{"id":"live-410","addedDate":"2026-11-16","title":"In re F-Star Socorro, L.P. (Five Star Development): Court Conditionally Approves Disclosure Statement, Sending Commercial Property Debtors' $180M Exit Plan to a Creditor Vote","brief":"A Texas bankruptcy judge let Five Star Development's Commercial Property Debtors seek votes on a plan that would roll $180 million of bankruptcy loans into exit loans and pay allowed unsecured claims in full.","category":"lending-foreclosure","status":"ruling","date":"2026-11-13","jurisdiction":"U.S. Bankruptcy Court, Southern District of Texas","state":"TX","amount":"$180 million in DIP loans converting to exit loans","source":"live","sourceUrl":"https://elevenflo.com/cases/f-star-socorro-l-p-2133","summary":"On November 13, 2026, the Houston bankruptcy court handling the F-Star Socorro cases conditionally approved the disclosure statement for the Commercial Property Debtors' Chapter 11 plan, so voting can begin, according to the ElevenFlo case summary. The plan, filed that day, would turn a $120 million senior mortgage DIP facility and a $60 million mezzanine DIP facility into exit loans without any cash changing hands. Ballots and objections are due December 7, and a combined hearing on final disclosure approval and confirmation is set for December 16, 2026.","significance":"The plan offers one route out of a lender dispute: replace the original lender's financing with new bankruptcy loans, then carry those loans forward as exit debt rather than refinance at emergence. Whether it is confirmed, and how the separate guaranty dispute tied to the lender's credit bid is resolved, will shape the outcome for creditors.","tags":["chapter 11","disclosure statement","dip financing","credit bid","exit financing"],"parties":[{"name":"F-Star Socorro, L.P.","role":"Debtor"},{"name":"Five Star Development Properties, LLC","role":"Debtor"},{"name":"Madison Realty Capital","role":"Lender"},{"name":"Farallon","role":"DIP Lender"}],"judge":"Alfredo R. Pérez","amountUsd":180000000,"amountBasis":"loan","docketUrl":"https://www.courtlistener.com/docket/71870809/f-star-socorro-lp-and-official-committee-of-unsecured-creditors-for-f-st/","docketLabel":"CourtListener docket","hasFull":true},{"id":"live-411","addedDate":"2026-11-16","title":"Penn Hurst Holdings DE LLC v. East Vincent Township: Judge Lets Adjoining Farm Owners and Residents' Group Join Appeal Over Rejected Pennhurst Data Center","brief":"A Chester County judge allowed adjoining farm owners and a 950-member residents' group to help defend East Vincent Township's denial of a 1.9 million-square-foot data center on the 124.6-acre Pennhurst property.","category":"zoning-land-use","status":"pending","date":"2026-11-10","jurisdiction":"Chester County Court of Common Pleas, Pennsylvania","state":"PA","amount":"Conditional-use approval for a 1.9 million-square-foot data center campus","source":"live","sourceUrl":"https://www.mychesco.com/a/communities/neighbors-gain-legal-standing-in-pennhurst-data-center-appeal/","propertyType":"Data Center","summary":"On November 10, 2026, Judge Nicole Forzato of the Chester County Court of Common Pleas granted intervenor status to the owners of a farm adjoining the Pennhurst property and to East Vincent Advocacy, a resident-led nonprofit, in the developer's land use appeal. Penn Hurst Holdings DE LLC is challenging the East Vincent Township supervisors' unanimous May 21, 2026 denial of its conditional-use application for a data center campus on about 124.6 acres. The developer had challenged the standing of both. The ruling decides only who may take part; the application remains denied and the merits are still to be briefed.","significance":"The ruling adds two parties who can brief the merits and take part in any resolution of the appeal, so it can no longer be settled between the developer and the township alone. The advocacy group, which owns no land in the township, was admitted after it had held party status in the township hearings.","tags":["data center","land use appeal","intervention","conditional use","pennsylvania"],"parties":[{"name":"Penn Hurst Holdings DE LLC","role":"Appellant"},{"name":"East Vincent Township Board of Supervisors","role":"Appellee"},{"name":"East Vincent Advocacy","role":"Intervenor"}],"judge":"Nicole Forzato","amountUsd":null,"hasFull":true},{"id":"live-412","addedDate":"2026-11-17","title":"Exton Square Mall: Chester County Judge Rules for Abrams Realty & Development on Mixed-Use Redevelopment After Township Supervisors' Denial","brief":"A Chester County judge ruled for Abrams Realty & Development on its plan to replace the closed Exton Square Mall with townhouses, apartments, shops and restaurants. The township supervisors say they intend to appeal.","category":"zoning-land-use","status":"ruling","date":"2026-11-13","jurisdiction":"Chester County Court of Common Pleas, Pennsylvania","state":"PA","amount":"Approval of a mixed-use mall redevelopment","source":"live","sourceUrl":"https://www.inquirer.com/real-estate/commercial/exton-square-mall-redevelopment-town-center-20261116.html","propertyType":"Mixed-Use","summary":"The Philadelphia Inquirer reported that Chester County Court of Common Pleas Judge Sarah B. Black ruled on Friday, November 13, 2026, for Abrams Realty & Development, the owner of the closed Exton Square Mall, in its suit against the West Whiteland Township Supervisors, who had rejected its redevelopment plans. The project would include 172 townhouses, 381 apartments and 165 age-restricted apartments. The supervisors' chair said the board intends to appeal.","significance":"The developer argued that its plan meets the township's zoning requirements and should be approved, and the judge agreed over a denial that cited sewer, traffic and density concerns. For owners converting closed malls to mixed use, it is an example of a court siding with the applicant after a local board said no. The planned appeal means the approval is not yet final.","tags":["mall redevelopment","mixed-use","land use appeal","pennsylvania"],"parties":[{"name":"Abrams Realty & Development","role":"Plaintiff"},{"name":"West Whiteland Township Supervisors","role":"Defendant"}],"judge":"Sarah B. Black","amountUsd":null,"hasFull":true},{"id":"live-413","addedDate":"2026-11-17","title":"Water's Edge at Wind Gap, LLC v. Zoning Hearing Board of Moore Township: Pennsylvania Commonwealth Court Affirms Denial of Woodland Variance for Two-Warehouse Plan","brief":"Pennsylvania's Commonwealth Court affirmed the Moore Township Zoning Hearing Board's denial of a variance that would have let a developer preserve 55% of a 51-acre golf course's woodlands, not the required 60%, for two warehouses.","category":"zoning-land-use","status":"ruling","date":"2026-11-16","jurisdiction":"Commonwealth Court of Pennsylvania","state":"PA","amount":"Zoning variance for a two-warehouse development on 51 acres","source":"live","sourceUrl":"https://www.pacourts.us/assets/opinions/Commonwealth/out/279CD24_11-16-2026.pdf","propertyType":"Industrial","summary":"On November 16, 2026, the Commonwealth Court of Pennsylvania affirmed the denial of a dimensional variance sought by Water's Edge at Wind Gap, LLC, which seeks to redevelop its 51-acre golf course property in Moore Township into an industrial development with two warehouses. The developer asked to preserve 55% of the property's woodlands, a 5% reduction from the 60% the zoning ordinance requires. The court held that substantial evidence supported the Zoning Hearing Board's finding that the variance would adversely affect the character of the neighborhood.","significance":"The court had earlier found that the developer showed unnecessary hardship, did not create it and asked for no more than necessary, yet the variance still failed on the one remaining factor. The Board found that about 0.21 acres of additional woodland disturbance would change the neighborhood's character, and the court treated the Board as the arbiter of credibility and the weight of the evidence. Warehouse developers should expect each variance factor to be tested separately, including the effect on neighboring homes.","tags":["warehouse","dimensional variance","woodland preservation","pennsylvania","zoning hearing board"],"parties":[{"name":"Water's Edge at Wind Gap, LLC","role":"Appellant"},{"name":"Zoning Hearing Board of Moore Township","role":"Appellee"},{"name":"Moore Township","role":"Appellee"}],"judge":"Matthew S. Wolf","amountUsd":null,"hasFull":true}],"trends":[{"id":"trend-001","title":"Texas Multifamily Syndicators Lose Ground as CRE Foreclosure Volume Tops $1.15B","category":"lending-foreclosure","date":"2026-08-03","scope":"Texas Triangle (Dallas–Fort Worth, Houston, Austin, San Antonio)","metric":"$1.15B in loans flagged for August foreclosure auctions","source":"live","sourceUrl":"https://therealdeal.com/texas/2026/08/03/texas-biggest-loans-head-to-foreclosure-auctions-in-august/","summary":"The Real Deal's monthly Texas distress tracker found $1.15 billion in commercial real estate loans flagged for foreclosure auction in August 2026, up from just under $1 billion in July, with Tarrant County leading at 11 of the 47 flagged loans. At least six multifamily syndication firms — including S2 Capital, Nitya Capital, GVA Management, and Lurin Capital — face losing control of apartment properties this month, together accounting for just under $600M, more than half the flagged total. S2 Capital told investors on July 1 it is dissolving its $400M first fund with 'no returns of capital' and separately faces foreclosure on six more properties tied to $320M in loans; Nitya Capital's Palace and Interlace Apartments (Dallas–Fort Worth) are exposed on $28.2M and $31.4M loans from One William Street Capital Management; Lurin Capital faces foreclosure on the 734-unit Latitude 2976 in Houston after an alleged default on a $77.2M Fannie Mae loan.","significance":"Syndicators that raised capital from passive retail investors to buy older apartment stock with floating-rate, value-add debt before rates spiked are now the epicenter of Texas CRE distress, and 17 of the 47 flagged loans have already cycled through the auction docket once before — a signal that lender forbearance is running out faster than workouts are closing. Lenders, mezzanine investors, and LPs in syndicated multifamily funds should treat repeat-flagged loans and fund-dissolution notices as leading indicators of contested foreclosures and potential fraud or mismanagement claims from wiped-out investors, which have followed similar syndicator collapses elsewhere.","tags":["multifamily","foreclosure","syndication","texas","distress"]},{"id":"trend-002","title":"CMBS Delinquency Rate Jumps to 7.86% as Refinancing Failures Replace Property Distress as the Driver","category":"lending-foreclosure","date":"2026-08-06","scope":"National CMBS market","metric":"7.86% delinquency rate, up 51 bps in one month","source":"live","sourceUrl":"https://www.connectcre.com/stories/cmbs-delinquency-rate-adds-51-basis-points-in-july-2026/","summary":"Trepp's July 2026 CMBS Delinquency Report shows the overall rate rising 51 basis points to 7.86%, the sharpest single-month increase in over a year, with five large loans accounting for $2.6B of the $6.0B in newly delinquent balances. Those loans include a showroom/exhibition-space portfolio split between North Carolina and Nevada, two Times Square properties in New York, a Chicago office tower anchored by the Aon Center, and a Seattle office portfolio. Non-performing matured balloon loans made up 66% of the newly delinquent balance, with most transfers tied to refinancing failures rather than weak property performance. Multifamily posted the largest sector increase, up 46 bps to 7.69%, on a cluster of newly delinquent loans in Ohio, Texas, and New York.","significance":"A maturity-default wave driven by refinancing failure rather than operating distress produces a different dispute mix than a typical downturn: extension and modification fights, guarantor liability under recourse carve-outs, appraisal disputes with special servicers, and cash-management sweep or lockbox disagreements. Because the trigger is loan structure and vintage rather than asset performance, sponsors with 2015-2016-vintage loans hitting 10-year maturities into a tighter lending market should expect portfolio-wide exposure rather than isolated, property-by-property risk.","tags":["cmbs","delinquency","refinancing","maturity default","guarantor liability"]},{"id":"trend-003","title":"CRE's $65B Year-End Maturity Wall Leaves $37B in 'Hard' Maturities With No Extensions Left","category":"lending-foreclosure","date":"2026-08-11","scope":"National CMBS market","metric":"$65B in CMBS loans maturing by year-end; $37B are hard maturities with no extension room","source":"live","sourceUrl":"https://www.credaily.com/newsletters/national/issue/cres-65b-maturity-wall-is-finally-hitting/","summary":"Trepp data reported by CRE Daily on August 11 shows roughly $65 billion in CMBS loans maturing by year-end 2026, including $37 billion of 'hard' maturities that have already exhausted their extension options; Trepp estimates more than half of those properties will need fresh borrower equity to refinance at current rates. Office debt bears a disproportionate share of the distress, with an 11.91% distress rate versus 7.6% market-wide serious delinquency, and all five nonperforming CMBS loans maturing in August are office loans totaling $1.8B. Examples cited include Rithm Capital injecting $73M of fresh equity to refinance a $500M maturity at 31 W. 52nd St. in Manhattan, and a San Francisco office CMBS investment that returned bondholders just $101M of an original $240M investment.","significance":"A maturity-default wave driven by loan structure and vintage rather than property performance tends to produce fights over extension and modification terms, guarantor liability claims under recourse carve-outs once a maturity default triggers personal exposure, appraisal disputes between borrowers and special servicers ahead of forced sales, and bondholder claims against special servicers over resolution timing and pricing when losses are as steep as the San Francisco example. Sponsors with 2015-2016-vintage 10-year loans or 2021-2022-vintage interest-only loans maturing into a tighter lending market should treat this as portfolio-wide exposure rather than an isolated, property-by-property risk.","tags":["cmbs","maturity wall","office","special servicing","guarantor liability"]},{"id":"trend-004","title":"Shareholder Activism Against Public REITs Tops 100 Campaigns Since 2020, With 2026 Proxy Fights Increasingly Settled Before a Vote","category":"reit-securities","date":"2026-01-13","scope":"Public REIT sector (national)","metric":"100+ public activist campaigns launched against REITs since 2020; over 90% resolve before any shareholder vote","source":"live","sourceUrl":"https://www.goodwinlaw.com/en/insights/publications/2026/01/alerts-realestate-shareholder-activism-in-the-public-reit-sector","summary":"Goodwin's January 2026 lookback counts more than 100 public activist campaigns and related engagements against REITs since 2020, with recent examples including Elliott Investment Management's campaign at Rexford Industrial Realty (which secured a CEO transition and an added independent director), Erez Asset Management's campaign at Whitestone REIT (which preceded MCB Acquisition's $15-per-share cash offer), Blackwells Capital's simultaneous campaigns at Ashford Hospitality Trust and Global Net Lease, and Land & Buildings-led liquidation campaigns at Equity Commonwealth (where shareholders approved a plan of sale and dissolution) and National Health Investors. Barclays' shareholder-advisory group separately counted 38 campaigns launched against public REITs in 2024 alone, with roughly 20 more in 2025 year to date. Over 90% of REIT activist campaigns now conclude before reaching a shareholder vote, and roughly 60% of targeted REITs are valued between $1 million and $1 billion, with another 30% between $1 billion and $10 billion.","significance":"REIT-sector counsel tie the settlement-first shift to the SEC's universal proxy card (Exchange Act Rule 14a-19), which lets shareholders mix and match nominees from competing slates and has raised activists' odds of seating at least one dissident director in an actual vote — pushing boards toward negotiated resolutions rather than risking a contested election. REIT boards and their counsel evaluating an activist approach, or diligencing a REIT counterparty's governance profile before a transaction, should treat settlement-readiness (board composition, standstill terms, advance-notice bylaws) as the live battleground rather than assume a proxy fight will reach a vote.","tags":["reit governance","shareholder activism","universal proxy","proxy contest"]},{"id":"trend-005","title":"Classified Boards at Public REITs Fall to 5% as Annual Elections and Majority Voting Become the Default","category":"reit-securities","date":"2026-02-25","scope":"Public REIT sector (national)","metric":"Classified boards among public equity REITs down to 5% in 2026, from 17% in 2017","source":"live","sourceUrl":"https://www.goodwinlaw.com/en/insights/publications/2026/02/alerts-realestate-corporate-governance-trends-in-the-public-reit-sector","summary":"Goodwin's February 2026 governance survey of the public REIT sector finds annual director elections now standard at 95% of REITs, majority-voting standards adopted by more than 80% (up from 76% in 2017), stockholder bylaw-amendment rights at 69% of REITs (up from 47%), and proxy-access provisions at 48% (up from 19%) — alongside CEO/chair separation at 77% of REITs (up from 55%) and women holding roughly a third of REIT board seats (up from 13%). Because nearly 80% of the RMZ REIT universe is incorporated in Maryland, the Maryland Unsolicited Takeover Act remains the backstop takeover-defense framework for most of the sector, and the same report finds 34% of Maryland REITs have affirmatively opted out of it.","significance":"The steady erosion of structural takeover defenses — fewer classified boards, broader bylaw-amendment and proxy-access rights — runs in the same direction as the activism data above: REITs have less structural insulation from a dissident campaign than they did a decade ago. Counsel advising a REIT board on its charter and bylaws, or diligencing a REIT's takeover-defense profile ahead of an activist approach or unsolicited bid, should confirm current MUTA opt-in/opt-out status and classified-board provisions rather than assume Maryland incorporation alone provides meaningful protection.","tags":["reit governance","classified boards","proxy access","maryland reit law","board diversity"]},{"id":"trend-006","title":"Local Data Center Moratoria Quadruple to 374 in a Quarter as Developers Turn to Vested-Rights Litigation","category":"zoning-land-use","date":"2026-09-10","scope":"National (local and state data center siting)","metric":"374 active local moratoria, up from 92 in June 2026","source":"live","sourceUrl":"https://www.wilmerhale.com/en/insights/client-alerts/using-temporary-pauses-to-develop-permanent-regulation","summary":"Wells Fargo's data center tracker, compiled by analyst Shahriar Pourreza, counted 374 active local moratoria on data center development by the end of summer 2026, up from 92 in June — a roughly fourfold increase in one quarter — with Michigan, Ohio, North Carolina, Iowa, and Tennessee leading in count. Active moratoria now average roughly 346 days, and the average across all tracked measures rose to 311 days from 277, with some running as long as five years. A separate state-level tracker counted 26 of 50 states restricting or considering restrictions as of September 7, including 18 with active bans or moratoria. New York moved first statewide: after the Legislature passed the Responsible Data Center Development Act on June 4, 2026, Governor Hochul declined to sign it and instead issued Executive Order No. 62 on July 14, pausing discretionary environmental permitting for data centers above 50 megawatts for one year; Seattle adopted an emergency municipal siting moratorium on June 9.","significance":"Developers have begun challenging these pauses rather than waiting them out, and early results suggest hastily adopted moratoria are legally vulnerable — RCM Hill, LLC's $100M federal suit over Hill County, Texas's moratorium (arguing Texas counties lack zoning authority) prompted rescission within two weeks; ECO TIP West LLC is suing Chatham County, North Carolina, claiming $11M in reliance spending on a by-right permit created statutory vested rights under N.C. Gen. Stat. § 160D-107; and a California developer is challenging Imperial County's emergency interim ordinance for failing the 'current and immediate threat' showing required by Cal. Gov't Code § 65858(c). The dispute mix this pattern produces — ultra vires challenges, vested-rights and estoppel claims, procedural attacks on emergency findings, and eventually regulatory takings, contract-impairment, dormant commerce clause, and Federal Power Act preemption theories — should concern any owner, developer, or investor holding land optioned or contracted for data center use, since the practical exposure is a stalled entitlement with carrying costs and no clear off-ramp. Because most moratoria are transitional, the setback, water-use, noise, and community-benefit standards adopted during the pause matter more for long-run project economics than the pause itself.","tags":["data centers","moratorium","vested rights","zoning","entitlement risk"]},{"id":"trend-007","title":"CRE CLO Distress Jumps From 19% to 28% in One Month as 2021–2022 Bridge Loans Hit Maturity","category":"lending-foreclosure","date":"2026-09-08","scope":"National CRE CLO and SASB CMBS markets","metric":"CRE CLO distress rate 28% in August, up from 19% in July","source":"live","sourceUrl":"https://commercialobserver.com/2026/09/cre-clo-distress-cred-iq/","summary":"CRED iQ data published September 8, 2026 shows the CRE CLO distress rate rising from 19% in July to 28% in August, the sharpest one-month move of any deal type this year, while single-asset, single-borrower (SASB) CMBS distress has held near 22% since June; conduit, Freddie Mac and single-family rental categories all remain under 5%. The distress is concentrated in 2021–2022 vintages: FSRIA 2021-FL3 alone has $353M of multifamily collateral in special servicing across seven loans, adding River Crossing at Roswell ($49M) and Grace Abernathy Apartments in Sandy Springs ($42M) in August, and ARCLO 2022-FL1 added the Residences at Medical in San Antonio ($27M) and Pebblebrook Apartments in Redlands ($12M). Five deals account for 38% of CRE CLO special-servicing balance, and Texas, Florida and Georgia hold 44% of the distressed balance. On the SASB side, four office and lab deals — BXHPP 2021-FILM ($525M, Hollywood studios/offices), ALEN 2021-ACEN ($203M, Three Allen Center, Houston), LIFE 2021-BMR ($190M, life sciences) and BSREP 2021-DC ($162M, eight D.C.-area office buildings, transferred Aug. 10) — make up 64% of the category's $1.7B distressed balance.","significance":"CRE CLO collateral is short-term floating-rate bridge debt with interest-rate-cap requirements, debt-yield or DSCR extension tests, and holdback-funded business plans, so maturity failures tend to produce disputes over whether extension conditions were met and future advances wrongly withheld, fast-track mezzanine UCC foreclosures met by commercial-reasonableness challenges, and claims against guarantors under completion, carry and carve-out guaranties. Serial defaults inside a single CLO invite noteholder scrutiny of underwriting and collateral management, and in syndicated multifamily deals passive investors often turn on sponsors once equity is wiped out. With office and mixed-use loans maturing over the next nine months pricing 170–180 bps above their in-place notes, as Commercial Observer reports, SASB borrowers face servicer fights over appraisal reductions, modifications and sale-versus-foreclosure decisions.","tags":["cre clo","bridge loans","special servicing","sasb","multifamily"]},{"id":"trend-008","title":"Office CMBS Delinquency Reaches 13.2% and Special Servicing 15.7% as Half of Office Loans Transfer Before Any Missed Payment","category":"lending-foreclosure","date":"2026-09-24","scope":"U.S. office loans in conduit, single-asset single-borrower and CRE CLO deals ($189.6B)","metric":"Office CMBS delinquency 13.2%, special servicing 15.7% (August 2026)","source":"live","sourceUrl":"https://cred-iq.com/blog/2026/09/24/office-special-servicing-hits-a-new-high-as-more-loans-transfer-before-default/","summary":"CRED iQ data published September 24, 2026 put the office CMBS delinquency rate at 13.2% in August and the office special servicing rate at 15.7%, both the highest since at least 2019, across $189.6 billion of office debt in conduit, single-asset single-borrower and CRE CLO deals. Over the past 12 months, 51% of office loans sent to special servicing were still current when they transferred, a median of about 11 months before maturity, up from 42% in the prior 12 months. Of the 93 office loans that transferred while current between August 2024 and August 2025, 72% later went 60 or more days delinquent or matured without paying off, and only 15% returned to the master servicer and were current. CRED iQ ties 71% of distressed office balance to a failed or imminent refinancing rather than missed payments; about $39 billion of office CMBS matures in the next 12 months, $13.9 billion of it not yet distressed but already showing warning signs. Deals reporting so far in September show office delinquency above 14%.","significance":"A transfer to special servicing before any payment is missed rests on an imminent-default determination under the pooling and servicing agreement, which borrowers can contest, and it brings special-servicing and workout fees, cash-management sweeps and servicer control over leasing and capital decisions while the loan is still current. The 72% later-default rate means most of these files end in maturity-default enforcement: receiverships, UCC foreclosures on mezzanine collateral and claims under carve-out and completion guaranties. With $39 billion of office maturities due within a year, expect more disputes over extension conditions and between certificateholders and special servicers over workout versus liquidation.","tags":["office","special servicing","cmbs","maturity default","imminent default"]},{"id":"trend-009","title":"CMBS Special Servicing Rate Rises to 11.42% in August, Highest Since February 2013, as $3.16B of Loans Transfer","category":"lending-foreclosure","date":"2026-09-16","scope":"U.S. CMBS, all property types (Trepp data, August 2026)","metric":"Special servicing rate 11.42%, up 33 bps","source":"live","sourceUrl":"https://www.credaily.com/briefs/cmbs-special-servicing-hits-highest-rate-since-2013/","summary":"Trepp's overall CMBS special servicing rate rose 33 basis points in August 2026 to 11.42%, its highest level since February 2013, CRE Daily reported September 16. New transfers totaled $3.16 billion across 32 whole loans, while only about $500.7 million across 14 loans left special servicing. The largest transfer was the $1.10 billion Los Angeles Office/Studio Portfolio, which moved to the special servicer before its August 9 maturity after exhausting its extension options. Office special servicing rose 32 bps to 16.90%, retail 32 bps to 13.60% and mixed-use 154 bps to 13.47%, the last because of the Los Angeles portfolio. Trepp's overall CMBS delinquency rate, by contrast, was essentially flat, down 1 bp to 7.85%.","significance":"Special servicing climbing while delinquency holds flat means distress is surfacing at maturity and through servicer-initiated transfers rather than missed monthly payments, which moves disputes to maturity default, extension-option conditions and the terms of forbearance and modification. Loans that transfer after exhausting their extensions generally resolve through negotiated extensions tied to paydowns, deeds in lieu, or receivership and foreclosure, and each path can produce guaranty and lender-liability claims.","tags":["cmbs","special servicing","trepp","maturity default","office"]},{"id":"trend-010","title":"Nonresidential Construction Input Costs Up 8.9% in a Year as 55% of Contractors Report Canceled, Postponed or Scaled-Back Projects","category":"construction-defect","date":"2026-09-10","scope":"U.S. new nonresidential construction (AGC analysis of producer price index data and member survey)","metric":"Input costs +8.9%, August 2025 to August 2026","source":"live","sourceUrl":"https://www.agc.org/news/2026/09/10/construction-input-costs-climb-89-between-august-2025-and-august-2026-association-survey-finds-war","summary":"The producer price index for inputs to new nonresidential construction rose 8.9% from August 2025 to August 2026, the Associated General Contractors of America reported September 10. Over the same year, diesel fuel rose 77.8%, liquid asphalt 16.4%, aluminum mill shapes 27.3%, steel mill products 23.4% and copper and brass mill shapes 20.9%, and some of these metals are subject to tariffs of up to 50%. In AGC's recent survey, 55% of respondents reported projects canceled, postponed or scaled back in the past six months: one-third attributed the disruptions to rising costs, 13% to lengthening or uncertain completion times and 10% to changes in demand tied to tariffs.","significance":"Increases this steep on fixed-price and guaranteed-maximum-price contracts are the classic source of price-escalation claims, change-order disputes and arguments over whether tariffs count as force majeure or a change in law. Cancellations and postponements add termination-for-convenience claims, delay damages, and lien and payment disputes among owners, general contractors and subcontractors on commercial projects.","tags":["construction costs","tariffs","price escalation","force majeure","change orders"]},{"id":"trend-011","title":"Federal ADA Title III Suits Reach 5,006 in the First Half of 2026, on Pace to Top 10,000 for the Year","category":"premises-liability","date":"2026-09-09","scope":"U.S. federal courts, all ADA Title III filings (Seyfarth Shaw tracking)","metric":"5,006 suits in H1 2026 vs. a 4,463 four-year first-half average","source":"live","sourceUrl":"https://www.adatitleiii.com/2026/09/2026-mid-year-report-ada-title-iii-federal-lawsuit-numbers-are-climbing/","summary":"Seyfarth Shaw's mid-year report, published September 9, counts 5,006 ADA Title III suits filed in federal court in the first half of 2026, against an average of 4,463 in the first six months of each of the prior four years. If the trend holds, the firm says, 2026 could end with more than 10,000 federal filings, the most since 2021's all-time high of 11,452. California led with 2,426 suits, followed by Florida (709), Illinois (505) and New York (485), and Seyfarth ties the rise in part to several relatively new plaintiffs' firms entering the field. The count covers all Title III suits, including website-accessibility claims, so it does not isolate physical-access suits against properties.","significance":"Title III reaches both the owner and the operator of a place of public accommodation, so landlords of retail centers, hotels, restaurants and office buildings can be named alongside their tenants in physical-access suits. More filings, driven in part by new serial-plaintiff firms, mean more claims to defend or settle and more disputes over how leases allocate accessibility compliance and indemnity between landlord and tenant.","tags":["ada title iii","accessibility","serial litigation","landlord liability","retail"]},{"id":"trend-012","title":"KBRA: CMBS Distress Rate Climbs to 10.3% in August Even as Delinquency Falls to 7.6%; Office Distress at 17.8%","category":"lending-foreclosure","date":"2026-09-01","scope":"KBRA-rated U.S. private-label CMBS ($343.4B: conduit, SASB and large loan)","metric":"Distress 10.3% (+24 bps); delinquency 7.6% (-22 bps)","source":"live","sourceUrl":"https://www.kbra.com/publications/bZbJXHWr","summary":"KBRA's August 2026 CMBS loan performance report, published September 1, shows the 30+ day delinquency rate on its $343.4 billion rated universe of U.S. private-label CMBS falling 22 bps to 7.6% ($25.4 billion), while the distress rate, which adds current loans in special servicing, rose 24 bps to 10.3%. Office distress rose 61 bps to 17.8% on an increase in current but specially serviced loans; notable new office transfers were Project James ($377.6 million in BSREP 2021-DC), 111 Livingston Street ($120 million) and 60 Madison Avenue ($100 million). Retail distress rose 50 bps to 10.1%, driven mainly by Fresno Fashion Fair Mall ($325 million across six conduits) transferring to the special servicer.","significance":"KBRA's figures show the same split as Trepp's and CRED iQ's: fewer loans behind on payments, more performing loans handed to special servicers ahead of maturity. For bondholders and trustees, distress rising while delinquency falls can keep losses out of delinquency-based deal triggers, raising the stakes of disputes over appraisal reductions, control-shift events and servicer advancing; for sponsors and guarantors, a transfer before maturity is often the first step toward enforcement at the maturity date.","tags":["cmbs","kbra","special servicing","office","retail"]},{"id":"trend-013","title":"FDIC: Troubled CRE Loans at the Largest Banks Fall to 3.08%, Still More Than Five Times the Pre-Pandemic Average","category":"lending-foreclosure","date":"2026-08-25","scope":"All FDIC-insured banks, second quarter 2026","metric":"Non-owner-occupied CRE past-due/nonaccrual rate at $250B+ banks: 3.08% (pre-pandemic average 0.59%)","source":"live","sourceUrl":"https://www.fdic.gov/news/speeches/2026/fdic-quarterly-banking-profile-second-quarter-2026","summary":"The FDIC's Quarterly Banking Profile statement for the second quarter of 2026, released August 25, reports that the past-due and nonaccrual rate on non-owner-occupied commercial real estate loans at banks with more than $250 billion in assets fell for the seventh consecutive quarter to 3.08%, below its 4.99% peak in the third quarter of 2024 but well above the 0.59% pre-pandemic average. Industry-wide, past-due and nonaccrual non-owner-occupied CRE balances fell $2.0 billion, or 8.9%, from the prior quarter. The FDIC notes that the largest banks hold lower concentrations of these loans relative to assets and capital than smaller banks. At community banks, the reserve coverage ratio declined to 145.6% because noncurrent loans of all types grew faster than loss allowances.","significance":"The industry improvement is carried by the largest banks, while smaller banks, which hold more CRE relative to capital, are seeing reserve coverage thin. Those lenders are the ones most likely to press local borrowers into workouts, sell notes to distressed-debt buyers, or enforce guaranties on office and retail loans, and a troubled-loan rate still several times its pre-pandemic level means legacy CRE workouts and foreclosures keep coming through bank channels.","tags":["fdic","bank exposure","nonaccrual","community banks","cre concentration"]},{"id":"trend-014","title":"Lenders Modified $2.36B of CMBS and CRE CLO Loans From May Through July, Mostly Extensions and Forbearances","category":"lending-foreclosure","date":"2026-08-13","scope":"U.S. CMBS and CRE CLO loans tracked by CRED iQ","metric":"82 loans, $2.36B modified; multifamily 48.4% of balance","source":"live","sourceUrl":"https://cred-iq.com/blog/2026/08/13/cre-loan-modifications-may-july-2026-multifamily-leads/","summary":"CRED iQ tracked 82 modified CMBS and CRE CLO loans with $2.36 billion outstanding from May through July 2026, in a report published August 13. Maturity extensions were the largest category at 21 loans and $802.5 million (34.0% of modified balance), followed by forbearances at 15 loans and $514.0 million (21.8%). Extensions, forbearances and combination modifications, the categories CRED iQ associates most closely with lenders buying time on distressed collateral, made up 70.5% of modified balance. Multifamily led by property type with 35 loans and $1.14 billion (48.4%), followed by hotels with 15 loans and $493.8 million (20.9%).","significance":"When distress is worked out through extensions and forbearances rather than foreclosure, the legal risk moves into the modification documents: forbearance defaults, springing guaranties, lender-liability and course-of-dealing claims when a lender declines a second extension, and bondholder challenges to servicers' modification decisions under pooling and servicing agreements. Multifamily's share points to where foreclosures are likely if these loans cannot be repaid or extended again.","tags":["loan modifications","forbearance","extensions","multifamily","cre clo"]},{"id":"trend-015","title":"Multifamily CMBS Distress More Than Doubles to 13% Since February as Apartments Make Up 96% of July's Newly Distressed Loans","category":"lending-foreclosure","date":"2026-08-07","scope":"CMBS loans in the 50 largest U.S. metros (CRED iQ, data through July 2026)","metric":"Multifamily distress 6.0% to 13.0%; 11.6% of $393.5B distressed overall","source":"live","sourceUrl":"https://cred-iq.com/blog/2026/08/07/cre-cmbs-distress-report-top-50-u-s-metro-rankings-and-whats-driving-them/","summary":"Across the 50 largest CMBS markets, CRED iQ counted $45.8 billion of $393.5 billion in outstanding balance as distressed, a balance-weighted rate of 11.6%, in a report published August 7, 2026. Multifamily distress more than doubled since February, from 6.0% to 13.0%, while office distress eased from 21.2% to 16.7%. In July, 180 loans totaling $992 million became newly distressed, 96% of it multifamily. Austin–Round Rock–San Marcos, Texas carried a 28.7% distress rate, and newly distressed apartment loans included Weston Medical Center Apartments in Houston ($84.0 million) and Hawthorne At Clairmont in Atlanta ($36.6 million).","significance":"In this data, apartments have replaced office as the fastest-growing source of CMBS distress. Expect more multifamily foreclosure and receivership actions by special servicers in high-distress markets such as Austin, disputes with syndicator borrowers over guaranties and cash-management sweeps, and claims by passive investors against sponsors; in Texas, where commercial foreclosure is typically non-judicial, rising distress also means more last-minute restraining-order requests and bankruptcy filings to stop trustee sales.","tags":["multifamily","sun belt","cmbs","texas","distress"]},{"id":"trend-016","title":"KBRA: CMBS Delinquency Rate Rises to 7.7% in September, Led by Office and Multifamily","category":"lending-foreclosure","date":"2026-09-30","scope":"KBRA-rated U.S. private label CMBS universe ($344.4 billion)","metric":"30+ day delinquency rate up 9 bps to 7.7%","source":"live","sourceUrl":"https://www.kbra.com/publications/TXmxGCqk/cmbs-loan-performance-trends-september-2026?format=web","summary":"KBRA's September 2026 CMBS Loan Performance Trends report, published September 30, found the 30+ day delinquency rate on its rated U.S. private-label CMBS rose 9 basis points to 7.7% in September from 7.6% in August, while the distress rate, which adds current loans in special servicing, declined 4 bps. Loans totaling $1.6 billion were newly added to the distress rate, and 74.9% of that balance ($1.2 billion) involved imminent or actual maturity default. Office accounted for the largest share of newly distressed loans (47.7%, $757.5 million), followed by multifamily (14.6%, $231.5 million) and mixed-use (13.6%, $216 million). KBRA's rated universe covers $344.4 billion.","significance":"With nearly three-quarters of the newly distressed balance tied to imminent or actual maturity default, more borrowers are reaching maturity unable to refinance or sell, the direct precursor to the foreclosure, receivership and workout litigation this tracker follows. The concentration in office and multifamily points to where that litigation is most likely to surface next.","tags":["cmbs","delinquency","office","multifamily","maturity default"]},{"id":"trend-017","title":"Multifamily CMBS Delinquency Climbs to 8.04%, Topping the Overall 8.02% Rate for the First Time Since Covid","category":"lending-foreclosure","date":"2026-10-02","scope":"U.S. CMBS, all property types (Trepp data, September 2026)","metric":"Multifamily delinquency 8.04% (+35 bps) vs. overall 8.02% (+17 bps)","source":"live","sourceUrl":"https://yieldpro.com/2026/10/multifamily-cmbs-delinquency-rate-leads-overall-rate-higher-in-september/","summary":"Trepp's September 2026 delinquency report puts the multifamily CMBS delinquency rate at 8.04 percent after a 35 basis point monthly rise, the largest increase of any property type Trepp tracks, and above the overall CMBS rate for the first time since the Covid shutdowns. The overall rate rose 17 basis points to 8.02 percent. A year ago the multifamily rate stood at 6.59 percent, and two years ago at 3.33 percent. Office remained the weakest sector at 12.16 percent, and counting loans past maturity but still current on interest would lift the overall rate to 9.66 percent.","significance":"Apartments, long treated as the safe CRE asset class, are now delinquent at a higher rate than the CMBS market as a whole, which points to more special-servicing transfers, receiverships and foreclosure filings against multifamily borrowers, and more guaranty enforcement against sponsors who signed carve-out guaranties. Borrowers negotiating workouts should expect servicers to press on cash management, reserve sweeps and recourse triggers, and investors in syndicated multifamily deals should watch for disputes over capital calls and sponsor disclosures.","tags":["cmbs","multifamily","delinquency","trepp","special servicing"]},{"id":"trend-018","title":"Large Commercial Property Insurance Rates Fall 14.5% in Q2 as the Soft Market Widens","category":"lease-disputes","date":"2026-10-05","scope":"U.S. large and complex commercial property insurance (Willis portfolio, Q2 2026)","metric":"Large property rates -14.5% year over year; 5+ carrier layered programs -23.4%","source":"live","sourceUrl":"https://www.insurancejournal.com/news/national/2026/10/05/887978.htm","summary":"Willis, a WTW business, reports in its fall 2026 Insurance Marketplace Realities that rates for large and complex commercial property programs fell 14.5 percent in the second quarter of 2026 versus a year earlier, compared with an 8.4 percent decline a year ago. Layered programs spread across five or more carriers saw reductions of about 23.4 percent, and treaty reinsurance renewals softened. First-half 2026 catastrophe losses of $42 billion were the lowest since 2020. Casualty rate increases are moderating rather than reversing, and cyber rates are flat within a 5 percent band.","significance":"Falling premiums tempt owners to restructure programs with higher deductibles, sublimits and more carriers, which can put them out of step with insurance covenants in loan documents and leases written in a tight market, handing distressed-loan servicers an additional default theory. Tenants are likely to audit past operating-expense pass-throughs for insurance overcharges, and layered programs raise the odds of claim-allocation disputes after a loss. Owners, REITs and lenders should review covenant compliance and insured values before capturing the savings.","tags":["insurance","property rates","covenants","cam audits","willis"]},{"id":"trend-019","title":"Trepp CMBS special servicing rate climbs to 11.49% in September, highest since February 2013","category":"lending-foreclosure","date":"2026-10-14","scope":"U.S. CMBS loans in special servicing (Trepp), September 2026, as reported by CRE Daily","metric":"11.49% overall (up 7 bps month over month, up 84 bps year over year); $2.65B newly transferred, 57% office; $1.95B resolved","source":"live","sourceUrl":"https://www.credaily.com/?p=224030","summary":"Trepp's share of CMBS loan balances with special servicers edged up seven basis points to 11.49% in September, the highest reading since February 2013 and 84 basis points above a year earlier. About $2.65B across 42 whole loans moved to special servicing during the month, and office loans made up 57% of that inflow; the single largest was the $512.8M One SoHo Square loan on a New York office building, flagged for imminent balloon or maturity default. Retail had the highest increase by property type, reaching 13.84%, while the office special servicing rate eased slightly to 16.85%. Exits also jumped: 48 whole loans totaling $1.95B left special servicing, a 237% increase over August.","significance":"More than one in nine CMBS loan dollars is now with a special servicer, the stage where modifications, forbearance, receivership motions and foreclosure filings are negotiated or launched. With much of the new inflow driven by loans that cannot pay off at maturity rather than missed payments, expect more extension fights, maturity-default suits and guarantor claims, while the jump in resolutions points to a busier pipeline of workouts and liquidations.","tags":["cmbs","special servicing","trepp","maturity default","office"]},{"id":"trend-020","title":"U.S. office vacancy eases to 19.8% in Q3 2026, but Class B and C vacancy keeps rising (Cushman & Wakefield)","category":"lease-disputes","date":"2026-10-06","scope":"U.S. office market, 92 markets tracked by Cushman & Wakefield, Q3 2026 Office MarketBeat","metric":"19.8% national vacancy (down 25 bps year over year, from a 20.1% high in Q3 2025); +50,000 sf Q3 net absorption; 7.1 msf delivered year to date","source":"live","sourceUrl":"https://www.cushmanwakefield.com/en/united-states/news/2026/10/office-recovery-broadens-as-vacancy-declines","summary":"Cushman & Wakefield put national office vacancy at 19.8% at the end of the third quarter, 25 basis points lower than a year earlier and down from the recent 20.1% high reached in Q3 2025. Net absorption was only slightly positive at 50,000 square feet, but it was the fifth straight quarter of gains, and vacancy fell year over year in 48 of the 92 markets the firm tracks. The improvement is concentrated at the top: vacancy in top-tier buildings has dropped 215 basis points over two years while Class B and C vacancy continues to climb. New supply remains thin, with just 7.1 msf delivered in the first three quarters of 2026.","significance":"A national vacancy rate still near one in five, with the gap between trophy and commodity buildings widening, means owners of older Class B and C office stock face falling rents and values that strain debt-service and loan-to-value covenants at refinancing. Tenants in those buildings gain leverage in renewals, co-tenancy and abatement disputes, while lenders on lower-tier assets should expect more modification requests, receiverships and deed-in-lieu negotiations even as the headline number improves.","tags":["office","vacancy","cushman & wakefield","class b","leasing"]},{"id":"trend-021","title":"MBA: CMBS and Bank Delinquency Ease in Q2 2026, but Fannie Mae, Freddie Mac and Life Company Rates All Rise","category":"lending-foreclosure","date":"2026-09-28","scope":"U.S. commercial and multifamily mortgages by capital source (MBA, Q2 2026)","metric":"CMBS 6.53% (-42 bps); Fannie Mae 0.60% (+18 bps); Freddie Mac 0.51% (+8 bps); life cos 0.48% (+10 bps)","source":"live","sourceUrl":"https://newslink.mba.org/mba-newslinks/2026/september/mba-newslink-tuesday-sept-29-2026/mba-commercial-and-multifamily-mortgage-delinquencies-mixed-in-second-quarter/","summary":"The Mortgage Bankers Association's second-quarter 2026 delinquency report shows a split market. CMBS delinquency fell 0.42 points to 6.53 percent and banks and thrifts slipped 0.04 points to 1.2 percent, while Fannie Mae rose 0.18 points to 0.6 percent, Freddie Mac 0.08 points to 0.51 percent and life company portfolios 0.10 points to 0.48 percent. MBA's Reggie Booker said multifamily faces a tough combination of higher interest rates and challenging market fundamentals. The five capital sources covered hold more than 80 percent of commercial mortgage debt, and each defines delinquency differently (30, 60 or 90 days, with differing forbearance treatment).","significance":"Stress is spreading from CMBS into the agency and life company lenders that finance stabilized assets, while the CMBS improvement partly reflects old problem loans being resolved, which generates its own deficiency and guaranty claims. Expect disputes over forbearance terms, reserve and escrow draws, and recourse guaranties, and note that differing delinquency definitions affect when default notices and remedies are triggered. Multifamily borrowers, sponsors and their lenders should review forbearance and cure language now.","tags":["mba","delinquency","multifamily","fannie mae","forbearance"]},{"id":"trend-022","title":"Colliers: National Retail Vacancy Dips to 4.3% in Q3 2026 as Absorption Hits Its Highest Level Since 2023","category":"lease-disputes","date":"2026-10-15","scope":"U.S. retail real estate market (Colliers Q3 2026 data, as reported by Chain Store Age)","metric":"4.3% national retail vacancy (down 10 bps); 10.5 million sq ft net absorption, the highest quarterly total since 2023","source":"live","sourceUrl":"https://chainstoreage.com/colliers-national-retail-vacancy-rate-hits-43-q3","summary":"Colliers data reported by Chain Store Age put national retail vacancy at 4.3% in the third quarter of 2026, down 10 basis points, with limited new supply keeping availability tight. Net absorption of 10.5 million square feet was the highest quarterly total since 2023, driven by retailer expansion and backfilled space. Malls ended the quarter at 8.2% vacancy and shopping centers at 5.4%. Average asking rents reached $26.20 per square foot, up 0.7% from the prior quarter. Retail construction totaled 58.1 million square feet, with 7.6 million square feet delivered, and Colliers said elevated construction and financing costs continue to hold back new development.","significance":"Retail vacancy near historic lows with limited new supply gives landlords more leverage in lease renewals and expansions, raising the stakes on co-tenancy, exclusive-use and percentage-rent clauses as tenants compete for scarce space. With construction pipelines constrained by financing costs, owners of well-located centers have fewer easy outs if a redevelopment or repositioning plan falls through, increasing the practical cost of disputes over lease terminations, assignment and tenant improvement allowances.","tags":["retail","vacancy","colliers","absorption","shopping centers"]},{"id":"trend-024","title":"Cushman & Wakefield: U.S. Industrial Vacancy Falls to 6.8% in Q3 2026 as Net Absorption Hits 76.6 Million Square Feet","category":"lease-disputes","date":"2026-10-12","scope":"U.S. industrial and logistics real estate (Cushman & Wakefield Q3 2026 U.S. Industrial MarketBeat)","metric":"6.8% national industrial vacancy, 20 bps below the late-2025 peak; 76.6 msf Q3 net absorption","source":"live","sourceUrl":"https://www.cushmanwakefield.com/en/united-states/news/2026/10/leasing-activity-remains-elevated-and-new-construction-rebounds","summary":"Cushman & Wakefield's Q3 2026 U.S. Industrial MarketBeat put national industrial vacancy at 6.8%, 20 basis points below its late-2025 peak and the lowest since year-end 2024. Net absorption reached 76.6 million square feet in the quarter, the strongest since the first quarter of 2023. The construction pipeline rose 6% from the second quarter to about 324 million square feet, up 23% year over year, and annual asking rent growth reached 4% nationwide. Data center-related users accounted for more than 8% of new leasing activity so far this year.","significance":"Falling vacancy and re-accelerating rents shift leverage to industrial landlords, raising the stakes in renewal-option and fair-market-rent resets, holdovers, expansion and right-of-first-offer disputes, and assignments by tenants trying to keep below-market leases. A rebuilding construction pipeline weighted toward build-to-suit projects brings more development-agreement, delay and mechanics' lien disputes, and data center-related users add zoning and power-supply questions to industrial siting.","tags":["industrial","vacancy","cushman & wakefield","logistics","leasing"]},{"id":"trend-025","title":"Wells Fargo and Bank of America CRE Write-Offs Jump to $107M and $105M in Q3 as Problem Loans Shrink","category":"lending-foreclosure","date":"2026-10-19","scope":"U.S. money-center bank commercial real estate loan books (third-quarter 2026 earnings, Wells Fargo and Bank of America)","metric":"CRE write-offs: Wells Fargo $107M (from $16M), Bank of America $105M (from $2M); problem CRE loans down 20% and 17%","source":"live","sourceUrl":"https://www.bisnow.com/news/national/capital-markets/big-banks-take-bigger-cre-losses-as-they-clear-problem-loans","summary":"Third-quarter results show the two banks taking far larger commercial real estate losses while shrinking their troubled books. Wells Fargo's CRE write-offs rose to $107M from $16M in the second quarter, its problem CRE loans fell 20% to $2.7B, and its office loans fell 7% to $18.6B. Bank of America's CRE write-offs rose to $105M from $2M while troubled CRE loans fell 17% to $888M. Both cut reserves: Wells Fargo to about $1.61 per $100 of CRE loans from $1.77, and Bank of America to $1.14 from $1.28.","significance":"Rising write-offs alongside falling problem-loan balances mean banks are resolving distressed CRE credits rather than extending them: note sales, discounted payoffs, foreclosures and receiverships. Borrowers on maturing bank loans should expect less forbearance and faster enforcement, guarantors should expect deficiency and guaranty claims to follow sales at a loss, and buyers of discounted notes step into the lender's enforcement rights, which tends to bring more litigation, not less.","tags":["bank cre losses","charge-offs","wells fargo","bank of america","loan sales"]},{"id":"trend-027","title":"CRED iQ: CMBS Distress Hits 11.2% as Stress Shifts From New York to Los Angeles, Chicago and Houston","category":"lending-foreclosure","date":"2026-11-03","scope":"U.S. conduit and SASB CMBS loans (CRED iQ October 2026 loan data, as reported by CRE Daily)","metric":"11.2% of $617 billion in conduit and SASB loans distressed (10.9% a year earlier); Chicago 23.5%, Houston 15.3%, Los Angeles 14.6%, New York 11.2%","source":"live","sourceUrl":"https://www.credaily.com/briefs/cmbs-distress-hits-11-2-as-stress-shifts-to-l-a-and-chicago/","summary":"CRED iQ's October loan data put 11.2% of the $617 billion in conduit and SASB loans in distress, up from 10.9% a year earlier, with the stress moving away from New York. New York improved to 11.2% from 12.5%, while Los Angeles jumped to 14.6% from 9.4%, Houston rose to 15.3% from 12.4% and Chicago to 23.5% from 19.5%. Office distress runs 16.4% nationally and represents 44% of troubled balance; office distress reached 21.5% in Los Angeles (from 9.9%), 32.6% in Chicago and 31.5% in Houston (from 21.9%). In Los Angeles, Equitable Plaza's $74 million loan came due again and wasn't repaid, with a latest valuation of $57.7 million against $150.5 million at origination, and Philadelphia's 99.5%-leased 2400 Market Street also hit a maturity wall.","significance":"Defaults driven by maturity and refinancing at current rates and values, rather than occupancy, tend to produce disputes over extensions, modifications and forbearance, guarantor and recourse carve-out claims, receivership and foreclosure timing, and mezzanine intercreditor conflicts. Owners and guarantors in the newly stressed metros, special servicers, and lenders weighing refinancings should expect more contested workouts, particularly where values sit far below origination.","tags":["cmbs","cred iq","office","maturity default","special servicing"]},{"id":"trend-029","title":"Trepp: CMBS Delinquency Slips to 7.87% in October on One Loan's Cure, While Retail, Office and Multifamily Worsen","category":"lending-foreclosure","date":"2026-11-03","scope":"U.S. CMBS loans (Trepp October 2026 delinquency report, as reported by CRE Daily)","metric":"7.87% overall (down 15 bps from 8.02%); retail 7.21% (+63 bps), office 12.33% (+17 bps), multifamily 8.09% (+5 bps), lodging 5.94% (-24 bps), industrial 1.10% (-4 bps)","source":"live","sourceUrl":"https://www.credaily.com/briefs/cmbs-delinquency-rate-dips-to-7-87-as-retail-jumps-63-bps/","summary":"Trepp's overall CMBS delinquency rate fell 15 basis points to 7.87% in October from 8.02% in September, but the improvement came largely from a single loan: a $975 million showroom portfolio loan tied to High Point and Las Vegas returned to current status. Underneath, retail posted the biggest increase, rising 63 basis points to 7.21%, office rose 17 basis points to 12.33%, still the highest of any property type, and multifamily edged up 5 basis points to 8.09%. Lodging improved to 5.94% and industrial eased to 1.10%. The largest new delinquencies were a $384.3 million Los Angeles office loan and a $210 million Bay Area apartment loan.","significance":"A headline decline driven by one large cure masks worsening payment performance in retail, office and multifamily, the sectors that generate most foreclosure, receivership and guaranty litigation. Newly delinquent large loans typically move to special servicing and then to default notices, receiver motions and maturity-default suits, so borrowers, guarantors and mezzanine lenders on retail and office collateral should expect more contested workouts rather than relief.","tags":["cmbs","delinquency","trepp","retail","office"]},{"id":"trend-030","title":"Green Street: Commercial Property Prices Fall 0.7% in October, Trimming 12-Month Gain to 3.7%","category":"lending-foreclosure","date":"2026-11-05","scope":"U.S. commercial real estate values (Green Street Commercial Property Price Index, October 2026)","metric":"All-property index -0.7% in October; +3.7% over twelve months","source":"live","sourceUrl":"https://www.greenstreet.com/property-prices-tick-lower/","summary":"Green Street reports that its Commercial Property Price Index declined 0.7 percent in October 2026, leaving values up 3.7 percent over the past twelve months. The firm's co-head of strategic research said a recent dip in bond yields is a welcome sign but that investors are still contending with a 10-year Treasury yield near 5 percent.","significance":"A monthly price decline with long-term rates near 5 percent keeps pressure on appraised values that drive loan-to-value tests, refinancing proceeds and maturity extensions. Where updated appraisals come in lower, borrowers face paydown demands, cash-management triggers and covenant defaults, and the gap between valuation and debt is what typically pushes a workout toward receivership or foreclosure litigation. Owners and lenders heading into 2027 maturities should expect valuation disputes to feature in extension and modification fights.","tags":["property values","price index","refinancing","interest rates","green street"]},{"id":"trend-031","title":"Trepp: CMBS Special Servicing Rate Jumps to 11.74% in October, Highest Since December 2012, as Hotel and Apartment Maturities Come Due","category":"lending-foreclosure","date":"2026-11-10","scope":"U.S. CMBS loans (Trepp October 2026 special servicing report, as reported by CRE Daily)","metric":"11.74% overall (up 25 bps in a month, up 90 bps year over year); $3.01 billion newly transferred across 46 loans, 37% lodging; lodging 10.17%, multifamily 9.22%, office 16.60%","source":"live","sourceUrl":"https://www.credaily.com/briefs/cmbs-special-servicing-rate-hits-11-74-a-13-year-high/","summary":"Trepp's CMBS special servicing rate rose 25 basis points to 11.74% in October, 90 basis points above a year earlier and the highest reading since December 2012, CRE Daily reports. About $3.01 billion moved into special servicing across 46 loans, up 14% from September, and lodging made up 37% of the new transfers, led by the $745.7 million Project Prime hotel portfolio loan, which matures Dec. 6, and the $517.7 million Blackjack apartment portfolio. The lodging rate jumped 122 bps to 10.17%, multifamily rose to 9.22% and mixed-use to 13.61%, while office improved to 16.60% and retail eased to 13.71%. Roughly 45% of the dollars in the bigger loans moved because a balloon payment or maturity was about to be missed, and exits slowed to about $1.53 billion across 38 loans, down 22% from September.","significance":"Transfers driven by maturities rather than missed monthly payments mean special servicers are taking over loans on properties that still cover debt service, which sets up disputes over extension terms, cash management, default interest and servicer fees rather than simple payment defaults. Hotel and apartment borrowers with near-term balloon dates should expect pre-negotiation agreements, receiver motions and guaranty demands, and lenders on large portfolios face contested valuations if workouts fail. With fewer loans leaving special servicing than entering, the backlog of foreclosure and receivership actions is likely to grow.","tags":["cmbs","special servicing","trepp","hotels","maturity defaults"]},{"id":"trend-032","title":"CRED iQ: Apartment Loans Hold 94% Occupancy but Income Slips, and Loans Below 1.0x Coverage Nearly Double in Denver and Austin","category":"lending-foreclosure","date":"2026-11-13","scope":"U.S. securitized apartment loans (CRED iQ review of 7,597 loans and Freddie Mac watchlist comments, as reported by CRE Daily)","metric":"Median occupancy 94%; revenue +1.0%, expenses +2.5%, NOI -0.2%; Denver 38 of 138 loans below 1.0x coverage (20 a year ago), Austin 39 of 87 (from 20); concessions in 6.8% of Freddie Mac watchlist comments (3.8% a year earlier); 294 loans carrying $6.3B affected","source":"live","sourceUrl":"https://www.credaily.com/briefs/apartment-concessions-climb-as-owners-defend-94-occupancy/","summary":"CRED iQ's review of 7,597 securitized apartment loans found median occupancy steady at 94%, but revenue rose only 1.0% against 2.5% higher expenses, so net operating income slipped 0.2%, CRE Daily reports. The weakness is concentrated in a few metros: Denver revenue fell 5.4% and NOI 11.8%, and Austin revenue fell 5.1% and NOI 10.8%. Denver now has 38 of its 138 loans below 1.0x debt service coverage, up from 20 a year ago, and Austin's count rose to 39 of 87, also from 20. Concessions appeared in 6.8% of Freddie Mac apartment watchlist comments in October, up from 3.8% a year earlier, and across all deal types 294 loans carrying $6.3 billion are affected.","significance":"Occupancy held up by free rent hides falling income, and a loan that no longer covers its debt service is the usual first step toward cash-management triggers, watchlist and special servicing transfers, and then default notices. Apartment owners in Denver, Austin and other oversupplied markets should expect lenders and servicers to test debt service coverage covenants and reserve requirements, and guarantors should review carve-out and shortfall exposure before a workout begins. Lenders weighing extensions will want current rent rolls that show concessions, since reported revenue lags what owners are giving away to keep units filled.","tags":["multifamily","debt service coverage","concessions","cred iq","freddie mac"]}],"regulatory":[{"id":"reg-001","title":"Philadelphia Algorithmic Rent-Fixing Ordinance","type":"Municipal Ordinance","jurisdiction":"Philadelphia, PA","state":"PA","enacted":"2024","summary":"Bars landlords and property managers from using algorithmic revenue-management software to set rents based on non-public competitor pricing data. Now the subject of the first courtroom tests naming both landlords and their software vendors.","relatedCases":["live-001"]},{"id":"reg-002","title":"San Diego Municipal Code § 98.1103 — Algorithmic Rent-Pricing Ban","type":"Municipal Ordinance","jurisdiction":"San Diego, CA","state":"CA","enacted":"Effective June 21, 2025","summary":"Prohibits landlords from using software that generates rent or occupancy recommendations derived from non-public competitor data. Unlike the federal antitrust theory pursued against RealPage, the ordinance requires no proof of coordination among competitors and authorizes a private right of action with statutory penalties up to $1,000 per violation.","relatedCases":["live-014"]},{"id":"reg-003","title":"New Jersey Algorithmic Pricing Ordinance","type":"State Ordinance","jurisdiction":"New Jersey","state":"NJ","enacted":"July 2026","summary":"Joins Philadelphia and San Diego among a growing wave of state and local bans on algorithmic rent-pricing tools, adopted the same month a cluster of related suits were filed against multifamily landlords in Philadelphia.","relatedCases":["live-001"]},{"id":"reg-004","title":"California SB 9 — Ministerial Two-Lot Subdivisions","type":"State Law","jurisdiction":"California","state":"CA","enacted":"In effect statewide","summary":"Allows qualifying two-lot residential subdivisions to be approved ministerially rather than through discretionary review. A live test over whether cities can condition SB 9 approvals on formula-based impact fees is now testing the limits of that ministerial status.","relatedCases":["live-012"]},{"id":"reg-005","title":"Florida SB 4-D — Condo Milestone Inspections & Structural Integrity Reserve Studies","type":"State Law","jurisdiction":"Florida","state":"FL","enacted":"Enacted May 26, 2022; SIRS deadline December 31, 2025","summary":"Enacted after the Surfside collapse, requires condo and co-op buildings three stories or taller to undergo milestone structural inspections (at 25 years for coastal buildings, 30 inland) and a Structural Integrity Reserve Study every 10 years covering nine structural components, with reserve-funding waivers now prohibited. Addresses ongoing building maintenance and disclosure, but does not shift underlying construction-quality risk away from developers and design/build teams.","relatedCases":["live-016"]},{"id":"reg-006","title":"NYC 467-m — Office-to-Residential Conversion Tax Incentive","type":"Municipal Tax Incentive","jurisdiction":"New York, NY","state":"NY","enacted":"2024, aligned with the City of Yes rezoning package","summary":"Offers up to 35 years of property tax abatement for qualifying office-to-residential conversions, provided at least 25% of the resulting units are affordable — paired with the City of Yes zoning text amendment to reduce barriers like parking mandates. Aimed at accelerating the same category of factory- and office-conversion projects already generating years-long construction-defect litigation once units are sold and occupied.","relatedCases":["live-018"]},{"id":"reg-007","title":"EPA CERCLA Hazardous Substance Designation — PFOA and PFOS (PFAS)","type":"Federal Rule","jurisdiction":"Federal (nationwide)","enacted":"Effective July 8, 2024","summary":"Designates two PFAS compounds — PFOA and PFOS — as CERCLA hazardous substances, meaning Phase I environmental site assessments must now consider them and current or past owners can face strict, retroactive cleanup liability regardless of fault. Industry groups including the U.S. Chamber of Commerce and the Associated General Contractors of America have filed a legal challenge to the designation, which significantly expands the universe of contamination that can trigger Superfund-style liability for commercial property owners.","relatedCases":["live-017","live-019"]},{"id":"reg-008","title":"Basel III Endgame Re-Proposal — Bank Capital Treatment of CRE Loans","type":"Federal Rule (Proposed)","jurisdiction":"Federal (nationwide)","enacted":"Re-proposed March 19, 2026; comments due June 18, 2026","summary":"The Federal Reserve, FDIC, and OCC re-proposed bank capital rules that reverse course from the original 2023 Basel III Endgame proposal, using loan-to-value-based risk weights to reduce punitive capital treatment of commercial real estate loans and cut minimum capital requirements for banks under $100B in assets by roughly 7.8%. A more favorable capital regime could ease the refinancing crunch behind the current wave of CMBS maturity defaults, though the rule remains in the comment period and is not yet final.","relatedCases":[]},{"id":"reg-009","title":"SEC Universal Proxy Rule — Exchange Act Rule 14a-19","type":"Federal Rule","jurisdiction":"Federal (nationwide)","enacted":"Adopted November 17, 2021 (Release No. 34-93596); compliance required for contested director elections at shareholder meetings held after August 31, 2022","summary":"Requires every party to a contested board election — the company and any dissident shareholder alike — to use a single 'universal' proxy card listing the full slate of both sides' nominees, so shareholders can vote for any mix of company and dissident candidates rather than being locked into one whole slate. REIT-sector law firm analyses marking the rule's third full proxy season report it has raised activists' odds of seating at least one dissident director while also increasing pressure on boards to settle before a contested vote is ever taken.","relatedCases":[]},{"id":"reg-010","title":"Maryland Unsolicited Takeover Act — Md. Code Ann., Corps. & Ass'ns §§ 3-800 to 3-806 (MGCL Title 3, Subtitle 8)","type":"State Law","jurisdiction":"Maryland","state":"MD","enacted":"Enacted 1999","summary":"Lets a Maryland corporation or REIT with at least three independent directors adopt, by board resolution alone and without a stockholder vote, up to five takeover defenses — a classified board, a two-thirds vote requirement to remove a trustee, board-only authority to fix trustee count and fill vacancies, and a majority-in-interest requirement for stockholder-requested special meetings. Because roughly 80% of the public REIT sector (by the RMZ index) is incorporated in Maryland, this statute is the default takeover-defense framework for most public REITs — though governance pressure has pushed about a third of Maryland REITs to affirmatively opt out of it.","relatedCases":[]}],"glossary":[{"id":"algorithmic-rent-pricing","term":"Algorithmic Rent-Pricing","definition":"Software that recommends rents or occupancy targets to landlords using pooled, often non-public, competitor data. RealPage-style suits allege that sharing this data functions as unlawful price coordination among competing landlords.","relatedCases":["live-001"],"relatedRegulatory":["reg-001","reg-002","reg-003"]},{"id":"article-78-proceeding","term":"Article 78 Proceeding","definition":"A special New York state-court proceeding used to challenge a government agency or board's decision as arbitrary, capricious, or beyond its authority — commonly used to fight rent-board and zoning-board rulings.","relatedCases":["live-011"]},{"id":"brownfield","term":"Brownfield","definition":"A property where redevelopment or reuse is complicated by the presence, or potential presence, of a hazardous substance or contaminant, typically left behind by prior industrial or commercial use.","relatedCases":["live-017","live-019"]},{"id":"cercla","term":"CERCLA (Superfund)","definition":"The federal Comprehensive Environmental Response, Compensation, and Liability Act — imposes strict, retroactive, joint-and-several cleanup liability on current and past owners of contaminated property, regardless of fault.","relatedCases":["live-017","live-019"],"relatedRegulatory":["reg-007"]},{"id":"chapter-11-reorganization","term":"Chapter 11 Reorganization","definition":"A form of bankruptcy that lets a financially distressed company — including a REIT — continue operating while it restructures its debts under court supervision, rather than liquidating outright.","relatedCases":["live-006"]},{"id":"cmbs","term":"CMBS (Commercial Mortgage-Backed Securities)","definition":"Bonds backed by a pool of commercial real estate loans. Monthly delinquency and special-servicing data on CMBS pools is one of the most closely watched signals of broad CRE distress.","relatedCases":["live-003"],"relatedTrends":["trend-002"]},{"id":"consent-decree","term":"Consent Decree","definition":"A court-approved settlement in which a defendant agrees to specific remedial obligations — often environmental cleanup — without admitting liability, enforceable afterward as a court order.","relatedCases":["live-019"]},{"id":"contempt-of-court","term":"Contempt of Court","definition":"A finding that a party violated a court order. In eminent-domain and zoning disputes, contempt motions are often used to enforce an injunction against a government body that keeps acting despite a prior ruling.","relatedCases":["live-009"]},{"id":"declaratory-judgment-action","term":"Declaratory Judgment Action","definition":"A lawsuit asking a court to define the parties' legal rights or obligations — for example, whether an insurance policy covers a claim — without necessarily awarding damages.","relatedCases":["live-017"]},{"id":"eminent-domain","term":"Eminent Domain / Condemnation","definition":"The government's power to take private property for public use in exchange for just compensation. Disputes typically center on whether the taking is genuinely for public use and whether the compensation offered is adequate.","relatedCases":["live-009"]},{"id":"fiduciary-duty","term":"Fiduciary Duty","definition":"A legal obligation to act in another party's best interest. In REIT litigation, breach-of-fiduciary-duty claims typically allege that directors or sponsors put their own financial interests ahead of shareholders'.","relatedCases":["live-013"]},{"id":"guarantor-liability","term":"Guarantor Liability / Recourse Carve-Out","definition":"Provisions in an otherwise non-recourse commercial loan — sometimes called a \"bad boy\" guaranty — that make a guarantor personally liable if specific triggering events occur, such as fraud or unauthorized additional debt.","relatedTrends":["trend-002"]},{"id":"inherently-beneficial-use","term":"Inherently Beneficial Use","definition":"A New Jersey zoning-law category — hospitals, schools, senior housing, and similar uses — historically given a near-automatic path past local zoning objections in a use-variance application.","relatedCases":["live-015"]},{"id":"milestone-inspection","term":"Milestone Inspection","definition":"A structural inspection now mandated for older condo and co-op buildings in states like Florida, timed to a building's age, aimed at catching structural deterioration before it becomes catastrophic.","relatedCases":["live-016"],"relatedRegulatory":["reg-005"]},{"id":"non-performing-matured-balloon-loan","term":"Non-Performing Matured Balloon Loan","definition":"A commercial mortgage that reached its scheduled maturity date without being paid off or refinanced, and is now in default status even if the borrower never missed a monthly payment.","relatedTrends":["trend-002"]},{"id":"phase-i-ii-environmental-assessment","term":"Phase I / Phase II Environmental Site Assessment","definition":"Standard pre-purchase due-diligence reports: a Phase I identifies potential contamination risk from a property's historical use, and a Phase II involves actual soil and groundwater testing if the Phase I flags a concern.","relatedCases":["live-017"],"relatedRegulatory":["reg-007"]},{"id":"pollution-exclusion","term":"Pollution Exclusion","definition":"A standard clause in general liability and property insurance policies that bars coverage for claims arising from the release of pollutants — frequently the subject of environmental-contamination coverage disputes.","relatedCases":["live-017"]},{"id":"regulatory-taking","term":"Regulatory Taking","definition":"A land-use restriction so severe that, even without physically seizing the property, courts treat it as a taking requiring just compensation under the Fifth Amendment.","relatedCases":["live-012"]},{"id":"special-servicer","term":"Special Servicer","definition":"The entity that takes over management of a securitized (CMBS) loan once it becomes distressed or defaults, with different incentives and legal options than the original lender — including foreclosure, note sale, or restructuring.","relatedTrends":["trend-002"]},{"id":"ucc-foreclosure","term":"UCC Foreclosure","definition":"A faster, non-judicial foreclosure process under Article 9 of the Uniform Commercial Code, used to seize the pledged equity interests — rather than the real property itself — in mezzanine-loan structures.","relatedCases":["live-003"]},{"id":"use-variance","term":"Use Variance","definition":"Permission from a local zoning board to use a property in a way the underlying zoning ordinance would otherwise prohibit, typically requiring the applicant to show hardship and that the variance won't harm the surrounding zone plan.","relatedCases":["live-015"]},{"id":"void-ab-initio","term":"Void Ab Initio","definition":"A legal finding that an action — such as a government's attempted condemnation — was invalid from the very moment it occurred, as if it never legally happened, rather than merely voidable going forward.","relatedCases":["live-009"]}],"courts":[{"jurisdiction":"U.S. Court of Appeals for the Eighth Circuit","url":"https://www.ca8.uscourts.gov/"},{"jurisdiction":"Appellate Court of Illinois, Fourth District","url":"https://www.illinoiscourts.gov/courts/appellate-court/districts-fourth-district"},{"jurisdiction":"Appellate Division, First Department, New York","url":"https://www.nycourts.gov/courts/AD1/"},{"jurisdiction":"Court of Common Pleas, Fayette County, Pennsylvania","url":"https://www.fayettecountypa.org/302/Court-of-Common-Pleas"},{"jurisdiction":"Circuit Court of St. Louis County, Missouri","url":"https://stlcountycourts.com/"},{"jurisdiction":"3rd Circuit Court, Wayne County, Michigan","url":"https://www.3rdcc.org/"},{"jurisdiction":"Philadelphia County Court of Common Pleas","url":"https://www.pacourts.us/courts/courts-of-common-pleas/individual-county-courts/philadelphia-courts"},{"jurisdiction":"Commonwealth Court of Pennsylvania","url":"https://www.pacourts.us/courts/commonwealth-court-judges"},{"jurisdiction":"Superior Court of Pennsylvania","url":"https://www.pacourts.us/courts/superior-court"},{"jurisdiction":"Supreme Court of New Jersey","url":"https://www.njcourts.gov/courts/supreme"},{"jurisdiction":"U.S. District Court, Southern District of New York","url":"https://www.nysd.uscourts.gov/"},{"jurisdiction":"U.S. District Court, Northern District of Illinois","url":"https://www.ilnd.uscourts.gov/"},{"jurisdiction":"U.S. District Court, Middle District of Florida","url":"https://www.flmd.uscourts.gov/"},{"jurisdiction":"U.S. Bankruptcy Court, Northern District of Texas","url":"https://www.txnb.uscourts.gov/"},{"jurisdiction":"Fifteenth Judicial Circuit Court, Palm Beach County, Florida","url":"https://www.15thcircuit.com/"},{"jurisdiction":"Hennepin County District Court, Minnesota","url":"https://mncourts.gov/find-courts/hennepin"},{"jurisdiction":"U.S. District Court, District of Rhode Island","url":"https://www.rid.uscourts.gov/"},{"jurisdiction":"New York Court of Appeals","url":"https://www.nycourts.gov/ctapps/"},{"jurisdiction":"Supreme Court of Florida","url":"https://supremecourt.flcourts.gov/"},{"jurisdiction":"Supreme Court of the State of New York","url":"https://www.nycourts.gov/courts/index.shtml"},{"jurisdiction":"San Mateo County Superior Court, California","url":"https://sanmateo.courts.ca.gov/"},{"jurisdiction":"U.S. District Court, District of New Jersey","url":"https://www.njd.uscourts.gov/"},{"jurisdiction":"U.S. District Court, Southern District of California","url":"https://www.casd.uscourts.gov/"},{"jurisdiction":"Miami-Dade County Circuit Court","url":"https://www.jud11.flcourts.org/"},{"jurisdiction":"Marion Superior Court, Indiana","url":"https://www.indycourts.org/"},{"jurisdiction":"Supreme Court of the State of New York, New York County","url":"https://ww2.nycourts.gov/courts/1jd/supctmanh/index.shtml"},{"jurisdiction":"U.S. District Court for the District of Montana","url":"https://www.mtd.uscourts.gov/"},{"jurisdiction":"U.S. District Court, District of Maryland (Northern Division)","url":"https://www.mdd.uscourts.gov/"},{"jurisdiction":"Alameda County Superior Court, California","url":"https://www.alameda.courts.ca.gov/"},{"jurisdiction":"Supreme Court of the State of New York, Appellate Division, Second Department","url":"https://www.nycourts.gov/courts/ad2/"},{"jurisdiction":"Superior Court of New Jersey, Union County","url":"https://www.njcourts.gov/courts/vicinages/union"},{"jurisdiction":"Circuit Court of Cook County, Illinois","url":"https://www.cookcountycourt.org/"},{"jurisdiction":"Massachusetts Appeals Court","url":"https://www.mass.gov/orgs/appeals-court"},{"jurisdiction":"U.S. District Court, Eastern District of Virginia","url":"https://www.vaed.uscourts.gov/"},{"jurisdiction":"Supreme Court of California","url":"https://supreme.courts.ca.gov/"},{"jurisdiction":"Greenville County Court of Common Pleas, South Carolina","url":"https://www.sccourts.org/courts/courthouse-search/greenville/"},{"jurisdiction":"342nd District Court, Tarrant County, Texas","url":"https://www.tarrantcountytx.gov/en/civil-courts/district-courts/342nd-district-court.html"},{"jurisdiction":"Massachusetts Supreme Judicial Court","url":"https://www.mass.gov/orgs/massachusetts-supreme-judicial-court"},{"jurisdiction":"U.S. District Court, Eastern District of Pennsylvania","url":"https://www.paed.uscourts.gov/"},{"jurisdiction":"Supreme Court of Arizona","url":"https://www.azcourts.gov/azsupremecourt"},{"jurisdiction":"Maricopa County Superior Court, Arizona","url":"https://superiorcourt.maricopa.gov/"},{"jurisdiction":"U.S. District Court, Middle District of North Carolina","url":"https://www.ncmd.uscourts.gov/"},{"jurisdiction":"Suffolk County Superior Court, Massachusetts","url":"https://www.mass.gov/locations/suffolk-county-superior-court"},{"jurisdiction":"Milwaukee County Circuit Court","url":"https://county.milwaukee.gov/EN/Courts"},{"jurisdiction":"Twelfth Judicial Circuit Court, Sarasota County, Florida","url":"https://www.jud12.flcourts.org/"},{"jurisdiction":"U.S. District Court, Middle District of Tennessee","url":"https://www.tnmd.uscourts.gov/"},{"jurisdiction":"Connecticut Supreme Court","url":"https://www.jud.ct.gov/external/supapp/"},{"jurisdiction":"U.S. District Court, Western District of North Carolina","url":"https://www.ncwd.uscourts.gov/"},{"jurisdiction":"Sacramento County Superior Court, California","url":"https://www.saccourt.ca.gov/"},{"jurisdiction":"U.S. District Court, District of Oregon","url":"https://www.ord.uscourts.gov/"},{"jurisdiction":"Supreme Court of the United States","url":"https://www.supremecourt.gov/"},{"jurisdiction":"U.S. District Court, Eastern District of Missouri","url":"https://www.moed.uscourts.gov/"},{"jurisdiction":"U.S. District Court, District of New Mexico","url":"https://www.nmd.uscourts.gov/"},{"jurisdiction":"Idaho Supreme Court","url":"https://isc.idaho.gov/"},{"jurisdiction":"Nebraska Supreme Court","url":"https://nebraskajudicial.gov/courts/supreme-court"},{"jurisdiction":"U.S. District Court, District of Nebraska","url":"https://www.ned.uscourts.gov/"},{"jurisdiction":"Intermediate Court of Appeals of West Virginia","url":"https://www.courtswv.gov/appellate-courts/intermediate-court-of-appeals/about-the-court"},{"jurisdiction":"Circuit Court of Kanawha County, West Virginia","url":"https://www.courtswv.gov/public-resources/court-information-county/kanawha_county"},{"jurisdiction":"Supreme Court of Alabama","url":"https://judicial.alabama.gov/Appellate/SupremeCourt"},{"jurisdiction":"Oklahoma County District Court, Oklahoma","url":"https://www.oscn.net/courts/oklahoma"},{"jurisdiction":"Arkansas Court of Appeals","url":"https://arcourts.gov/courts/court-of-appeals"},{"jurisdiction":"Supreme Court of Mississippi","url":"https://courts.ms.gov/appellatecourts/sc/sc.php"},{"jurisdiction":"U.S. District Court, Western District of Washington","url":"https://www.wawd.uscourts.gov/"},{"jurisdiction":"Grafton Superior Court, New Hampshire","url":"https://www.courts.nh.gov/your-visit/find-court/grafton-superior-court"},{"jurisdiction":"Supreme Court of Indiana","url":"https://www.in.gov/courts/supreme/"},{"jurisdiction":"Harris County District Court, Texas","url":"https://www.hcdistrictclerk.com/"},{"jurisdiction":"Ninth Judicial Circuit Court, Osceola County, Florida","url":"https://ninthcircuit.org/"},{"jurisdiction":"Los Angeles County Superior Court","url":"https://www.lacourt.org/"},{"jurisdiction":"Supreme Court of Texas","url":"https://www.txcourts.gov/supreme/"},{"jurisdiction":"Fourth Court of Appeals, San Antonio, Texas","url":"https://www.txcourts.gov/4thcoa/"},{"jurisdiction":"Fifth Court of Appeals, Dallas, Texas","url":"https://www.txcourts.gov/5thcoa/"},{"jurisdiction":"Fourteenth Court of Appeals, Houston, Texas","url":"https://www.txcourts.gov/14thcoa/"},{"jurisdiction":"Dallas County District Court, Texas","url":"https://www.dallascounty.org/government/district-clerk/"},{"jurisdiction":"U.S. District Court, Eastern District of California","url":"https://www.caed.uscourts.gov/"},{"jurisdiction":"U.S. District Court, Central District of California","url":"https://www.cacd.uscourts.gov/"},{"jurisdiction":"U.S. District Court, District of Maine","url":"https://www.med.uscourts.gov/"},{"jurisdiction":"Supreme Court of Wyoming","url":"https://www.wyocourts.gov/supreme-court/"},{"jurisdiction":"Delaware Court of Chancery","url":"https://courts.delaware.gov/chancery/"},{"jurisdiction":"U.S. Court of Appeals for the Fourth Circuit","url":"https://www.ca4.uscourts.gov/"},{"jurisdiction":"U.S. Court of Appeals for the Third Circuit","url":"https://www.ca3.uscourts.gov/"},{"jurisdiction":"U.S. Court of Federal Claims","url":"https://www.uscfc.uscourts.gov/"},{"jurisdiction":"Supreme Court of Ohio","url":"https://www.supremecourt.ohio.gov/"},{"jurisdiction":"California Court of Appeal, First Appellate District, Division Two","url":"https://www.courts.ca.gov/1dca.htm"},{"jurisdiction":"U.S. Bankruptcy Court, District of New Jersey","url":"https://www.njb.uscourts.gov/"},{"jurisdiction":"Montgomery County Court of Common Pleas, Pennsylvania","url":"https://www.montgomerycountypa.gov/departments/county-courts/court-common-pleas"},{"jurisdiction":"Circuit Court of Will County, Illinois","url":"https://judges.willcountyillinois.com/"},{"jurisdiction":"U.S. District Court, District of Colorado","url":"https://www.cod.uscourts.gov/"},{"jurisdiction":"Penobscot County Superior Court, Maine","url":"https://www.courts.maine.gov/courts/superior/"},{"jurisdiction":"U.S. District Court, Northern District of Ohio","url":"https://www.ohnd.uscourts.gov/"},{"jurisdiction":"U.S. District Court for the Southern District of West Virginia","url":"https://www.wvsd.uscourts.gov/"},{"jurisdiction":"Supreme Court of Alabama","url":"https://judicial.alabama.gov/"},{"jurisdiction":"U.S. District Court, Southern District of Texas (Galveston Division)","url":"https://www.txs.uscourts.gov/"},{"jurisdiction":"Ohio Court of Appeals, Eighth Appellate District","url":"https://appeals.cuyahogacounty.gov/"},{"jurisdiction":"Appellate Division, Third Department, New York","url":"https://www.nycourts.gov/courts/ad3/"},{"jurisdiction":"Indiana Court of Appeals","url":"https://www.in.gov/courts/appeals/"},{"jurisdiction":"Court of Appeals of Tennessee","url":"https://www.tncourts.gov/courts/court-appeals"},{"jurisdiction":"Court of Appeals of Kentucky","url":"https://kycourts.gov/Courts/Court-of-Appeals/"},{"jurisdiction":"Thirteenth Court of Appeals, Corpus Christi-Edinburg, Texas","url":"https://www.txcourts.gov/13thcoa/"},{"jurisdiction":"U.S. Court of Appeals for the Sixth Circuit","url":"https://www.ca6.uscourts.gov/"},{"jurisdiction":"Court of Appeals of Georgia","url":"https://www.gaappeals.gov/"}],"judges":[{"name":"Christine M. Clark","slug":"christine-m-clark","title":"Associate Justice — authored the panel opinion","court":"Appellate Division, Third Department, New York","background":"Appointed to the Appellate Division, Third Department effective April 24, 2014 by Governor Andrew M. Cuomo. Previously elected to the Supreme Court of the State of New York, Fourth Judicial District in 2012, becoming only the second woman ever elected to that court, after being elected to Schenectady County Family Court in 2010. A 1996 graduate of Albany Law School.","bioUrl":"https://nycourts.gov/ad3/about/bios/clark.shtml"},{"name":"Eileen T. Gallagher","slug":"eileen-t-gallagher","title":"Presiding Judge — authored the panel's opinion on reconsideration","court":"Ohio Court of Appeals, Eighth Appellate District","background":"First elected to the Eighth District Court of Appeals in 2012 and reelected in 2018, after serving roughly eight years as a trial judge in the Cuyahoga County Court of Common Pleas, General Division, where she chaired the court's Foreclosure Committee. Earlier in her career she worked as a judicial staff attorney, a foreclosure magistrate, and an assistant prosecuting attorney in the Cuyahoga County Prosecutor's office.","bioUrl":"https://appeals.cuyahogacounty.gov/about-us/judges/judge-eileen-t-gallagher"},{"name":"Llinét M. Rosado","slug":"llinet-m-rosado","title":"Associate Justice — authored the panel opinion","court":"Appellate Division, First Department, New York","background":"Appointed to the Appellate Division, First Department by Governor Kathy Hochul in July 2023, after serving as a Justice of the Supreme Court of the State of New York in Bronx County since her election in November 2018. Previously elected to the Civil Court of the City of New York in Bronx County in 2012 and assigned to Bronx Family Court, after beginning her legal career as a staff attorney with the Legal Aid Society's Criminal Defense Division.","bioUrl":"https://www.nycourts.gov/courts/AD1/JusticesOfTheCourt/Justice_Rosado.shtml"},{"name":"Theodore A. McKee","slug":"theodore-a-mckee","title":"Senior Circuit Judge — authored the panel opinion","court":"U.S. Court of Appeals for the Third Circuit","background":"Nominated by President Clinton in March 1994 to a seat vacated by Judge A. Leon Higginbotham Jr., confirmed that June. Served as Chief Judge of the Third Circuit from 2010 to 2016 and assumed senior status in October 2022. Previously a Pennsylvania state trial judge and an Assistant U.S. Attorney.","bioUrl":"https://www.fjc.gov/history/judges/mckee-theodore-alexander"},{"name":"Melissa R. DuBose","slug":"melissa-r-dubose","title":"U.S. District Judge","court":"U.S. District Court, District of Rhode Island","background":"Confirmed to the federal bench in March 2024 after serving as an associate judge on the Rhode Island District Court and as senior legal counsel at Schneider Electric. The first person of color and first openly LGBTQ judge to serve on the U.S. District Court for the District of Rhode Island.","bioUrl":"https://www.fjc.gov/history/judges/dubose-melissa-raye"},{"name":"Michael A. Shipp","slug":"michael-a-shipp","title":"U.S. District Judge","court":"U.S. District Court, District of New Jersey","background":"Appointed by President Obama in 2012 after serving as a U.S. Magistrate Judge for the District of New Jersey since 2007. Previously an assistant attorney general for New Jersey.","bioUrl":"https://www.fjc.gov/history/judges/shipp-michael-andre"},{"name":"Andrew M. Edison","slug":"andrew-m-edison","title":"U.S. Magistrate Judge","court":"U.S. District Court, Southern District of Texas (Galveston Division)","background":"Appointed effective February 20, 2018 to a seat vacated by the retirement of Magistrate Judge John Froeschner, sworn in by then-Chief Judge Lee H. Rosenthal. Practiced law in Houston from 1994 to 2018, including as a partner at Bracewell LLP and at Edison, McDowell & Hetherington LLP, after earning his J.D. from the University of Virginia School of Law in 1994.","bioUrl":"https://www.txs.uscourts.gov/page/judge-andrew-m-edison-biography"},{"name":"George H. Wu","slug":"george-h-wu","title":"U.S. District Judge","court":"U.S. District Court, Central District of California","background":"Nominated by President George W. Bush in January 2007 and confirmed by the Senate that March, filling a seat vacated by Judge Ronald S.W. Lew. Previously in private practice in Los Angeles and an assistant professor of law at the University of Tennessee College of Law. Assumed senior status in November 2023.","bioUrl":"https://www.fjc.gov/history/judges/wu-george-h"},{"name":"Stuart Rabner","slug":"stuart-rabner","title":"Chief Justice — authored the Court's unanimous opinion","court":"Supreme Court of New Jersey","background":"Chief Justice of the New Jersey Supreme Court since 2007, nominated by Gov. Jon Corzine. Previously served as New Jersey Attorney General and as an Assistant U.S. Attorney in Newark.","bioUrl":"https://www.njcourts.gov/public/museum/meet-the-justices/chief-justice-stuart-rabner"},{"name":"Anne M. Patterson","slug":"anne-m-patterson","title":"Associate Justice — authored the Court's opinion","court":"Supreme Court of New Jersey","background":"Associate Justice since 2011, nominated by Gov. Chris Christie and later granted tenure under Gov. Phil Murphy. Previously a partner at Riker, Danzig, Scherer, Hyland & Perretti focused on commercial litigation.","bioUrl":"https://www.njcourts.gov/public/museum/meet-the-justices/associate-justice-anne-m-patterson"},{"name":"Rowan D. Wilson","slug":"rowan-d-wilson","title":"Chief Judge — authored the majority opinion (Judge Cannataro dissenting)","court":"New York Court of Appeals","background":"Chief Judge of the State of New York since 2023, after serving as an Associate Judge from 2017. Previously a partner at Cravath, Swaine & Moore for over two decades. The first African-American to serve as Chief Judge of the New York Court of Appeals.","bioUrl":"https://www.nycourts.gov/ctapps/jwilson.htm"},{"name":"Joel M. Cohen","slug":"joel-m-cohen","title":"Justice, Commercial Division","court":"Supreme Court of the State of New York, New York County","background":"Assigned to the Commercial Division, New York County since 2019 after appointment to the Court of Claims by Gov. Andrew Cuomo. Previously a litigation partner at Davis Polk & Wardwell.","bioUrl":"https://www.nycourts.gov/commercial-division-new-york-county-manhattan/biography-justice-joel-m-cohen"},{"name":"Mark X. Mullin","slug":"mark-x-mullin","title":"U.S. Bankruptcy Judge","court":"U.S. Bankruptcy Court, Northern District of Texas","background":"Appointed to the bankruptcy bench in the Fort Worth division in 2015. Previously a member of Haynes and Boone LLP's Bankruptcy and Business Restructuring practice group, and a licensed CPA before attending law school.","bioUrl":"https://www.txnb.uscourts.gov/content/judge-mark-x-mullin"},{"name":"Andrew Borrok","slug":"andrew-borrok","title":"Justice, Commercial Division","court":"Supreme Court of the State of New York, New York County","background":"Elected to the New York State Supreme Court in 2017 after serving on the New York City Civil Court beginning in 2014. Assigned to the Commercial Division, New York County effective January 1, 2019, where he is designated to preside over all New York County cases alleging violations of the Securities Act of 1933.","bioUrl":"https://www.nycourts.gov/commercial-division-new-york-county-manhattan/biography-justice-andrew-borrok"},{"name":"Michael Noriega","slug":"michael-noriega","title":"Associate Justice — authored the Court's majority opinion (Justice Hoffman dissenting)","court":"Supreme Court of New Jersey","background":"Nominated by Gov. Phil Murphy and sworn in as an Associate Justice on July 6, 2023, becoming the first former public defender to serve on the New Jersey Supreme Court. Previously an assistant public defender in Essex County and, at the time of his appointment, a partner at Bramnick, Rodriguez, Grabas, Arnold, and Mangan focused on immigration and criminal law.","bioUrl":"https://www.njcourts.gov/public/museum/meet-the-justices/associate-justice-michael-noriega"},{"name":"Sookyoung Shin","slug":"sookyoung-shin","title":"Associate Justice — authored the Court's unanimous opinion","court":"Massachusetts Appeals Court","background":"Appointed to the Massachusetts Appeals Court in July 2016 by Gov. Charlie Baker after serving since 2005 as an assistant attorney general in the Commonwealth's Administrative Law Division. Previously practiced patent litigation at Finnegan, Henderson, Farabow, Garrett & Dunner and general litigation at Kirkland & Ellis.","bioUrl":"https://www.mass.gov/courts/court-info/appealscourt/appeals-court-justices/associate-justice-sookyoung-shin.html"},{"name":"Leondra Kruger","slug":"leondra-kruger","title":"Associate Justice — authored the Court's unanimous opinion","court":"Supreme Court of California","background":"Nominated by Gov. Jerry Brown and sworn in as an Associate Justice on January 5, 2015. Previously served as Assistant to the Solicitor General and Acting Principal Deputy Solicitor General in the U.S. Department of Justice's Office of the Solicitor General, arguing 12 cases before the U.S. Supreme Court, and clerked for Justice John Paul Stevens on the U.S. Supreme Court.","bioUrl":"https://supreme.courts.ca.gov/about-court/justices-court"},{"name":"Jessica Salvini","slug":"jessica-salvini","title":"Circuit Court Judge","court":"Greenville County Court of Common Pleas, South Carolina","background":"Elected to the South Carolina Family Court bench in 2019 and to the Circuit Court bench in 2024, serving the Thirteenth Judicial Circuit (Greenville and Pickens Counties). Previously a senior partner at her own law firm in Greenville, South Carolina, practicing civil, family, and criminal litigation, after relocating from California in 2002.","bioUrl":"https://www.sccourts.org/courts/trial-courts/circuit-court/judges/jessica-ann-salvini/"},{"name":"Kimberly Fitzpatrick","slug":"kimberly-fitzpatrick","title":"District Judge","court":"342nd District Court, Tarrant County, Texas","background":"Appointed to the 342nd Judicial District Court by Governor Greg Abbott in 2018 and subsequently elected and re-elected to the seat, most recently in November 2024. Previously a partner at Harris Cook, L.L.P. in Fort Worth handling business, civil litigation, and real estate matters, and before that served as mayor of Dalworthington Gardens, Texas.","bioUrl":"https://www.tarrantcountytx.gov/en/civil-courts/district-courts/342nd-district-court.html"},{"name":"Gabrielle R. Wolohojian","slug":"gabrielle-r-wolohojian","title":"Associate Justice","court":"Massachusetts Supreme Judicial Court","background":"Appointed to the Massachusetts Supreme Judicial Court by Governor Maura Healey and sworn in as an associate justice in April 2024. Previously served as an associate justice of the Massachusetts Appeals Court beginning in 2008 following her appointment by Governor Deval Patrick, and before that was a litigation partner at Hale and Dorr (now WilmerHale) in Boston.","bioUrl":"https://www.mass.gov/info-details/associate-justice-gabrielle-r-wolohojian"},{"name":"Andrea Masley","slug":"andrea-masley","title":"Justice, Commercial Division","court":"Supreme Court of the State of New York, New York County","background":"Elected to the New York State Supreme Court in 2016 and assigned to the Commercial Division, New York County in 2017. Previously elected to the New York City Civil Court in 2007 and served in Family Court from 2008 to 2010, and before that spent a decade as Principal Court Attorney to Commercial Division Justice Charles Edward Ramos.","bioUrl":"https://www.nycourts.gov/commercial-division-new-york-county-manhattan/biography-justice-andrea-masley"},{"name":"Nitza I. Quiñones Alejandro","slug":"nitza-i-quinones-alejandro","title":"U.S. District Judge","court":"U.S. District Court, Eastern District of Pennsylvania","background":"Nominated by President Obama in November 2012 and confirmed to the federal bench in June 2013, after serving as a judge on the Philadelphia County Court of Common Pleas. The first lesbian Latina to serve as a federal judge.","bioUrl":"https://www.fjc.gov/history/judges/qui%C3%B1ones-alejandro-nitza-ileana"},{"name":"Ann A. Scott Timmer","slug":"ann-a-scott-timmer","title":"Chief Justice — authored the Court's unanimous opinion","court":"Supreme Court of Arizona","background":"Chief Justice of the Arizona Supreme Court since July 1, 2024, after serving as an Associate Justice from October 2012 following appointment by Gov. Jan Brewer. Previously served on the Arizona Court of Appeals, Division One, from 2000, including as Chief Judge from 2008 to 2011.","bioUrl":"https://www.azcourts.gov/meetthejustices/Chief-Justice-Ann-A-Scott-Timmer"},{"name":"William Lindsay Osteen Jr.","slug":"william-lindsay-osteen-jr","title":"U.S. District Judge","court":"U.S. District Court, Middle District of North Carolina","background":"Nominated by President George W. Bush on January 9, 2007 and confirmed to the federal bench that September, filling the seat vacated by his father, Judge William L. Osteen Sr. Presides over the DOJ's multistate RealPage algorithmic-pricing antitrust litigation.","bioUrl":"https://www.fjc.gov/history/judges/osteen-william-lindsay-jr"},{"name":"Waverly D. Crenshaw Jr.","slug":"waverly-d-crenshaw-jr","title":"U.S. District Judge","court":"U.S. District Court, Middle District of Tennessee","background":"Nominated by President Obama in February 2015 and confirmed to the federal bench in April 2016, later serving as Chief Judge of the Middle District of Tennessee from 2017 to 2024. Previously practiced law in Nashville after clerking for judges of the Davidson County Chancery Court and the U.S. District Court for the Middle District of Tennessee.","bioUrl":"https://www.fjc.gov/history/judges/crenshaw-waverly-david-jr"},{"name":"Richard K. Sueyoshi","slug":"richard-k-sueyoshi","title":"Judge, Sacramento County Superior Court","court":"Sacramento County Superior Court, California","background":"Appointed to the Sacramento County Superior Court bench by Governor Arnold Schwarzenegger in September 2009. Previously a partner at Downey Brand LLP in Sacramento, practicing business and commercial litigation. Now serves as Supervising Judge of the court's Civil Division and presides over its Complex Civil Case Management department.","bioUrl":"https://www.saccourt.ca.gov/civil/docs/cv-department-53.pdf"},{"name":"John M. Bodenhausen","slug":"john-m-bodenhausen","title":"U.S. Magistrate Judge","court":"U.S. District Court, Eastern District of Missouri","background":"Appointed a U.S. Magistrate Judge for the Eastern District of Missouri on April 16, 2015, after serving as an Assistant U.S. Attorney for the district since 2002. Previously practiced patent law at the St. Louis firm Senniger Powers following a clerkship for Judge David R. Hansen of the U.S. Court of Appeals for the Eighth Circuit.","bioUrl":"https://www.moed.uscourts.gov/judge/john-m-bodenhausen"},{"name":"Jane Bland","slug":"jane-bland","title":"Justice — authored the Court's majority opinion (Justice Hawkins dissenting)","court":"Supreme Court of Texas","background":"Justice on the Supreme Court of Texas since 2019, after 15 years as a justice on the First Court of Appeals and 6 years as a state district judge — 28 years on the state judiciary in total. Previously a partner at Vinson & Elkins LLP in Houston; received the William H. Rehnquist Award for judicial excellence in 2010. Board-certified in civil appellate law and civil trial law.","bioUrl":"https://www.txcourts.gov/supreme/about-the-court/justices/justice-jane-bland/"},{"name":"H. Todd McCray","slug":"h-todd-mccray","title":"Justice — authored the panel's opinion","court":"Fourth Court of Appeals, San Antonio, Texas","background":"Justice on the Fourth Court of Appeals, Place 3, since January 2025. Practiced as a trial and appellate attorney in Texas for over three decades, including as an assistant county attorney in Grayson County and an assistant district attorney in Bexar County. Board Certified in Criminal Law by the Texas Board of Legal Specialization since 1997.","bioUrl":"https://www.txcourts.gov/4thcoa/about-the-court/justices/justice-h-todd-mccray/"},{"name":"Emily Miskel","slug":"emily-miskel","title":"Justice — authored the panel's opinion","court":"Fifth Court of Appeals, Dallas, Texas","background":"Appointed to the Fifth Court of Appeals by Governor Greg Abbott in 2022, after serving as judge of the 470th District Court (a Collin County family court) from 2015. Recipient of the William H. Rehnquist Award for Judicial Excellence in 2020. Holds a Harvard Law degree and a Stanford engineering degree, and worked in the oil and gas industry before law school.","bioUrl":"https://www.txcourts.gov/5thcoa/about-the-court/justices/justice-emily-miskel/"},{"name":"Kevin Jewell","slug":"kevin-jewell","title":"Justice — authored the panel's opinion","court":"Fourteenth Court of Appeals, Houston, Texas","background":"Elected to the Fourteenth Court of Appeals in November 2016 and took office in January 2017. Previously a litigation and appellate shareholder at Chamberlain, Hrdlicka, White, Williams & Aughtry in Houston, where he chaired the firm's appellate practice group. Board Certified in Civil Appellate Law since 1998.","bioUrl":"https://www.txcourts.gov/14thcoa/about-the-court/justices/justice-kevin-jewell/"},{"name":"Hernán D. Vera","slug":"hernan-d-vera","title":"U.S. District Judge","court":"U.S. District Court, Central District of California","background":"Nominated by President Biden in January 2023 and confirmed to the federal bench in June 2023, after serving as a Los Angeles County Superior Court judge from 2020. Previously a principal at Bird Marella P.C. and, from 2002 to 2014, directing attorney and later President and CEO of the pro bono law firm Public Counsel.","bioUrl":"https://www.fjc.gov/history/judges/vera-hern-n-diego"},{"name":"Elizabeth Dewar","slug":"elizabeth-dewar","title":"Associate Justice","court":"Massachusetts Supreme Judicial Court","background":"Appointed to the Massachusetts Supreme Judicial Court by Governor Maura Healey in January 2024, filling the first open seat of her administration. Previously served as Massachusetts State Solicitor from 2016 to 2024 and clerked at all three levels of the federal judiciary, including for U.S. Supreme Court Justice Stephen G. Breyer.","bioUrl":"https://www.mass.gov/info-details/supreme-judicial-court-justices"},{"name":"Valerie E. Caproni","slug":"valerie-e-caproni","title":"U.S. District Judge","court":"U.S. District Court, Southern District of New York","background":"Nominated by President Obama on January 4, 2013 to a seat vacated by Judge Richard J. Holwell, confirmed by the Senate that September. Previously general counsel to the FBI from 2003 to 2011 and vice president and deputy general counsel at Northrop Grumman Corporation. Assumed senior status in January 2025.","bioUrl":"https://www.fjc.gov/history/judges/caproni-valerie-elaine"},{"name":"Bridget Hill","slug":"bridget-hill","title":"Justice","court":"Supreme Court of Wyoming","background":"Appointed to the Wyoming Supreme Court by Governor Mark Gordon and sworn in May 28, 2025, filling the seat vacated by the retirement of Chief Justice Kate Fox. Previously served as Wyoming Attorney General from 2019 to 2025 and as Director of the Wyoming Office of State Lands and Investments from 2013 to 2018.","bioUrl":"https://www.wyocourts.gov/supreme-court/"},{"name":"Bonnie W. David","slug":"bonnie-w-david","title":"Vice Chancellor","court":"Delaware Court of Chancery","background":"Sworn in as Vice Chancellor of the Delaware Court of Chancery on January 7, 2025 after nomination by Gov. John Carney, following nearly two years of service as a Magistrate in Chancery. Previously a litigator at Skadden, Arps, Slate, Meagher & Flom focused on deal litigation, corporate statutory proceedings, and contract disputes, and clerked in the Court of Chancery for Vice Chancellor Sam Glasscock III immediately after law school.","bioUrl":"https://courts.delaware.gov/forms/download.aspx?id=275388"},{"name":"J. Harvie Wilkinson III","slug":"j-harvie-wilkinson-iii","title":"U.S. Circuit Judge","court":"U.S. Court of Appeals for the Fourth Circuit","background":"Appointed to the Fourth Circuit by President Reagan in 1984 and served as the court's chief judge from 1996 to 2003. Previously a law clerk to U.S. Supreme Court Justice Lewis F. Powell Jr. and a professor at the University of Virginia School of Law.","bioUrl":"https://www.fjc.gov/history/judges/wilkinson-james-harvie-iii"},{"name":"Serge Georges, Jr.","slug":"serge-georges-jr","title":"Associate Justice","court":"Massachusetts Supreme Judicial Court","background":"Appointed to the Massachusetts Supreme Judicial Court by Governor Charlie Baker and sworn in December 16, 2020, after serving as a judge of the Boston Municipal Court from 2013 to 2020. Previously in private practice at several Boston-area law firms following the start of his legal career in 1996; a former president of the Massachusetts Black Lawyers Association.","bioUrl":"https://www.mass.gov/info-details/supreme-judicial-court-justices"},{"name":"Joseph T. Deters","slug":"joseph-t-deters","title":"Justice","court":"Supreme Court of Ohio","background":"Appointed to the Supreme Court of Ohio by Governor Mike DeWine in January 2023 and elected to a full six-year term in November 2024. Previously Hamilton County Prosecutor from 1992 to 1999 and again from 2005 to 2023, after beginning his career as an assistant prosecutor in the same office in 1982.","bioUrl":"https://www.supremecourt.ohio.gov/judicial-system/supreme-court-of-ohio/justices-overview/joseph-deters/"},{"name":"Mark E. Hall","slug":"mark-e-hall","title":"U.S. Bankruptcy Judge","court":"U.S. Bankruptcy Court, District of New Jersey","background":"Appointed to the U.S. Bankruptcy Court for the District of New Jersey, assuming office October 15, 2024, after serving as a partner at Fox Rothschild LLP and, before that, Riker Danzig LLP, representing debtors, creditors' committees, and secured lenders in Chapter 11, 7, and 13 cases. Previously a judicial law clerk to the Honorable Novalyn L. Winfield, U.S. Bankruptcy Judge for the District of New Jersey.","bioUrl":"https://www.njb.uscourts.gov/content/honorable-mark-e-hall"},{"name":"Victoria Breslan","slug":"victoria-breslan","title":"Circuit Judge","court":"Circuit Court of Will County, Illinois","background":"Elected Circuit Judge of Illinois's 12th Judicial Circuit in November 2024, after serving as an Associate Judge in the same circuit since 2018. Previously worked as a Will County Assistant State's Attorney and in private practice in Joliet. Holds a J.D. from IIT Chicago-Kent College of Law.","bioUrl":"https://www.circuitclerkofwillcounty.com/Judge-Rules/Judge-Breslan"},{"name":"Madeline Cox Arleo","slug":"madeline-cox-arleo","title":"U.S. District Judge","court":"U.S. District Court, District of New Jersey","background":"Nominated by President Obama on June 26, 2014 and confirmed by the Senate that November, after serving as a U.S. Magistrate Judge for the District of New Jersey since 2000. Previously in private practice in Newark, New Jersey, focusing on civil litigation in state and federal courts.","bioUrl":"https://www.fjc.gov/history/judges/arleo-madeline-cox"},{"name":"Regina M. Rodriguez","slug":"regina-m-rodriguez","title":"U.S. District Judge","court":"U.S. District Court, District of Colorado","background":"Nominated by President Biden on April 19, 2021 and confirmed by the Senate on June 8, 2021, to a seat vacated by Marcia S. Krieger. Previously served as an Assistant U.S. Attorney for the District of Colorado from 1995 to 2002 and in private practice in Denver.","bioUrl":"https://www.fjc.gov/history/judges/rodriguez-regina-marie"},{"name":"Bruce Mallonee","slug":"bruce-mallonee","title":"Justice","court":"Penobscot County Superior Court, Maine","background":"Nominated to the Maine District Court by Governor John Baldacci in November 2010, then nominated to the Maine Superior Court by Governor Paul LePage in May 2015. Previously in private practice in Bangor, Maine.","bioUrl":"https://www.courts.maine.gov/courts/superior/justices.html"},{"name":"Bridget Meehan Brennan","slug":"bridget-meehan-brennan","title":"U.S. District Judge","court":"U.S. District Court, Northern District of Ohio","background":"Nominated by President Biden on January 3, 2022 to a seat vacated by Judge Dan A. Polster, confirmed by the Senate on February 1, 2022, and commissioned that February. Previously an Assistant U.S. Attorney for the Northern District of Ohio from 2007 to 2022, including service as First Assistant U.S. Attorney from 2018 to 2021.","bioUrl":"https://www.fjc.gov/history/judges/brennan-bridget-meehan"},{"name":"Frank Volk","slug":"frank-volk","title":"Chief U.S. District Judge","court":"U.S. District Court for the Southern District of West Virginia","background":"Nominated by President Trump on April 4, 2019 to a seat vacated by Judge John Thomas Copenhaver, Jr., confirmed by the Senate on October 16, 2019. Previously served as a U.S. Bankruptcy Judge, and as chief bankruptcy judge, for the Southern District of West Virginia from 2015 to 2019.","bioUrl":"https://www.fjc.gov/history/judges/volk-frank-william"},{"name":"Robert E. Toone Jr.","slug":"robert-e-toone-jr","title":"Associate Justice — authored the panel opinion","court":"Massachusetts Appeals Court","background":"Nominated by Governor Maura Healey in November 2023 and confirmed by the Governor's Council that December. Served from 2015 to 2023 as chief of the Massachusetts Attorney General's Government Bureau; previously a litigation partner at Foley Hoag and counsel to U.S. Senator Edward Kennedy on the Senate Judiciary Committee.","bioUrl":"https://www.mass.gov/info-details/associate-justice-robert-e-toone-jr"},{"name":"Lori A. Dumas","slug":"lori-a-dumas","title":"Judge, Commonwealth Court of Pennsylvania","court":"Commonwealth Court of Pennsylvania","background":"Elected to the Commonwealth Court in 2021 and sworn in for a term beginning January 2022; previously a judge on the Philadelphia County Court of Common Pleas from 2002 to 2021. Holds a J.D. from North Carolina Central University School of Law and a B.A. from Duke University.","bioUrl":"https://www.pacourts.us/courts/commonwealth-court-judges/judge-lori-a-dumas"},{"name":"Andre B. Mathis","slug":"andre-b-mathis","title":"Circuit Judge — authored the panel opinion","court":"U.S. Court of Appeals for the Sixth Circuit","background":"Nominated by President Biden on November 18, 2021 and confirmed by the Senate on September 8, 2022, taking the seat vacated by Judge Bernice B. Donald. Previously a partner at Butler Snow LLP and, from 2007 to 2020, an attorney at Glankler Brown, PLLC in Memphis.","bioUrl":"https://www.fjc.gov/history/judges/mathis-andre-bernard"},{"name":"Maria C. McLaughlin","slug":"maria-c-mclaughlin","title":"Judge — authored the panel's memorandum opinion","court":"Superior Court of Pennsylvania","background":"Elected to the Superior Court of Pennsylvania in November 2017 and sworn in January 2018, after serving as a judge on the Philadelphia County Court of Common Pleas, Family Division, following her 2011 election. Earlier in her career she was a Philadelphia Assistant District Attorney and later Chief Deputy District Attorney.","bioUrl":"https://www.pacourts.us/courts/superior-court/superior-court-judges/judge-maria-mclaughlin"},{"name":"Will Parker","slug":"will-parker","title":"Associate Justice","court":"Supreme Court of Alabama","background":"Appointed by Governor Kay Ivey in November 2025 to fill the vacancy left when Justice Bill Lewis was appointed to a federal judgeship. Previously served nearly six years as General Counsel to the Governor and, before that, as an assistant attorney general in the Alabama Attorney General's Constitutional Defense Division.","bioUrl":"https://judicial.alabama.gov/CourtMemberBio/ViewBio?id=91"},{"name":"Robert S. Lasnik","slug":"robert-s-lasnik","title":"U.S. District Judge","court":"U.S. District Court, Western District of Washington","background":"Nominated by President Clinton on May 11, 1998 to a seat vacated by Judge Carolyn R. Dimmick, confirmed by the Senate and commissioned later that year. Served as chief judge of the district from 2004 to 2011 and represented the Ninth Circuit on the Judicial Conference of the United States from 2010 to 2015. Previously served on the King County Superior Court from 1990 to 1998 and in the King County Prosecuting Attorney's Office from 1978 to 1990. Assumed senior status on January 27, 2016.","bioUrl":"https://www.fjc.gov/history/judges/lasnik-robert-s"},{"name":"Peter C. Cavanagh","slug":"peter-c-cavanagh","title":"Presiding Justice","court":"Appellate Court of Illinois, Fourth District","background":"Assigned by the Illinois Supreme Court to the Fourth District Appellate Court in March 2018, filling the vacancy left by the death of Justice John P. Schmidt, and later elected to retain the seat. Previously a resident Circuit Judge of the Seventh Judicial Circuit, appointed in 2008. Unanimously appointed Presiding Justice of the Fourth District effective February 29, 2024.","bioUrl":"https://www.illinoiscourts.gov/justice/39/Peter-C-Cavanagh/justice"},{"name":"N. Mark Klappenbach","slug":"n-mark-klappenbach","title":"Chief Judge — authored the panel opinion","court":"Arkansas Court of Appeals","background":"First elected to the Arkansas Court of Appeals in 2016 and reelected in 2020, after more than 31 years in Arkansas legal and accounting work, including service as a public defender and deputy prosecuting attorney. Appointed Chief Judge of the Arkansas Court of Appeals by the Arkansas Supreme Court's chief justice for a four-year term beginning January 1, 2025.","bioUrl":"https://www.arcourts.gov/courts/court-of-appeals/judges/Mark-Klappenbach"},{"name":"Stan L. Pritzker","slug":"stan-l-pritzker","title":"Associate Justice — authored the panel opinion","court":"Appellate Division, Third Department, New York","background":"Appointed to the Appellate Division, Third Department by Governor Andrew Cuomo in 2017. Previously elected to the New York State Supreme Court, Fourth Judicial District, in 2013.","bioUrl":"https://www.nycourts.gov/ad3/about/bios/pritzker.shtml"},{"name":"Nancy H. Vaidik","slug":"nancy-h-vaidik","title":"Judge — authored the panel opinion","court":"Indiana Court of Appeals","background":"Appointed to the Indiana Court of Appeals in February 2000 by Governor Frank O'Bannon and retained by voters in 2002, 2012, and 2022. Served as judge of the Porter Superior Court from 1992 to 2000, and served two terms as the Court of Appeals' chief judge, from January 2014 through December 2019.","bioUrl":"https://www.in.gov/courts/appeals/judges/nancy-vaidik"},{"name":"Jeffrey Usman","slug":"jeffrey-usman","title":"Judge — authored the panel opinion","court":"Court of Appeals of Tennessee","background":"Appointed to the Tennessee Court of Appeals, Middle Division, by Governor Bill Lee in March 2022, succeeding Judge Richard H. Dinkins, and confirmed by the Tennessee General Assembly. Previously an associate professor at Belmont University College of Law and a senior law clerk to Tennessee Supreme Court Justice William C. Koch Jr.","bioUrl":"https://tncourts.gov/node/7920985"},{"name":"Lisa Payne Jones","slug":"lisa-payne-jones","title":"Judge — authored the panel opinion","court":"Court of Appeals of Kentucky","background":"Appointed to the Kentucky Court of Appeals, 1st Appellate District, Division 2, by Governor Andy Beshear in April 2024 to fill the vacancy created by Judge Donna Dixon's retirement, and elected to the seat in November 2024. Previously served as judge of the Daviess Circuit Court and, from 2001 to 2019, as a Daviess County District Court judge, the first woman to hold either position in the county.","bioUrl":"https://kycourts.gov/Courts/Court-of-Appeals/Pages/1st-Appellate-District-Division-2.aspx"},{"name":"Ysmael D. Fonseca","slug":"ysmael-d-fonseca","title":"Justice — authored the panel opinion","court":"Thirteenth Court of Appeals, Corpus Christi-Edinburg, Texas","background":"Elected to Place 4 of the Thirteenth Court of Appeals on November 5, 2024, with his term beginning January 1, 2025. By appointment of Governor Greg Abbott, previously served as judge of the 464th District Court of Hidalgo County from 2019 to 2020 and of the 476th District Court of Hidalgo County from 2023 to 2024.","bioUrl":"https://www.txcourts.gov/13thcoa/about-the-court/justices/justice-ysmael-d-fonseca/"},{"name":"Jeffrey S. Sutton","slug":"jeffrey-s-sutton","title":"Circuit Judge — authored the panel opinion","court":"U.S. Court of Appeals for the Sixth Circuit","background":"Nominated to the Sixth Circuit in 2001 and has served on the court since 2003, including as Chief Judge from 2014 to 2021. Previously served as Solicitor of Ohio from 1995 to 1998 and as a partner at Jones Day, and clerked for Justices Lewis F. Powell Jr. and Antonin Scalia and for Judge Thomas Meskill of the Second Circuit.","bioUrl":"https://www.fjc.gov/history/judges/sutton-jeffrey-s"},{"name":"Sara L. Doyle","slug":"sara-l-doyle","title":"Presiding Judge — authored the panel opinion","court":"Court of Appeals of Georgia","background":"Elected to the Court of Appeals of Georgia in December 2008 and took office January 1, 2009, after practicing as a litigator and equity partner at Holland & Knight. Served as the court's Chief Judge from July 2015 to June 2017 and currently serves as a Presiding Judge.","bioUrl":"https://www.gaappeals.gov/?p=583"},{"name":"Jeffrey R. Davis","slug":"jeffrey-r-davis","title":"Judge — authored the panel opinion","court":"Court of Appeals of Georgia","background":"Elected to the Court of Appeals of Georgia in 2024 and took office January 1, 2025, after serving as director of the Georgia Judicial Qualifications Commission. A 1987 graduate of the University of Tennessee at Chattanooga.","bioUrl":"https://www.gaappeals.gov/?p=5075"},{"name":"Ryan White","slug":"ryan-white","title":"Judge, Division 1 — authored the panel opinion","court":"Intermediate Court of Appeals of West Virginia","background":"Elected in 2024 as the first judge to win a seat on West Virginia's newly created Intermediate Court of Appeals, Division 1, taking office for a 10-year term on January 1, 2025. Previously a practicing attorney for 18 years, including founding White Law Offices, PLLC in 2012 after working at Jackson Kelly PLLC; clerked for Judge Joseph R. Goodwin of the U.S. District Court for the Southern District of West Virginia from 2005 to 2006.","bioUrl":"https://www.courtswv.gov/appellate-courts/intermediate-court-of-appeals/judges-staff/judge-white"},{"name":"Jonathan A. Kobes","slug":"jonathan-a-kobes","title":"U.S. Circuit Judge","court":"U.S. Court of Appeals for the Eighth Circuit","background":"Appointed by President Trump in 2018, confirmed by a tie-breaking vote from Vice President Mike Pence, after serving as general counsel and deputy chief of staff to U.S. Senator Mike Rounds. Previously an assistant U.S. attorney and law clerk to Judge Roger Wollman of the Eighth Circuit.","bioUrl":"https://www.fjc.gov/history/judges/kobes-jonathan-allen"},{"name":"Renée Cohn Jubelirer","slug":"renee-cohn-jubelirer","title":"President Judge — authored the panel's memorandum opinion","court":"Commonwealth Court of Pennsylvania","background":"Elected to the Commonwealth Court in 2001 and retained in 2011 and 2021; elected by her colleagues as President Judge effective January 2022, succeeding P. Kevin Brobson. Earlier served as a South Whitehall Township commissioner in Lehigh County and practiced law in Chicago. Holds a B.A. from Penn State, a J.D. from Northwestern University, and an LL.M. in Judicial Studies from Duke University.","bioUrl":"https://www.pacourts.us/courts/commonwealth-court-judges/judge-renee-cohn-jubelirer"}],"trackedParties":[{"name":"RealPage","slug":"realpage","description":"Multifamily revenue-management software vendor named across a wave of algorithmic rent-pricing litigation nationwide.","website":"https://www.realpage.com"},{"name":"Yardi Systems","matchTerm":"Yardi","slug":"yardi-systems","description":"Property-management software vendor whose revenue-management products are named across algorithmic rent-pricing litigation nationwide.","website":"https://www.yardi.com"},{"name":"Apollo Global Management","matchTerm":"Apollo","slug":"apollo-global-management","description":"Alternative asset manager active in CRE mezzanine lending and distressed-debt acquisitions.","website":"https://www.apollo.com"},{"name":"CoStar Group","matchTerm":"CoStar","slug":"costar-group","description":"Commercial real estate data and lease-comparables platform.","website":"https://www.costargroup.com"},{"name":"UDR, Inc.","matchTerm":"UDR","slug":"udr-inc","description":"NYSE-listed multifamily REIT.","website":"https://www.udr.com"},{"name":"Lightstone Group","matchTerm":"Lightstone","slug":"lightstone-group","description":"Sponsor of the Lightstone Value Plus non-traded REIT family.","website":"https://www.lightstonegroup.com"},{"name":"Silver Star Properties REIT","matchTerm":"Silver Star Properties","slug":"silver-star-properties-reit","description":"Houston-based non-traded REIT, repositioning from office to self-storage."},{"name":"RAD Diversified REIT","matchTerm":"RAD Diversified","slug":"rad-diversified-reit","description":"Tampa-based non-traded REIT."},{"name":"Metro Loft","slug":"metro-loft","description":"New York City office-to-residential conversion developer led by Nathan Berman."},{"name":"Willow Bridge Property Company","matchTerm":"Willow Bridge","slug":"willow-bridge-property","description":"National multifamily property management and development company.","website":"https://www.willowbridgepc.com"},{"name":"Travelers","slug":"travelers","description":"Commercial property and casualty insurance carrier.","website":"https://www.travelers.com"},{"name":"Columbia Falls Aluminum Company","matchTerm":"Columbia Falls Aluminum","slug":"columbia-falls-aluminum","description":"Former Montana aluminum smelter operator, now managing legacy Superfund cleanup liability at the site."},{"name":"Penn-Florida Companies","matchTerm":"Penn-Florida","slug":"penn-florida-companies","description":"Boca Raton-based luxury real estate developer active in mixed-use, residential, and hospitality projects across South Florida.","website":"https://pennflorida.com"},{"name":"U.S. Bank National Association","matchTerm":"U.S. Bank","slug":"us-bank-national-association","description":"National bank that frequently serves as trustee or administrative agent for CMBS trusts and lender groups in commercial foreclosure and receivership litigation.","website":"https://www.usbank.com"},{"name":"Jones Lang LaSalle Incorporated","matchTerm":"JLL","slug":"jll","description":"NYSE-listed global commercial real estate brokerage and investment management firm.","website":"https://www.jll.com"},{"name":"Wilmington Trust National Association","matchTerm":"Wilmington Trust","slug":"wilmington-trust-national-association","description":"National bank and trust company that frequently serves as trustee for CMBS trusts and bondholders in commercial mortgage foreclosure litigation.","website":"https://www.wilmingtontrust.com"},{"name":"Wells Fargo Bank, National Association","matchTerm":"Wells Fargo","slug":"wells-fargo","description":"National bank that serves as trustee for CMBS trusts in commercial mortgage foreclosure and receivership litigation, and is also a major corporate office tenant nationally.","website":"https://www.wellsfargo.com"},{"name":"Goldman Sachs","slug":"goldman-sachs","description":"Global investment bank that originates and securitizes commercial mortgage loans, and frequently appears as a lender or plaintiff in CMBS foreclosure litigation.","website":"https://www.goldmansachs.com"},{"name":"Deutsche Bank","slug":"deutsche-bank","description":"Global investment bank that originates, services, and represents lender groups in commercial mortgage and CMBS foreclosure litigation.","website":"https://www.db.com"},{"name":"Cushman & Wakefield","slug":"cushman-wakefield","description":"Global commercial real estate services firm providing brokerage, leasing, and property and receivership management services.","website":"https://www.cushmanwakefield.com"},{"name":"CBRE Group, Inc.","matchTerm":"CBRE","slug":"cbre-group","description":"NYSE-listed global commercial real estate services and investment management firm, frequently serving as broker, property manager, or court-appointed receiver in distressed CRE matters.","website":"https://www.cbre.com"},{"name":"D.R. Horton, Inc.","matchTerm":"D.R. Horton","slug":"dr-horton","description":"NYSE-listed national homebuilder and land developer, active in single-family and multifamily residential land entitlement and development nationally.","website":"https://www.drhorton.com"},{"name":"Rialto Capital Advisors","matchTerm":"Rialto Capital","slug":"rialto-capital-advisors","description":"Miami-based investment and asset management platform that frequently serves as special servicer for CMBS trusts in commercial mortgage foreclosure litigation.","website":"https://rialtocapital.com"},{"name":"Blackstone","slug":"blackstone","description":"Global alternative asset manager and one of the largest owners of multifamily, office, and other commercial real estate nationally, both directly and through portfolio landlord entities.","website":"https://www.blackstone.com"},{"name":"Simon Property Group","slug":"simon-property-group","description":"NYSE-listed REIT and the nation's largest owner of shopping malls and premium outlet centers.","website":"https://www.simon.com"},{"name":"Verizon Wireless","matchTerm":"Verizon","slug":"verizon-wireless","description":"National wireless carrier that leases rooftop and site space from commercial landlords nationwide for communications and distributed-antenna equipment.","website":"https://www.verizon.com"},{"name":"Fortress Investment Group","matchTerm":"Fortress","slug":"fortress-investment-group","description":"Multi-strategy alternative asset manager active as a CRE lender, frequently pursuing foreclosure and UCC Article 9 remedies against defaulted commercial borrowers.","website":"https://www.fortress.com"},{"name":"Brightline","matchTerm":"Brightline","slug":"brightline","description":"Fortress Investment Group-backed private passenger railroad whose station-area real estate is held and developed through a network of affiliated holding and development entities.","website":"https://www.gobrightline.com"},{"name":"Namdar Realty Group","matchTerm":"Namdar","slug":"namdar-realty-group","description":"Great Neck, New York-based private owner of more than 100 shopping malls and retail centers nationally, frequently named in tenant, insurer, and municipal code-enforcement litigation over property conditions.","website":"https://namdarrealtygroup.com"},{"name":"Vesta Realty, LLC","matchTerm":"Vesta Realty","slug":"vesta-realty","description":"Tulsa, Oklahoma-based private multifamily platform that controlled a roughly $1 billion, nearly 10,000-unit apartment portfolio across Oklahoma, Kansas, and Arkansas before its collapse into dozens of investor-fraud, foreclosure, receivership, and regulatory enforcement actions."},{"name":"Phoenix American Hospitality","matchTerm":"Phoenix American Hospitality","slug":"phoenix-american-hospitality","description":"Dallas-based external manager of two non-traded hospitality REITs, which settled SEC fraud charges in 2026 over an $86 million Regulation A hotel-fund offering before the REITs themselves filed Chapter 11."},{"name":"Fannie Mae","matchTerm":"Fannie Mae","slug":"fannie-mae","description":"Federally chartered mortgage finance enterprise that purchases and guarantees multifamily and single-family mortgage loans, and frequently appears as plaintiff or loan-purchaser in commercial mortgage foreclosure litigation.","website":"https://www.fanniemae.com"},{"name":"BroadRange Logistics LLC","matchTerm":"BroadRange","slug":"broadrange-logistics","description":"Georgia-based third-party logistics (3PL) operator leasing large warehouse and distribution space across multiple states, named as defendant in separate landlord lawsuits over defaulted industrial leases."},{"name":"Brookfield Properties","matchTerm":"Brookfield","slug":"brookfield-properties","description":"Global alternative asset manager and one of the world's largest owners and operators of office, retail, and mixed-use commercial real estate, operating through numerous property-level subsidiaries and platforms.","website":"https://www.brookfieldproperties.com"},{"name":"ACORE Capital","matchTerm":"ACORE","slug":"acore-capital","description":"San Francisco-based commercial real estate debt manager that originates construction, bridge, and CMBS financing nationally, and frequently appears as a lender in commercial foreclosure litigation.","website":"https://acorecapital.com"},{"name":"LNR Partners, LLC","matchTerm":"LNR Partners","slug":"lnr-partners","description":"Miami Beach-based CMBS special servicer, a Starwood Property Trust subsidiary, that manages defaulted commercial mortgage loans and frequently pursues foreclosure on behalf of CMBS trust bondholders nationally."},{"name":"Alexandria Real Estate Equities, Inc.","matchTerm":"Alexandria","slug":"alexandria-real-estate-equities","description":"NYSE-listed REIT (ARE) and the nation's largest publicly traded owner and developer of life-science laboratory and office space, concentrated in life-science megacampuses including sites in Manhattan.","website":"https://www.are.com"},{"name":"Thor Equities","matchTerm":"Thor Equities","slug":"thor-equities","description":"Privately held New York City real estate investment and development firm led by Joseph Sitt, active in retail, mixed-use, and data-center development nationally.","website":"https://thorequities.com"},{"name":"PMC Property Group, Inc.","matchTerm":"PMC Property Group","slug":"pmc-property-group","description":"Philadelphia-based developer and owner specializing in new construction, renovation, and adaptive reuse of urban apartment and office buildings.","website":"https://www.pmcpropertygroup.com"},{"name":"JBG Smith Properties","matchTerm":"JBG Smith","slug":"jbg-smith","description":"Washington, D.C.-area REIT and real estate operating company focused on mixed-use office, multifamily, and retail development.","website":"https://www.jbgsmith.com"},{"name":"Federal Home Loan Mortgage Corporation (Freddie Mac)","matchTerm":"Freddie Mac","slug":"freddie-mac","description":"Federally chartered mortgage finance enterprise that purchases and guarantees multifamily mortgage loans and frequently appears as foreclosing lender or loan guarantor in commercial mortgage litigation.","website":"https://www.freddiemac.com"},{"name":"Walker & Dunlop, Inc.","matchTerm":"Walker & Dunlop","slug":"walker-dunlop","description":"Bethesda, Maryland-based commercial real estate finance and advisory firm that originates and services multifamily loans for Fannie Mae and Freddie Mac, frequently appearing as loan servicer or foreclosing plaintiff in agency-backed multifamily foreclosure litigation.","website":"https://www.walkerdunlop.com"},{"name":"Hillwood","matchTerm":"Hillwood","slug":"hillwood","description":"Dallas-based private real estate development firm founded by Ross Perot Jr., active nationally in industrial, mixed-use, and large-scale data center development."},{"name":"CommunityAmerica Credit Union","matchTerm":"CommunityAmerica","slug":"communityamerica-credit-union","description":"Lenexa, Kansas-based credit union that originates and acquires commercial mortgage loans, frequently appearing as foreclosing plaintiff in office and other commercial property litigation nationally.","website":"https://www.communityamerica.com"},{"name":"Arbor Realty Trust, Inc.","matchTerm":"Arbor Realty","slug":"arbor-realty-trust","description":"Uniondale, New York-based mortgage REIT (NYSE: ABR) and nationwide bridge and agency lender to multifamily and single-family-rental owners, frequently appearing as lender, foreclosing plaintiff, or securities defendant in commercial real estate litigation.","website":"https://www.arbor.com"}]};
